function makeWindowTexture(litChance, warm) {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const g = c.getContext('2d');
  g.fillStyle = '#1a1626';
  g.fillRect(0, 0, 128, 128);
  for (let y = 0; y < 4; y++) {
    for (let x = 0; x < 4; x++) {
      const lit = Math.random() < litChance;
      const hue = warm ? rand(30, 50) : rand(180, 210);
      g.fillStyle = lit ? `hsl(${hue}, 90%, ${rand(62, 80)}%)` : '#2b2f45';
      g.fillRect(x * 32 + 7, y * 32 + 6, 18, 20);
    }
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function makeRoadTexture() {
  const c = document.createElement('canvas');
  c.width = 64;
  c.height = 128;
  const g = c.getContext('2d');
  g.fillStyle = '#22222a';
  g.fillRect(0, 0, 64, 128);
  g.fillStyle = '#4a4a55';
  g.fillRect(0, 0, 3, 128);
  g.fillRect(61, 0, 3, 128);
  g.fillStyle = '#f5d76e';
  g.fillRect(30, 10, 4, 54);
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return tex;
}

function makeTextTexture(text, color) {
  const c = document.createElement('canvas');
  c.width = 512;
  c.height = 128;
  const g = c.getContext('2d');
  g.font = 'bold 72px "Segoe UI", system-ui, sans-serif';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.shadowColor = color;
  g.shadowBlur = 24;
  g.fillStyle = '#ffffff';
  g.fillText(text, 256, 64);
  g.fillText(text, 256, 64);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

