function makeBuildingGeometry(w, h, d) {
  const geo = new THREE.BoxGeometry(w, h, d);
  const uv = geo.attributes.uv;
  // Faces: +x, -x, +y, -y, +z, -z (4 verts each). Scale UVs so windows keep world size.
  for (let face = 0; face < 6; face++) {
    for (let v = 0; v < 4; v++) {
      const i = face * 4 + v;
      if (face === 2 || face === 3) {
        uv.setXY(i, 0.002, 0.002);
      } else {
        const across = face < 2 ? d : w;
        uv.setXY(i, uv.getX(i) * Math.max(1, Math.round(across / 2)) / 4, uv.getY(i) * Math.max(1, Math.round(h / 2)) / 4);
      }
    }
  }
  geo.translate(0, h / 2, 0);
  return geo;
}

const cityGroup = new THREE.Group();
scene.add(cityGroup);
const parkSpots = [];

function cellIntervals() {
  const edges = [-CITY_EXTENT, ...ROADS.flatMap((r) => [r - ROAD_WIDTH / 2, r + ROAD_WIDTH / 2]), CITY_EXTENT];
  const out = [];
  for (let i = 0; i < edges.length; i += 2) out.push([edges[i], edges[i + 1]]);
  return out;
}

for (const [x0, x1] of cellIntervals()) {
  for (const [z0, z1] of cellIntervals()) {
    const nx = Math.max(1, Math.floor((x1 - x0) / 9));
    const nz = Math.max(1, Math.floor((z1 - z0) / 9));
    const lx = (x1 - x0) / nx;
    const lz = (z1 - z0) / nz;
    for (let i = 0; i < nx; i++) {
      for (let j = 0; j < nz; j++) {
        const cx = x0 + lx * (i + 0.5);
        const cz = z0 + lz * (j + 0.5);
        const distC = Math.hypot(cx, cz);
        if (distC < PLAZA_RADIUS + 6) {
          parkSpots.push({ x: cx, z: cz, w: lx, d: lz });
          continue;
        }
        if (Math.random() < 0.12) {
          parkSpots.push({ x: cx, z: cz, w: lx, d: lz });
          continue;
        }
        const w = lx - rand(1.6, 3);
        const d = lz - rand(1.6, 3);
        const centerBoost = Math.max(0, 1 - distC / 80);
        let h = rand(6, 16) + centerBoost * rand(6, 22);
        if (Math.random() < 0.1) h += rand(14, 26);
        const mat = pick(buildingMaterials);
        const b = new THREE.Mesh(makeBuildingGeometry(w, h, d), mat);
        b.position.set(cx, 0, cz);
        b.castShadow = true;
        b.receiveShadow = true;
        cityGroup.add(b);
        state.buildings++;

        const roof = new THREE.Mesh(new THREE.BoxGeometry(w * 0.6, 0.8, d * 0.6), roofMaterial);
        roof.position.set(cx, h + 0.4, cz);
        roof.castShadow = true;
        cityGroup.add(roof);

        if (Math.random() < 0.55) {
          const neon = pick(neonList);
          const trimGeo = new THREE.BoxGeometry(w + 0.14, 0.18, d + 0.14);
          const trim = new THREE.Mesh(trimGeo, neon);
          trim.position.set(cx, h - 0.3, cz);
          cityGroup.add(trim);
          if (h > 22 && Math.random() < 0.6) {
            const trim2 = new THREE.Mesh(trimGeo, neon);
            trim2.position.set(cx, h * 0.55, cz);
            cityGroup.add(trim2);
          }
        }
        if (h > 26) {
          const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.12, 5, 6), roofMaterial);
          mast.position.set(cx, h + 3.3, cz);
          cityGroup.add(mast);
          const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.28, 10, 8), beaconMaterial.clone());
          beacon.position.set(cx, h + 5.9, cz);
          beacon.userData.phase = Math.random() * Math.PI * 2;
          cityGroup.add(beacon);
          beacons.push(beacon);
        }
      }
    }
  }
}

