let sparkCursor = 0;

function emitSparks(n, origin, power = 1) {
  for (let k = 0; k < n; k++) {
    const i = sparkCursor;
    sparkCursor = (sparkCursor + 1) % SPARK_COUNT;
    sparkPos[i * 3] = origin.x + rand(-0.3, 0.3);
    sparkPos[i * 3 + 1] = origin.y;
    sparkPos[i * 3 + 2] = origin.z + rand(-0.3, 0.3);
    const a = Math.random() * Math.PI * 2;
    const s = rand(2, 9) * power;
    sparkVel[i * 3] = Math.cos(a) * s;
    sparkVel[i * 3 + 1] = rand(3, 10) * power;
    sparkVel[i * 3 + 2] = Math.sin(a) * s;
    sparkLife[i] = rand(0.6, 1.4);
  }
}

function updateSparks(dt) {
  for (let i = 0; i < SPARK_COUNT; i++) {
    if (sparkLife[i] <= 0) {
      sparkCol[i * 3] = sparkCol[i * 3 + 1] = sparkCol[i * 3 + 2] = 0;
      continue;
    }
    sparkLife[i] -= dt;
    sparkVel[i * 3 + 1] -= 16 * dt;
    sparkPos[i * 3] += sparkVel[i * 3] * dt;
    sparkPos[i * 3 + 1] += sparkVel[i * 3 + 1] * dt;
    sparkPos[i * 3 + 2] += sparkVel[i * 3 + 2] * dt;
    if (sparkPos[i * 3 + 1] < 0.08) {
      sparkPos[i * 3 + 1] = 0.08;
      sparkVel[i * 3 + 1] *= -0.35;
      sparkVel[i * 3] *= 0.6;
      sparkVel[i * 3 + 2] *= 0.6;
    }
    const l = Math.max(0, Math.min(1, sparkLife[i]));
    sparkCol[i * 3] = 1.0 * l + 0.2;
    sparkCol[i * 3 + 1] = 0.55 * l * l;
    sparkCol[i * 3 + 2] = 0.12 * l * l * l;
    if (sparkLife[i] <= 0) sparkCol[i * 3] = 0;
  }
  sparkGeo.attributes.position.needsUpdate = true;
  sparkGeo.attributes.color.needsUpdate = true;
}

// ---------------------------------------------------------------------------
// Road graph for cats
// ---------------------------------------------------------------------------

const nodes = [];
const nodeAt = new Map();
function addNode(x, z) {
  const key = `${x},${z}`;
  if (nodeAt.has(key)) return nodeAt.get(key);
  const n = { x, z, links: [] };
  nodes.push(n);
  nodeAt.set(key, n);
  return n;
}
function link(a, b) {
  if (!a.links.includes(b)) a.links.push(b);
  if (!b.links.includes(a)) b.links.push(a);
}
const RING_R = 8.5;
const ringNodes = [];
for (let k = 0; k < 8; k++) {
  const a = (k / 8) * Math.PI * 2;
  ringNodes.push(addNode(Math.round(Math.cos(a) * RING_R * 100) / 100, Math.round(Math.sin(a) * RING_R * 100) / 100));
}
ringNodes.forEach((n, k) => link(n, ringNodes[(k + 1) % 8]));
const isCenter = (i, j) => i === 2 && j === 2;
const gridNode = (i, j) => (isCenter(i, j) ? null : addNode(ROADS[i], ROADS[j]));
function centerSubstitute(i, j) {
  // neighbour of center -> plaza ring node pointing toward it
  if (i === 1) return ringNodes[4];
  if (i === 3) return ringNodes[0];
  if (j === 1) return ringNodes[6];
  return ringNodes[2];
}
for (let i = 0; i < ROADS.length; i++) {
  for (let j = 0; j < ROADS.length; j++) {
    const here = gridNode(i, j);
    for (const [di, dj] of [[1, 0], [0, 1]]) {
      const ni = i + di;
      const nj = j + dj;
      if (ni >= ROADS.length || nj >= ROADS.length) continue;
      const there = gridNode(ni, nj);
      if (here && there) link(here, there);
      else if (here && !there) link(here, centerSubstitute(i, j));
      else if (!here && there) link(there, centerSubstitute(ni, nj));
    }
  }
}

