// Moru Cats
// ---------------------------------------------------------------------------

const CAT_PALETTE = [
  { body: 0xf29a3a, accent: 0xffffff },
  { body: 0xf4f0ea, accent: 0xf29a3a },
  { body: 0x2a2a30, accent: 0xffffff },
  { body: 0x9a9aa8, accent: 0xe8e8f0 },
  { body: 0xf3d9a8, accent: 0x8a5a30 },
  { body: 0x6a4a3a, accent: 0xf3d9a8 },
  { body: 0xff7ad9, accent: 0x7af6ff },
];
const catGeo = {
  body: new THREE.CapsuleGeometry(0.3, 0.55, 6, 12).rotateX(Math.PI / 2),
  head: new THREE.SphereGeometry(0.32, 16, 12),
  ear: new THREE.ConeGeometry(0.11, 0.24, 4),
  eye: new THREE.SphereGeometry(0.055, 8, 6),
  nose: new THREE.SphereGeometry(0.035, 6, 4),
  leg: new THREE.CylinderGeometry(0.075, 0.065, 0.36, 6).translate(0, -0.18, 0),
  tail: new THREE.CylinderGeometry(0.05, 0.065, 0.32, 6).translate(0, 0.16, 0),
  belly: new THREE.SphereGeometry(0.26, 12, 8),
};
const eyeMat = new THREE.MeshStandardMaterial({ color: 0x111111, emissive: 0x3ef2ff, emissiveIntensity: 0.6, roughness: 0.2 });
const noseMat = new THREE.MeshStandardMaterial({ color: 0xff8fb1, roughness: 0.6 });
const matCache = new Map();
function catMat(color) {
  if (!matCache.has(color)) matCache.set(color, new THREE.MeshStandardMaterial({ color, roughness: 0.75 }));
  return matCache.get(color);
}

let catIdSeq = 0;
function buildCatMesh(palette) {
  const root = new THREE.Group();
  const bodyGroup = new THREE.Group();
  bodyGroup.position.y = 0.55;
  root.add(bodyGroup);
  const bodyMat = catMat(palette.body);
  const accentMat = catMat(palette.accent);

  const body = new THREE.Mesh(catGeo.body, bodyMat);
  const belly = new THREE.Mesh(catGeo.belly, accentMat);
  belly.scale.set(0.9, 0.8, 1.5);
  belly.position.set(0, -0.08, 0.05);
  bodyGroup.add(body, belly);

  const head = new THREE.Group();
  head.position.set(0, 0.28, 0.5);
  bodyGroup.add(head);
  const skull = new THREE.Mesh(catGeo.head, bodyMat);
  skull.scale.set(1.1, 0.95, 1);
  head.add(skull);
  for (const s of [-1, 1]) {
    const ear = new THREE.Mesh(catGeo.ear, bodyMat);
    ear.position.set(0.17 * s, 0.3, -0.02);
    ear.rotation.z = -0.25 * s;
    head.add(ear);
    const eye = new THREE.Mesh(catGeo.eye, eyeMat);
    eye.position.set(0.12 * s, 0.05, 0.28);
    head.add(eye);
  }
  const muzzle = new THREE.Mesh(catGeo.belly, accentMat);
  muzzle.scale.set(0.55, 0.38, 0.4);
  muzzle.position.set(0, -0.09, 0.24);
  head.add(muzzle);
  const nose = new THREE.Mesh(catGeo.nose, noseMat);
  nose.position.set(0, -0.02, 0.33);
  head.add(nose);

  const legs = [];
  for (const [lx, lz, ph] of [[-0.16, 0.3, 0], [0.16, 0.3, Math.PI], [-0.16, -0.3, Math.PI], [0.16, -0.3, 0]]) {
    const leg = new THREE.Mesh(catGeo.leg, bodyMat);
    leg.position.set(lx, -0.1, lz);
    leg.userData.phase = ph;
    bodyGroup.add(leg);
    legs.push(leg);
  }

  const tailRoot = new THREE.Group();
  tailRoot.position.set(0, 0.1, -0.55);
  tailRoot.rotation.x = -0.9;
  bodyGroup.add(tailRoot);
  const tailSegs = [];
  let parent = tailRoot;
  for (let k = 0; k < 4; k++) {
    const seg = new THREE.Group();
    if (k > 0) seg.position.y = 0.3;
    const m = new THREE.Mesh(catGeo.tail, k === 3 ? accentMat : bodyMat);
    seg.add(m);
    parent.add(seg);
    tailSegs.push(seg);
    parent = seg;
  }

  root.traverse((o) => {
    if (o.isMesh) o.castShadow = true;
  });
  return { root, bodyGroup, head, legs, tailRoot, tailSegs };
}

function spawnCat({ fromForge = true } = {}) {
  if (state.cats.length >= MAX_CATS) {
    toast(`Cat village is full (${MAX_CATS} cats)!`);
    return null;
  }
  const palette = pick(CAT_PALETTE);
  const mesh = buildCatMesh(palette);
  const scale = rand(0.85, 1.2);
  mesh.root.scale.setScalar(scale);
  let start;
  let target;
  if (fromForge) {
    start = { x: 0, z: 0 };
    target = pick(ringNodes);
  } else {
    start = pick(nodes);
    target = pick(start.links);
  }
  const cat = {
    id: ++catIdSeq,
    name: `Moru Cat #${catIdSeq}`,
    palette,
    mesh,
    group: mesh.root,
    x: start.x,
    z: start.z,
    y: fromForge ? ANVIL_TOP : 0,
    vy: fromForge ? 9 : 0,
    heading: Math.random() * Math.PI * 2,
    speed: rand(2.6, 4.6),
    lane: rand(-1.6, 1.6),
    phase: Math.random() * 10,
    prev: fromForge ? null : start,
    target,
    airborne: fromForge,
    jumps: 0,
    scale,
  };
  cat.group.position.set(cat.x, cat.y, cat.z);
  scene.add(cat.group);
  state.cats.push(cat);
  state.catCount = state.cats.length;
  return cat;
}

function catJump(cat, power = 1) {
  if (cat.airborne) return;
  cat.airborne = true;
  cat.vy = rand(5, 7) * power;
  cat.jumps++;
}

const GRAVITY = 20;
function updateCat(cat, dt, t) {
  // steer to target with a lane offset
  const prev = cat.prev || { x: cat.x, z: cat.z };
  let dx = cat.target.x - prev.x;
  let dz = cat.target.z - prev.z;
  const segLen = Math.hypot(dx, dz) || 1;
  const px = dz / segLen;
  const pz = -dx / segLen;
  const tx = cat.target.x + px * cat.lane;
  const tz = cat.target.z + pz * cat.lane;
  dx = tx - cat.x;
  dz = tz - cat.z;
  const dist = Math.hypot(dx, dz);
  if (dist < 0.5) {
    const options = cat.target.links.filter((n) => n !== cat.prev);
    const next = pick(options.length ? options : cat.target.links);
    cat.prev = cat.target;
    cat.target = next;
    if (Math.random() < 0.3) catJump(cat);
  } else {
    const step = Math.min(dist, cat.speed * dt * (cat.airborne ? 1.15 : 1));
    cat.x += (dx / dist) * step;
    cat.z += (dz / dist) * step;
    const desired = Math.atan2(dx, dz);
    let diff = desired - cat.heading;
    diff = Math.atan2(Math.sin(diff), Math.cos(diff));
    cat.heading += diff * Math.min(1, dt * 8);
  }

  // random hops
  if (!cat.airborne && Math.random() < dt * 0.12) catJump(cat);

  const m = cat.mesh;
  cat.phase += dt * cat.speed * 3.2;
  if (cat.airborne) {
    cat.vy -= GRAVITY * dt;
    cat.y += cat.vy * dt;
    if (cat.y <= 0 && cat.vy < 0) {
      cat.y = 0;
      cat.vy = 0;
      cat.airborne = false;
    }
    const stretch = THREE.MathUtils.clamp(cat.vy * 0.03, -0.2, 0.25);
    m.bodyGroup.rotation.x = -stretch;
    for (const leg of m.legs) leg.rotation.x = leg.position.z > 0 ? -0.9 : 0.9;
    m.bodyGroup.position.y = 0.55;
  } else {
    for (const leg of m.legs) leg.rotation.x = Math.sin(cat.phase + leg.userData.phase) * 0.75;
    m.bodyGroup.position.y = 0.55 + Math.abs(Math.sin(cat.phase)) * 0.07;
    m.bodyGroup.rotation.x = Math.sin(cat.phase * 2) * 0.04;
  }
  m.head.rotation.y = Math.sin(t * 1.3 + cat.id) * 0.25;
  m.tailRoot.rotation.z = Math.sin(t * 5 + cat.id) * 0.4;
  m.tailSegs.forEach((seg, k) => {
    if (k > 0) seg.rotation.x = 0.35 + Math.sin(t * 4 + k + cat.id) * 0.15;
  });

  cat.group.position.set(cat.x, cat.y, cat.z);
  cat.group.rotation.y = cat.heading;
}

