const THEMES = {
  night: {
    skyTop: 0x05031a, skyBottom: 0x2a0f3d, fog: 0x140a26, fogNear: 50, fogFar: 200,
    hemiSky: 0x8a7dff, hemiGround: 0x1a1030, hemi: 0.35,
    sun: 0x9db4ff, sunI: 0.35, sunPos: [-40, 80, 30],
    windows: 1.4, lamps: 3.2, pool: 0.28, neon: 2.4, stars: 1, bloom: 1.05, exposure: 1.0,
  },
  gold: {
    skyTop: 0x3a2a6a, skyBottom: 0xffa25a, fog: 0xe0905a, fogNear: 60, fogFar: 230,
    hemiSky: 0xffd0a0, hemiGround: 0x4a2a30, hemi: 0.7,
    sun: 0xffa860, sunI: 2.4, sunPos: [90, 28, 50],
    windows: 0.6, lamps: 1.6, pool: 0.12, neon: 1.4, stars: 0.15, bloom: 0.6, exposure: 1.05,
  },
  day: {
    skyTop: 0x3d8de0, skyBottom: 0xcde8ff, fog: 0xc4dff5, fogNear: 80, fogFar: 300,
    hemiSky: 0xd8ecff, hemiGround: 0x5a5a48, hemi: 1.1,
    sun: 0xfff4e0, sunI: 3.0, sunPos: [50, 110, 40],
    windows: 0.05, lamps: 0.15, pool: 0.0, neon: 0.6, stars: 0, bloom: 0.25, exposure: 1.0,
  },
};

const themeLive = (() => {
  const t = THEMES.night;
  return {
    skyTop: new THREE.Color(t.skyTop), skyBottom: new THREE.Color(t.skyBottom), fog: new THREE.Color(t.fog),
    hemiSky: new THREE.Color(t.hemiSky), hemiGround: new THREE.Color(t.hemiGround), sun: new THREE.Color(t.sun),
    sunPos: new THREE.Vector3(...t.sunPos),
    fogNear: t.fogNear, fogFar: t.fogFar, hemi: t.hemi, sunI: t.sunI, windows: t.windows, lamps: t.lamps,
    pool: t.pool, neon: t.neon, stars: t.stars, bloom: t.bloom, exposure: t.exposure,
  };
})();
const tmpColor = new THREE.Color();
const tmpVec = new THREE.Vector3();

function updateTheme(dt) {
  const target = THEMES[state.theme];
  const k = 1 - Math.exp(-dt * 3);
  for (const key of ['skyTop', 'skyBottom', 'fog', 'hemiSky', 'hemiGround', 'sun']) {
    themeLive[key].lerp(tmpColor.set(target[key]), k);
  }
  themeLive.sunPos.lerp(tmpVec.set(...target.sunPos), k);
  for (const key of ['fogNear', 'fogFar', 'hemi', 'sunI', 'windows', 'lamps', 'pool', 'neon', 'stars', 'bloom', 'exposure']) {
    themeLive[key] += (target[key] - themeLive[key]) * k;
  }
  skyUniforms.topColor.value.copy(themeLive.skyTop);
  skyUniforms.bottomColor.value.copy(themeLive.skyBottom);
  scene.fog.color.copy(themeLive.fog);
  scene.fog.near = themeLive.fogNear;
  scene.fog.far = themeLive.fogFar;
  hemi.color.copy(themeLive.hemiSky);
  hemi.groundColor.copy(themeLive.hemiGround);
  hemi.intensity = themeLive.hemi;
  sun.color.copy(themeLive.sun);
  sun.intensity = themeLive.sunI;
  sun.position.copy(themeLive.sunPos);
  for (const m of buildingMaterials) m.emissiveIntensity = themeLive.windows;
  bulbMaterial.emissiveIntensity = themeLive.lamps;
  poolMaterial.opacity = themeLive.pool;
  for (const m of neonList) m.emissiveIntensity = themeLive.neon;
  starMat.opacity = themeLive.stars;
  stars.visible = themeLive.stars > 0.02;
  bloomPass.strength = themeLive.bloom;
  renderer.toneMappingExposure = themeLive.exposure;
}

