const VIEWS = {
  overview: { pos: [72, 62, 72], target: [0, 2, 0], fov: 50 },
  iso: { pos: [140, 140, 140], target: [0, 0, 0], fov: 22 },
  street: { pos: [1.5, 2.2, 46], target: [0, 3.5, 0], fov: 62 },
};
const camTransition = { active: false, pos: new THREE.Vector3(), target: new THREE.Vector3(), fov: 50 };

function setCameraView(view) {
  state.cameraView = view;
  if (view === 'follow') {
    if (!state.cats.length) spawnCat();
    controls.enabled = false;
    camTransition.active = false;
  } else {
    const v = VIEWS[view];
    camTransition.active = true;
    camTransition.pos.set(...v.pos);
    camTransition.target.set(...v.target);
    camTransition.fov = v.fov;
    controls.enabled = true;
  }
  setActive(['cam-overview', 'cam-iso', 'cam-street', 'cam-follow-cat'], view === 'follow' ? 'cam-follow-cat' : `cam-${view}`);
}

function followedCat() {
  if (!state.cats.length) return null;
  state.followIndex = ((state.followIndex % state.cats.length) + state.cats.length) % state.cats.length;
  return state.cats[state.followIndex];
}

const followOffset = new THREE.Vector3();
const followLook = new THREE.Vector3();
function updateCamera(dt) {
  const k = 1 - Math.exp(-dt * 3.5);
  if (state.cameraView === 'follow') {
    const cat = followedCat();
    if (cat) {
      const back = 5.5;
      followOffset.set(cat.x - Math.sin(cat.heading) * back, cat.y + 3.0, cat.z - Math.cos(cat.heading) * back);
      followOffset.y = Math.max(followOffset.y, 1.2);
      camera.position.lerp(followOffset, 1 - Math.exp(-dt * 4));
      followLook.set(cat.x, cat.y + 1.0, cat.z);
      controls.target.lerp(followLook, 1 - Math.exp(-dt * 8));
      camera.lookAt(controls.target);
    }
    camera.fov += (58 - camera.fov) * k;
    camera.updateProjectionMatrix();
    return;
  }
  if (camTransition.active) {
    camera.position.lerp(camTransition.pos, k);
    controls.target.lerp(camTransition.target, k);
    camera.fov += (camTransition.fov - camera.fov) * k;
    camera.updateProjectionMatrix();
    if (camera.position.distanceTo(camTransition.pos) < 0.3 && Math.abs(camera.fov - camTransition.fov) < 0.2) {
      camTransition.active = false;
    }
  }
  controls.autoRotate = !state.paused && state.cameraView === 'overview' && !camTransition.active;
  controls.update(dt);
}

// Stop transitions when the user grabs the camera
controls.addEventListener('start', () => {
  camTransition.active = false;
});

// ---------------------------------------------------------------------------
// Forge strike
// ---------------------------------------------------------------------------

const hammer = { t: -1, impacted: true };
let anvilHeat = 0;
let shake = 0;

function strikeAnvil() {
  hammer.t = 0;
  hammer.impacted = false;
}

function onImpact() {
  state.strikes++;
  anvilHeat = Math.min(1.6, anvilHeat + 0.8);
  shake = 0.35;
  strikeLight.intensity = 160;
  emitSparks(110, new THREE.Vector3(0.1, ANVIL_TOP + 0.05, 0.15), 1);
  emitSparks(30, new THREE.Vector3(-4.2, 1.3, -3.2), 0.6);
  for (const cat of state.cats) {
    const d = Math.hypot(cat.x, cat.z);
    if (d < 32) catJump(cat, 1.15 - d / 80);
  }
  if (state.strikes % 5 === 0) {
    const cat = spawnCat({ fromForge: true });
    if (cat) toast(`✨ Strike ${state.strikes}! The forge birthed ${cat.name}`);
  } else {
    toast(`🔨 CLANG! Strike ${state.strikes}`);
  }
}

function updateForge(dt, simDt, t) {
  if (hammer.t >= 0) {
    hammer.t += dt;
    const down = 0.11;
    const up = 0.45;
    if (hammer.t < down) {
      hammerPivot.rotation.x = HAMMER_REST * (1 - (hammer.t / down) ** 2);
    } else {
      if (!hammer.impacted) {
        hammer.impacted = true;
        onImpact();
      }
      const u = Math.min(1, (hammer.t - down) / up);
      hammerPivot.rotation.x = HAMMER_REST * (1 - (1 - u) ** 3);
      if (u >= 1) hammer.t = -1;
    }
  }
  anvilHeat = Math.max(0, anvilHeat - dt * 0.5);
  anvilHotMat.emissiveIntensity = anvilHeat * 1.8;
  strikeLight.intensity *= Math.exp(-dt * 7);
  hearthLight.intensity = 26 + Math.sin(t * 11) * 4 + Math.sin(t * 23.7) * 3 + anvilHeat * 25;
  emberMat.emissiveIntensity = 2.2 + Math.sin(t * 9) * 0.4 + anvilHeat;
  if (Math.random() < dt * 6) emitSparks(1, new THREE.Vector3(-4.2, 1.3, -3.2), 0.35);

  // Holo spin is paused with the world
  holo.position.y = 9 + Math.sin(t * 1.2) * 0.35;
  ringA.rotation.z += simDt * 0.8;
  ringB.rotation.x += simDt * 1.1;
  ringB.rotation.y += simDt * 0.4;
  ringC.rotation.y -= simDt * 0.6;
  ringC.rotation.x = Math.PI / 2 + Math.sin(t * 0.7) * 0.4;
  plazaRing2.rotation.z += simDt * 0.3;

  for (const b of beacons) {
    b.material.emissiveIntensity = 0.3 + 3 * Math.max(0, Math.sin(t * 2.2 + b.userData.phase)) ** 6;
  }
}

