    `Cats     ${String(state.catCount).padStart(4)} / ${MAX_CATS}  ↑${airborne}\n` +
    `Strikes  ${String(state.strikes).padStart(4)}\n` +
    `Theme    ${state.theme}\n` +
    `Camera   ${state.cameraView}${follow ? ` → #${follow.id}` : ''}\n` +
    `Sim      ${state.paused ? 'PAUSED' : 'running'}  t=${state.simTime.toFixed(1)}s\n` +
    `City     ${state.buildings} bldg · ${state.trees} trees · ${state.lamps} lamps\n` +
    `GPU      ${info.render.calls} calls · ${(info.render.triangles / 1000).toFixed(1)}k tris`;
}

function frame() {
  const rawDt = clock.getDelta();
  const dt = Math.min(rawDt, 0.05);
  const simDt = state.paused ? 0 : dt;
  state.elapsed += dt;
  state.simTime += simDt;
  const t = state.simTime;

  fpsFrames++;
  fpsAccum += rawDt;
  if (fpsAccum >= 0.5) {
    state.fps = fpsFrames / fpsAccum;
    state.frameMs = (fpsAccum / fpsFrames) * 1000;
    fpsFrames = 0;
    fpsAccum = 0;
  }

  if (simDt > 0) for (const cat of state.cats) updateCat(cat, simDt, t);
  updateForge(dt, simDt, state.elapsed);
  updateSparks(dt);
  updateTheme(dt);
  updateCamera(dt);

  // transient camera shake (applied only for this render)
  shake = Math.max(0, shake - dt * 1.4);
  shakeOffset.set(rand(-1, 1), rand(-1, 1), rand(-1, 1)).multiplyScalar(shake * 0.6);
  camera.position.add(shakeOffset);

  renderer.info.reset();
  composer.render(dt);
  camera.position.sub(shakeOffset);

  hudAccum += dt;
  if (hudAccum > 0.25) {
    hudAccum = 0;
    updateHud();
  }
}

// ---------------------------------------------------------------------------
// Boot
// ---------------------------------------------------------------------------

for (let i = 0; i < INITIAL_CATS; i++) spawnCat({ fromForge: false });
setTheme('night');
setCameraView('overview');
updateTheme(10);

window.__app = { scene, camera, renderer, state };

renderer.setAnimationLoop(frame);


