import * as THREE from 'three';

// ---------------------------------------------------------------------------
// Chibi 3D Moru Cat
//  - createMoruCat(index, seed): builds an articulated cat (faces +Z locally)
//  - updateMoruCat(cat, dt, elapsed): locomotion along plaza ring / avenues
//  - exciteMoruCat(cat, strength): triggers a big jump (forge strike)
// All animation state advances only by `dt`, so dt === 0 freezes the cat
// in a byte-identical pose.
// ---------------------------------------------------------------------------

const CAT_SCALE = 2.0;

const FUR_PALETTES = [
  { fur: 0xf2a65a, belly: 0xfff1dc, stripe: 0xd9822b, name: 'Ginger' },
  { fur: 0x9aa3b5, belly: 0xf1f3f8, stripe: 0x6f7889, name: 'Ash' },
  { fur: 0xfbe7c6, belly: 0xffffff, stripe: 0xe7c48f, name: 'Cream' },
  { fur: 0x3a3440, belly: 0xe9e1f0, stripe: 0x241f29, name: 'Coal' },
  { fur: 0xffffff, belly: 0xffe6ef, stripe: 0xe8e2ea, name: 'Snow' },
  { fur: 0xc98a5b, belly: 0xf7e3cf, stripe: 0x8f5a36, name: 'Mocha' },
  { fur: 0xe9c46a, belly: 0xfff6dc, stripe: 0xc89b33, name: 'Honey' },
];

const COLLAR_COLORS = [0xe63946, 0x2a9df4, 0x8338ec, 0x06d6a0, 0xff7b00, 0xff4fa3];

// Seeded PRNG (mulberry32)
function makeRng(seed) {
  let a = (seed >>> 0) || 0x9e3779b9;
  return function rng() {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function std(color, opts = {}) {
  return new THREE.MeshStandardMaterial({
    color,
    roughness: opts.roughness ?? 0.65,
    metalness: opts.metalness ?? 0.0,
    emissive: opts.emissive ?? 0x000000,
    emissiveIntensity: opts.emissiveIntensity ?? 1.0,
  });
}

function mesh(geometry, material, name, castShadow = true) {
  const m = new THREE.Mesh(geometry, material);
  m.name = name;
  m.castShadow = castShadow;
  m.receiveShadow = false;
  return m;
}

// ---------------------------------------------------------------------------
// Routes: plaza ring + main avenues (x = 0 and z = 0 axes) — kept on open
// ground outside the forge dais and away from building lots.
// ---------------------------------------------------------------------------

function ringPoints(radius, startAngle, endAngle, steps) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const a = startAngle + (endAngle - startAngle) * (i / steps);
    pts.push(new THREE.Vector2(Math.cos(a) * radius, Math.sin(a) * radius));
  }
  return pts;
}

function buildRoute(index, rng) {
  const kind = index % 3;
  const ringR = 19 + (index % 4) * 2.2 + rng() * 1.2;
  const dir = rng() < 0.5 ? 1 : -1;
  const phase = Math.floor(rng() * 4) * (Math.PI / 2);
  let pts = [];

  if (kind === 0) {
    // Full plaza ring loop
    pts = ringPoints(ringR, phase, phase + dir * Math.PI * 2, 48);
  } else if (kind === 1) {
    // Ring quarter then an excursion down an avenue and back
    const reach = 55 + rng() * 25;
    const lane = (rng() < 0.5 ? -1 : 1) * (1.6 + rng() * 1.2);
    for (let q = 0; q < 4; q++) {
      const a0 = phase + dir * q * (Math.PI / 2);
      const a1 = a0 + dir * (Math.PI / 2);
      const arc = ringPoints(ringR, a0, a1, 12);
      if (q > 0) arc.shift();
      pts.push(...arc);
      if (q % 2 === 0) {
        // Out along the avenue at angle a1 (aligned to an axis)
        const ax = Math.round(Math.cos(a1));
        const az = Math.round(Math.sin(a1));
        const px = -az * lane;
        const pz = ax * lane;
        pts.push(new THREE.Vector2(ax * (ringR + 2) + px, az * (ringR + 2) + pz));
        pts.push(new THREE.Vector2(ax * reach + px, az * reach + pz));
        pts.push(new THREE.Vector2(ax * reach - px, az * reach - pz));
        pts.push(new THREE.Vector2(ax * (ringR + 2) - px, az * (ringR + 2) - pz));
        pts.push(new THREE.Vector2(Math.cos(a1) * ringR, Math.sin(a1) * ringR));
      }
    }
  } else {
    // Cross route: through the avenue on one axis, around the ring, out the other
    const reach = 48 + rng() * 22;
    const lane = 2.2 + rng() * 0.8;
    const swap = rng() < 0.5;
    const P = (x, z) => (swap ? new THREE.Vector2(z, x) : new THREE.Vector2(x, z));
    pts.push(P(lane, ringR));
    pts.push(P(lane, reach));
    pts.push(P(-lane, reach));
    pts.push(P(-lane, ringR));
    const arcA = ringPoints(ringR, Math.PI / 2 + 0.12, Math.PI * 1.5 - 0.12, 20).map((v) => P(v.x, v.y));
    pts.push(...arcA);
    pts.push(P(-lane, -ringR));
    pts.push(P(-lane, -reach));
    pts.push(P(lane, -reach));
    pts.push(P(lane, -ringR));
    const arcB = ringPoints(ringR, -Math.PI / 2 + 0.12, Math.PI / 2 - 0.12, 20).map((v) => P(v.x, v.y));
    pts.push(...arcB);
    if (dir < 0) pts.reverse();
  }

  // Close loop and precompute cumulative lengths
  if (pts[0].distanceTo(pts[pts.length - 1]) > 1e-3) pts.push(pts[0].clone());
  const cumulative = [0];
  for (let i = 1; i < pts.length; i++) {
    cumulative.push(cumulative[i - 1] + pts[i].distanceTo(pts[i - 1]));
  }
  return { points: pts, cumulative, length: cumulative[cumulative.length - 1] };
}

function sampleRoute(route, distance, out) {
  const { points, cumulative, length } = route;
  let d = distance % length;
  if (d < 0) d += length;
  // Binary search segment
  let lo = 0;
  let hi = cumulative.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (cumulative[mid] <= d) lo = mid;
    else hi = mid;
  }
  const segLen = cumulative[hi] - cumulative[lo] || 1;
  const t = (d - cumulative[lo]) / segLen;
  const a = points[lo];
  const b = points[hi];
  out.x = a.x + (b.x - a.x) * t;
  out.z = a.y + (b.y - a.y) * t;
  out.heading = Math.atan2(b.x - a.x, b.y - a.y);
  return out;
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------

export function createMoruCat(index = 0, seed = 1) {
  const rng = makeRng((seed * 2654435761) ^ (index * 40503 + 17));
  const palette = FUR_PALETTES[(index + Math.floor(rng() * FUR_PALETTES.length)) % FUR_PALETTES.length];
  const collarColor = COLLAR_COLORS[Math.floor(rng() * COLLAR_COLORS.length)];

  const cat = new THREE.Group();
  cat.name = `MoruCat_${index}`;

  // Materials
  const furMat = std(palette.fur, { roughness: 0.8 });
  const stripeMat = std(palette.stripe, { roughness: 0.82 });
  const bellyMat = std(palette.belly, { roughness: 0.85 });
  const innerEarMat = std(0xff9fb8, { roughness: 0.7 });
  const cheekMat = std(0xffb3c6, { roughness: 0.75, emissive: 0xff6f91, emissiveIntensity: 0.12 });
  const eyeMat = new THREE.MeshPhysicalMaterial({
    color: 0x1a1426, roughness: 0.08, metalness: 0.0, clearcoat: 1.0, clearcoatRoughness: 0.04,
  });
  const irisMat = std(rng() < 0.5 ? 0x3ec7ff : 0x7bd66b, { roughness: 0.2, emissive: 0x113344, emissiveIntensity: 0.4 });
  const catchMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const noseMat = std(0xff7aa2, { roughness: 0.35 });
  const mouthMat = std(0x5a2a3a, { roughness: 0.6 });
  const whiskerMat = new THREE.MeshStandardMaterial({ color: 0xf8f8ff, roughness: 0.4, emissive: 0x444455, emissiveIntensity: 0.3 });
  const collarMat = std(collarColor, { roughness: 0.45 });
  const bellMat = std(0xffc93c, { roughness: 0.18, metalness: 0.95, emissive: 0x6b4a00, emissiveIntensity: 0.35 });
  const helmetMat = std(0x7d8590, { roughness: 0.32, metalness: 0.85 });
  const helmetRimMat = std(0xb07a3c, { roughness: 0.35, metalness: 0.8 });
  const rivetMat = std(0xffd27a, { roughness: 0.25, metalness: 0.9, emissive: 0xff8a00, emissiveIntensity: 0.25 });
  const pawMat = std(palette.belly, { roughness: 0.8 });
  const padMat = std(0xff9fb8, { roughness: 0.6 });

  // Root that hops / flips (cat group itself handles position + heading)
  const body = new THREE.Group();
  body.name = 'bodyRoot';
  cat.add(body);

  // ---- Torso -------------------------------------------------------------
  const torsoGroup = new THREE.Group();
  torsoGroup.position.set(0, 0.42, 0);
  body.add(torsoGroup);

  const torso = mesh(new THREE.CapsuleGeometry(0.24, 0.34, 10, 20), furMat, 'torso');
  torso.rotation.x = Math.PI / 2;
  torso.scale.set(1.0, 1.0, 0.95);
  torsoGroup.add(torso);

  const belly = mesh(new THREE.SphereGeometry(0.2, 20, 16), bellyMat, 'bellyPatch');
  belly.scale.set(0.95, 0.75, 1.55);
  belly.position.set(0, -0.09, 0.02);
  torsoGroup.add(belly);

  // Tabby stripes on the back
  for (let i = 0; i < 3; i++) {
    const stripe = mesh(new THREE.TorusGeometry(0.235, 0.025, 6, 20, Math.PI * 0.9), stripeMat, `stripe_${i}`, false);
    stripe.rotation.set(0, Math.PI / 2, Math.PI * 0.05);
    stripe.position.set(0, 0.02, -0.18 + i * 0.13);
