  }

  // Big glossy eyes with catchlights
  const eyes = [];
  for (const s of [-1, 1]) {
    const eyeGroup = new THREE.Group();
    eyeGroup.position.set(0.13 * s, 0.03, 0.27);
    eyeGroup.rotation.y = 0.28 * s;
    headPivot.add(eyeGroup);

    const eye = mesh(new THREE.SphereGeometry(0.095, 22, 18), eyeMat, s < 0 ? 'eyeL' : 'eyeR', false);
    eye.scale.set(0.9, 1.08, 0.55);
    eyeGroup.add(eye);

    const iris = mesh(new THREE.SphereGeometry(0.06, 18, 14), irisMat, s < 0 ? 'irisL' : 'irisR', false);
    iris.scale.set(0.85, 1.1, 0.35);
