  const rim = mesh(new THREE.TorusGeometry(0.315, 0.035, 10, 32), helmetRimMat, 'helmetRim');
  rim.rotation.x = Math.PI / 2;
  rim.scale.set(1.08, 1.04, 1);
  helmetGroup.add(rim);

  const ridge = mesh(new THREE.BoxGeometry(0.05, 0.05, 0.56), helmetRimMat, 'helmetRidge');
  ridge.position.set(0, 0.215, 0);
  ridge.scale.set(1, 1, 1);
  helmetGroup.add(ridge);

  const visor = mesh(new THREE.BoxGeometry(0.34, 0.03, 0.1), helmetRimMat, 'helmetVisor');
  visor.position.set(0, 0.01, 0.33);
  visor.rotation.x = 0.18;
  helmetGroup.add(visor);

  for (const s of [-1, 0, 1]) {
    const rivet = mesh(new THREE.SphereGeometry(0.022, 8, 6), rivetMat, `helmetRivet_${s + 1}`, false);
    const a = s * 0.55;
    rivet.position.set(Math.sin(a) * 0.33, 0.03, Math.cos(a) * 0.33);
    helmetGroup.add(rivet);
  }

  // Tiny glowing forge rune on the helmet front
  const rune = mesh(new THREE.OctahedronGeometry(0.035, 0), new THREE.MeshBasicMaterial({ color: 0xff8a2a }), 'helmetRune', false);
  rune.position.set(0, 0.13, 0.26);
  helmetGroup.add(rune);

  // ---- Legs (4 swinging) -------------------------------------------------
  const legGeo = new THREE.CapsuleGeometry(0.075, 0.2, 6, 12);
  const pawGeo = new THREE.SphereGeometry(0.088, 14, 10);
  const padGeo = new THREE.CircleGeometry(0.045, 12);
  const legs = [];
  const legLayout = [
    { x: -0.15, z: 0.2, name: 'FL', phase: 0 },
    { x: 0.15, z: 0.2, name: 'FR', phase: Math.PI },
    { x: -0.15, z: -0.2, name: 'BL', phase: Math.PI },
    { x: 0.15, z: -0.2, name: 'BR', phase: 0 },
  ];
  for (const L of legLayout) {
    const pivot = new THREE.Group();
    pivot.name = `legPivot_${L.name}`;
    pivot.position.set(L.x, 0.36, L.z);
    body.add(pivot);

    const leg = mesh(legGeo, furMat, `leg_${L.name}`);
    leg.position.y = -0.15;
    pivot.add(leg);

    const paw = mesh(pawGeo, pawMat, `paw_${L.name}`);
    paw.scale.set(1, 0.7, 1.25);
    paw.position.set(0, -0.3, 0.025);
    pivot.add(paw);

    const pad = mesh(padGeo, padMat, `pawPad_${L.name}`, false);
    pad.rotation.x = Math.PI / 2;
    pad.position.set(0, -0.362, 0.03);
    pivot.add(pad);

    legs.push({ pivot, phase: L.phase });
  }

  // ---- Tail (3 segments + tip) ------------------------------------------
  const tailRoot = new THREE.Group();
  tailRoot.name = 'tailRoot';
  tailRoot.position.set(0, 0.5, -0.38);
  tailRoot.rotation.x = -0.75;
  body.add(tailRoot);

  const tailSegments = [];
  let parent = tailRoot;
  const segLen = 0.17;
  for (let i = 0; i < 3; i++) {
    const segPivot = new THREE.Group();
    segPivot.name = `tailPivot_${i}`;
    if (i > 0) segPivot.position.y = segLen;
    parent.add(segPivot);
    const radius = 0.06 - i * 0.01;
    const seg = mesh(new THREE.CapsuleGeometry(radius, segLen - radius, 6, 10), i === 1 ? stripeMat : furMat, `tailSeg_${i}`);
    seg.position.y = segLen / 2;
    segPivot.add(seg);
    tailSegments.push(segPivot);
    parent = segPivot;
  }
  const tailTip = mesh(new THREE.SphereGeometry(0.045, 12, 10), stripeMat, 'tailTip');
  tailTip.position.y = segLen + 0.01;
  parent.add(tailTip);

  // ---- Ground shadow blob (soft contact) ---------------------------------
  const shadowBlob = mesh(
    new THREE.CircleGeometry(0.42, 24),
    new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.28, depthWrite: false }),
    'shadowBlob',
    false,
  );
  shadowBlob.rotation.x = -Math.PI / 2;
  shadowBlob.position.y = 0.02;
  shadowBlob.scale.set(1, 1.3, 1);
  cat.add(shadowBlob);

  cat.scale.setScalar(CAT_SCALE * (0.92 + rng() * 0.16));

  // ---- Locomotion state --------------------------------------------------
  const route = buildRoute(index, rng);
  const startDist = rng() * route.length;
  const speed = 3.2 + rng() * 1.6;
  const sample = sampleRoute(route, startDist, { x: 0, z: 0, heading: 0 });
  cat.position.set(sample.x, 0, sample.z);
  cat.rotation.y = sample.heading;

  cat.userData = {
    isMoruCat: true,
    index,
    seed,
    furName: palette.name,
    route,
    distance: startDist,
    speed,
    heading: sample.heading,
    time: rng() * 10,
    gaitPhase: rng() * Math.PI * 2,
    hopTimer: 1.5 + rng() * 3,
    hopT: -1,
    hopHeight: 0,
    hopDuration: 0.5,
    flip: false,
    excitedT: -1,
    blinkTimer: 1 + rng() * 3,
    blinkT: -1,
    rng,
    parts: {
      body, torsoGroup, headPivot, ears, eyes, whiskers, bellPivot, helmetGroup,
      legs, tailRoot, tailSegments, shadowBlob,
    },
  };

  return cat;
}

// ---------------------------------------------------------------------------
// External triggers
// ---------------------------------------------------------------------------

export function exciteMoruCat(cat, strength = 1) {
  const u = cat?.userData;
  if (!u?.isMoruCat) return;
  u.hopT = 0;
  u.hopDuration = 0.75 + 0.15 * strength;
  u.hopHeight = 0.55 + 0.35 * strength;
  u.flip = u.rng() < 0.45;
  u.excitedT = 0;
}

// ---------------------------------------------------------------------------
// Per-frame update
// ---------------------------------------------------------------------------

const _sample = { x: 0, z: 0, heading: 0 };

function shortestAngle(a) {
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
}

export function updateMoruCat(cat, dt, elapsed) {
  const u = cat?.userData;
  if (!u?.isMoruCat || !(dt > 0)) return;
  const step = Math.min(dt, 0.1);
  const p = u.parts;
  u.time += step;
  const t = u.time;

  // Excited state speeds the cat up briefly
  let speedMul = 1;
  if (u.excitedT >= 0) {
    u.excitedT += step;
    speedMul = 1.6;
    if (u.excitedT > 2.5) u.excitedT = -1;
  }

  // ---- Travel along route ----
  u.distance += u.speed * speedMul * step;
  sampleRoute(u.route, u.distance, _sample);
  cat.position.x = _sample.x;
  cat.position.z = _sample.z;
  const dh = shortestAngle(_sample.heading - u.heading);
  u.heading += dh * Math.min(1, step * 8);
  cat.rotation.y = u.heading;

  // ---- Hops ----
  u.hopTimer -= step;
  if (u.hopT < 0 && u.hopTimer <= 0) {
    u.hopT = 0;
    u.hopDuration = 0.45 + u.rng() * 0.2;
    u.hopHeight = 0.18 + u.rng() * 0.2;
    u.flip = u.rng() < 0.12;
    if (u.flip) {
      u.hopDuration = 0.8;
      u.hopHeight = 0.7;
    }
    u.hopTimer = 2 + u.rng() * 4;
  }

  let hopY = 0;
  let flipAngle = 0;
  let airborne = false;
  if (u.hopT >= 0) {
    u.hopT += step;
    const k = Math.min(1, u.hopT / u.hopDuration);
    hopY = Math.sin(k * Math.PI) * u.hopHeight;
    airborne = true;
    if (u.flip) flipAngle = -k * Math.PI * 2;
    if (k >= 1) {
      u.hopT = -1;
      u.flip = false;
    }
  }

  // ---- Gait ----
  const gaitSpeed = 11 * speedMul;
  u.gaitPhase += step * gaitSpeed;
  const g = u.gaitPhase;
  const bob = Math.abs(Math.sin(g)) * 0.045;

  p.body.position.y = hopY + bob;
  p.body.rotation.x = flipAngle + (airborne ? -0.12 : Math.sin(g * 2) * 0.03);
  p.body.rotation.z = Math.sin(g) * 0.04;
  // keep flip centred on the torso
  if (flipAngle !== 0) {
    p.body.position.y += Math.sin(-flipAngle / 2) * 0.35;
  }

  for (const leg of p.legs) {
    if (airborne) {
      // tuck legs mid-air
      leg.pivot.rotation.x += ((leg.phase === 0 ? 0.7 : -0.6) - leg.pivot.rotation.x) * Math.min(1, step * 12);
    } else {
      leg.pivot.rotation.x = Math.sin(g + leg.phase) * 0.75;
    }
  }

  // Head bob / look-around
  p.headPivot.rotation.x = Math.sin(g * 2) * 0.05 + (airborne ? -0.15 : 0);
  p.headPivot.rotation.y = Math.sin(t * 0.7 + u.index) * 0.22;
  p.headPivot.rotation.z = Math.sin(t * 1.3) * 0.06;

  // Ear twitch
  const twitch = Math.max(0, Math.sin(t * 2.3 + u.index * 1.7)) ** 12;
  p.ears[0].rotation.x = -twitch * 0.5;
  p.ears[1].rotation.x = -(Math.max(0, Math.sin(t * 2.1 + u.index)) ** 12) * 0.5;

  // Whisker wiggle
  for (let i = 0; i < p.whiskers.length; i++) {
    const s = i < 2 ? -1 : 1;
    p.whiskers[i].rotation.y = -0.25 * s + Math.sin(t * 9 + i) * 0.06;
  }

  // Blinking
  u.blinkTimer -= step;
  if (u.blinkT < 0 && u.blinkTimer <= 0) {
    u.blinkT = 0;
    u.blinkTimer = 2 + u.rng() * 3.5;
  }
  let eyeScaleY = 1;
  if (u.blinkT >= 0) {
    u.blinkT += step;
    const k = u.blinkT / 0.16;
    eyeScaleY = Math.max(0.1, Math.abs(1 - 2 * Math.min(1, k)));
    if (k >= 1) u.blinkT = -1;
  }
  for (const eye of p.eyes) eye.scale.y = eyeScaleY;

  // Bell jingle
  p.bellPivot.rotation.x = Math.sin(g * 2) * 0.35;
  p.bellPivot.rotation.z = Math.sin(g * 1.3) * 0.2;

  // Tail wag (wave propagates down the segments)
  const wagSpeed = u.excitedT >= 0 ? 14 : 6;
  p.tailRoot.rotation.z = Math.sin(t * wagSpeed) * 0.45;
  p.tailRoot.rotation.x = -0.75 + Math.sin(t * wagSpeed * 0.5) * 0.12;
  for (let i = 0; i < p.tailSegments.length; i++) {
    const seg = p.tailSegments[i];
    seg.rotation.z = Math.sin(t * wagSpeed - (i + 1) * 0.8) * (0.35 + i * 0.1);
    if (i > 0) seg.rotation.x = 0.35 + Math.sin(t * 3 + i) * 0.1;
  }

  // Shadow blob shrinks when airborne
  const sh = 1 - Math.min(0.6, hopY * 0.6);
  p.shadowBlob.scale.set(sh, sh * 1.3, sh);
  p.shadowBlob.material.opacity = 0.28 * sh;

  // `elapsed` is accepted for API compatibility; internal time advances only by dt
  void elapsed;
}


