import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
import { createSkyTexture } from './world/textures.js';
import { buildCity } from './world/city.js';
import { MoruForge } from './world/forge.js';
import { createMoruCat, updateMoruCat, exciteMoruCat } from './entities/moruCat.js';

// ---------------------------------------------------------------------------
// Theme table: exposure, fog and bloom balanced so no theme blacks out
// (darkPct < 70%) or clips (brightPct < 5%) while keeping stdLum >= 30.
// ---------------------------------------------------------------------------
const THEMES = {
  night: {
    exposure: 1.15, bloom: 0.45, fog: 0x1a1830, fogDensity: 0.0065,
    hemiSky: 0x6a74c8, hemiGround: 0x2a1c26, hemi: 0.95,
    sun: 0x9fb2ff, sunIntensity: 0.85, sunPos: [-40, 60, 30], ambient: 0x2c2a44, ambientIntensity: 0.55,
  },
  gold: {
    exposure: 0.92, bloom: 0.25, fog: 0xc98a5e, fogDensity: 0.0048,
    hemiSky: 0xffd2a0, hemiGround: 0x5a3a2a, hemi: 0.75,
    sun: 0xffb070, sunIntensity: 1.7, sunPos: [70, 28, 40], ambient: 0x553a30, ambientIntensity: 0.3,
  },
  day: {
    exposure: 0.82, bloom: 0.18, fog: 0x9fc0dc, fogDensity: 0.0042,
    hemiSky: 0xcfe6ff, hemiGround: 0x5d6a4a, hemi: 0.7,
    sun: 0xfff3e0, sunIntensity: 1.9, sunPos: [50, 80, 35], ambient: 0x6b7480, ambientIntensity: 0.25,
  },
};

const CAMERA_PRESETS = {
  overview: { pos: [2, 26, 40], target: [0, 3.5, 0] },
  iso: { pos: [58, 58, 58], target: [0, 2, 0] },
  street: { pos: [6, 3.2, 34], target: [0, 4, 0] },
};

const params = new URLSearchParams(window.location.search);
const initialTheme = THEMES[params.get('theme')] ? params.get('theme') : 'night';

const state = {
  theme: initialTheme,
  cameraMode: 'overview',
  spinning: true,
  catCount: 0,
  forgeStrikes: 0,
  disposedCount: 0,
  frame: 0,
  fps: 60,
  elapsed: 0,
  followIndex: 0,
  buildingCount: 0,
  lampCount: 0,
  treeCount: 0,
  triangles: 0,
};

// --- Renderer / scene / camera ---------------------------------------------
const canvas = document.getElementById('studio-canvas');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, preserveDrawingBuffer: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 900);
camera.position.set(...CAMERA_PRESETS.overview.pos);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableRotate = true;
controls.enableZoom = true;
controls.enablePan = true;
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.autoRotate = true;
controls.autoRotateSpeed = 2.2;
controls.minDistance = 6;
controls.maxDistance = 220;
controls.maxPolarAngle = Math.PI * 0.49;
controls.target.set(0, 3.5, 0);
camera.lookAt(controls.target);
controls.update();

// --- Lighting ---------------------------------------------------------------
const hemi = new THREE.HemisphereLight(0xffffff, 0x222222, 1);
const ambient = new THREE.AmbientLight(0xffffff, 0.3);
const sun = new THREE.DirectionalLight(0xffffff, 1);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
Object.assign(sun.shadow.camera, { left: -90, right: 90, top: 90, bottom: -90, near: 1, far: 260 });
sun.shadow.bias = -0.0004;
scene.add(hemi, ambient, sun, sun.target);
scene.fog = new THREE.FogExp2(0x000000, 0.005);

// --- World ------------------------------------------------------------------
function attach(obj) {
  const node = obj?.isObject3D ? obj : (obj?.group ?? obj?.root ?? obj?.object3d);
  if (node?.isObject3D && !node.parent) scene.add(node);
}
const city = buildCity(scene, { theme: state.theme });
attach(city);
const forge = new MoruForge(scene);
attach(forge);
state.buildingCount = city?.buildingCount ?? city?.buildings?.length ?? 0;
state.lampCount = city?.lampCount ?? city?.lamps?.length ?? 0;
state.treeCount = city?.treeCount ?? city?.trees?.length ?? 0;

const cats = [];
function spawnCat() {
  const i = cats.length;
  const cat = createMoruCat(i, i + 1);
  scene.add(cat);
  cats.push(cat);
  state.catCount = cats.length;
  state.triangles = countTriangles();
  return cat;
}

function countTriangles() {
  let tris = 0;
  scene.traverse((o) => {
    if (!o.isMesh || !o.geometry) return;
    const g = o.geometry;
    const n = g.index ? g.index.count : (g.attributes.position?.count ?? 0);
    tris += (n / 3) * (o.isInstancedMesh ? o.count : 1);
  });
  return Math.round(tris);
}

// --- Post-processing ---------------------------------------------------------
const composer = new EffectComposer(renderer);
composer.setPixelRatio(renderer.getPixelRatio());
composer.setSize(window.innerWidth, window.innerHeight);
composer.addPass(new RenderPass(scene, camera));
const bloomPass = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 0.45, 0.55, 0.82);
bloomPass.threshold = 0.82;
composer.addPass(bloomPass);
composer.addPass(new OutputPass());

// --- Theme switching ---------------------------------------------------------
let skyTexture = null;
function applyTheme(name, { updateUrl = true } = {}) {
  const t = THEMES[name] ?? THEMES.night;
  state.theme = THEMES[name] ? name : 'night';
  if (skyTexture) {
    skyTexture.dispose();
    state.disposedCount++;
  }
  skyTexture = createSkyTexture(state.theme);
  scene.background = skyTexture;
  renderer.toneMappingExposure = t.exposure;
  bloomPass.strength = t.bloom;
  bloomPass.threshold = 0.82;
  scene.fog.color.set(t.fog);
  scene.fog.density = t.fogDensity;
  hemi.color.set(t.hemiSky);
  hemi.groundColor.set(t.hemiGround);
  hemi.intensity = t.hemi;
  ambient.color.set(t.ambient);
  ambient.intensity = t.ambientIntensity;
  sun.color.set(t.sun);
  sun.intensity = t.sunIntensity;
  sun.position.set(...t.sunPos);
  city?.setTheme?.(state.theme);
  forge?.setTheme?.(state.theme);
  for (const id of ['night', 'gold', 'day']) {
    document.getElementById(`mode-${id}`)?.classList.toggle('active', id === state.theme);
  }
  if (updateUrl) {
    const url = new URL(window.location.href);
    url.searchParams.set('theme', state.theme);
    window.history.replaceState(null, '', url);
  }
  if (!state.spinning) composer.render();
}

// --- Camera presets ------------------------------------------------------------
function setCameraPreset(name) {
  document.querySelectorAll('[id^="cam-"]').forEach((b) => b.classList.toggle('active', b.id === `cam-${name === 'follow' ? 'follow-cat' : name}`));
  state.cameraMode = name;
  if (name === 'follow') {
    controls.autoRotate = false;
    state.followIndex = (state.followIndex + 1) % Math.max(cats.length, 1);
    return;
  }
  const p = CAMERA_PRESETS[name];
  controls.autoRotate = true;
  camera.position.set(...p.pos);
  controls.target.set(...p.target);
  camera.lookAt(controls.target);
  controls.update();
  if (!state.spinning) composer.render();
}

const _followPos = new THREE.Vector3();
const _followLook = new THREE.Vector3();
function updateFollowCam(dt) {
  const cat = cats[state.followIndex % cats.length];
  if (!cat) return;
  const heading = cat.rotation.y;
  _followPos.set(cat.position.x - Math.sin(heading) * 9, cat.position.y + 5.5, cat.position.z - Math.cos(heading) * 9);
  _followLook.set(cat.position.x, cat.position.y + 2, cat.position.z);
  const k = 1 - Math.exp(-dt * 3.5);
  camera.position.lerp(_followPos, k);
  controls.target.lerp(_followLook, k);
}

// --- UI wiring ------------------------------------------------------------------
const $ = (id) => document.getElementById(id);
$('cam-overview').addEventListener('click', () => setCameraPreset('overview'));
$('cam-iso').addEventListener('click', () => setCameraPreset('iso'));
$('cam-street').addEventListener('click', () => setCameraPreset('street'));
$('cam-follow-cat').addEventListener('click', () => setCameraPreset('follow'));
$('mode-night').addEventListener('click', () => applyTheme('night'));
$('mode-gold').addEventListener('click', () => applyTheme('gold'));
$('mode-day').addEventListener('click', () => applyTheme('day'));
$('btn-spawn-cat').addEventListener('click', () => spawnCat());
$('btn-forge-strike').addEventListener('click', () => {
  forge.strike();
  for (const c of cats) exciteMoruCat(c);
  state.forgeStrikes++;
});
const spinBtn = $('toggle-spin');
spinBtn.addEventListener('click', () => {
  state.spinning = !state.spinning;
  spinBtn.textContent = state.spinning ? 'Pause' : 'Resume';
  spinBtn.classList.toggle('active', !state.spinning);
  lastTime = performance.now();
});

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  composer.setSize(window.innerWidth, window.innerHeight);
  bloomPass.setSize(window.innerWidth, window.innerHeight);
  if (!state.spinning) composer.render();
});

// --- Boot -------------------------------------------------------------------------
for (let i = 0; i < 8; i++) spawnCat();
applyTheme(state.theme, { updateUrl: params.has('theme') });
state.triangles = countTriangles();

const hud = $('fps-hud');
let lastTime = performance.now();
let hudTimer = 0;
let fpsFrames = 0;

function updateHud() {
  hud.textContent =
    `FPS        ${state.fps.toFixed(0)}\n` +
    `Theme      ${state.theme}  ·  Cam ${state.cameraMode}\n` +
    `Cats       ${state.catCount}\n` +
    `Buildings  ${state.buildingCount}  ·  Lamps ${state.lampCount}\n` +
    `Triangles  ${(state.triangles / 1000).toFixed(1)}k tris\n` +
    `Strikes    ${state.forgeStrikes}\n` +
    `Frame      ${state.frame}`;
}

function animate() {
  requestAnimationFrame(animate);
  if (!state.spinning) return; // frozen: no sim, camera, controls, HUD or redraw

  const now = performance.now();
  const dt = Math.min((now - lastTime) / 1000, 0.05);
  lastTime = now;
  state.elapsed += dt;
  state.frame++;

  forge.update?.(dt, state.elapsed);
  city?.update?.(dt, state.elapsed);
  for (const c of cats) updateMoruCat(c, dt, state.elapsed);

  if (state.cameraMode === 'follow') updateFollowCam(dt);
  controls.update();

  composer.render(dt);

  fpsFrames++;
  hudTimer += dt;
  if (hudTimer >= 0.4) {
    state.fps = fpsFrames / hudTimer;
    fpsFrames = 0;
    hudTimer = 0;
    updateHud();
  }
}

updateHud();
window.__app = { scene, camera, renderer, composer, state, controls, forge, city, cats };
animate();


