import * as THREE from 'three';
import { createWindowTexture, createRoadTexture, createLightPoolTexture } from './textures.js';

// ---------------------------------------------------------------------------
// Neon city
//  - buildCity(scene): ground, paved road grid + crosswalks, multi-tier
//    skyscrapers (neon trims, helipads, spires), stylized trees, streetlamps.
//  - The central plaza (radius < 35) is kept completely open.
// ---------------------------------------------------------------------------

const GRID = 40;
const ROAD_W = 8;
const ROADS = [-160, -120, -80, -40, 0, 40, 80, 120, 160];
const CENTERS = [-140, -100, -60, -20, 20, 60, 100, 140];
const PLAZA_R = 35;
const SPAN = 330;

const THEMES = {
  night: { ground: 0x15181f, slab: 0x2a2e38, plaza: 0x323848, neon: [0xff3df5, 0x3df5ff, 0xffd23d, 0x7cff6a], window: 1.4, bulb: 0xfff1b0, bulbI: 2.2, pool: 0.85 },
  dusk: { ground: 0x2a2230, slab: 0x4a4050, plaza: 0x5a4c60, neon: [0xff7ad9, 0x7af0ff, 0xffb347, 0xb4ff7a], window: 0.8, bulb: 0xffd59a, bulbI: 1.4, pool: 0.5 },
  day: { ground: 0x5d6b52, slab: 0x9a9ea6, plaza: 0xc9c2b4, neon: [0xd94fc4, 0x3fb8c9, 0xd9a93f, 0x6fc95a], window: 0.12, bulb: 0xfff7e0, bulbI: 0.2, pool: 0.08 },
};

function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function triCount(geo) {
  return geo.index ? geo.index.count / 3 : geo.attributes.position.count / 3;
}

export function buildCity(scene) {
  const rand = mulberry32(20261024);
  const group = new THREE.Group();
  group.name = 'city';
  const buildings = [];
  const lamps = [];
  const trees = [];

  // ---- shared materials -------------------------------------------------
  const groundMat = new THREE.MeshStandardMaterial({ color: THEMES.night.ground, roughness: 1 });
  const slabMat = new THREE.MeshStandardMaterial({ color: THEMES.night.slab, roughness: 0.9 });
  const plazaMat = new THREE.MeshStandardMaterial({ color: THEMES.night.plaza, roughness: 0.8 });
  const roadTex = createRoadTexture();
  if (roadTex) {
    roadTex.wrapS = roadTex.wrapT = THREE.RepeatWrapping;
    roadTex.repeat.set(1, SPAN / 8);
  }
  const roadMat = new THREE.MeshStandardMaterial({ map: roadTex || null, color: 0xffffff, roughness: 0.85 });
  const stripeMat = new THREE.MeshBasicMaterial({ color: 0xf2f2f2 });
  const roofMat = new THREE.MeshStandardMaterial({ color: 0x3a3f4a, roughness: 0.7, metalness: 0.3 });
  const padMat = new THREE.MeshStandardMaterial({ color: 0x2b2f36, roughness: 0.6 });
  const markMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const neonMats = THEMES.night.neon.map((c) => new THREE.MeshBasicMaterial({ color: c }));
  const windowMats = [];
  for (let i = 0; i < 8; i++) {
    const tex = createWindowTexture(i);
    if (tex) {
      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
      tex.repeat.set(1 + (i % 2), 2 + (i % 3));
    }
    const hue = (0.55 + i * 0.06) % 1;
    windowMats.push(new THREE.MeshStandardMaterial({
      color: new THREE.Color().setHSL(hue, 0.15, 0.45),
      map: tex || null,
      emissive: new THREE.Color().setHSL((0.1 + i * 0.07) % 1, 0.6, 0.6),
      emissiveMap: tex || null,
      emissiveIntensity: THEMES.night.window,
      roughness: 0.4,
      metalness: 0.5,
    }));
  }
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x5a3b24, roughness: 1 });
  const leafMats = [0x2f8f4e, 0x3fae5a, 0x267a52].map((c) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.9 }));
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x2c3038, metalness: 0.6, roughness: 0.4 });
  const bulbMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: THEMES.night.bulb, emissiveIntensity: THEMES.night.bulbI });
  const poolMat = new THREE.MeshBasicMaterial({
    map: createLightPoolTexture() || null, color: 0xffe2a0, transparent: true,
    opacity: THEMES.night.pool, depthWrite: false, blending: THREE.AdditiveBlending,
  });

  // ---- shared geometries ------------------------------------------------
  const boxGeo = new THREE.BoxGeometry(1, 1, 1);
  const padGeo = new THREE.CylinderGeometry(1, 1, 0.2, 24);
  const spireGeo = new THREE.ConeGeometry(1, 1, 12);
  const beaconGeo = new THREE.SphereGeometry(0.4, 12, 10);
  const leafGeo = new THREE.SphereGeometry(1.1, 12, 10);
  const trunkGeo = new THREE.CylinderGeometry(0.25, 0.35, 2, 8);
  const poleGeo = new THREE.CylinderGeometry(0.12, 0.16, 5, 8);
  const bulbGeo = new THREE.SphereGeometry(0.35, 12, 10);
  const poolGeo = new THREE.PlaneGeometry(9, 9).rotateX(-Math.PI / 2);

  const mesh = (geo, mat, parent, x, y, z, sx = 1, sy = 1, sz = 1, shadow = true) => {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(x, y, z);
    m.scale.set(sx, sy, sz);
    m.castShadow = shadow;
    m.receiveShadow = shadow;
    parent.add(m);
    return m;
  };

  // ---- ground, blocks, plaza --------------------------------------------
  const ground = mesh(new THREE.PlaneGeometry(420, 420).rotateX(-Math.PI / 2), groundMat, group, 0, 0, 0);
  ground.castShadow = false;
  for (const bx of CENTERS) {
    for (const bz of CENTERS) mesh(boxGeo, slabMat, group, bx, 0.1, bz, GRID - ROAD_W, 0.2, GRID - ROAD_W).castShadow = false;
  }
  const plaza = mesh(new THREE.CircleGeometry(PLAZA_R - 1, 48).rotateX(-Math.PI / 2), plazaMat, group, 0, 0.24, 0);
  plaza.castShadow = false;

  // ---- road grid + crosswalks ---------------------------------------------
  const roadGeo = new THREE.PlaneGeometry(ROAD_W, SPAN).rotateX(-Math.PI / 2);
  for (const r of ROADS) {
    mesh(roadGeo, roadMat, group, r, 0.02, 0).castShadow = false;
    const xr = mesh(roadGeo, roadMat, group, 0, 0.025, r);
    xr.rotation.y = Math.PI / 2;
    xr.castShadow = false;
  }
  const stripeGeo = new THREE.PlaneGeometry(0.5, 2).rotateX(-Math.PI / 2);
  const crossings = [];
  for (const rx of ROADS) for (const rz of ROADS) if (Math.hypot(rx, rz) >= PLAZA_R) crossings.push([rx, rz]);
  const stripes = new THREE.InstancedMesh(stripeGeo, stripeMat, crossings.length * 4 * 6);
  const dummy = new THREE.Object3D();
  let si = 0;
  for (const [rx, rz] of crossings) {
    for (const side of [-1, 1]) {
      for (let k = 0; k < 6; k++) {
        const off = -2.75 + k * 1.1;
        dummy.rotation.set(0, 0, 0);
        dummy.position.set(rx + off, 0.04, rz + side * 5.5);
        dummy.updateMatrix();
        stripes.setMatrixAt(si++, dummy.matrix);
        dummy.rotation.set(0, Math.PI / 2, 0);
        dummy.position.set(rx + side * 5.5, 0.04, rz + off);
        dummy.updateMatrix();
        stripes.setMatrixAt(si++, dummy.matrix);
      }
    }
  }
  stripes.instanceMatrix.needsUpdate = true;
  group.add(stripes);

  // ---- skyscrapers --------------------------------------------------------
  const LOTS = [[-7, -7], [7, -7], [-7, 7], [7, 7]];
  CENTERS.forEach((bx, i) => CENTERS.forEach((bz, j) => {
    const skip = Math.floor(rand() * 4);
    LOTS.forEach(([ox, oz], li) => {
      const x = bx + ox, z = bz + oz;
      if (li === skip || Math.hypot(x, z) < PLAZA_R) return;
      const b = new THREE.Group();
      b.position.set(x, 0.2, z);
      const h = 12 + rand() * 56;
      const tiers = h > 42 ? 3 : h > 24 ? 2 : 1;
      const shares = tiers === 3 ? [0.55, 0.3, 0.15] : tiers === 2 ? [0.65, 0.35] : [1];
      const mat = windowMats[(i * 8 + j + li + Math.floor(rand() * 8)) % 8];
      let w = 6.5 + rand() * 2.5, d = 6.5 + rand() * 2.5, y = 0;
      for (const s of shares) {
        const th = h * s;
        mesh(boxGeo, mat, b, 0, y + th / 2, 0, w, th, d);
        mesh(boxGeo, roofMat, b, 0, y + th + 0.1, 0, w + 0.2, 0.2, d + 0.2);
        y += th;
        w *= 0.74; d *= 0.74;
      }
      w /= 0.74; d /= 0.74;
      // rooftop neon trim frame
      const neon = neonMats[Math.floor(rand() * neonMats.length)];
      const ty = y + 0.35;
      mesh(boxGeo, neon, b, 0, ty, d / 2 + 0.15, w + 0.5, 0.22, 0.22, false);
      mesh(boxGeo, neon, b, 0, ty, -d / 2 - 0.15, w + 0.5, 0.22, 0.22, false);
      mesh(boxGeo, neon, b, w / 2 + 0.15, ty, 0, 0.22, 0.22, d + 0.5, false);
      mesh(boxGeo, neon, b, -w / 2 - 0.15, ty, 0, 0.22, 0.22, d + 0.5, false);
      let feature = 'roof';
      if (h > 46 || (h > 30 && rand() < 0.4)) {
        feature = 'spire';
        const sh = 4 + rand() * 8;
        mesh(spireGeo, roofMat, b, 0, y + 0.2 + sh / 2, 0, 0.6, sh, 0.6);
        mesh(beaconGeo, neon, b, 0, y + 0.4 + sh, 0, 1, 1, 1, false);
      } else if (rand() < 0.55) {
        feature = 'helipad';
        const r = Math.min(w, d) * 0.4;
        mesh(padGeo, padMat, b, 0, y + 0.3, 0, r, 1, r);
        mesh(boxGeo, markMat, b, -r * 0.3, y + 0.42, 0, 0.25, 0.05, r * 0.9, false);
        mesh(boxGeo, markMat, b, r * 0.3, y + 0.42, 0, 0.25, 0.05, r * 0.9, false);
        mesh(boxGeo, markMat, b, 0, y + 0.42, 0, r * 0.6, 0.05, 0.25, false);
      } else {
        mesh(boxGeo, roofMat, b, w * 0.15, y + 0.9, -d * 0.1, w * 0.35, 1.4, d * 0.3);
      }
      b.userData = { height: h, tiers, feature };
      group.add(b);
      buildings.push(b);
    });
  }));

  // ---- trees (two diagonal corners per block) ----------------------------
  CENTERS.forEach((bx, i) => CENTERS.forEach((bz, j) => {
    const corners = (i + j) % 2 ? [[-1, -1], [1, 1]] : [[1, -1], [-1, 1]];
    for (const [cx, cz] of corners) {
      const x = bx + cx * 14.3, z = bz + cz * 14.3;
      if (Math.hypot(x, z) < PLAZA_R + 2) continue;
      const t = new THREE.Group();
      t.position.set(x, 0.2, z);
      mesh(trunkGeo, trunkMat, t, 0, 1, 0, 1, 1, 1, false);
      const leaf = leafMats[Math.floor(rand() * leafMats.length)];
      const puffs = [[0, 2.7, 0, 1.3], [0.7, 2.3, 0.3, 0.95], [-0.6, 2.4, -0.4, 1.0], [0.1, 3.5, 0.1, 0.85]];
      for (const [px, py, pz, s] of puffs) mesh(leafGeo, leaf, t, px, py, pz, s, s, s, false);
      t.rotation.y = rand() * Math.PI * 2;
      group.add(t);
      trees.push(t);
    }
  }));

  // ---- streetlamps ----------------------------------------------------------
  const addLamp = (x, z, ax, az) => {
    if (Math.hypot(x, z) < PLAZA_R + 2) return;
    const l = new THREE.Group();
    l.position.set(x, 0.2, z);
    mesh(poleGeo, poleMat, l, 0, 2.5, 0, 1, 1, 1, false);
    const arm = mesh(boxGeo, poleMat, l, ax * 0.6, 4.95, az * 0.6, ax ? 1.3 : 0.12, 0.12, az ? 1.3 : 0.12, false);
    arm.castShadow = false;
    mesh(bulbGeo, bulbMat, l, ax * 1.2, 4.75, az * 1.2, 1, 1, 1, false);
    const pool = mesh(poolGeo, poolMat, l, ax * 1.2, 0.03, az * 1.2, 1, 1, 1, false);
    pool.receiveShadow = false;
    pool.renderOrder = 1;
    group.add(l);
    lamps.push(l);
  };
  ROADS.forEach((r) => CENTERS.forEach((c, k) => {
    const side = k % 2 ? 1 : -1;
    addLamp(r + side * 5.6, c, -side, 0);
    addLamp(c, r - side * 5.6, 0, side);
  }));

  scene.add(group);

  let triangles = 0;
  group.traverse((o) => {
    if (o.isMesh) triangles += triCount(o.geometry) * (o.isInstancedMesh ? o.count : 1);
  });

  let theme = 'night';
  function setTheme(themeName) {
    const t = THEMES[themeName] || THEMES.night;
    theme = THEMES[themeName] ? themeName : 'night';
    groundMat.color.setHex(t.ground);
    slabMat.color.setHex(t.slab);
    plazaMat.color.setHex(t.plaza);
    neonMats.forEach((m, i) => m.color.setHex(t.neon[i % t.neon.length]));
    windowMats.forEach((m) => { m.emissiveIntensity = t.window; });
    bulbMat.emissive.setHex(t.bulb);
    bulbMat.emissiveIntensity = t.bulbI;
    poolMat.opacity = t.pool;
    return theme;
  }

  return {
    group,
    buildings,
    lamps,
    trees,
    counts: { buildings: buildings.length, lamps: lamps.length, trees: trees.length, triangles },
    setTheme,
    get theme() { return theme; },
  };
}


