import * as THREE from 'three';
import { createRuneTexture } from './textures.js';

const THEMES = {
  night: { rune: 0x66e0ff, holoA: 0x00f0ff, holoB: 0xff3cf2, hearth: 3.2, emissive: 1.6, brazier: 1.4 },
  gold: { rune: 0xffc861, holoA: 0xffb347, holoB: 0xff5fa2, hearth: 2.4, emissive: 1.1, brazier: 1.0 },
  day: { rune: 0x8ad8ff, holoA: 0x3fb8ff, holoB: 0xd86bff, hearth: 1.4, emissive: 0.6, brazier: 0.5 },
};

class ForgeHammer {
  constructor() {
    this.group = new THREE.Group();
    this.pivot = new THREE.Group();
    this.group.add(this.pivot);
    const wood = new THREE.MeshStandardMaterial({ color: 0x5a3a22, roughness: 0.8 });
    const steel = new THREE.MeshStandardMaterial({ color: 0x8892a0, metalness: 0.9, roughness: 0.3 });
    const handle = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.1, 2.4, 12), wood);
    handle.rotation.z = Math.PI / 2;
    handle.position.x = 1.2;
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.55, 0.9, 2, 2, 2), steel);
    head.position.x = 2.4;
    const face = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.3, 0.12, 20), steel);
    face.position.set(2.4, -0.33, 0);
    const band = new THREE.Mesh(new THREE.TorusGeometry(0.12, 0.03, 8, 16), steel);
    band.rotation.y = Math.PI / 2;
    band.position.x = 2.1;
    [handle, head, face, band].forEach((m) => { m.castShadow = true; this.pivot.add(m); });
    this.angle = 0.9;
    this.swing = 0;
  }
  slam() { this.swing = 1; }
  update(dt) {
    if (this.swing > 0) {
      this.swing = Math.max(0, this.swing - dt * 2.2);
      const t = 1 - this.swing;
      this.angle = t < 0.25 ? 0.9 - (t / 0.25) * 0.9 : ((t - 0.25) / 0.75) * 0.9;
    } else {
      this.angle += (0.9 + Math.sin(performance.now() * 0.002) * 0.05 - this.angle) * Math.min(1, dt * 4);
    }
    this.pivot.rotation.z = this.angle;
  }
}

export class MoruForge {
  constructor(scene) {
    this.scene = scene;
    this.group = new THREE.Group();
    this.group.name = 'MoruForge';
    scene.add(this.group);
    this.autoTimer = 0;
    this.strikes = 0;
    this.shockwaves = [];
    this.braziers = [];

    // Octagonal 3-tier stone dais
    const stone = new THREE.MeshStandardMaterial({ color: 0x4a4c56, roughness: 0.85, metalness: 0.1 });
    const trim = new THREE.MeshStandardMaterial({ color: 0x2c2e36, roughness: 0.6, metalness: 0.4 });
    [[14, 0.6], [11, 0.6], [8, 0.6]].forEach(([r, h], i) => {
      const tier = new THREE.Mesh(new THREE.CylinderGeometry(r, r + 0.4, h, 8, 2), stone);
      tier.position.y = h / 2 + i * h;
      tier.rotation.y = Math.PI / 8;
      tier.receiveShadow = tier.castShadow = true;
      const edge = new THREE.Mesh(new THREE.CylinderGeometry(r + 0.05, r + 0.05, 0.08, 8, 1, true), trim);
      edge.position.y = (i + 1) * h;
      edge.rotation.y = Math.PI / 8;
      this.group.add(tier, edge);
    });
    this.topY = 1.8;

    // Glowing rune ring floor
    const runeTex = createRuneTexture();
    this.runeMat = new THREE.MeshBasicMaterial({
      map: runeTex || null, color: 0x66e0ff, transparent: true, opacity: 0.9,
      blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
    });
    this.rune = new THREE.Mesh(new THREE.RingGeometry(3.2, 7.6, 96, 2), this.runeMat);
    this.rune.rotation.x = -Math.PI / 2;
    this.rune.position.y = this.topY + 0.02;
    this.group.add(this.rune);

    // Molten magma hearth
    const hearthBase = new THREE.Mesh(new THREE.CylinderGeometry(1.9, 2.2, 0.7, 24), trim);
    hearthBase.position.set(-3.6, this.topY + 0.35, 0);
    hearthBase.castShadow = true;
    this.magmaMat = new THREE.MeshStandardMaterial({ color: 0xff5a14, emissive: 0xff3a00, emissiveIntensity: 2.2, roughness: 0.4 });
    this.magma = new THREE.Mesh(new THREE.CylinderGeometry(1.6, 1.6, 0.12, 32), this.magmaMat);
    this.magma.position.set(-3.6, this.topY + 0.72, 0);
    this.hearthLight = new THREE.PointLight(0xff6a20, 3.2, 22, 1.6);
    this.hearthLight.position.set(-3.6, this.topY + 1.6, 0);
    this.group.add(hearthBase, this.magma, this.hearthLight);

    // Detailed anvil
    const iron = new THREE.MeshStandardMaterial({ color: 0x3a3d44, metalness: 0.85, roughness: 0.35 });
    const anvil = new THREE.Group();
    const base = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.4, 1.3), iron);
    base.position.y = 0.2;
    const waist = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.6, 0.7, 8), iron);
    waist.position.y = 0.75;
    const top = new THREE.Mesh(new THREE.BoxGeometry(2.0, 0.42, 0.85), iron);
    top.position.y = 1.31;
    const horn = new THREE.Mesh(new THREE.ConeGeometry(0.4, 1.2, 16), iron);
    horn.rotation.z = Math.PI / 2;
    horn.position.set(1.6, 1.36, 0);
    const heel = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.3, 0.6), iron);
    heel.position.set(-1.2, 1.38, 0);
    [base, waist, top, horn, heel].forEach((m) => { m.castShadow = m.receiveShadow = true; anvil.add(m); });
    this.ingotMat = new THREE.MeshStandardMaterial({ color: 0xffa040, emissive: 0xff6010, emissiveIntensity: 2.0, metalness: 0.3, roughness: 0.4 });
    this.ingot = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.14, 0.3), this.ingotMat);
    this.ingot.position.set(0.1, 1.6, 0);
    anvil.add(this.ingot);
    anvil.position.y = this.topY;
    this.group.add(anvil);
    this.anvilTop = new THREE.Vector3(0.1, this.topY + 1.65, 0);

    // Animated hammer
    this.hammer = new ForgeHammer();
    this.hammer.group.position.set(-2.3, this.topY + 2.0, 0);
    this.group.add(this.hammer.group);

    // Counter-rotating neon holo-rings
    this.holoMatA = new THREE.MeshBasicMaterial({ color: 0x00f0ff, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false });
    this.holoMatB = this.holoMatA.clone();
    this.holoMatB.color.set(0xff3cf2);
    this.holoA = new THREE.Mesh(new THREE.TorusGeometry(2.6, 0.05, 12, 128), this.holoMatA);
    this.holoB = new THREE.Mesh(new THREE.TorusGeometry(3.2, 0.04, 12, 128), this.holoMatB);
    this.holoA.position.set(0, this.topY + 4.2, 0);
    this.holoB.position.set(0, this.topY + 4.6, 0);
    this.holoA.rotation.x = this.holoB.rotation.x = Math.PI / 2;
    this.group.add(this.holoA, this.holoB);

    // 8 perimeter braziers
    const flameGeo = new THREE.ConeGeometry(0.28, 0.8, 12);
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2 + Math.PI / 8;
      const b = new THREE.Group();
      const post = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.28, 1.6, 10), trim);
      post.position.y = 0.8;
      const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.3, 0.35, 14), iron);
      bowl.position.y = 1.75;
      post.castShadow = bowl.castShadow = true;
      const mat = new THREE.MeshStandardMaterial({ color: 0xffa040, emissive: 0xff5a10, emissiveIntensity: 1.4, transparent: true, opacity: 0.9 });
      const flame = new THREE.Mesh(flameGeo, mat);
      flame.position.y = 2.3;
      b.add(post, bowl, flame);
      b.position.set(Math.cos(a) * 12.4, 1.2, Math.sin(a) * 12.4);
      this.group.add(b);
      this.braziers.push({ flame, mat, phase: i * 1.3 });
    }

    // Shockwave ring pool
    this.shockGeo = new THREE.RingGeometry(0.85, 1.0, 64);
    for (let i = 0; i < 4; i++) {
      const mat = new THREE.MeshBasicMaterial({ color: 0xffc070, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
      const ring = new THREE.Mesh(this.shockGeo, mat);
      ring.rotation.x = -Math.PI / 2;
      ring.position.y = this.topY + 0.05;
      ring.visible = false;
      ring.castShadow = false;
      this.group.add(ring);
      this.shockwaves.push({ ring, mat, life: 0 });
    }

    // 160 spark particles
    this.sparkCount = 160;
    this.sparkPos = new Float32Array(this.sparkCount * 3);
    this.sparkVel = new Float32Array(this.sparkCount * 3);
    this.sparkLife = new Float32Array(this.sparkCount);
    for (let i = 0; i < this.sparkCount; i++) this.resetEmber(i, Math.random() * 3);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.sparkPos, 3));
    this.sparkMat = new THREE.PointsMaterial({ color: 0xffb050, size: 0.18, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false });
    this.sparks = new THREE.Points(geo, this.sparkMat);
    this.sparks.castShadow = false;
    this.sparks.receiveShadow = false;
    this.sparks.frustumCulled = false;
    this.group.add(this.sparks);

    this.setTheme('night');
  }

  resetEmber(i, life = 1.5 + Math.random() * 1.5) {
