// ====== src/main.js (18887 bytes) ======
import * as THREE from 'three';

// ---------- helpers ----------
let seed = 1337;
const rand = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
const rr = (a, b) => a + rand() * (b - a);
const $ = (id) => document.getElementById(id);

// ---------- renderer / scene ----------
const container = $('app');
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = false;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
container.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x070816);
scene.fog = new THREE.Fog(0x070816, 60, 220);

const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 600);
camera.position.set(0, 70, 95);

const hemi = new THREE.HemisphereLight(0x6677ff, 0x221133, 0.5);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0x8899ff, 0.6);
sun.position.set(40, 80, 30);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
Object.assign(sun.shadow.camera, { left: -90, right: 90, top: 90, bottom: -90, near: 1, far: 250 });
scene.add(sun);
const forgeLight = new THREE.PointLight(0xff7a1a, 40, 60, 1.6);
forgeLight.position.set(0, 4, 0);
scene.add(forgeLight);

// ---------- ground & roads ----------
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(400, 400),
  new THREE.MeshStandardMaterial({ color: 0x10131f, roughness: 1 })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

const roadMat = new THREE.MeshStandardMaterial({ color: 0x1b1d2a, roughness: 0.8 });
const lineMat = new THREE.MeshBasicMaterial({ color: 0x33e6ff });
const ROAD_W = 8;
const roadPositions = [-48, 0, 48];
function addRoad(w, d, x, z) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, 0.2, d), roadMat);
  m.position.set(x, 0.1, z);
  m.receiveShadow = true;
  scene.add(m);
  const l = new THREE.Mesh(new THREE.BoxGeometry(w > d ? w : 0.3, 0.05, w > d ? 0.3 : d), lineMat);
  l.position.set(x, 0.24, z);
  scene.add(l);
}
roadPositions.forEach((p) => { addRoad(300, ROAD_W, 0, p); addRoad(ROAD_W, 300, p, 0); });

// ---------- plaza & forge ----------
const plaza = new THREE.Mesh(
  new THREE.CylinderGeometry(20, 21, 0.6, 48),
  new THREE.MeshStandardMaterial({ color: 0x2a2630, roughness: 0.6, metalness: 0.3 })
);
plaza.position.y = 0.3; plaza.receiveShadow = true;
scene.add(plaza);
const ring = new THREE.Mesh(
  new THREE.TorusGeometry(19, 0.25, 8, 64),
  new THREE.MeshBasicMaterial({ color: 0xff8a1f })
);
ring.rotation.x = Math.PI / 2; ring.position.y = 0.7;
scene.add(ring);

const forge = new THREE.Group();
const metal = new THREE.MeshStandardMaterial({ color: 0x3a3f4d, metalness: 0.9, roughness: 0.35 });
const base = new THREE.Mesh(new THREE.BoxGeometry(3, 1.6, 2), new THREE.MeshStandardMaterial({ color: 0x5a3b22, roughness: 0.9 }));
base.position.y = 0.8;
const anvilBody = new THREE.Mesh(new THREE.BoxGeometry(3.6, 0.9, 1.4), metal);
anvilBody.position.y = 2.05;
const anvilTop = new THREE.Mesh(new THREE.BoxGeometry(4.4, 0.35, 1.7), metal);
anvilTop.position.y = 2.7;
const horn = new THREE.Mesh(new THREE.ConeGeometry(0.7, 1.8, 16), metal);
horn.rotation.z = -Math.PI / 2; horn.position.set(3.1, 2.7, 0);
const hot = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.15, 0.5), new THREE.MeshStandardMaterial({ color: 0xff6a00, emissive: 0xff5500, emissiveIntensity: 2 }));
hot.position.y = 2.95;
[base, anvilBody, anvilTop, horn].forEach((m) => { m.castShadow = true; });
forge.add(base, anvilBody, anvilTop, horn, hot);
// hammer
const hammer = new THREE.Group();
const handle = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.1, 2.6, 8), new THREE.MeshStandardMaterial({ color: 0x7a4a22 }));
const head = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.6, 0.6), metal);
head.position.y = 1.4;
hammer.add(handle, head);
hammer.position.set(-1.2, 4.4, 0);
hammer.rotation.z = 0.9;
forge.add(hammer);
// furnace
const furnace = new THREE.Mesh(new THREE.CylinderGeometry(2, 2.4, 3.6, 16), new THREE.MeshStandardMaterial({ color: 0x4a2a22, roughness: 0.9 }));
furnace.position.set(-7, 1.8, -3); furnace.castShadow = true;
const fire = new THREE.Mesh(new THREE.SphereGeometry(1.3, 16, 12), new THREE.MeshBasicMaterial({ color: 0xff7a1a }));
fire.position.set(-7, 3.8, -3);
forge.add(furnace, fire);
forge.position.y = 0.6;
scene.add(forge);

// sparks
const SPARKS = 160;
const sparkGeo = new THREE.BufferGeometry();
const sparkPos = new Float32Array(SPARKS * 3);
const sparkVel = new Float32Array(SPARKS * 3);
const sparkLife = new Float32Array(SPARKS);
sparkGeo.setAttribute('position', new THREE.BufferAttribute(sparkPos, 3));
const sparks = new THREE.Points(sparkGeo, new THREE.PointsMaterial({ color: 0xffc060, size: 0.35, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending }));
sparks.frustumCulled = false;
scene.add(sparks);
for (let i = 0; i < SPARKS; i++) sparkPos[i * 3 + 1] = -100;

// ---------- buildings ----------
function windowTexture(color) {
  const c = document.createElement('canvas');
  c.width = 64; c.height = 128;
  const g = c.getContext('2d');
  g.fillStyle = '#0a0c18'; g.fillRect(0, 0, 64, 128);
  for (let y = 4; y < 124; y += 12) for (let x = 4; x < 60; x += 12) {
    if (rand() > 0.35) { g.fillStyle = color; g.fillRect(x, y, 7, 7); }
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
const neonColors = ['#33e6ff', '#ff3de0', '#ffb347', '#8a5bff', '#4dffa0'];
const winTextures = neonColors.map(windowTexture);
const buildingMats = [];
const buildings = [];
const blockCenters = [-72, -24, 24, 72];
for (const bx of blockCenters) for (const bz of blockCenters) {
  for (let i = 0; i < 3; i++) {
    const w = rr(6, 11), d = rr(6, 11), h = rr(10, 42) * (1 + (Math.abs(bx) + Math.abs(bz)) / 400);
