  const whiskerR = mesh(shared.whiskerGeo, shared.whisker, cat, [0.4, 1.28, 1.1]);
  whiskerL.rotation.y = 0.35; whiskerR.rotation.y = -0.35;
  const collar = mesh(new THREE.TorusGeometry(0.36, 0.055, 8, 20), shared.collar, cat, [0, 1.1, 0.66]);
  collar.rotation.x = Math.PI / 2 - 0.35;
  const bell = mesh(shared.sphere, shared.bell, cat, [0, 0.98, 0.98], [0.09, 0.09, 0.09]);
  const helmet = mesh(
    new THREE.SphereGeometry(0.5, 18, 10, 0, Math.PI * 2, 0, Math.PI / 2),
    shared.helmet, cat, [0, 1.6, 0.7]);
  helmet.scale.set(0.95, 0.7, 0.95);

  // articulated legs: origin at the hip so rotation.x swings the limb
  const hips = [[-0.25, 0.72, 0.42], [0.25, 0.72, 0.42], [-0.25, 0.72, -0.4], [0.25, 0.72, -0.4]];
  const legs = hips.map((h) => mesh(shared.limb, bodyMat, cat, h));

  // multi-segment tail
  const tail = [];
  for (let i = 0; i < 3; i++) {
    const seg = mesh(shared.tailSeg, bodyMat, cat, [0, 0.95 + i * 0.26, -0.78 - i * 0.12]);
    seg.rotation.x = -0.7 - i * 0.2;
    tail.push(seg);
  }

  cat.userData.parts = { torso, head, legs, tail, earL, earR };
  cat.userData.childMeshCount = cat.children.length;
  cat.scale.setScalar(1.5);
  return cat;
}

// Per-cat locomotion state (trot / hop / backflip around the plaza & avenues).
export function initCatMotion(cat, i, rand = Math.random) {
  cat.userData.motion = {
    radius: 13 + (i % 5) * 3.6 + rand() * 1.5,
    angle: rand() * Math.PI * 2,
    speed: (0.16 + rand() * 0.1) * (i % 2 ? -1 : 1),
    phase: rand() * 10,
    excite: 0,
    flip: 0,
    nextFlip: 4 + rand() * 8,
  };
}

export function triggerCatJump(cat) {
  cat.userData.motion.excite = 0.9;
}

export function updateCat(cat, dt, t) {
  const m = cat.userData.motion;
  const { legs, tail, head, earL, earR } = cat.userData.parts;
  m.angle += m.speed * dt;
  const a = m.angle;
  const dir = Math.sign(m.speed);

  let y = Math.abs(Math.sin(t * 8 + m.phase)) * 0.18;
  if (m.excite > 0) {
    m.excite = Math.max(0, m.excite - dt);
    y += Math.sin((1 - m.excite / 0.9) * Math.PI) * 2.2;
  }
  m.nextFlip -= dt;
  if (m.nextFlip <= 0 && m.flip <= 0) { m.flip = 0.9; m.nextFlip = 6 + Math.random() * 8; }
  let flipRot = 0;
  if (m.flip > 0) {
    m.flip = Math.max(0, m.flip - dt);
    const p = 1 - m.flip / 0.9;
    y += Math.sin(p * Math.PI) * 2.6;
    flipRot = -p * Math.PI * 2;
  }

  cat.position.set(Math.cos(a) * m.radius, y, Math.sin(a) * m.radius);
  const vx = -Math.sin(a) * dir, vz = Math.cos(a) * dir;
  cat.rotation.set(flipRot, Math.atan2(vx, vz), 0, 'YXZ');

  const sw = Math.sin(t * 10 + m.phase) * 0.8;
  legs[0].rotation.x = sw;
  legs[1].rotation.x = -sw;
  legs[2].rotation.x = -sw;
  legs[3].rotation.x = sw;
  for (let i = 0; i < tail.length; i++) {
    tail[i].rotation.z = Math.sin(t * 6 + m.phase - i * 0.9) * (0.35 + i * 0.12);
  }
  head.rotation.z = Math.sin(t * 3 + m.phase) * 0.06;
  earL.rotation.z = 0.25 + Math.sin(t * 5 + m.phase) * 0.08;
  earR.rotation.z = -0.25 - Math.sin(t * 5 + m.phase) * 0.08;
}


