import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import {
  makeWindowTexture,
  makeRoadTexture,
  makeCrosswalkTexture,
} from './textures.js';

const PITCH = 30;       // road lattice pitch
const ROAD_W = 8;
const PLAZA_R = 36;     // no buildings inside this radius
const EXTENT = 180;

function mulberry(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// distance from x to the nearest road centre line (roads at multiples of PITCH)
function roadDist(v) {
  const m = ((v % PITCH) + PITCH) % PITCH;
  return Math.min(m, PITCH - m);
}

const WINDOW_PALETTES = [
  ['#ffd27a', '#ffe9b0', '#ffb347'],
  ['#7fd8ff', '#b8ecff', '#5ab8ff'],
  ['#ff8ad8', '#ffc0ec', '#c86bff'],
  ['#9dffb0', '#d6ffd8', '#ffe27a'],
];

// scale side-face UVs so window cells keep a constant world size
function scaleBoxUVs(geo, w, h, d) {
  const uv = geo.attributes.uv;
  // BoxGeometry face order: +x, -x, +y, -y, +z, -z (4 verts each)
  const faces = [
    { start: 0, su: d / 16, sv: h / 32 },
    { start: 4, su: d / 16, sv: h / 32 },
    { start: 16, su: w / 16, sv: h / 32 },
    { start: 20, su: w / 16, sv: h / 32 },
  ];
  for (const f of faces) {
    for (let i = 0; i < 4; i++) {
      uv.setXY(f.start + i, uv.getX(f.start + i) * f.su, uv.getY(f.start + i) * f.sv);
    }
  }
  uv.needsUpdate = true;
}

// Collects static geometry per material and merges it into one mesh each,
// keeping draw calls low on software WebGL.
function makeBatcher(parent) {
  const buckets = new Map();
  const m4 = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const e = new THREE.Euler();
  return {
    add(geo, mat, pos, scale = 1, rot = null, opts = {}) {
      const g = geo.clone();
      e.set(rot ? rot[0] : 0, rot ? rot[1] : 0, rot ? rot[2] : 0);
      q.setFromEuler(e);
      const sc = typeof scale === 'number' ? [scale, scale, scale] : scale;
      m4.compose(new THREE.Vector3(...pos), q, new THREE.Vector3(...sc));
      g.applyMatrix4(m4);
      if (g.index) { /* keep indexed */ }
      let b = buckets.get(mat);
      if (!b) { b = { geos: [], opts }; buckets.set(mat, b); }
      b.geos.push(g);
    },
    flush() {
      for (const [mat, b] of buckets) {
        const merged = mergeGeometries(b.geos, false);
        const mesh = new THREE.Mesh(merged, mat);
        mesh.castShadow = !!b.opts.castShadow;
        mesh.receiveShadow = !!b.opts.receiveShadow;
        if (b.opts.isLampPool) mesh.userData.isLampPool = true;
        parent.add(mesh);
        b.geos.forEach((g) => g.dispose());
      }
      buckets.clear();
    },
  };
}

export function buildCity(scene, themeCfg) {
  const rand = mulberry(20240611);
  const group = new THREE.Group();
  group.name = 'city';
  scene.add(group);

  const stats = { buildings: 0, trees: 0, lamps: 0 };

  // ---- ground ----
  const groundMat = new THREE.MeshStandardMaterial({ color: 0x59606c, roughness: 0.95, metalness: 0.0 });
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(900, 900), groundMat);
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  group.add(ground);

  // ---- roads ----
  const roadTex = makeRoadTexture();
  roadTex.repeat.set(1, (EXTENT * 2) / 16);
  const roadMat = new THREE.MeshStandardMaterial({ map: roadTex, roughness: 0.85, metalness: 0.05 });
  const roadGeo = new THREE.PlaneGeometry(ROAD_W, EXTENT * 2);
  const roadBatch = makeBatcher(group);
  for (let k = -6; k <= 6; k++) {
    roadBatch.add(roadGeo, roadMat, [k * PITCH, 0.03, 0], 1, [-Math.PI / 2, 0, 0], { receiveShadow: true });
    roadBatch.add(roadGeo, roadMat, [0, 0.035, k * PITCH], 1, [-Math.PI / 2, 0, Math.PI / 2], { receiveShadow: true });
  }
  roadBatch.flush();
  // crosswalks next to the plaza intersections
  const cwTex = makeCrosswalkTexture();
  const cwMat = new THREE.MeshStandardMaterial({ map: cwTex, roughness: 0.85 });
  const cwGeo = new THREE.PlaneGeometry(ROAD_W, 4);
  const cwBatch = makeBatcher(group);
  for (let i = -3; i <= 3; i++) {
    for (let j = -3; j <= 3; j++) {
      if ((Math.abs(i) + Math.abs(j)) % 2 !== 0) continue;
      const x = i * PITCH, z = j * PITCH;
      if (Math.hypot(x, z) > 100) continue;
      cwBatch.add(cwGeo, cwMat, [x, 0.05, z + ROAD_W / 2 + 3], 1, [-Math.PI / 2, 0, 0]);
      cwBatch.add(cwGeo, cwMat, [x + ROAD_W / 2 + 3, 0.055, z], 1, [-Math.PI / 2, 0, Math.PI / 2]);
    }
  }
  cwBatch.flush();

  // ---- window textures (themed, regenerated on theme change) ----
  let windowTextures = [];
  const windowMats = [];
  const roofMat = new THREE.MeshStandardMaterial({ color: 0x3a4152, roughness: 0.8, metalness: 0.2 });
  const trimMats = [];

  function makeWindowSet(cfg) {
    return WINDOW_PALETTES.map((pal, i) => makeWindowTexture(101 + i * 17, cfg.litRatio, pal));
  }
  windowTextures = makeWindowSet(themeCfg);
  for (let i = 0; i < 4; i++) {
    windowMats.push(new THREE.MeshStandardMaterial({
      map: windowTextures[i],
      emissive: 0xffffff,
      emissiveMap: windowTextures[i],
      emissiveIntensity: themeCfg.windowEmissive,
      roughness: 0.55,
      metalness: 0.25,
    }));
  }

  // ---- buildings ----
  const trimColors = [0xff4fd8, 0x4fe8ff, 0xffb347, 0x8aff7a];
  trimColors.forEach((c) => {
    trimMats.push(new THREE.MeshStandardMaterial({
      color: c, emissive: c, emissiveIntensity: 1.1, roughness: 0.4,
    }));
  });
  const beaconMat = new THREE.MeshStandardMaterial({ color: 0xff3030, emissive: 0xff2020, emissiveIntensity: 1.4 });
  const padMat = new THREE.MeshStandardMaterial({ color: 0x2a2f3a, roughness: 0.7 });
  const padRingMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xffe08a, emissiveIntensity: 0.6 });

  const buildingSpots = [];
  for (let i = -5; i <= 5; i++) {
    for (let j = -5; j <= 5; j++) {
      const cx = i * PITCH + PITCH / 2;
      const cz = j * PITCH + PITCH / 2;
      if (Math.hypot(cx, cz) < PLAZA_R + 12) continue;
      buildingSpots.push([cx, cz]);
    }
  }
  // deterministic shuffle, keep up to 72
  for (let i = buildingSpots.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [buildingSpots[i], buildingSpots[j]] = [buildingSpots[j], buildingSpots[i]];
  }
  const spots = buildingSpots.slice(0, 72);

  const buildingBoxes = [];
  const trimBatch = makeBatcher(group);
  for (const [cx, cz] of spots) {
    const variant = Math.floor(rand() * 4);
    const dist = Math.hypot(cx, cz);
    const heightBias = Math.max(0.5, 1.5 - dist / 180);
    const tiers = 2 + Math.floor(rand() * 2);
    let baseW = 11 + rand() * 6;
    let baseD = 11 + rand() * 6;
    let y = 0;
    const totalH = (16 + rand() * 46) * heightBias;
    const g = new THREE.Group();
    g.position.set(cx, 0, cz);
    for (let t = 0; t < tiers; t++) {
      const h = t === 0 ? totalH * 0.55 : totalH * (0.45 / (tiers - 1)) * (1.0 - t * 0.1);
      const w = baseW * (1 - t * 0.22);
      const d = baseD * (1 - t * 0.22);
      const geo = new THREE.BoxGeometry(w, h, d);
      scaleBoxUVs(geo, w, h, d);
      const mat = [windowMats[variant], windowMats[variant], roofMat, roofMat, windowMats[variant], windowMats[variant]];
      const m = new THREE.Mesh(geo, mat);
      m.position.y = y + h / 2;
      m.castShadow = true;
      m.receiveShadow = true;
      g.add(m);
      // rooftop neon trim frame
      const trim = trimMats[(variant + t) % 4];
      const th = 0.35;
      const frame = [
        [w + 0.4, th, 0.4, 0, h / 2 + th / 2, d / 2],
        [w + 0.4, th, 0.4, 0, h / 2 + th / 2, -d / 2],
        [0.4, th, d + 0.4, w / 2, h / 2 + th / 2, 0],
        [0.4, th, d + 0.4, -w / 2, h / 2 + th / 2, 0],
      ];
      for (const f of frame) {
        trimBatch.add(new THREE.BoxGeometry(f[0], f[1], f[2]), trim, [cx + f[3], y + h / 2 + f[4], cz + f[5]]);
      }
      y += h;
      baseW = w;
      baseD = d;
    }
    // rooftop crown: helipad or spire
    if (rand() < 0.35) {
      const pad = new THREE.Mesh(new THREE.CylinderGeometry(Math.min(baseW, baseD) * 0.38, Math.min(baseW, baseD) * 0.38, 0.3, 20), padMat);
      pad.position.y = y + 0.15;
      g.add(pad);
