      spire.position.y = y + sh / 2;
      g.add(spire);
      const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.4, 10, 8), beaconMat);
      beacon.position.y = y + sh + 0.2;
      g.add(beacon);
