  // ---- streetlamps with ground light pools ----
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x2c313d, roughness: 0.6, metalness: 0.5 });
  const bulbMat = new THREE.MeshStandardMaterial({
    color: 0xfff0c8, emissive: 0xffd890, emissiveIntensity: themeCfg.lampEmissive, roughness: 0.4,
  });
  const poolMat = new THREE.MeshBasicMaterial({
    color: 0xffd890, transparent: true, opacity: themeCfg.poolOpacity, depthWrite: false,
  });
  poolMat.polygonOffset = true;
  poolMat.polygonOffsetFactor = -2;
  const poleGeo = new THREE.CylinderGeometry(0.1, 0.14, 5, 6);
  const armGeo = new THREE.BoxGeometry(1.1, 0.12, 0.12);
  const bulbGeo = new THREE.SphereGeometry(0.34, 10, 8);
  const poolGeo = new THREE.CircleGeometry(3.4, 24);
  const lampPositions = [];
  for (let k = -5; k <= 5; k++) {
    for (let s = -165; s <= 165; s += 30) {
      const off = ROAD_W / 2 + 1.4;
      // along x-roads (constant z=k*PITCH) and z-roads
      lampPositions.push([s + 7.5, k * PITCH + off, 1]);
      lampPositions.push([k * PITCH - off, s + 15, -1]);
    }
  }
  // keep ~120 lamps, nearest to centre first
  lampPositions.sort((a, b) => Math.hypot(a[0], a[1]) - Math.hypot(b[0], b[1]));
  const lampBatch = makeBatcher(group);
  const poolBatch = makeBatcher(group);
  for (const [x, z, dir] of lampPositions.slice(0, 120)) {
    lampBatch.add(poleGeo, poleMat, [x, 2.5, z]);
    lampBatch.add(armGeo, poleMat, [x + 0.5 * dir, 5, z]);
    lampBatch.add(bulbGeo, bulbMat, [x + 1.0 * dir, 4.8, z]);
    poolBatch.add(poolGeo, poolMat, [x + 1.0 * dir, 0.07, z], 1, [-Math.PI / 2, 0, 0], { isLampPool: true });
    stats.lamps++;
