  lampBatch.flush();
  poolBatch.flush();

  // ---- trees (multi-foliage) ----
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x6b4a2e, roughness: 0.9 });
  const leafMats = [0x2f8f4e, 0x3da35d, 0x5fb34a, 0x2a7d5a].map((c) =>
    new THREE.MeshStandardMaterial({ color: c, roughness: 0.8, flatShading: true }));
  const trunkGeo = new THREE.CylinderGeometry(0.28, 0.4, 3, 8);
  const leafGeo = new THREE.IcosahedronGeometry(1, 2);
  const treeSpots = [];
  // ring just outside the cat promenade, inside the plaza
  for (let i = 0; i < 40 && treeSpots.length < 22; i++) {
    const a = (i / 40) * Math.PI * 2 + 0.07;
    const r = 32.5 + (i % 2) * 2.2;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    if (roadDist(x) < 6 || roadDist(z) < 6) continue;
    treeSpots.push([x, z]);
  }
  let guard = 0;
  while (treeSpots.length < 84 && guard++ < 4000) {
    const x = (rand() - 0.5) * 2 * 150;
    const z = (rand() - 0.5) * 2 * 150;
    if (Math.hypot(x, z) < PLAZA_R + 2) continue;
    if (roadDist(x) < 6 || roadDist(z) < 6) continue;
    // keep out of building footprints (cell centres)
    let blocked = false;
    for (const b of buildingBoxes) {
      if (Math.abs(b.x - x) < 11 && Math.abs(b.z - z) < 11) { blocked = true; break; }
    }
    if (blocked) continue;
    treeSpots.push([x, z]);
  }
  const treeBatch = makeBatcher(group);
  for (const [x, z] of treeSpots) {
    const sc = 0.8 + rand() * 0.7;
    treeBatch.add(trunkGeo, trunkMat, [x, 1.5 * sc, z], sc, null, { castShadow: true });
    const lm = leafMats[Math.floor(rand() * leafMats.length)];
    const blobs = [
      [0, 4.0, 0, 2.0],
      [0.9, 3.4, 0.5, 1.4],
      [-0.8, 3.6, -0.5, 1.5],
    ];
    for (const [bx, by, bz, br] of blobs) {
      treeBatch.add(leafGeo, lm, [x + bx * sc, by * sc, z + bz * sc], br * sc, null, { castShadow: true });
    }
    stats.trees++;
  }
  treeBatch.flush();

  // ---- theme application ----
  function applyTheme(cfg) {
    let disposed = 0;
    const old = windowTextures;
    windowTextures = makeWindowSet(cfg);
    windowMats.forEach((m, i) => {
      m.map = windowTextures[i];
      m.emissiveMap = windowTextures[i];
      m.emissiveIntensity = cfg.windowEmissive;
      m.needsUpdate = true;
    });
    for (const t of old) { t.dispose(); disposed++; }
    bulbMat.emissiveIntensity = cfg.lampEmissive;
    poolMat.opacity = cfg.poolOpacity;
    groundMat.color.setHex(cfg.ground);
    return disposed;
  }
  groundMat.color.setHex(themeCfg.ground);

  return { group, stats, applyTheme, buildingBoxes };
}


// ====== src/world/forge.js (11083 bytes) ======
import * as THREE from 'three';
import { makeRuneTexture, makeGlowSpriteTexture } from './textures.js';

const DAIS_TOP = 1.5;
const EMBER_COUNT = 150;
const SPARK_COUNT = 90;
const SWING_TIME = 0.7;

export class MoruForge {
  constructor(scene) {
    this.group = new THREE.Group();
    this.group.name = 'moru-forge';
    scene.add(this.group);
    this.swingT = 0;
    this.impacted = true;
    this.time = 0;

    this._buildDais();
    this._buildAnvil();
    this._buildHearth();
    this._buildHammer();
    this._buildRings();
    this._buildParticles();
  }

  _buildDais() {
    const stone = new THREE.MeshStandardMaterial({ color: 0x8a8f9c, roughness: 0.85, metalness: 0.05 });
    const stoneDark = new THREE.MeshStandardMaterial({ color: 0x6d7280, roughness: 0.9 });
    const radii = [9.5, 8, 6.5];
    radii.forEach((r, i) => {
      const t = new THREE.Mesh(new THREE.CylinderGeometry(r, r + 0.35, 0.5, 40), i % 2 ? stoneDark : stone);
      t.position.y = 0.25 + i * 0.5;
      t.castShadow = true;
      t.receiveShadow = true;
      this.group.add(t);
    });
    // rune circle on the paving
    this.runeTex = makeRuneTexture();
    this.runeMat = new THREE.MeshBasicMaterial({
      map: this.runeTex, transparent: true, opacity: 0.85, depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    this.runes = new THREE.Mesh(new THREE.CircleGeometry(14, 48), this.runeMat);
    this.runes.rotation.x = -Math.PI / 2;
    this.runes.position.y = 0.09;
    this.group.add(this.runes);
    // stone pillars with glowing caps around the dais
    const pillarMat = new THREE.MeshStandardMaterial({ color: 0x7b8090, roughness: 0.8 });
    const capMat = new THREE.MeshStandardMaterial({ color: 0xffa040, emissive: 0xff7a18, emissiveIntensity: 1.3 });
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2 + Math.PI / 8;
      const p = new THREE.Mesh(new THREE.CylinderGeometry(0.45, 0.6, 3.4, 10), pillarMat);
      p.position.set(Math.cos(a) * 11.5, 1.7, Math.sin(a) * 11.5);
      p.castShadow = true;
      this.group.add(p);
      const c = new THREE.Mesh(new THREE.OctahedronGeometry(0.55, 0), capMat);
      c.position.set(p.position.x, 3.9, p.position.z);
      this.group.add(c);
    }
  }

  _buildAnvil() {
    const iron = new THREE.MeshStandardMaterial({ color: 0x4d5260, roughness: 0.35, metalness: 0.85 });
    const anvil = new THREE.Group();
    anvil.position.y = DAIS_TOP;
    const parts = [
      new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.6, 1.8), iron),   // base
      new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.9, 1.0), iron),   // waist
      new THREE.Mesh(new THREE.BoxGeometry(3.0, 0.6, 1.3), iron),   // face
      new THREE.Mesh(new THREE.ConeGeometry(0.62, 1.8, 12), iron),  // horn
      new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.5, 1.1), iron),   // heel
    ];
    parts[0].position.y = 0.3;
    parts[1].position.y = 1.05;
    parts[2].position.y = 1.8;
    parts[3].rotation.z = -Math.PI / 2;
    parts[3].position.set(2.35, 1.8, 0);
    parts[4].position.set(-1.75, 1.85, 0);
    parts.forEach((p) => { p.castShadow = true; anvil.add(p); });
    // heated ingot
    this.ingotMat = new THREE.MeshStandardMaterial({
      color: 0xff7a1a, emissive: 0xff5a10, emissiveIntensity: 1.6, roughness: 0.5,
    });
    const ingot = new THREE.Mesh(new THREE.BoxGeometry(1.1, 0.28, 0.55), this.ingotMat);
    ingot.position.set(0, 2.24, 0);
    anvil.add(ingot);
    this.anvilTopY = DAIS_TOP + 2.1;
    this.group.add(anvil);
    this.anvil = anvil;
  }

  _buildHearth() {
    const brick = new THREE.MeshStandardMaterial({ color: 0x7a4a3a, roughness: 0.9 });
    const hearth = new THREE.Group();
    hearth.position.set(-4.2, DAIS_TOP, 3.2);
    const bowl = new THREE.Mesh(new THREE.CylinderGeometry(1.7, 1.3, 1.0, 20, 1, true), brick);
    bowl.position.y = 0.5;
    bowl.castShadow = true;
    hearth.add(bowl);
    const base = new THREE.Mesh(new THREE.CylinderGeometry(1.3, 1.3, 0.2, 20), brick);
    base.position.y = 0.1;
    hearth.add(base);
    this.magmaMat = new THREE.MeshStandardMaterial({
      color: 0xff6a10, emissive: 0xff4a08, emissiveIntensity: 1.8, roughness: 0.6,
    });
    const magma = new THREE.Mesh(new THREE.CylinderGeometry(1.5, 1.5, 0.12, 24), this.magmaMat);
    magma.position.y = 0.85;
    hearth.add(magma);
    this.hearthLight = new THREE.PointLight(0xff7a2a, 40, 26, 1.6);
    this.hearthLight.position.set(0, 2.2, 0);
    hearth.add(this.hearthLight);
    this.hearthPos = new THREE.Vector3(-4.2, DAIS_TOP + 0.9, 3.2);
    this.group.add(hearth);
  }

  _buildHammer() {
    this.hammer = new THREE.Group();
    this.hammer.position.set(0, this.anvilTopY + 1.55, -2.4);
    const wood = new THREE.MeshStandardMaterial({ color: 0x8a5a30, roughness: 0.8 });
    const steel = new THREE.MeshStandardMaterial({ color: 0xb4bac8, roughness: 0.3, metalness: 0.9 });
    const handle = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.22, 2.4), wood);
    handle.position.z = 1.2;
    handle.castShadow = true;
    this.hammer.add(handle);
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.8, 0.8), steel);
    head.position.z = 2.4;
    head.castShadow = true;
    this.hammer.add(head);
    const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.16, 1.1, 10), steel);
    cap.rotation.z = Math.PI / 2;
    cap.position.z = 2.4;
    this.hammer.add(cap);
    this.group.add(this.hammer);
  }

  _buildRings() {
    this.rings = [];
    for (let i = 0; i < 3; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: 0xffb060, transparent: true, opacity: 0, depthWrite: false,
        blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
      });
      const ring = new THREE.Mesh(new THREE.RingGeometry(0.92, 1, 48), mat);
      ring.rotation.x = -Math.PI / 2;
      ring.position.y = DAIS_TOP + 0.12;
      ring.visible = false;
      ring.userData.age = -1;
      this.group.add(ring);
      this.rings.push(ring);
    }
  }

  _buildParticles() {
    const sprite = makeGlowSpriteTexture();
    const mk = (n, color, size) => {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(n * 3), 3));
      const mat = new THREE.PointsMaterial({
        color, size, map: sprite, transparent: true, depthWrite: false,
        blending: THREE.AdditiveBlending, sizeAttenuation: true,
      });
      const pts = new THREE.Points(geo, mat);
      pts.frustumCulled = false;
      this.group.add(pts);
      return pts;
    };
    this.embers = mk(EMBER_COUNT, 0xff9030, 0.7);
    this.emberVel = new Float32Array(EMBER_COUNT * 3);
    this.emberLife = new Float32Array(EMBER_COUNT);
    for (let i = 0; i < EMBER_COUNT; i++) this._respawnEmber(i, true);

    this.sparks = mk(SPARK_COUNT, 0xffe0a0, 0.55);
    this.sparkVel = new Float32Array(SPARK_COUNT * 3);
    this.sparkLife = new Float32Array(SPARK_COUNT);
    const p = this.sparks.geometry.attributes.position.array;
    for (let i = 0; i < SPARK_COUNT; i++) p[i * 3 + 1] = -50;
  }

  _respawnEmber(i, scatter) {
    const p = this.embers.geometry.attributes.position.array;
    const a = Math.random() * Math.PI * 2;
    const r = Math.random() * 1.3;
    p[i * 3] = this.hearthPos.x + Math.cos(a) * r;
    p[i * 3 + 1] = this.hearthPos.y + (scatter ? Math.random() * 7 : 0);
    p[i * 3 + 2] = this.hearthPos.z + Math.sin(a) * r;
    this.emberVel[i * 3] = (Math.random() - 0.5) * 0.5;
    this.emberVel[i * 3 + 1] = 1.2 + Math.random() * 2.0;
    this.emberVel[i * 3 + 2] = (Math.random() - 0.5) * 0.5;
    this.emberLife[i] = scatter ? Math.random() * 3.5 : 3 + Math.random() * 1.5;
  }

  strike() {
    if (this.swingT > 0) return;
    this.swingT = SWING_TIME;
    this.impacted = false;
  }

  _burstSparks() {
    const p = this.sparks.geometry.attributes.position.array;
    for (let i = 0; i < SPARK_COUNT; i++) {
      const a = Math.random() * Math.PI * 2;
      const sp = 3 + Math.random() * 6;
      p[i * 3] = 0;
      p[i * 3 + 1] = this.anvilTopY + 0.3;
      p[i * 3 + 2] = 0;
      this.sparkVel[i * 3] = Math.cos(a) * sp;
      this.sparkVel[i * 3 + 1] = 4 + Math.random() * 6;
      this.sparkVel[i * 3 + 2] = Math.sin(a) * sp;
      this.sparkLife[i] = 1.2 + Math.random() * 1.2;
    }
    // shockwave rings
    this.rings.forEach((r, i) => {
      r.userData.age = -i * 0.12;
    });
  }

  update(dt, t) {
    this.time += dt;
    this.runes.rotation.z += dt * 0.25;
    this.runeMat.opacity = 0.7 + Math.sin(t * 2.2) * 0.15;
    this.ingotMat.emissiveIntensity = 1.4 + Math.sin(t * 3.1) * 0.3;
    this.magmaMat.emissiveIntensity = 1.6 + Math.sin(t * 4.3 + 1) * 0.35;
    this.hearthLight.intensity = 38 + Math.sin(t * 7.3) * 5 + Math.sin(t * 13.1) * 3;

    // hammer: idle hover, strike swing
    let angle = -1.0 + Math.sin(t * 1.6) * 0.06;
    if (this.swingT > 0) {
      this.swingT = Math.max(0, this.swingT - dt);
      const p = 1 - this.swingT / SWING_TIME;
      if (p < 0.5) {
        const k = p / 0.5;
        angle = -1.0 + (k * k) * 1.0;
      } else {
        const k = (p - 0.5) / 0.5;
        angle = -k * 1.0;
        if (!this.impacted) { this.impacted = true; this._burstSparks(); }
      }
      if (p >= 0.5 && !this.impacted) { this.impacted = true; this._burstSparks(); }
    }
    this.hammer.rotation.x = Math.min(angle, 0.0);

    // shockwave rings
    for (const r of this.rings) {
      if (r.userData.age === -1) continue;
      r.userData.age += dt;
      const a = r.userData.age;
      if (a < 0) { r.visible = false; continue; }
      const k = a / 1.4;
      if (k >= 1) { r.visible = false; r.userData.age = -1; r.material.opacity = 0; continue; }
      r.visible = true;
      r.scale.setScalar(1.5 + k * 16);
      r.material.opacity = (1 - k) * 0.8;
    }

    // embers rise
    const ep = this.embers.geometry.attributes.position.array;
    for (let i = 0; i < EMBER_COUNT; i++) {
      this.emberLife[i] -= dt;
      if (this.emberLife[i] <= 0) { this._respawnEmber(i, false); continue; }
      ep[i * 3] += (this.emberVel[i * 3] + Math.sin(t * 2 + i) * 0.3) * dt;
      ep[i * 3 + 1] += this.emberVel[i * 3 + 1] * dt;
      ep[i * 3 + 2] += (this.emberVel[i * 3 + 2] + Math.cos(t * 2 + i) * 0.3) * dt;
    }
    this.embers.geometry.attributes.position.needsUpdate = true;

    // bouncing sparks
    const sp = this.sparks.geometry.attributes.position.array;
    for (let i = 0; i < SPARK_COUNT; i++) {
      if (this.sparkLife[i] <= 0) continue;
      this.sparkLife[i] -= dt;
      if (this.sparkLife[i] <= 0) { sp[i * 3 + 1] = -50; continue; }
      this.sparkVel[i * 3 + 1] -= 18 * dt;
      sp[i * 3] += this.sparkVel[i * 3] * dt;
      sp[i * 3 + 1] += this.sparkVel[i * 3 + 1] * dt;
      sp[i * 3 + 2] += this.sparkVel[i * 3 + 2] * dt;
      if (sp[i * 3 + 1] < DAIS_TOP + 0.05) {
        sp[i * 3 + 1] = DAIS_TOP + 0.05;
        this.sparkVel[i * 3 + 1] *= -0.55;
        this.sparkVel[i * 3] *= 0.8;
        this.sparkVel[i * 3 + 2] *= 0.8;
      }
    }
    this.sparks.geometry.attributes.position.needsUpdate = true;
  }
}


