import * as THREE from 'three';

// Procedural canvas textures. NOTE: anisotropy is intentionally never set so
// software WebGL stays fast.

function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function makeCanvas(w, h) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  return c;
}

function finish(canvas, repeat = false) {
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  if (repeat) {
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
  }
  tex.needsUpdate = true;
  return tex;
}

// One tile = 8 columns x 16 rows of windows (16 x 32 world units).
export function makeWindowTexture(seed, litRatio, palette) {
  const rand = rng(seed);
  const cols = 8, rows = 16, cw = 16, ch = 16;
  const canvas = makeCanvas(cols * cw, rows * ch);
  const g = canvas.getContext('2d');
  g.fillStyle = '#1b2234';
  g.fillRect(0, 0, canvas.width, canvas.height);
  // faint structural mullions
  g.fillStyle = '#2a3350';
  for (let c = 0; c <= cols; c++) g.fillRect(c * cw - 1, 0, 2, canvas.height);
  for (let r = 0; r <= rows; r++) g.fillRect(0, r * ch - 1, canvas.width, 2);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const lit = rand() < litRatio;
      if (lit) {
        const col = palette[Math.floor(rand() * palette.length)];
        const grad = g.createLinearGradient(0, r * ch, 0, (r + 1) * ch);
        grad.addColorStop(0, col);
        grad.addColorStop(1, '#ffffff');
        g.fillStyle = grad;
        g.globalAlpha = 0.65 + rand() * 0.35;
      } else {
        g.fillStyle = rand() < 0.5 ? '#0f1626' : '#18203a';
        g.globalAlpha = 1;
      }
      g.fillRect(c * cw + 3, r * ch + 3, cw - 6, ch - 6);
      g.globalAlpha = 1;
    }
  }
  return finish(canvas, true);
}

// Asphalt strip: lane edges, dashed centre line. Runs along texture V axis.
export function makeRoadTexture() {
  const canvas = makeCanvas(128, 256);
  const g = canvas.getContext('2d');
  g.fillStyle = '#3b404c';
  g.fillRect(0, 0, 128, 256);
  const rand = rng(77);
  for (let i = 0; i < 1400; i++) {
    const v = 52 + Math.floor(rand() * 30);
    g.fillStyle = `rgb(${v},${v + 3},${v + 10})`;
    g.fillRect(rand() * 128, rand() * 256, 2, 2);
  }
  g.fillStyle = '#d8d8c0';
  g.fillRect(6, 0, 4, 256);
  g.fillRect(118, 0, 4, 256);
  g.fillStyle = '#ffd24a';
  for (let y = 0; y < 256; y += 64) g.fillRect(61, y + 8, 6, 36);
  return finish(canvas, true);
