const BUILDING_COLORS = [0x6c7a95, 0x8a6f5c, 0x4e5b78, 0x9aa7bd, 0x5d4a6e, 0x3f6b74, 0xa5866a, 0x2f3c57, 0x7d6b8f];

function makeWindowTextures(variant) {
  const cell = 32;
  const N = 4;
  const S = cell * N;
  const cm = document.createElement('canvas');
  const ce = document.createElement('canvas');
  cm.width = cm.height = ce.width = ce.height = S;
  const gm = cm.getContext('2d');
  const ge = ce.getContext('2d');
  gm.fillStyle = ['#e9edf5', '#dfe6f0', '#f3efe6'][variant];
  gm.fillRect(0, 0, S, S);
  ge.fillStyle = '#000';
  ge.fillRect(0, 0, S, S);
  for (let r = 0; r < N; r++) {
    for (let c = 0; c < N; c++) {
      const x = c * cell + 7;
      const y = r * cell + 8;
      gm.fillStyle = '#2b3850';
      gm.fillRect(x, y, cell - 14, cell - 14);
      if (rand() < 0.5) {
        ge.fillStyle = rand() < 0.75 ? '#ffd27a' : '#9fe8ff';
        ge.fillRect(x, y, cell - 14, cell - 14);
      }
    }
  }
  const map = canvasTexture(cm);
  const emissiveMap = canvasTexture(ce);
  map.wrapS = map.wrapT = emissiveMap.wrapS = emissiveMap.wrapT = THREE.RepeatWrapping;
  return { map, emissiveMap };
}
const windowVariants = [0, 1, 2].map(makeWindowTextures);

const blinkers = [];
const city = { buildings: 0, trees: 0, lamps: 0 };
const treeSpots = [];
const lampSpots = [];

function addBuilding(cx, cz) {
  const w = rr(6, 12);
  const d = rr(6, 12);
  const h = rand() < 0.15 ? rr(38, 62) : rr(8, 34);
  const v = pick(windowVariants);
  const map = v.map.clone();
  map.repeat.set(Math.max(1, Math.round(w / 6)), Math.max(1, Math.round(h / 6)));
  const emissiveMap = v.emissiveMap.clone();
  emissiveMap.repeat.copy(map.repeat);
  const mat = new THREE.MeshStandardMaterial({
    color: pick(BUILDING_COLORS), map, emissiveMap, emissive: 0xffc977,
    emissiveIntensity: cur.windows, roughness: 0.55, metalness: 0.1,
  });
  windowMats.push(mat);

  const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  body.position.set(cx, h / 2, cz);
  body.castShadow = true;
  body.receiveShadow = true;
  scene.add(body);
  city.buildings++;

  let top = h;
  if (rand() < 0.4) {
    const sbH = rr(3, 7);
    const sb = new THREE.Mesh(new THREE.BoxGeometry(w * 0.6, sbH, d * 0.6), mat);
    sb.position.set(cx, h + sbH / 2, cz);
    sb.castShadow = true;
    scene.add(sb);
    top += sbH;
  }
  if (h > 30) {
    const ant = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.08, 3.5, 6), mats.pole);
    ant.position.set(cx, top + 1.75, cz);
    scene.add(ant);
    const light = new THREE.Mesh(new THREE.SphereGeometry(0.22, 8, 6), mats.blink);
    light.position.set(cx, top + 3.6, cz);
    scene.add(light);
    blinkers.push(light);
  }
  if (rand() < 0.35) {
    const strip = new THREE.Mesh(new THREE.BoxGeometry(w * 0.7, 0.45, 0.14), pick(neonMats));
    strip.position.set(cx, rr(3, h - 2), cz + d / 2 + 0.08);
    scene.add(strip);
  }
}

for (let i = -GRID; i < GRID; i++) {
  for (let j = -GRID; j < GRID; j++) {
    const cx = (i + 0.5) * PITCH;
    const cz = (j + 0.5) * PITCH;
    const nearPlaza = (i === -1 || i === 0) && (j === -1 || j === 0);
    if (nearPlaza) continue;
    if (rand() < 0.16) {
      const park = new THREE.Mesh(new THREE.PlaneGeometry(14, 14).rotateX(-Math.PI / 2), mats.park);
      park.position.set(cx, 0.05, cz);
      park.receiveShadow = true;
      scene.add(park);
      for (let t = 0; t < 3; t++) treeSpots.push([cx + rr(-5, 5), cz + rr(-5, 5)]);
    } else {
      addBuilding(cx, cz);
    }
  }
}

/* Street-level props sit on the sidewalk band between roads and buildings. */
for (let i = -GRID; i <= GRID; i++) {
  for (let j = -GRID; j <= GRID; j++) {
    if (!nodeOK(i, j)) continue;
    const x = i * PITCH;
    const z = j * PITCH;
    lampSpots.push([x + 4, z + 4]);
    if (rand() < 0.7) treeSpots.push([x - 4, z - 4]);
  }
}

/* Instanced trees and lamps: a handful of draw calls for the whole street grid. */
const trunkGeo = new THREE.CylinderGeometry(0.25, 0.35, 2.2, 6);
const foliageGeo = new THREE.IcosahedronGeometry(1.6, 0);
const trunks = new THREE.InstancedMesh(trunkGeo, mats.trunk, treeSpots.length);
const foliage = new THREE.InstancedMesh(foliageGeo, mats.leaves, treeSpots.length);
{
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const pos = new THREE.Vector3();
  const sc = new THREE.Vector3();
  const tint = new THREE.Color();
  const greens = [0x3f8f4a, 0x4fa35a, 0x2f7a3e, 0x6bb35f];
  treeSpots.forEach(([x, z], i) => {
    const s = rr(0.8, 1.3);
    q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), rand() * Math.PI * 2);
    pos.set(x, 1.1, z);
    sc.set(s, s, s);
    m.compose(pos, q, sc);
    trunks.setMatrixAt(i, m);
    pos.set(x, 3.2 * s, z);
    m.compose(pos, q, sc);
    foliage.setMatrixAt(i, m);
    foliage.setColorAt(i, tint.set(pick(greens)));
  });
  for (const im of [trunks, foliage]) {
    im.instanceMatrix.needsUpdate = true;
    im.castShadow = true;
    im.receiveShadow = true;
    scene.add(im);
  }
  foliage.instanceColor.needsUpdate = true;
  city.trees = treeSpots.length;
}

const poleGeo = new THREE.CylinderGeometry(0.1, 0.14, 6.5, 6);
const headGeo = new THREE.SphereGeometry(0.42, 10, 8);
const poles = new THREE.InstancedMesh(poleGeo, mats.pole, lampSpots.length);
const heads = new THREE.InstancedMesh(headGeo, mats.lampHead, lampSpots.length);
{
  const m = new THREE.Matrix4();
  const pos = new THREE.Vector3();
  const q = new THREE.Quaternion();
  const sc = new THREE.Vector3(1, 1, 1);
  lampSpots.forEach(([x, z], i) => {
    pos.set(x, 3.25, z);
    m.compose(pos, q, sc);
    poles.setMatrixAt(i, m);
    pos.set(x, 6.6, z);
    m.compose(pos, q, sc);
    heads.setMatrixAt(i, m);
  });
  for (const im of [poles, heads]) {
    im.instanceMatrix.needsUpdate = true;
    im.castShadow = true;
    scene.add(im);
  }
  city.lamps = lampSpots.length;
}

/* Night-sky stars, only visible when the theme asks for them. */
const starsMat = new THREE.PointsMaterial({
  color: 0xffffff, size: 1.8, sizeAttenuation: false, transparent: true, opacity: 1, fog: false, depthWrite: false,
});
{
  const starPos = new Float32Array(900 * 3);
  for (let i = 0; i < 900; i++) {
    const u = rr(0, 1);
    const v = rr(0.05, 1);
    const th = u * Math.PI * 2;
    const ph = Math.acos(1 - v);
    starPos[i * 3] = 380 * Math.sin(ph) * Math.cos(th);
    starPos[i * 3 + 1] = 380 * Math.cos(ph);
    starPos[i * 3 + 2] = 380 * Math.sin(ph) * Math.sin(th);
  }
  const starGeo = new THREE.BufferGeometry();
  starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
  scene.add(new THREE.Points(starGeo, starsMat));
}

/* ------------------------------------------------------------------ *
 * Moru Cats
 * ------------------------------------------------------------------ */
const G = {
  body: new THREE.SphereGeometry(0.5, 16, 12),
  head: new THREE.SphereGeometry(0.42, 16, 12),
  ear: new THREE.ConeGeometry(0.16, 0.4, 4),
  innerEar: new THREE.ConeGeometry(0.08, 0.22, 4),
  eye: new THREE.SphereGeometry(0.07, 8, 6),
  shine: new THREE.SphereGeometry(0.025, 6, 4),
  nose: new THREE.SphereGeometry(0.05, 8, 6),
  leg: new THREE.CapsuleGeometry(0.11, 0.35, 4, 8),
  paw: new THREE.SphereGeometry(0.13, 10, 8),
  collar: new THREE.TorusGeometry(0.3, 0.05, 6, 16),
  bell: new THREE.SphereGeometry(0.09, 10, 8),
  whisker: new THREE.BoxGeometry(0.55, 0.015, 0.015),
  tail: new THREE.TubeGeometry(
    new THREE.CatmullRomCurve3([
      new THREE.Vector3(0, 0, 0),
      new THREE.Vector3(0, 0.25, -0.3),
      new THREE.Vector3(0, 0.65, -0.5),
      new THREE.Vector3(0, 0.9, -0.4),
    ]),
    16, 0.09, 8, false,
  ),
};
const furColors = [0xf2a03d, 0x9aa3b8, 0x2e2f3a, 0xffe3bd, 0xb9866b, 0xe8836b];
const furMats = new Map();
const furMat = (hex) => {
  if (!furMats.has(hex)) furMats.set(hex, new THREE.MeshStandardMaterial({ color: hex, roughness: 0.75 }));
  return furMats.get(hex);
};
const creamMat = new THREE.MeshStandardMaterial({ color: 0xfff4e0, roughness: 0.7 });
const pinkMat = new THREE.MeshStandardMaterial({ color: 0xff8fb1, roughness: 0.5 });
const eyeMat = new THREE.MeshStandardMaterial({ color: 0x101014, roughness: 0.2 });
const shineMat = new THREE.MeshBasicMaterial({ color: 0xffffff });

function buildCat(furHex) {
  const root = new THREE.Group();
  const bob = new THREE.Group();
  root.add(bob);
  const fur = furMat(furHex);
  const add = (geo, mat, x, y, z, parent = bob) => {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(x, y, z);
    m.castShadow = true;
    parent.add(m);
    return m;
  };

  const body = add(G.body, fur, 0, 0.95, 0);
  body.scale.set(0.9, 0.85, 1.25);
  const chest = add(G.body, creamMat, 0, 0.85, 0.5);
  chest.scale.set(0.55, 0.6, 0.5);
  const head = add(G.head, fur, 0, 1.7, 0.55);

  for (const s of [-1, 1]) {
    const ear = add(G.ear, fur, 0.22 * s, 2.1, 0.5);
    ear.rotation.z = -0.25 * s;
    const inner = add(G.innerEar, pinkMat, 0.22 * s, 2.04, 0.53);
    inner.rotation.z = -0.25 * s;
    add(G.eye, eyeMat, 0.16 * s, 1.76, 0.94);
    add(G.shine, shineMat, 0.18 * s, 1.8, 1.0);
    for (const wy of [1.6, 1.55]) {
      const w = add(G.whisker, mats.whisker, 0.5 * s, wy, 0.95);
      w.rotation.z = -0.1 * s;
      w.castShadow = false;
    }
  }
  add(G.nose, pinkMat, 0, 1.66, 0.98);

  const collar = add(G.collar, mats.gold, 0, 1.3, 0.35);
  collar.rotation.x = Math.PI / 2;
  add(G.bell, mats.gold, 0, 1.18, 0.66);

  const tail = new THREE.Group();
  tail.position.set(0, 1.0, -0.55);
  bob.add(tail);
  const tailMesh = new THREE.Mesh(G.tail, fur);
  tailMesh.castShadow = true;
  tail.add(tailMesh);

  const legs = [];
  const hips = [
    { x: -0.25, z: 0.42, off: 0, front: true },
    { x: 0.25, z: 0.42, off: Math.PI, front: true },
    { x: -0.25, z: -0.38, off: Math.PI, front: false },
    { x: 0.25, z: -0.38, off: 0, front: false },
  ];
  for (const h of hips) {
    const pivot = new THREE.Group();
    pivot.position.set(h.x, 0.7, h.z);
    bob.add(pivot);
    add(G.leg, fur, 0, -0.3, 0, pivot);
    add(G.paw, creamMat, 0, -0.55, 0.04, pivot).scale.set(1, 0.7, 1.3);
    legs.push({ pivot, off: h.off, front: h.front });
  }
  return { root, bob, legs, tail, head, body };
}

const cats = [];
let catIdSeq = 0;

function neighbors(i, j) {
  return [[1, 0], [-1, 0], [0, 1], [0, -1]].filter(([di, dj]) => nodeOK(i + di, j + dj));
}

function randomNode() {
  for (;;) {
    const i = Math.floor(rand() * (2 * GRID + 1)) - GRID;
    const j = Math.floor(rand() * (2 * GRID + 1)) - GRID;
    if (nodeOK(i, j)) return { i, j };
  }
}

/* A cat walks road segments between intersections, never cutting across blocks. */
function beginSegment(c) {
  const opts = neighbors(c.ni, c.nj);
  let choices = opts.filter(([di, dj]) => !(di === -c.di && dj === -c.dj));
  if (!choices.length || rand() < 0.1) choices = opts;
  [c.di, c.dj] = pick(choices);
  c.p = 0;
  c.laneT = rr(-1.2, 1.2);
}

function jumpCat(c, power = 1) {
  if (c.airT >= 0) return;
  c.airT = 0;
  c.airDur = rr(0.6, 0.8);
  c.hop = rr(1.8, 2.6) * power;
}

function spawnCat() {
  if (cats.length >= MAX_CATS) {
    return null;
  }
  const start = randomNode();
  const c = {
    ...buildCat(pick(furColors)),
    id: ++catIdSeq,
    ni: start.i,
    nj: start.j,
    di: 1,
    dj: 0,
    p: 0,
    speed: rr(7, 10),
    lane: 0,
    laneT: 0,
    phase: rand() * Math.PI * 2,
    yaw: 0,
    airT: -1,
    airDur: 0.7,
    hop: 2,
    squash: 0,
    baseY: ROAD_Y,
    spawnT: state.paused ? 1 : 0,
  };
  beginSegment(c);
  c.yaw = Math.atan2(c.di, c.dj);
  c.root.scale.setScalar(c.spawnT < 1 ? 0.001 : 1);
  scene.add(c.root);
  cats.push(c);
  placeCat(c, 0);
  return c;
}

function placeCat(c, dt) {
  const p = c.p;
  const ax = c.ni * PITCH;
  const az = c.nj * PITCH;
  const x = ax + c.di * PITCH * p;
  const z = az + c.dj * PITCH * p;
  c.lane += (c.laneT - c.lane) * Math.min(1, dt * 3);
  const px = x - c.dj * c.lane;
  const pz = z + c.di * c.lane;
  c.root.position.x = px;
  c.root.position.z = pz;
  const targetBase = Math.hypot(px, pz) < PLAZA_R + 0.4 ? PLAZA_Y : ROAD_Y;
  c.baseY += (targetBase - c.baseY) * Math.min(1, dt * 8);
  const lift = c.airT >= 0 ? c.hop * 4 * (c.airT / c.airDur) * (1 - c.airT / c.airDur) : 0;
  c.root.position.y = c.baseY + lift;
}

function updateCats(dt) {
  for (const c of cats) {
    if (c.spawnT < 1) {
      c.spawnT = Math.min(1, c.spawnT + dt / 0.6);
      c.root.scale.setScalar(Math.max(0.001, easeOutBack(c.spawnT)));
    }

    // Movement along the current road segment.
    c.p += (c.speed * dt) / PITCH;
    if (c.p >= 1) {
      c.ni += c.di;
      c.nj += c.dj;
      beginSegment(c);
    }

    // Hops: random while running, and a bonus hop when the anvil rings.
    if (c.airT < 0 && rand() < dt * 0.25) jumpCat(c);
    if (c.airT >= 0) {
      c.airT += dt;
      if (c.airT >= c.airDur) {
        c.airT = -1;
        c.squash = 1;
      }
    }
    c.squash = Math.max(0, c.squash - dt * 5);
    placeCat(c, dt);

    // Face travel direction with a short turn.
    const targetYaw = Math.atan2(c.di, c.dj);
    c.yaw += shortestAngle(c.yaw, targetYaw) * Math.min(1, dt * 10);
    c.root.rotation.y = c.yaw;

    // Run cycle, tucked legs in the air, and squash on landing.
    const running = c.airT < 0;
    c.phase += dt * c.speed * 0.9;
    const tuck = running ? 0 : Math.sin(Math.PI * (c.airT / c.airDur));
    for (const leg of c.legs) {
      if (running) {
        leg.pivot.rotation.x = Math.sin(c.phase + leg.off) * 0.6;
      } else {
        leg.pivot.rotation.x = (leg.front ? -0.9 : 0.9) * tuck;
      }
    }
    c.bob.position.y = running ? Math.abs(Math.sin(c.phase)) * 0.08 : 0;
    c.bob.scale.set(1 + c.squash * 0.12, 1 - c.squash * 0.25, 1 + c.squash * 0.12);
    c.head.rotation.x = running ? Math.sin(c.phase * 2) * 0.05 : 0;
    c.tail.rotation.y = Math.sin(state.elapsed * 5 + c.id) * 0.35;
  }
}

function summonCat() {
  const c = spawnCat();
  if (!c) {
    console.warn(`Cat village is full (${MAX_CATS} max).`);
  }
  return c;
}

function strike() {
  state.strikes++;
  anvilSquash = 1;
  forgeFlash = 1;
  shake = 1;
  shockT = 0;
  emitSparks(90);
  for (const c of cats) {
    if (c.root.position.distanceTo(anvil.position) < 30) jumpCat(c, 1.4);
  }
}

/* ------------------------------------------------------------------ *
 * Camera: tweens for presets, chase for follow mode
 * ------------------------------------------------------------------ */
const tween = { on: false, t: 0, dur: 1.5, p0: new THREE.Vector3(), p1: new THREE.Vector3(), t0: new THREE.Vector3(), t1: new THREE.Vector3() };
const followTarget = new THREE.Vector3();
const followPos = new THREE.Vector3();

function flyTo(pos, tgt, dur = 1.5) {
  tween.on = true;
  tween.t = 0;
  tween.dur = dur;
  tween.p0.copy(camera.position);
  tween.p1.set(...pos);
  tween.t0.copy(controls.target);
  tween.t1.set(...tgt);
}

function updateCamera(dt) {
  if (tween.on) {
    tween.t = Math.min(1, tween.t + dt / tween.dur);
    const e = easeInOutCubic(tween.t);
    camera.position.lerpVectors(tween.p0, tween.p1, e);
    controls.target.lerpVectors(tween.t0, tween.t1, e);
    if (tween.t >= 1) tween.on = false;
    return;
  }
  if (state.view === 'follow' && cats.length) {
    const c = cats[state.followIndex] || cats[0];
    const p = c.root.position;
    const k = 1 - Math.exp(-dt * 4);
    followTarget.set(p.x, p.y + 1.3, p.z);
    followPos.set(p.x - Math.sin(c.yaw) * 9, p.y + 4.2, p.z - Math.cos(c.yaw) * 9);
    controls.target.lerp(followTarget, k);
    camera.position.lerp(followPos, k);
  }
}

/* ------------------------------------------------------------------ *
 * Atmosphere themes
 * ------------------------------------------------------------------ */
function updateTheme(dt) {
  const T = THEMES[state.theme];
  const k = 1 - Math.exp(-dt * 2.5);
  for (const key of colorKeys) cur[key].lerp(T[key], k);
  for (const key of numberKeys) cur[key] += (T[key] - cur[key]) * k;

  scene.background.copy(cur.bg);
  scene.fog.color.copy(cur.fog);
  scene.fog.near = cur.fogNear;
  scene.fog.far = cur.fogFar;
  hemi.color.copy(cur.hemiSky);
  hemi.groundColor.copy(cur.hemiGround);
  hemi.intensity = cur.hemi;
  sun.color.copy(cur.sunColor);
  sun.intensity = cur.sun;
  for (const m of windowMats) m.emissiveIntensity = cur.windows;
  for (const m of neonMats) m.emissiveIntensity = cur.neon;
  mats.lampHead.emissiveIntensity = cur.lamps;
  starsMat.opacity = cur.stars;
}

/* ------------------------------------------------------------------ *
 * State, telemetry, UI wiring
 * ------------------------------------------------------------------ */
const state = {
  paused: false,
  theme: 'night',
  view: 'overview',
  followIndex: -1,
  strikes: 0,
  elapsed: 0,
  fps: 0,
  frameMs: 0,
  drawCalls: 0,
  triangles: 0,
  cats,
  city,
  get catCount() {
    return cats.length;
  },
};

const $ = (id) => document.getElementById(id);
const hud = $('fps-hud');
const pauseBtn = $('toggle-spin');

function syncButtons() {
  for (const t of ['night', 'gold', 'day']) $(`mode-${t}`).setAttribute('aria-pressed', String(state.theme === t));
  for (const v of ['overview', 'iso', 'street', 'follow']) {
    $(v === 'follow' ? 'cam-follow-cat' : `cam-${v}`).setAttribute('aria-pressed', String(state.view === v));
  }
  pauseBtn.setAttribute('aria-pressed', String(state.paused));
  pauseBtn.textContent = state.paused ? '▶ Resume' : '⏸ Pause';
}

function setTheme(name) {
  state.theme = name;
  syncButtons();
}

function setView(name) {
  if (name === 'follow') {
    if (!cats.length) spawnCat();
    if (state.view === 'follow') {
      state.followIndex = (state.followIndex + 1) % cats.length;
    } else {
      state.followIndex = Math.floor(Math.random() * cats.length);
    }
  }
  state.view = name;
  controls.enabled = name !== 'follow';
  if (name !== 'follow') flyTo(VIEWS[name].pos, VIEWS[name].tgt);
  syncButtons();
}

function togglePause() {
  state.paused = !state.paused;
  syncButtons();
}

$('btn-spawn-cat').addEventListener('click', summonCat);
$('btn-forge-strike').addEventListener('click', strike);
pauseBtn.addEventListener('click', togglePause);
$('cam-overview').addEventListener('click', () => setView('overview'));
$('cam-iso').addEventListener('click', () => setView('iso'));
$('cam-street').addEventListener('click', () => setView('street'));
$('cam-follow-cat').addEventListener('click', () => setView('follow'));
$('mode-night').addEventListener('click', () => setTheme('night'));
$('mode-gold').addEventListener('click', () => setTheme('gold'));
$('mode-day').addEventListener('click', () => setTheme('day'));

window.addEventListener('keydown', (e) => {
  if (e.target instanceof HTMLButtonElement) return;
  if (e.code === 'Space') {
    e.preventDefault();
    strike();
  } else if (e.code === 'KeyC') {
    summonCat();
  } else if (e.code === 'KeyP') {
    togglePause();
  }
});

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

function updateHud(frameTimes) {
  const avg = frameTimes.reduce((a, b) => a + b, 0) / frameTimes.length;
  state.frameMs = avg;
  state.fps = avg > 0 ? 1000 / avg : 0;
  state.drawCalls = renderer.info.render.calls;
  state.triangles = renderer.info.render.triangles;
  hud.textContent = [
    'MORU · LIVE TELEMETRY',
    `FPS     ${state.fps.toFixed(1).padStart(6)}   ${state.frameMs.toFixed(2)} ms`,
    `CATS    ${String(cats.length).padStart(3)} / ${MAX_CATS}   STRIKES ${state.strikes}`,
    `THEME   ${THEMES[state.theme].label.padEnd(6)}  VIEW ${state.view}`,
    `DRAW    ${String(state.drawCalls).padStart(5)}   TRIS ${(state.triangles / 1000).toFixed(1)}k`,
    `CITY    BLDG ${city.buildings}  TREE ${city.trees}  LAMP ${city.lamps}`,
    `SIM     ${(state.paused ? 'PAUSED ' : 'RUNNING').padEnd(8)} T ${fmtTime(state.elapsed)}`,
  ].join('\n');
}

/* ------------------------------------------------------------------ *
 * Main loop
 * ------------------------------------------------------------------ */
for (let k = 0; k < 6; k++) spawnCat();
syncButtons();

window.__app = { scene, camera, renderer, state };

let last = performance.now();
const frameTimes = [];
let hudAcc = 0;
const shakeOffset = new THREE.Vector3();

function frame(now) {
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  frameTimes.push(dt * 1000);
  if (frameTimes.length > 60) frameTimes.shift();

  camera.position.sub(shakeOffset);
  updateTheme(dt);
  updateCamera(dt);
  if (!state.paused) {
    state.elapsed += dt;
    updateCats(dt);
    updateForge(dt);
  }
  controls.autoRotate = state.view === 'overview' && !state.paused;
  controls.update();

  if (shake > 0 && !state.paused) {
    shake = Math.max(0, shake - dt * 2.2);
    shakeOffset.set(jitter(), jitter(), jitter()).multiplyScalar(shake * 0.5);
  } else {
    shakeOffset.set(0, 0, 0);
  }
  camera.position.add(shakeOffset);

  for (const b of blinkers) b.visible = Math.sin(state.elapsed * 4) > -0.2 || state.paused;

  renderer.render(scene, camera);

  hudAcc += dt;
  if (hudAcc >= 0.25) {
    hudAcc = 0;
    updateHud(frameTimes);
  }
}

renderer.setAnimationLoop(frame);


