import * as THREE from 'three';

// Chibi Moru Cat factory. Each cat is ~38 child meshes: rounded torso, belly patch, chibi head with
// puffy cheeks, pointed ears with inner detail, glossy eyes with catchlights, whiskers, a red collar
// with a jingling golden bell, a steel blacksmith helmet, four swinging legs and a 4-segment tail.
// The cat trots along a closed avenue loop, hops, and backflips when `excite()` is called.

const FUR = ['#f2a65a', '#3e3b4c', '#ece7df', '#7d5a46', '#7190c4', '#b8738f'];
const FLIP_TIME = 0.9;
const JUMP_TIME = 1.4;
const EYE_HEIGHT = 0.12;

const geo = {
  ball: new THREE.SphereGeometry(1, 18, 14),
  cyl: new THREE.CylinderGeometry(1, 1, 1, 12),
  cone: new THREE.ConeGeometry(1, 1, 12),
  torus: new THREE.TorusGeometry(1, 0.12, 8, 28),
  helmet: new THREE.SphereGeometry(1, 18, 10, 0, Math.PI * 2, 0, Math.PI / 2),
};

const shared = {
  belly: new THREE.MeshStandardMaterial({ color: '#fff1da', roughness: 0.6 }),
  pink: new THREE.MeshStandardMaterial({ color: '#ff9ab0', roughness: 0.5 }),
  eye: new THREE.MeshStandardMaterial({ color: '#1a1a22', roughness: 0.12, metalness: 0.1 }),
  white: new THREE.MeshBasicMaterial({ color: '#ffffff' }),
  steel: new THREE.MeshStandardMaterial({ color: '#b9c2d3', roughness: 0.3, metalness: 0.8 }),
  red: new THREE.MeshStandardMaterial({ color: '#c83a3a', roughness: 0.5 }),
  gold: new THREE.MeshStandardMaterial({ color: '#ffcc3d', roughness: 0.25, metalness: 0.6, emissive: '#ff9a1a', emissiveIntensity: 0.4 }),
};

function part(parent, geometry, material, [x, y, z], [sx = 1, sy = 1, sz = 1] = [], [rx = 0, ry = 0, rz = 0] = []) {
  const m = new THREE.Mesh(geometry, material);
  m.position.set(x, y, z);
  m.scale.set(sx, sy, sz);
  m.rotation.set(rx, ry, rz);
  m.castShadow = true;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

function pivot(parent, [x, y, z]) {
  const g = new THREE.Group();
  g.position.set(x, y, z);
  parent.add(g);
  return g;
}

// Closed-loop sampler: returns the position and heading at arc length `s`.
function makeLoop(route) {
  const segs = [];
  let total = 0;
  route.forEach((a, i) => {
    const b = route[(i + 1) % route.length];
    const len = Math.hypot(b.x - a.x, b.z - a.z);
    segs.push({ a, b, len, start: total });
    total += len;
  });
  return (s) => {
    const u = ((s % total) + total) % total;
    const seg = segs.find((g) => u >= g.start && u < g.start + g.len) || segs[segs.length - 1];
    const f = (u - seg.start) / seg.len;
    const dx = seg.b.x - seg.a.x;
    const dz = seg.b.z - seg.a.z;
    return { x: seg.a.x + dx * f, z: seg.a.z + dz * f, heading: Math.atan2(dx, dz) };
  };
}

export function createMoruCat({ index, route, speed = 9, offset = 0, color = FUR[index % FUR.length] }) {
  const group = new THREE.Group();
  group.name = `moru-cat-${index}`;
  group.userData.isMoruCat = true;
  group.rotation.order = 'YXZ'; // yaw (heading) first, then pitch for backflips

  const fur = new THREE.MeshStandardMaterial({ color, roughness: 0.62 });
  const furTip = new THREE.MeshStandardMaterial({ color: new THREE.Color(color).multiplyScalar(0.6), roughness: 0.62 });

  // Torso and belly.
  part(group, geo.ball, fur, [0, 1.0, 0], [0.55, 0.52, 0.75]);
  part(group, geo.ball, shared.belly, [0, 0.88, 0.32], [0.36, 0.34, 0.35]);

  // Head pivot sits on the neck and turns to look around.
  const head = pivot(group, [0, 1.62, 0.42]);
  part(head, geo.ball, fur, [0, 0, 0], [0.5, 0.46, 0.46]);
  part(head, geo.ball, fur, [-0.3, -0.12, 0.12], [0.2, 0.18, 0.18]);
  part(head, geo.ball, fur, [0.3, -0.12, 0.12], [0.2, 0.18, 0.18]);
  part(head, geo.ball, shared.pink, [0, -0.1, 0.42], [0.14, 0.11, 0.1]);
  part(head, geo.ball, shared.pink, [0, -0.04, 0.55], [0.05, 0.05, 0.05]);
  for (const side of [-1, 1]) {
    for (let k = -1; k <= 1; k++) {
      part(head, geo.cyl, shared.white, [side * 0.42, -0.1 + k * 0.07, 0.42], [0.012, 0.5, 0.012], [Math.PI / 2, 0, side * k * 0.2]);
    }
  }

  // Ears: each ear pivots so it flaps; inner ear is a pink cone inside the outer one.
  const ears = [];
  for (const side of [-1, 1]) {
    const ear = pivot(head, [side * 0.3, 0.42, 0]);
    part(ear, geo.cone, fur, [0, 0.12, 0], [0.22, 0.42, 0.2]);
    part(ear, geo.cone, shared.pink, [0, 0.1, 0.05], [0.12, 0.26, 0.1]);
    ears.push(ear);
  }

  // Glossy eyes with white catchlights; the eyes blink on a timer.
  const eyes = [];
  for (const side of [-1, 1]) {
    eyes.push(part(head, geo.ball, shared.eye, [side * 0.2, 0.06, 0.4], [0.1, EYE_HEIGHT, 0.06]));
    part(head, geo.ball, shared.white, [side * 0.23, 0.1, 0.45], [0.03, 0.03, 0.03]);
  }

  // Blacksmith helmet: steel dome, brim and a red crest.
  part(head, geo.helmet, shared.steel, [0, 0.12, 0], [0.52, 0.46, 0.5]);
  part(head, geo.torus, shared.steel, [0, 0.12, 0], [0.5, 0.5, 0.5], [Math.PI / 2, 0, 0]);
  part(head, geo.cone, shared.red, [0, 0.82, -0.05], [0.08, 0.18, 0.08]);

  // Collar and jingling bell.
  part(group, geo.torus, shared.red, [0, 1.36, 0.22], [0.42, 0.42, 0.42], [Math.PI / 2 - 0.35, 0, 0]);
  const bell = pivot(group, [0, 1.18, 0.72]);
  part(bell, geo.ball, shared.gold, [0, 0, 0], [0.1, 0.1, 0.1]);

  // Four articulated legs; diagonal pairs swing together.
  const legs = [
    { pivot: pivot(group, [-0.26, 0.8, 0.36]), phase: 0 },
    { pivot: pivot(group, [0.26, 0.8, 0.36]), phase: Math.PI },
    { pivot: pivot(group, [-0.26, 0.8, -0.36]), phase: Math.PI },
    { pivot: pivot(group, [0.26, 0.8, -0.36]), phase: 0 },
  ];
  legs.forEach(({ pivot: p }) => {
    part(p, geo.cyl, fur, [0, -0.3, 0], [0.14, 0.6, 0.14]);
    part(p, geo.ball, fur, [0, -0.66, 0.03], [0.17, 0.12, 0.2]);
  });

  // Tail: four chained segments that wag from the root.
  const tailRoot = pivot(group, [0, 0.95, -0.62]);
  tailRoot.rotation.x = 0.9;
  const tail = [];
  let parent = tailRoot;
  for (let i = 0; i < 4; i++) {
    const seg = pivot(parent, [0, 0, i === 0 ? 0 : -0.2]);
    const r = 0.13 - 0.01 * i;
    part(seg, geo.ball, i === 3 ? furTip : fur, [0, 0, -0.1], [r, r, 0.14]);
    tail.push(seg);
    parent = seg;
  }

  let s = offset;
  let phase = offset * 0.37;
  let jumpT = 0;
  let flipT = 0;
  const sampleLoop = makeLoop(route);

  return {
    group,
    speed,
    get heading() {
      return group.rotation.y;
    },
    excite() {
      jumpT = JUMP_TIME;
      flipT = FLIP_TIME;
    },
    update(dt, t) {
      s += speed * dt;
      phase += dt * speed * 1.4;
      const { x, z, heading } = sampleLoop(s);

      jumpT = Math.max(0, jumpT - dt);
      flipT = Math.max(0, flipT - dt);
      const flipP = flipT > 0 ? 1 - flipT / FLIP_TIME : 0;
      const pitch = -flipP * Math.PI * 2;
      const jumpLift = jumpT > 0 ? Math.sin((1 - jumpT / JUMP_TIME) * Math.PI) * 1.4 : 0;
      const hop = Math.abs(Math.sin(phase)) * 0.14;
      group.position.set(x, hop + jumpLift, z);
      group.rotation.set(pitch, heading, 0);

      legs.forEach((l) => {
        l.pivot.rotation.x = Math.sin(phase + l.phase) * 0.5;
      });

      head.rotation.y = Math.sin(t * 1.3) * 0.25;
      head.position.y = 1.62 + Math.sin(phase * 2) * 0.02;
      ears.forEach((e, i) => {
        e.rotation.z = Math.sin(t * 7 + i * 2) * 0.18;
      });

      const blink = (t + index * 0.7) % 3.4 < 0.12;
      eyes.forEach((e) => (e.scale.y = EYE_HEIGHT * (blink ? 0.15 : 1)));

      tail.forEach((seg, i) => {
        seg.rotation.y = Math.sin(t * 6 - i * 0.8) * 0.35;
      });
      bell.rotation.z = Math.sin(t * 12) * 0.25;
    },
  };
}


