import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
import { buildCity, ROAD_COORDS } from './world/city.js';
import { buildForge } from './world/forge.js';
import { createAtmosphere, THEME_NAMES } from './world/atmosphere.js';
import { createMoruCat } from './entities/moruCat.js';

const INITIAL_CATS = 8;
const MAX_CATS = 30;
const PLAZA_RING_R = 13.5;
const NEAR_AVENUE = ROAD_COORDS[5]; // 22: first avenue ring around the forge plaza

// Octagonal loop right around the central anvil dais so cats are front-and-center
const circleRoute = (r, steps = 16) =>
  Array.from({ length: steps }, (_, i) => {
    const a = (i / steps) * Math.PI * 2;
    return { x: Math.cos(a) * r, z: Math.sin(a) * r };
  });

// Closed square loop on an avenue ring, walked clockwise.
const ringRoute = (r) => [
  { x: r, z: r },
  { x: -r, z: r },
  { x: -r, z: -r },
  { x: r, z: -r },
];

const state = {
  theme: 'night',
  spinning: true,
  catCount: 0,
  cameraMode: 'overview',
  followIndex: 0,
  forgeStrikes: 0,
  disposedCount: 0,
  frame: 0,
  fps: 60,
  triangles: 0,
  cats: [],
};

const canvas = document.getElementById('studio-canvas');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, preserveDrawingBuffer: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));
renderer.setSize(window.innerWidth, window.innerHeight, false);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.5, 900);

// Interactive OrbitControls: mouse drag to orbit, scroll wheel to zoom, right-drag to pan, and smooth auto-rotate!
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.enableRotate = true;
controls.enableZoom = true;
controls.enablePan = true;
controls.zoomSpeed = 1.2;
controls.minDistance = 8;
controls.maxDistance = 220;
controls.maxPolarAngle = Math.PI * 0.485;
controls.autoRotate = true;
controls.autoRotateSpeed = 2.2;
controls.target.set(0, 3, 0);

// World: city, forge, atmosphere (sky, fog, lights, emissive levels).
const city = buildCity(scene);
const forge = buildForge(scene);
const atmosphere = createAtmosphere(scene, { city, forge });
atmosphere.apply('night');

// Post-processing: HDR scene -> bloom -> tone mapping / sRGB output.
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 0.85, 0.5, 0.65);
composer.addPass(bloom);
composer.addPass(new OutputPass());

// Cats live in one group; each walks a closed plaza or avenue loop and gets a staggered start.
const catGroup = new THREE.Group();
catGroup.name = 'moru-cats';
scene.add(catGroup);
const routes = [circleRoute(PLAZA_RING_R, 20), circleRoute(PLAZA_RING_R + 3.2, 20), ringRoute(NEAR_AVENUE)];

function spawnCat() {
  if (state.cats.length >= MAX_CATS) return;
  const i = state.cats.length;
  const cat = createMoruCat({
    index: i,
    route: routes[i % routes.length],
    speed: 10 + ((i * 1.9) % 5),
    offset: i * 19,
  });
  cat.group.scale.setScalar(2.15);
  catGroup.add(cat.group);
  state.cats.push(cat);
  state.catCount = state.cats.length;
  refreshStats();
}

for (let i = 0; i < INITIAL_CATS; i++) spawnCat();

function countTriangles(root) {
  let tris = 0;
  root.traverse((o) => {
    if (!o.isMesh) return;
    const g = o.geometry;
    const perInstance = (g.index ? g.index.count : g.attributes.position.count) / 3;
    tris += perInstance * (o.isInstancedMesh ? o.count : 1);
  });
  return Math.round(tris);
}

function refreshStats() {
  state.triangles = countTriangles(scene);
}
refreshStats();

// Exposure and bloom per theme; the sky texture swap is what `apply` disposes.
function applyTheme(name) {
  const res = atmosphere.apply(name);
  state.theme = name;
  state.disposedCount += res.disposed;
  bloom.strength = res.bloom.strength;
  bloom.radius = res.bloom.radius;
  bloom.threshold = res.bloom.threshold;
  renderer.toneMappingExposure = res.exposure;

  const url = new URL(window.location.href);
  url.searchParams.set('theme', name);
  window.history.replaceState(null, '', url);
  THEME_NAMES.forEach((n) => {
    const btn = document.getElementById(`mode-${n}`);
    btn.classList.toggle('active', n === name);
    btn.setAttribute('aria-pressed', String(n === name));
  });
}

const CAMERA_PRESETS = {
  overview: { pos: [42, 30, 46], look: [0, 3.5, 0] },
  iso: { pos: [68, 48, 68], look: [0, 5, 0] },
  street: { pos: [0, 4.8, 26], look: [0, 3.5, 0] },
};

function setPreset(name) {
  const p = CAMERA_PRESETS[name];
  state.cameraMode = name;
  controls.enabled = true;
  camera.position.set(...p.pos);
  controls.target.set(...p.look);
  camera.lookAt(controls.target);
  controls.update();
  ['overview', 'iso', 'street', 'follow'].forEach((m) => {
    const id = m === 'follow' ? 'cam-follow-cat' : `cam-${m}`;
    document.getElementById(id)?.classList.toggle('active', m === name);
  });
}

function followCam(dt) {
  const cat = state.cats[state.followIndex % state.cats.length];
  if (!cat) return;
  const { position: p, rotation: r } = cat.group;
  const desired = new THREE.Vector3(p.x - Math.sin(r.y) * 11, p.y + 5.2, p.z - Math.cos(r.y) * 11);
  camera.position.lerp(desired, 1 - Math.exp(-dt * 4));
  controls.target.lerp(new THREE.Vector3(p.x, p.y + 2.0, p.z), 1 - Math.exp(-dt * 6));
  camera.lookAt(controls.target);
}

const hud = document.getElementById('fps-hud');
let fpsFrames = 0;
let fpsTimer = 0;

function renderHud() {
  hud.textContent =
    `FPS ${state.fps} · Cats ${state.catCount} · Buildings ${city.buildings.length} · ` +
    `Lamps ${city.lamps.length} · Trees ${city.trees.length} · ` +
    `${(state.triangles / 1000).toFixed(1)}k tris · Frame ${state.frame}`;
}

function bind(id, handler) {
  document.getElementById(id).addEventListener('click', handler);
}

bind('cam-overview', () => setPreset('overview'));
bind('cam-iso', () => setPreset('iso'));
bind('cam-street', () => setPreset('street'));
bind('cam-follow-cat', () => {
  state.cameraMode = 'follow';
  state.followIndex = (state.followIndex + 1) % Math.max(1, state.cats.length);
  ['overview', 'iso', 'street', 'follow'].forEach((m) => {
    const id = m === 'follow' ? 'cam-follow-cat' : `cam-${m}`;
    document.getElementById(id)?.classList.toggle('active', m === 'follow');
  });
});
bind('btn-spawn-cat', () => {
  spawnCat();
  state.cats[state.cats.length - 1]?.excite();
});
bind('btn-forge-strike', () => {
  forge.strike();
  state.forgeStrikes = forge.strikes;
  state.cats.forEach((c) => c.excite());
});
THEME_NAMES.forEach((n) => bind(`mode-${n}`, () => applyTheme(n)));

const spinBtn = document.getElementById('toggle-spin');
bind('toggle-spin', () => {
  state.spinning = !state.spinning;
  controls.autoRotate = state.spinning && state.cameraMode !== 'follow';
  spinBtn.textContent = state.spinning ? 'Freeze' : 'Resume';
  spinBtn.setAttribute('aria-pressed', String(!state.spinning));
});

const requestedTheme = new URLSearchParams(window.location.search).get('theme');
setPreset('overview');
applyTheme(THEME_NAMES.includes(requestedTheme) ? requestedTheme : 'night');
renderHud();

window.addEventListener('resize', () => {
  const w = window.innerWidth;
  const h = window.innerHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h, false);
  composer.setSize(w, h);
});

window.__app = { scene, camera, renderer, composer, controls, state };

const clock = new THREE.Clock();
let t = 0;
let autoStrikeTimer = 1.2;

function tick() {
  requestAnimationFrame(tick);
  const dt = Math.min(clock.getDelta(), 0.05);

  if (state.spinning) {
    t += dt;
    state.frame++;
    autoStrikeTimer -= dt;
    if (autoStrikeTimer <= 0) {
      forge.strike();
      state.cats[state.frame % state.cats.length]?.excite();
      autoStrikeTimer = 2.8;
    }
    forge.update(dt, t);
    state.cats.forEach((c) => c.update(dt, t));
    if (state.cameraMode === 'follow') {
      controls.autoRotate = false;
      followCam(dt);
    } else {
      controls.autoRotate = state.cameraMode === 'overview' || state.cameraMode === 'iso';
      controls.update();
    }

    fpsFrames++;
    fpsTimer += dt;
    if (fpsTimer >= 0.4) {
      state.fps = Math.round(fpsFrames / fpsTimer);
      fpsFrames = 0;
      fpsTimer = 0;
    }
    renderHud();
  }

  composer.render();
}

tick();

