// Three exposure-balanced looks. Values were tuned against the luminance guard
// (dark < 70 %, clipped-bright < 8 %, luminance stdev >= 26) for each theme.
export const THEMES = {
  night: {
    label: 'Night',
    skyTop: '#050818',
    skyMid: '#131a40',
    skyBottom: '#23306a',
    stars: true,
    fog: '#1a2450',
    fogDensity: 0.0042,
    hemiSky: '#5a6fc4',
