    stars: false,
    fog: '#e9a46a',
    fogDensity: 0.0038,
    hemiSky: '#ffd9a6',
    hemiGround: '#6b4a32',
    hemi: 1.35,
    sunColor: '#ffc27a',
    sunIntensity: 2.2,
    sunPos: [-180, 70, 90],
    ground: '#8a7560',
    windows: 0.55,
    neon: 1.2,
    lamp: 1.9,
    pool: 0.45,
