    stars: false,
    fog: '#d7ecff',
    fogDensity: 0.0030,
    hemiSky: '#bfdfff',
    hemiGround: '#7a7060',
    hemi: 1.45,
    sunColor: '#fff3e0',
    sunIntensity: 2.4,
