  },
};

export const THEME_NAMES = Object.keys(THEMES);

// Owns sky dome, fog, lights and emissive levels. `apply` swaps the sky texture
// and returns how many GPU resources were disposed so the HUD can report them.
export function createAtmosphere(scene, { city, forge }) {
  const hemi = new THREE.HemisphereLight(0xffffff, 0x222222, 1);
  scene.add(hemi);

  const sun = new THREE.DirectionalLight(0xffffff, 1);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  Object.assign(sun.shadow.camera, { left: -160, right: 160, top: 160, bottom: -160, near: 20, far: 700 });
  sun.shadow.bias = -0.0005;
  sun.shadow.normalBias = 0.04;
  scene.add(sun);
  scene.add(sun.target);

  const sunGlowMat = new THREE.SpriteMaterial({
    map: createGlowTexture('sun', '255,220,160'),
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    fog: false,
  });
  const sunGlow = new THREE.Sprite(sunGlowMat);
  sunGlow.scale.set(260, 260, 1);
  scene.add(sunGlow);

  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(900, 32, 16),
    new THREE.MeshBasicMaterial({ side: THREE.BackSide, fog: false }),
  );
  sky.name = 'sky-dome';
  scene.add(sky);

  scene.fog = new THREE.FogExp2(0x000000, 0.004);

  function apply(name) {
    const p = THEMES[name];
    let disposed = 0;

    const oldSky = sky.material.map;
    sky.material.map = createSkyTexture(p);
    sky.material.needsUpdate = true;
    if (oldSky) {
      oldSky.dispose();
      disposed++;
    }

    scene.fog.color.set(p.fog);
    scene.fog.density = p.fogDensity;
    hemi.color.set(p.hemiSky);
    hemi.groundColor.set(p.hemiGround);
    hemi.intensity = p.hemi;

    sun.color.set(p.sunColor);
    sun.intensity = p.sunIntensity;
    sun.position.set(...p.sunPos);
    sunGlowMat.color.set(p.sunColor);
    sunGlow.position.set(p.sunPos[0] * 3.2, p.sunPos[1] * 3.2, p.sunPos[2] * 3.2);
    sunGlow.visible = name !== 'night';

    city.facadeMaterials.forEach((m) => (m.emissiveIntensity = p.windows));
    city.neonMaterials.forEach((m) => (m.emissiveIntensity = p.neon));
    city.lampMaterial.emissiveIntensity = p.lamp;
    city.poolMaterial.opacity = p.pool;
    city.groundMaterial.color.set(p.ground);
    forge.lightLevel = p.forgeLight;

    return { disposed, bloom: p.bloom, exposure: p.exposure };
  }

  return { apply, sun, hemi, sky };
}


