import * as THREE from 'three';
import { seededRandom, pick } from './random.js';
import {
  createFacadeTextures,
  createRoadTexture,
  createGroundTexture,
  createGlowTexture,
  tileFacadeUVs,
  scaleUVs,
} from './textures.js';

// Grid of city blocks (9 x 9 minus the forge plaza) separated by 10-unit avenues.
export const BLOCK = 34;
export const PITCH = 44;
export const GRID = 4;
export const ROAD_COORDS = Array.from({ length: 2 * GRID + 2 }, (_, k) => (k - GRID - 0.5) * PITCH);
export const ROAD_EXTENT = 200;

const ROAD_WIDTH = 10;
const LAMP_SIDE = 6.2;
const TREE_TARGET = 78;
const CROSS_OFFSET = 7;
const PLAZA_CLEAR = 17;

const FACADE_SETS = [
  { id: 0, base: '#1f2740', windows: ['#ffd58a', '#ffb050', '#fff1c4'], litChance: 0.52, neon: '#ff4fb8' },
  { id: 1, base: '#26213f', windows: ['#9ff3ff', '#6fd6ff', '#d7f7ff'], litChance: 0.46, neon: '#27e1ff' },
  { id: 2, base: '#2b2435', windows: ['#ff9a6b', '#ffd08a', '#ffc4a0'], litChance: 0.5, neon: '#ffc857' },
  { id: 3, base: '#1a2a33', windows: ['#8cffb0', '#c6ffd6', '#6ef0c2'], litChance: 0.42, neon: '#8cff5a' },
  { id: 4, base: '#2f2d3d', windows: ['#ffe9a8', '#ffd166', '#ffffff'], litChance: 0.55, neon: '#ff7ac6' },
  { id: 5, base: '#16213a', windows: ['#a9c7ff', '#7ea8ff', '#e0ebff'], litChance: 0.48, neon: '#5ad7ff' },
];

const LEAF_COLORS = [0x2f8f4e, 0x3ea85a, 0x267a45, 0x4fae5c];

function mesh(parent, geometry, material, x, y, z, { cast = true, receive = true } = {}) {
  const m = new THREE.Mesh(geometry, material);
  m.position.set(x, y, z);
  m.castShadow = cast;
  m.receiveShadow = receive;
  parent.add(m);
  return m;
}

function overlaps(box, footprints, pad = 0) {
  return footprints.some(
    (f) => box.x0 < f.x1 + pad && box.x1 > f.x0 - pad && box.z0 < f.z1 + pad && box.z1 > f.z0 - pad,
  );
}

function buildRoads(group) {
  const roadLen = ROAD_EXTENT * 2 + ROAD_WIDTH;
  const vertical = new THREE.MeshStandardMaterial({ map: createRoadTexture(false), roughness: 0.82, metalness: 0.05 });
  const horizontal = new THREE.MeshStandardMaterial({ map: createRoadTexture(true), roughness: 0.82, metalness: 0.05 });
  ROAD_COORDS.forEach((c) => {
    const gz = scaleUVs(new THREE.PlaneGeometry(ROAD_WIDTH, roadLen), 1, roadLen / 24);
    const zRoad = mesh(group, gz, vertical, c, 0.02, 0, { cast: false });
    zRoad.rotation.x = -Math.PI / 2;
    const gx = scaleUVs(new THREE.PlaneGeometry(roadLen, ROAD_WIDTH), roadLen / 24, 1);
    const xRoad = mesh(group, gx, horizontal, 0, 0.03, c, { cast: false });
    xRoad.rotation.x = -Math.PI / 2;
  });

  // Zebra crosswalk bars at every intersection, one InstancedMesh for all 2000 bars.
  const bars = [];
  ROAD_COORDS.forEach((cx) => {
    ROAD_COORDS.forEach((cz) => {
      [-1, 1].forEach((dir) => {
        for (let s = -2; s <= 2; s++) {
          bars.push([cx + s * 1.9, cz + dir * CROSS_OFFSET, 1, 3.2]);
          bars.push([cx + dir * CROSS_OFFSET, cz + s * 1.9, 3.2, 1]);
        }
      });
    });
  });
  const barMat = new THREE.MeshStandardMaterial({ color: 0xe9e9e4, roughness: 0.7 });
  const crosswalk = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 0.02, 1), barMat, bars.length);
  const m4 = new THREE.Matrix4();
  const pos = new THREE.Vector3();
  const scl = new THREE.Vector3();
  bars.forEach(([x, z, sx, sz], i) => {
    m4.compose(pos.set(x, 0.05, z), new THREE.Quaternion(), scl.set(sx, 1, sz));
    crosswalk.setMatrixAt(i, m4);
  });
  crosswalk.instanceMatrix.needsUpdate = true;
  crosswalk.receiveShadow = true;
  group.add(crosswalk);
  return crosswalk;
}

function addTower(ctx, x, z, w, h, d, set) {
  const { group, buildings, footprints, roofMat, podiumMat, steelMat } = ctx;
  const tower = new THREE.Group();
  tower.position.set(x, 0, z);
  tower.userData.isBuilding = true;
  tower.userData.height = h;
  group.add(tower);

  const body = tileFacadeUVs(new THREE.BoxGeometry(w, h, d), w, h, d);
  mesh(tower, body, [set.facade, set.facade, roofMat, roofMat, set.facade, set.facade], 0, h / 2, 0);
  mesh(tower, new THREE.BoxGeometry(w * 1.12, 3.2, d * 1.12), podiumMat, 0, 1.6, 0);

  let top = h;
  let cw = w;
  let cd = d;
  if (h > 46) {
    const ch = h * 0.2;
    cw = w * 0.62;
    cd = d * 0.62;
    const crown = tileFacadeUVs(new THREE.BoxGeometry(cw, ch, cd), cw, ch, cd);
    mesh(tower, crown, [set.facade, set.facade, roofMat, roofMat, set.facade, set.facade], 0, h + ch / 2, 0);
    top = h + ch;
  }

  // Rooftop neon trim frame.
  const trimY = top + 0.25;
  mesh(tower, new THREE.BoxGeometry(cw + 0.5, 0.5, 0.5), set.neon, 0, trimY, cd / 2 + 0.25, { cast: false });
  mesh(tower, new THREE.BoxGeometry(cw + 0.5, 0.5, 0.5), set.neon, 0, trimY, -(cd / 2 + 0.25), { cast: false });
  mesh(tower, new THREE.BoxGeometry(0.5, 0.5, cd + 0.5), set.neon, cw / 2 + 0.25, trimY, 0, { cast: false });
  mesh(tower, new THREE.BoxGeometry(0.5, 0.5, cd + 0.5), set.neon, -(cw / 2 + 0.25), trimY, 0, { cast: false });

  if (ctx.rnd() < 0.3 && h > 30) {
    mesh(tower, new THREE.CylinderGeometry(3, 3, 0.3, 20), steelMat, 0, top + 0.15, 0);
  }
  if (ctx.rnd() < 0.45 || h > 60) {
    const sh = 6 + ctx.rnd() * 8;
    mesh(tower, new THREE.CylinderGeometry(0.04, 0.5, sh, 20), steelMat, 0, top + sh / 2, 0);
    mesh(tower, new THREE.SphereGeometry(0.3, 20, 16), set.neon, 0, top + sh, 0, { cast: false });
  }

  buildings.push(tower);
  footprints.push({ x0: x - w / 2 - 2, x1: x + w / 2 + 2, z0: z - d / 2 - 2, z1: z + d / 2 + 2 });
  return tower;
}

function buildTowers(ctx) {
  const { rnd, facadeSets } = ctx;
  for (let i = -GRID; i <= GRID; i++) {
    for (let j = -GRID; j <= GRID; j++) {
      if (i === 0 && j === 0) continue;
      if ((((i + 2 * j) % 4) + 4) % 4 === 0) continue; // park blocks stay green for trees
      const cx = i * PITCH;
      const cz = j * PITCH;
      if (Math.hypot(cx, cz) < 34) continue; // Keep central plaza & inner avenue ring open for clear sightlines
      const set = pick(rnd, facadeSets).variant;
      const fw = 12 + rnd() * 8;
      const fd = 12 + rnd() * 8;
      const h = 16 + Math.pow(rnd(), 1.4) * 72;
      const ox = (rnd() - 0.5) * (BLOCK - fw - 4);
      const oz = (rnd() - 0.5) * (BLOCK - fd - 4);
      const setObj = facadeSets[set.id];
      addTower(ctx, cx + ox, cz + oz, fw, h, fd, setObj);
      if (rnd() < 0.35) {
        const sw = 7 + rnd() * 3;
        const sd = 7 + rnd() * 3;
        for (let attempt = 0; attempt < 6; attempt++) {
          const sx = cx + (rnd() - 0.5) * (BLOCK - sw - 2);
          const sz = cz + (rnd() - 0.5) * (BLOCK - sd - 2);
          const box = { x0: sx - sw / 2, x1: sx + sw / 2, z0: sz - sd / 2, z1: sz + sd / 2 };
          if (!overlaps(box, ctx.footprints)) {
            addTower(ctx, sx, sz, sw, 12 + rnd() * 24, sd, setObj);
            break;
          }
        }
      }
    }
  }
}

function buildTrees(ctx) {
  const { group, rnd, footprints, trees } = ctx;
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x5a3b22, roughness: 0.9 });
  const leafMats = LEAF_COLORS.map((c) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.8 }));
  const treeGroup = new THREE.Group();
  treeGroup.name = 'trees';
  group.add(treeGroup);

  const spotFree = (x, z) => {
    if (Math.hypot(x, z) < PLAZA_CLEAR) return false;
    if (overlaps({ x0: x - 1.2, x1: x + 1.2, z0: z - 1.2, z1: z + 1.2 }, footprints)) return false;
    return trees.every((t) => Math.hypot(t.position.x - x, t.position.z - z) > 3.4);
  };

  const trunkGeo = new THREE.CylinderGeometry(0.32, 0.45, 3.2, 10);
  const leafGeoA = new THREE.SphereGeometry(2.4, 12, 10);
  const leafGeoB = new THREE.SphereGeometry(1.7, 10, 8);
  for (let pass = 0; pass < 8 && trees.length < TREE_TARGET; pass++) {
    for (let i = -GRID; i <= GRID; i++) {
      for (let j = -GRID; j <= GRID; j++) {
        if (trees.length >= TREE_TARGET) return;
        const x = i * PITCH + (rnd() - 0.5) * (BLOCK - 6);
        const z = j * PITCH + (rnd() - 0.5) * (BLOCK - 6);
        if (!spotFree(x, z)) continue;
        const s = 0.85 + rnd() * 0.35;
        const tree = new THREE.Group();
        tree.position.set(x, 0, z);
        tree.rotation.y = rnd() * Math.PI * 2;
        tree.scale.setScalar(s);
        tree.userData.isTree = true;
        mesh(tree, trunkGeo, trunkMat, 0, 1.6, 0, { cast: false, receive: false });
        mesh(tree, leafGeoA, pick(rnd, leafMats), 0, 4.4, 0, { cast: false, receive: true });
        mesh(tree, leafGeoB, pick(rnd, leafMats), 1.0, 5.9, 0.4, { cast: false, receive: false });
        treeGroup.add(tree);
        trees.push(tree);
      }
    }
  }
}

function buildLamps(ctx) {
  const { group, footprints, lamps, lampSpots } = ctx;
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x2b2f3d, roughness: 0.5, metalness: 0.6 });
  const bulbMat = new THREE.MeshStandardMaterial({ color: 0xffe2a8, emissive: 0xffc46b, emissiveIntensity: 3, roughness: 0.3 });
  const poleGeo = new THREE.CylinderGeometry(0.09, 0.14, 6, 10);
  const bulbGeo = new THREE.SphereGeometry(0.42, 10, 8);
  const lampGroup = new THREE.Group();
  lampGroup.name = 'lamps';
  group.add(lampGroup);

  // One lamp per block side on every avenue (z-avenues) and every other avenue (x-avenues).
  const spots = [];
  ROAD_COORDS.forEach((r) => {
    for (let k = -4; k <= 4; k++) spots.push([r + LAMP_SIDE, k * PITCH]);
  });
  ROAD_COORDS.forEach((r, idx) => {
    if (idx % 2) return;
    for (let k = -4; k <= 4; k++) spots.push([k * PITCH, r + LAMP_SIDE]);
  });

  spots.forEach(([x, z]) => {
    if (overlaps({ x0: x - 0.8, x1: x + 0.8, z0: z - 0.8, z1: z + 0.8 }, footprints)) return;
    const lamp = new THREE.Group();
    lamp.position.set(x, 0, z);
    lamp.userData.isStreetlamp = true;
    mesh(lamp, poleGeo, poleMat, 0, 3, 0, { cast: false, receive: false });
    mesh(lamp, bulbGeo, bulbMat, 0, 6.25, 0, { cast: false, receive: false });
    lampGroup.add(lamp);
    lamps.push(lamp);
    lampSpots.push({ x, z });
  });

  const poolMat = new THREE.MeshBasicMaterial({
    map: createGlowTexture('lamp-pool', '255,190,110'),
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    opacity: 0.85,
  });
  const pools = new THREE.InstancedMesh(new THREE.CircleGeometry(4.6, 24), poolMat, lampSpots.length);
  const m4 = new THREE.Matrix4();
  const rot = new THREE.Quaternion().setFromEuler(new THREE.Euler(-Math.PI / 2, 0, 0));
  lampSpots.forEach((p, i) => {
    m4.compose(new THREE.Vector3(p.x, 0.06, p.z), rot, new THREE.Vector3(1, 1, 1));
    pools.setMatrixAt(i, m4);
  });
  pools.instanceMatrix.needsUpdate = true;
  pools.name = 'lamp-pools';
  group.add(pools);
  return { bulbMat, poolMat };
}

export function buildCity(scene) {
  const rnd = seededRandom(20260611);
  const group = new THREE.Group();
  group.name = 'moru-city';

  const groundMaterial = new THREE.MeshStandardMaterial({ map: createGroundTexture(), roughness: 0.95, metalness: 0 });
  const ground = scaleUVs(new THREE.PlaneGeometry(540, 540), 36, 36);
  const groundMesh = new THREE.Mesh(ground, groundMaterial);
  groundMesh.rotation.x = -Math.PI / 2;
  groundMesh.position.y = -0.02;
  groundMesh.receiveShadow = true;
  group.add(groundMesh);

  buildRoads(group);

  const facadeSets = FACADE_SETS.map((variant) => {
    const { map, emissiveMap } = createFacadeTextures(variant);
    return {
      variant,
      facade: new THREE.MeshStandardMaterial({ map, emissiveMap, emissive: 0xffffff, emissiveIntensity: 1, roughness: 0.42, metalness: 0.2 }),
      neon: new THREE.MeshStandardMaterial({ color: variant.neon, emissive: variant.neon, emissiveIntensity: 1, roughness: 0.3 }),
    };
  });

  const ctx = {
    group,
    rnd,
    facadeSets,
    footprints: [],
    buildings: [],
    trees: [],
    lamps: [],
    lampSpots: [],
    roofMat: new THREE.MeshStandardMaterial({ color: 0x161a26, roughness: 0.75, metalness: 0.35 }),
    podiumMat: new THREE.MeshStandardMaterial({ color: 0x3b4152, roughness: 0.6, metalness: 0.2 }),
    steelMat: new THREE.MeshStandardMaterial({ color: 0x9aa3b5, roughness: 0.3, metalness: 0.85 }),
  };

  buildTowers(ctx);
  buildTrees(ctx);
  const { bulbMat, poolMat } = buildLamps(ctx);

  scene.add(group);
  return {
    group,
    buildings: ctx.buildings,
    trees: ctx.trees,
    lamps: ctx.lamps,
    footprints: ctx.footprints,
    facadeMaterials: facadeSets.map((s) => s.facade),
    neonMaterials: facadeSets.map((s) => s.neon),
    lampMaterial: bulbMat,
    poolMaterial: poolMat,
    groundMaterial,
  };
}


