import * as THREE from 'three';
import { seededRandom } from './random.js';
import { createRuneTexture } from './textures.js';

const EMBER_COUNT = 150;
const SPARK_START = 110;
const SHOCK_COUNT = 3;
const HAMMER_IDLE = 1.1;
const HAMMER_STRIKE = -0.7;
const STRIKE_TIME = 0.55;
const ANVIL_TOP = 1.5;

// Central Moru Blacksmith Anvil Forge: tiered dais, rune circle, magma braziers,
// anvil with heated ingot, swinging hammer, shockwave rings, and particle embers.
export function buildForge(scene) {
  const rnd = seededRandom(7331);
  const group = new THREE.Group();
  group.name = 'moru-forge';
  group.userData.isForge = true;

  const stone = new THREE.MeshStandardMaterial({ color: 0x4b4f5c, roughness: 0.85, metalness: 0.1 });
  const stoneDark = new THREE.MeshStandardMaterial({ color: 0x2a2d38, roughness: 0.9, metalness: 0.05 });
  const steel = new THREE.MeshStandardMaterial({ color: 0x9aa4b8, roughness: 0.35, metalness: 0.85 });
  const iron = new THREE.MeshStandardMaterial({ color: 0x3c4150, roughness: 0.45, metalness: 0.7 });
  const wood = new THREE.MeshStandardMaterial({ color: 0x6b4423, roughness: 0.9 });
  const magma = new THREE.MeshStandardMaterial({ color: 0xff5a10, emissive: 0xff4a00, emissiveIntensity: 2.6, roughness: 0.4 });
  const ingotMat = new THREE.MeshStandardMaterial({ color: 0xffa040, emissive: 0xffa040, emissiveIntensity: 3.2, roughness: 0.5 });
  const runeMat = new THREE.MeshBasicMaterial({
    map: createRuneTexture(),
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    opacity: 0.9,
  });

  const add = (parent, geo, mat, x, y, z, { rx = 0, ry = 0, rz = 0, cast = true } = {}) => {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(x, y, z);
    m.rotation.set(rx, ry, rz);
    m.castShadow = cast;
    m.receiveShadow = true;
    parent.add(m);
    return m;
  };

  // Tiered stone dais: three stacked drums, each 0.5 units tall.
  [
    [15, 0.25],
    [11, 0.75],
    [7, 1.25],
  ].forEach(([r, y], i) => {
    add(group, new THREE.CylinderGeometry(r, r * 1.03, 0.5, 20), i === 0 ? stoneDark : stone, 0, y, 0);
  });

  const rune = add(group, new THREE.CircleGeometry(12.6, 64), runeMat, 0, 0.52, 0, { rx: -Math.PI / 2, cast: false });
  rune.receiveShadow = false;

  // Four magma braziers around the plaza, each a stone pedestal with a glowing bowl.
  for (let k = 0; k < 4; k++) {
    const a = Math.PI / 4 + (k * Math.PI) / 2;
    const bx = Math.cos(a) * 12.4;
    const bz = Math.sin(a) * 12.4;
    add(group, new THREE.CylinderGeometry(0.7, 0.9, 1.4, 20), stoneDark, bx, 1.2, bz);
    add(group, new THREE.CylinderGeometry(0.95, 0.95, 0.14, 20), magma, bx, 1.92, bz, { cast: false });
    add(group, new THREE.SphereGeometry(0.6, 20, 16), magma, bx, 2.1, bz, { cast: false });
  }

  // Anvil stands on the top dais.
  const anvil = new THREE.Group();
  anvil.name = 'anvil';
  anvil.userData.isAnvil = true;
  group.add(anvil);
  const A = ANVIL_TOP;
  add(anvil, new THREE.BoxGeometry(1.6, 0.9, 1.1), iron, 0, A + 0.45, 0);
  add(anvil, new THREE.CylinderGeometry(0.42, 0.62, 0.55, 20), iron, 0, A + 1.175, 0);
  add(anvil, new THREE.BoxGeometry(2.5, 0.42, 1.2), steel, 0, A + 1.66, 0);
  add(anvil, new THREE.CylinderGeometry(0.03, 0.34, 1.15, 20), steel, 1.82, A + 1.66, 0, { rz: -Math.PI / 2 });
  add(anvil, new THREE.BoxGeometry(0.4, 0.36, 1.2), steel, -1.45, A + 1.66, 0);
  const ingot = add(anvil, new THREE.BoxGeometry(0.9, 0.16, 0.48), ingotMat, 0.2, A + 1.95, 0, { cast: false });
  ingot.castShadow = false;

  // Hammer pivots at the heel; rotation.z sweeps the head from raised to strike.
  const hammerPivot = new THREE.Group();
  hammerPivot.position.set(-1.6, A + 2.1, 0);
  group.add(hammerPivot);
  add(hammerPivot, new THREE.CylinderGeometry(0.07, 0.07, 2.0, 16), wood, 0, 1.0, 0);
  add(hammerPivot, new THREE.BoxGeometry(0.55, 0.5, 1.0), iron, 0, 2.05, 0);
  hammerPivot.rotation.z = HAMMER_IDLE;

  // Shockwave rings expand off the anvil when the hammer lands.
  const shocks = [];
  for (let i = 0; i < SHOCK_COUNT; i++) {
    const mat = new THREE.MeshBasicMaterial({
      color: 0xffa040,
      transparent: true,
      opacity: 0,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    const ring = add(group, new THREE.TorusGeometry(1, 0.06, 8, 64), mat, 0, A + 0.05, 0, { rx: Math.PI / 2, cast: false });
    ring.visible = false;
    shocks.push({ mesh: ring, age: 1 });
  }

  // Ember particles: one InstancedMesh; first SPARK_START are rising embers, the rest are strike sparks.
  const emberMat = new THREE.MeshBasicMaterial({ color: 0xffa040, toneMapped: false });
  const embers = new THREE.InstancedMesh(new THREE.SphereGeometry(0.11, 8, 6), emberMat, EMBER_COUNT);
  embers.name = 'forge-embers';
  embers.frustumCulled = false;
  group.add(embers);

  // Floating neon holo-rings above the anvil that spin visibly in overview mode
  const holoGroup = new THREE.Group();
  holoGroup.position.set(0, A + 5.2, 0);
  const holoMatCyan = new THREE.MeshBasicMaterial({ color: 0x27e1ff, toneMapped: false });
  const holoMatPink = new THREE.MeshBasicMaterial({ color: 0xff4fb8, toneMapped: false });
  const holoRing1 = add(holoGroup, new THREE.TorusGeometry(3.2, 0.08, 10, 48), holoMatCyan, 0, 0, 0, { rx: Math.PI / 2, cast: false });
  const holoRing2 = add(holoGroup, new THREE.TorusGeometry(2.4, 0.07, 10, 48), holoMatPink, 0, 0, 0, { rx: Math.PI / 3, cast: false });
  group.add(holoGroup);
  const particles = Array.from({ length: EMBER_COUNT }, () => ({ x: 0, y: -10, z: 0, vx: 0, vy: 0, vz: 0, life: 0, max: 1 }));
  const m4 = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const sc = new THREE.Vector3();
  const ps = new THREE.Vector3();

  const light = new THREE.PointLight(0xff8a3c, 40, 60, 1.6);
  light.position.set(0, 3.6, 0);
  group.add(light);

  scene.add(group);

  const spawnRising = (p) => {
    const a = rnd() * Math.PI * 2;
    const r = 3 + rnd() * 8;
    p.x = Math.cos(a) * r;
    p.z = Math.sin(a) * r;
    p.y = 1 + rnd() * 1.5;
    p.vx = (rnd() - 0.5) * 0.4;
    p.vy = 0.6 + rnd() * 1.4;
    p.vz = (rnd() - 0.5) * 0.4;
    p.max = 2.5 + rnd() * 2.5;
    p.life = p.max;
  };
  const spawnSpark = (p) => {
    p.x = 0.2;
    p.y = A + 2.0;
    p.z = 0;
    p.vx = (rnd() - 0.5) * 7;
    p.vy = 3 + rnd() * 5;
    p.vz = (rnd() - 0.5) * 6;
    p.max = 1.2 + rnd() * 0.8;
    p.life = p.max;
  };
  particles.forEach((p, i) => (i < SPARK_START ? spawnRising(p) : (p.life = 0)));

  let strikeT = -1;
  let sparkCursor = 0;

  const forge = {
    group,
    anvil,
    hammerPivot,
    light,
    lightLevel: 1,
    strikes: 0,

    strike() {
      strikeT = 0;
      forge.strikes++;
      for (let i = 0; i < 40; i++) {
        const idx = SPARK_START + ((sparkCursor + i) % (EMBER_COUNT - SPARK_START));
        spawnSpark(particles[idx]);
      }
      sparkCursor = (sparkCursor + 40) % (EMBER_COUNT - SPARK_START);
      const ring = shocks.find((s) => s.age >= 1) || shocks[0];
      ring.age = 0;
      ring.mesh.visible = true;
    },

    update(dt, t) {
      // Hammer: raised idle sway, then a downward swing with an impact flash at the bottom.
      if (strikeT >= 0) {
        strikeT += dt;
        const p = Math.min(strikeT / STRIKE_TIME, 1);
        const down = p < 0.5 ? p / 0.5 : 1 - (p - 0.5) / 0.5;
        const ease = down * down * (3 - 2 * down);
        hammerPivot.rotation.z = THREE.MathUtils.lerp(HAMMER_IDLE, HAMMER_STRIKE, ease);
        if (p >= 1) strikeT = -1;
      } else {
        hammerPivot.rotation.z = HAMMER_IDLE + Math.sin(t * 2.2) * 0.12;
      }
      rune.rotation.z = t * 0.45;
      holoRing1.rotation.z = t * 1.4;
      holoRing1.rotation.x = Math.PI / 2 + Math.sin(t * 1.1) * 0.35;
      holoRing2.rotation.y = -t * 1.8;
      holoGroup.position.y = A + 5.2 + Math.sin(t * 2.0) * 0.35;
      light.intensity = (40 + Math.sin(t * 7.1) * 4 + (strikeT >= 0 ? 35 : 0)) * forge.lightLevel;

      shocks.forEach((s) => {
        if (s.age >= 1) {
          s.mesh.visible = false;
          return;
        }
        s.age = Math.min(1, s.age + dt / 0.9);
        const k = 1 + s.age * 13;
        s.mesh.scale.set(k, k, 1);
        s.mesh.material.opacity = (1 - s.age) * 0.9;
      });

      for (let i = 0; i < EMBER_COUNT; i++) {
        const p = particles[i];
        if (dt > 0) {
          p.life -= dt;
          if (i >= SPARK_START) p.vy -= 9.8 * dt;
          p.x += p.vx * dt;
          p.y += p.vy * dt;
          p.z += p.vz * dt;
          if (i >= SPARK_START && p.y < 0.6) {
            p.y = 0.6;
            p.vy = -p.vy * 0.45;
            p.vx *= 0.8;
            p.vz *= 0.8;
          }
          if (i < SPARK_START && p.life <= 0) spawnRising(p);
        }
        const alive = p.life > 0;
        const s = alive ? 0.45 + 0.55 * (p.life / p.max) : 0;
        ps.set(p.x, p.y, p.z);
        sc.set(s, s, s);
        m4.compose(ps, q, sc);
        embers.setMatrixAt(i, m4);
      }
      embers.instanceMatrix.needsUpdate = true;
    },
  };
  return forge;
}


