import * as THREE from 'three';
import { seededRandom } from './random.js';

// Procedural CanvasTexture factory. Static textures are cached so that
// 80+ towers share six facade canvases instead of allocating new ones.
const cache = new Map();

function cached(key, make) {
  if (!cache.has(key)) cache.set(key, make());
  return cache.get(key);
}

function makeCanvas(w, h) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  return c;
}

function toTexture(canvas, { repeat = false, anisotropy = 4 } = {}) {
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  if (repeat) tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.anisotropy = anisotropy;
  return tex;
}

// Multi-color illuminated skyscraper facade: a lit-window albedo map plus an
// emissive map that carries only the glowing windows and neon floor bands.
export function createFacadeTextures(variant) {
  return cached(`facade:${variant.id}`, () => {
    const W = 256;
    const H = 512;
    const cols = 8;
    const rows = 16;
    const albedo = makeCanvas(W, H);
    const emissive = makeCanvas(W, H);
    const g = albedo.getContext('2d');
    const e = emissive.getContext('2d');
    const rnd = seededRandom(900 + variant.id * 17);
    const cw = W / cols;
    const ch = H / rows;

    g.fillStyle = variant.base;
    g.fillRect(0, 0, W, H);
    e.fillStyle = '#000';
    e.fillRect(0, 0, W, H);

    for (let r = 0; r < rows; r++) {
      for (let k = 0; k < cols; k++) {
        const x = k * cw + cw * 0.2;
        const y = r * ch + ch * 0.22;
        const w = cw * 0.6;
        const h = ch * 0.5;
        g.fillStyle = 'rgba(8,12,26,0.92)';
        g.fillRect(x, y, w, h);
        if (rnd() < variant.litChance) {
          const col = variant.windows[Math.floor(rnd() * variant.windows.length)];
          g.fillStyle = col;
          g.fillRect(x, y, w, h);
          e.fillStyle = col;
          e.fillRect(x, y, w, h);
          if (rnd() < 0.22) {
            g.fillStyle = 'rgba(255,255,255,0.35)';
            g.fillRect(x + w * 0.1, y + h * 0.1, w * 0.22, h * 0.35);
          }
        }
      }
      if (r % 4 === 3) {
        const band = r * ch + ch * 0.9;
        g.fillStyle = variant.neon;
        g.fillRect(0, band, W, 5);
        e.fillStyle = variant.neon;
        e.fillRect(0, band, W, 5);
      }
    }

    const shade = g.createLinearGradient(0, 0, 0, H);
    shade.addColorStop(0, 'rgba(255,255,255,0.10)');
    shade.addColorStop(1, 'rgba(0,0,0,0.30)');
    g.fillStyle = shade;
    g.fillRect(0, 0, W, H);

    return { map: toTexture(albedo, { repeat: true }), emissiveMap: toTexture(emissive, { repeat: true }) };
  });
}

// Asphalt with a dashed yellow centre line and white edge lines.
// `horizontal` rotates the markings for roads that run along the X axis.
export function createRoadTexture(horizontal) {
  return cached(`road:${horizontal ? 'h' : 'v'}`, () => {
    const S = 256;
    const c = makeCanvas(S, S);
    const g = c.getContext('2d');
    const rnd = seededRandom(77);
    g.fillStyle = '#23262e';
    g.fillRect(0, 0, S, S);
    for (let i = 0; i < 260; i++) {
      g.fillStyle = rnd() < 0.5 ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.14)';
      g.fillRect(rnd() * S, rnd() * S, 2 + rnd() * 3, 2 + rnd() * 3);
    }
    g.fillStyle = '#f5c542';
    for (let d = 0; d < S; d += 64) {
      if (horizontal) g.fillRect(d, S / 2 - 3, 36, 6);
      else g.fillRect(S / 2 - 3, d, 6, 36);
    }
    g.fillStyle = 'rgba(240,240,240,0.75)';
    if (horizontal) {
      g.fillRect(0, 8, S, 4);
      g.fillRect(0, S - 12, S, 4);
    } else {
      g.fillRect(8, 0, 4, S);
      g.fillRect(S - 12, 0, 4, S);
    }
    return toTexture(c, { repeat: true });
  });
}

// Concrete slab tile used for the city ground plane.
export function createGroundTexture() {
  return cached('ground', () => {
    const S = 512;
    const c = makeCanvas(S, S);
    const g = c.getContext('2d');
    const rnd = seededRandom(5);
    g.fillStyle = '#5b606c';
    g.fillRect(0, 0, S, S);
    for (let i = 0; i < 900; i++) {
      g.fillStyle = rnd() < 0.5 ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.12)';
      g.fillRect(rnd() * S, rnd() * S, 2 + rnd() * 4, 2 + rnd() * 4);
    }
    g.strokeStyle = 'rgba(20,22,30,0.35)';
    g.lineWidth = 3;
    g.strokeRect(0, 0, S, S);
    return toTexture(c, { repeat: true });
  });
}

// Glowing rune ring for the forge plaza: concentric bands plus runic glyph strokes.
export function createRuneTexture() {
  return cached('rune', () => {
    const S = 512;
    const R = S / 2;
    const c = makeCanvas(S, S);
    const g = c.getContext('2d');
    const rnd = seededRandom(31);
    g.translate(R, R);
    g.strokeStyle = '#ffb347';
    g.shadowColor = '#ff7a1a';
    g.shadowBlur = 18;
    g.lineCap = 'round';
    g.lineWidth = 7;
    g.beginPath();
    g.arc(0, 0, R * 0.92, 0, Math.PI * 2);
    g.stroke();
    g.lineWidth = 4;
    g.beginPath();
    g.arc(0, 0, R * 0.8, 0, Math.PI * 2);
    g.stroke();
    g.beginPath();
    g.arc(0, 0, R * 0.6, 0, Math.PI * 2);
    g.stroke();
    g.lineWidth = 5;
    for (let k = 0; k < 24; k++) {
      g.save();
      g.rotate((k / 24) * Math.PI * 2);
      for (let s = 0; s < 3; s++) {
        const r0 = R * 0.64;
        const r1 = R * 0.76;
        const y0 = (rnd() - 0.5) * R * 0.14;
        const y1 = (rnd() - 0.5) * R * 0.14;
        g.beginPath();
        g.moveTo(r0, y0);
        g.lineTo(r1, y1);
        g.stroke();
      }
      g.restore();
    }
    return toTexture(c);
  });
}

// Soft radial falloff used for light pools, lamp halos and the sun glow.
export function createGlowTexture(key, rgb) {
  return cached(`glow:${key}`, () => {
    const S = 128;
    const c = makeCanvas(S, S);
    const g = c.getContext('2d');
    const grd = g.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
    grd.addColorStop(0, `rgba(${rgb},1)`);
    grd.addColorStop(0.35, `rgba(${rgb},0.55)`);
    grd.addColorStop(1, `rgba(${rgb},0)`);
    g.fillStyle = grd;
    g.fillRect(0, 0, S, S);
    return toTexture(c);
  });
}

// Sky gradient per theme. Not cached: the atmosphere disposes it on every switch.
export function createSkyTexture(preset) {
  const c = makeCanvas(4, 512);
  const g = c.getContext('2d');
  const grad = g.createLinearGradient(0, 0, 0, 512);
  grad.addColorStop(0, preset.skyTop);
  grad.addColorStop(0.55, preset.skyMid || preset.skyBottom);
  grad.addColorStop(1, preset.skyBottom);
  g.fillStyle = grad;
  g.fillRect(0, 0, 4, 512);
  if (preset.stars) {
    const rnd = seededRandom(99);
    for (let i = 0; i < 220; i++) {
      const y = Math.pow(rnd(), 1.6) * 300;
      g.fillStyle = `rgba(255,255,255,${0.35 + rnd() * 0.65})`;
      g.fillRect(rnd() * 4, y, 1, 1 + (rnd() < 0.1 ? 1 : 0));
    }
  }
  return toTexture(c);
}

// Scales a PlaneGeometry/BoxGeometry UV so one texture tile spans `su` x `sv` repeats.
export function scaleUVs(geometry, su, sv) {
  const uv = geometry.attributes.uv;
  for (let i = 0; i < uv.count; i++) uv.setXY(i, uv.getX(i) * su, uv.getY(i) * sv);
  uv.needsUpdate = true;
  return geometry;
}

// Facade tiling for a BoxGeometry: side faces repeat per tile width/height in world units,
// so windows keep a constant real-world size across towers of any footprint.
export function tileFacadeUVs(geometry, w, h, d, tileW = 12, tileH = 14) {
  const uv = geometry.attributes.uv;
  const normal = geometry.attributes.normal;
  for (let i = 0; i < uv.count; i++) {
    const sideIsX = Math.abs(normal.getX(i)) > 0.5;
    const faceW = sideIsX ? d : w;
    uv.setXY(i, uv.getX(i) * (faceW / tileW), uv.getY(i) * (h / tileH));
  }
  uv.needsUpdate = true;
  return geometry;
}


