/* =====================================================================
 * Moru 3D Neon Forge City & Animated Cat Village
 * ---------------------------------------------------------------------
 * A procedural neon city built around the Moru Blacksmith Anvil Forge
 * plaza, populated by low-poly Moru Cats that run, hop and gather at
 * the anvil whenever the hammer falls.
 *
 *   Three.js + Vite.  Entry point: src/main.js
 * ===================================================================== */

import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

/* ---------------------------------------------------------------------
 * 1. Configuration
 * ------------------------------------------------------------------- */

const CONFIG = {
  grid: 5,            // city blocks per axis
  block: 26,          // building block footprint
  road: 10,           // road width
  plazaRadius: 16,    // Moru forge plaza radius
  maxCats: 48,
  initialCats: 6,
  sparkCount: 620,
  shockwaves: 6,
};

