function makeCanvas(w, h) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  return { c, ctx: c.getContext('2d') };
}

/** Facade: returns { map, emissiveMap } with a lit-window pattern. */
function makeFacade(variant) {
  const W = 128;
  const H = 256;
  const cols = [4, 5, 6, 3][variant % 4];
  const rows = [14, 18, 12, 16][variant % 4];
  const wallTone = [0x1b2030, 0x151a28, 0x222838, 0x191d2b][variant % 4];

  const base = makeCanvas(W, H);
  const emis = makeCanvas(W, H);

  const wall = new THREE.Color(wallTone);
  base.ctx.fillStyle = `#${wall.getHexString()}`;
  base.ctx.fillRect(0, 0, W, H);

  // concrete speckle
  for (let i = 0; i < 1400; i++) {
    const a = Math.random() * 0.06;
    base.ctx.fillStyle = `rgba(255,255,255,${a.toFixed(3)})`;
    base.ctx.fillRect(Math.random() * W, Math.random() * H, 1, 1);
  }

  emis.ctx.fillStyle = '#000000';
  emis.ctx.fillRect(0, 0, W, H);

  const padX = W * 0.1;
  const padY = H * 0.035;
  const cw = (W - padX * 2) / cols;
  const ch = (H - padY * 2) / rows;
  const winW = cw * 0.6;
  const winH = ch * 0.5;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const x = padX + c * cw + (cw - winW) / 2;
      const y = padY + r * ch + (ch - winH) / 2;
      const lit = Math.random() < 0.62;

      base.ctx.fillStyle = lit ? 'rgba(210,245,255,0.92)' : 'rgba(10,14,24,0.95)';
      base.ctx.fillRect(x, y, winW, winH);

      if (lit) {
        const warm = Math.random();
        const g = 190 + Math.floor(Math.random() * 60);
        emis.ctx.fillStyle =
          warm < 0.2 ? `rgb(255,${g - 40},150)` :
          warm < 0.42 ? `rgb(150,${g},255)` :
          `rgb(190,${g + 20},255)`;
        emis.ctx.fillRect(x, y, winW, winH);
        emis.ctx.fillStyle = 'rgba(255,255,255,0.35)';
        emis.ctx.fillRect(x, y, winW, winH * 0.25);
      }
    }
    // occasional floor band
    if (r % 5 === 4) {
      base.ctx.fillStyle = 'rgba(0,0,0,0.35)';
      base.ctx.fillRect(0, padY + r * ch + ch * 0.9, W, 2);
    }
  }

  const mk = (cv) => {
    const t = new THREE.CanvasTexture(cv);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.colorSpace = THREE.SRGBColorSpace;
    t.anisotropy = 4;
    return t;
  };

  return { map: mk(base.c), emissiveMap: mk(emis.c) };
}

/** Soft radial sprite used for sparks, embers and lamp glows. */
function makeGlowTexture(inner = 'rgba(255,255,255,1)', mid = 'rgba(255,190,90,0.65)') {
  const { c, ctx } = makeCanvas(64, 64);
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0.0, inner);
  g.addColorStop(0.35, mid);
  g.addColorStop(1.0, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/** Neon billboard sign texture. */
function makeSignTexture(text, colorA, colorB) {
  const { c, ctx } = makeCanvas(512, 256);
  ctx.fillStyle = '#05060c';
  ctx.fillRect(0, 0, 512, 256);
  ctx.strokeStyle = colorA;
  ctx.lineWidth = 8;
  ctx.strokeRect(16, 16, 480, 224);
  const grd = ctx.createLinearGradient(0, 0, 512, 256);
  grd.addColorStop(0, colorA);
  grd.addColorStop(1, colorB);
  ctx.fillStyle = grd;
  ctx.font = 'bold 118px "SF Mono", monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 256, 132);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/** Plaza floor: concentric rings + radial spokes + anvil rune. */
function makePlazaTexture() {
  const S = 512;
  const { c, ctx } = makeCanvas(S, S);
  ctx.fillStyle = '#14161f';
  ctx.fillRect(0, 0, S, S);

  // stone tiles
  for (let i = 0; i < 2600; i++) {
    ctx.fillStyle = `rgba(255,255,255,${(Math.random() * 0.05).toFixed(3)})`;
    ctx.fillRect(Math.random() * S, Math.random() * S, 2, 2);
  }

  ctx.translate(S / 2, S / 2);
  for (let r = 40; r < 250; r += 34) {
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, TAU);
    ctx.strokeStyle = 'rgba(82,246,255,0.26)';
    ctx.lineWidth = r % 68 === 40 ? 3 : 1.5;
    ctx.stroke();
  }
  for (let i = 0; i < 16; i++) {
    ctx.save();
    ctx.rotate((i / 16) * TAU);
    ctx.strokeStyle = 'rgba(255,94,196,0.18)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(44, 0);
    ctx.lineTo(248, 0);
    ctx.stroke();
    ctx.restore();
  }
  ctx.fillStyle = 'rgba(255,181,69,0.5)';
  ctx.font = 'bold 86px serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('⚒', 0, 4);

  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

