// ====== src/entities/moruCat.js (19555 bytes) ======
/**
 * moruCat.js — Expressive Chibi 3D "Moru Cat" factory + quadruped locomotion.
 *
 * Every cat is a THREE.Group tagged `userData.isMoruCat = true`. Parts are
 * attached directly to the cat root (or to a small animation pivot) so the
 * rig stays flat and inspectable — 30+ meshes per cat:
 *
 *   rounded torso · belly patch · chest ruff · haunch · 2 shoulder blades ·
 *   2 back stripes · chibi head · 2 puffy cheeks · muzzle · 2 pointed ears +
 *   2 inner-ear details · 2 big glossy eyes · 2 pupils · 2 white catchlights ·
 *   pink snout · nose bridge · 4 whiskers · collar + golden bell (+ slit,
 *   loop) · blacksmith helmet (dome, brim, crest, visor, 4 rivets) ·
 *   4 articulated legs with paws · 4-segment wagging tail + tail tip
 *
 * Locomotion: cats trot and hop along the city avenues, swinging their legs
 * and tail every frame, flicking ears, blinking and jingling the bell, and
 * doing a celebratory backflip when the anvil is struck.
 */
import * as THREE from 'three';
import { CITY } from '../world/city.js';

const FUR_PALETTE = [
  { fur: 0xf6d9a8, belly: 0xfff3dd, ear: 0xffb0b8, name: 'cream' },
  { fur: 0x7e8ea8, belly: 0xdbe4f0, ear: 0xf2a8c0, name: 'slate' },
  { fur: 0xd98c4a, belly: 0xffe2bd, ear: 0xffa8b4, name: 'ginger' },
  { fur: 0x4a4f5e, belly: 0xc3ccdb, ear: 0xe892ac, name: 'soot' },
  { fur: 0xf4f7ff, belly: 0xffffff, ear: 0xffb6c4, name: 'snow' },
  { fur: 0xa9754a, belly: 0xf6dcbb, ear: 0xffaab6, name: 'bronze' },
  { fur: 0x9b82c4, belly: 0xe8dcff, ear: 0xffb0d0, name: 'violet' },
  { fur: 0x5fa38c, belly: 0xd6f1e6, ear: 0xffb2c2, name: 'jade' },
];

const HELMET_TINTS = [0x9aa3b4, 0xb0764a, 0x79818f, 0xc9a24a, 0xa8b4c6];

const BODY_Y = 0.98;   // standing height of the torso centre

let CAT_SERIAL = 0;

/* ------------------------------------------------------------------ */
/* factory                                                            */
/* ------------------------------------------------------------------ */

/** Builds one fully articulated chibi Moru Cat. */
export function createMoruCat(opts = {}) {
  const rng = opts.rng || Math.random;
  const pal = FUR_PALETTE[(opts.paletteIndex != null
    ? opts.paletteIndex
    : Math.floor(rng() * FUR_PALETTE.length)) % FUR_PALETTE.length];

  const cat = new THREE.Group();
  cat.name = `moru-cat-${CAT_SERIAL++}`;
  cat.userData.isMoruCat = true;
  cat.rotation.order = 'YXZ';   // yaw first → rotation.x is a true backflip

  /* ---------------- materials ---------------- */
  const furMat = new THREE.MeshStandardMaterial({ color: pal.fur, roughness: 0.84, metalness: 0.03 });
  const bellyMat = new THREE.MeshStandardMaterial({ color: pal.belly, roughness: 0.88, metalness: 0.02 });
  const stripeMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(pal.fur).multiplyScalar(0.7), roughness: 0.85, metalness: 0.03,
  });
  const earMat = new THREE.MeshStandardMaterial({ color: pal.ear, roughness: 0.75, metalness: 0.02 });
  const eyeMat = new THREE.MeshStandardMaterial({
    color: 0xfdfdff, roughness: 0.07, metalness: 0.0,
    emissive: 0x9ec0ff, emissiveIntensity: 0.25,
  });
  const pupilMat = new THREE.MeshStandardMaterial({ color: 0x14181f, roughness: 0.05, metalness: 0.25 });
  const glintMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const noseMat = new THREE.MeshStandardMaterial({ color: 0xff97ad, roughness: 0.5, metalness: 0.02 });
  const whiskerMat = new THREE.MeshStandardMaterial({ color: 0xf4f6fb, roughness: 0.6, metalness: 0.12 });
  const collarMat = new THREE.MeshStandardMaterial({
    color: 0xd7452f, emissive: 0x6a1a0a, emissiveIntensity: 0.45, roughness: 0.55, metalness: 0.15,
  });
  const bellMat = new THREE.MeshStandardMaterial({
    color: 0xffd866, emissive: 0xffb429, emissiveIntensity: 1.3, roughness: 0.24, metalness: 0.92,
  });
  const helmetMat = new THREE.MeshStandardMaterial({
    color: HELMET_TINTS[Math.floor(rng() * HELMET_TINTS.length)], roughness: 0.3, metalness: 0.88,
  });
  const visorMat = new THREE.MeshStandardMaterial({ color: 0x2c3240, roughness: 0.3, metalness: 0.72 });

  cat.userData.materials = [
    furMat, bellyMat, stripeMat, earMat, eyeMat, pupilMat, glintMat,
    noseMat, whiskerMat, collarMat, bellMat, helmetMat, visorMat,
  ];

  const add = (parent, mesh, name, shadow = true) => {
    mesh.name = name;
    mesh.castShadow = shadow;
    parent.add(mesh);
    return mesh;
  };

  /* ---------------- torso (direct children of the cat root) ------- */
  const torso = add(cat, new THREE.Mesh(new THREE.SphereGeometry(0.78, 18, 14), furMat), 'torso');
  torso.position.y = BODY_Y;
  torso.scale.set(1.0, 0.88, 1.28);

  const belly = add(cat, new THREE.Mesh(new THREE.SphereGeometry(0.62, 16, 12), bellyMat), 'belly-patch');
  belly.position.set(0, BODY_Y - 0.2, 0.18);
  belly.scale.set(0.93, 0.76, 1.1);

  const ruff = add(cat, new THREE.Mesh(new THREE.SphereGeometry(0.46, 14, 10), bellyMat), 'chest-ruff');
  ruff.position.set(0, BODY_Y - 0.04, 0.72);
  ruff.scale.set(1.05, 0.82, 0.7);

  const haunch = add(cat, new THREE.Mesh(new THREE.SphereGeometry(0.52, 14, 10), furMat), 'haunch');
  haunch.position.set(0, BODY_Y - 0.06, -0.62);
  haunch.scale.set(1.02, 0.96, 0.86);

  for (const s of [-1, 1]) {
    const blade = add(cat, new THREE.Mesh(new THREE.SphereGeometry(0.3, 12, 10), furMat),
      s < 0 ? 'shoulder-L' : 'shoulder-R');
    blade.position.set(s * 0.56, BODY_Y + 0.17, 0.3);
    blade.scale.set(0.8, 0.8, 1.0);
  }

  for (let i = 0; i < 2; i++) {
    const stripe = add(cat, new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.09, 0.16), stripeMat),
      `back-stripe-${i}`);
    stripe.position.set(0, BODY_Y + 0.66 - i * 0.03, -0.1 - i * 0.34);
  }

  const collar = add(cat, new THREE.Mesh(new THREE.TorusGeometry(0.52, 0.075, 10, 16), collarMat), 'collar');
  collar.position.set(0, BODY_Y + 0.3, 0.6);
  collar.rotation.x = 0.44;

  /* ---------------- head ---------------- */
  const head = new THREE.Group();
  head.name = 'cat-head';
  head.position.set(0, BODY_Y + 0.6, 0.72);
  cat.add(head);

  const skull = add(head, new THREE.Mesh(new THREE.SphereGeometry(0.62, 18, 14), furMat), 'skull');
  skull.scale.set(1.08, 0.98, 0.98);

  for (const s of [-1, 1]) {
    const cheek = add(head, new THREE.Mesh(new THREE.SphereGeometry(0.3, 12, 10), furMat),
      s < 0 ? 'cheek-L' : 'cheek-R');
    cheek.position.set(s * 0.42, -0.14, 0.3);
    cheek.scale.set(1.0, 0.86, 0.82);
  }

  const muzzle = add(head, new THREE.Mesh(new THREE.SphereGeometry(0.3, 14, 10), bellyMat), 'muzzle');
  muzzle.position.set(0, -0.14, 0.5);
  muzzle.scale.set(1.12, 0.72, 0.74);

  const earGeo = new THREE.ConeGeometry(0.26, 0.52, 10);
  const innerGeo = new THREE.ConeGeometry(0.15, 0.32, 8);
  const ears = [];
  for (const s of [-1, 1]) {
    const ear = add(head, new THREE.Mesh(earGeo, furMat), s < 0 ? 'ear-L' : 'ear-R');
    ear.position.set(s * 0.37, 0.52, -0.02);
    ear.rotation.set(-0.16, 0, s * 0.3);
    ears.push(ear);
    const inner = add(head, new THREE.Mesh(innerGeo, earMat), s < 0 ? 'ear-inner-L' : 'ear-inner-R');
    inner.position.set(s * 0.38, 0.5, 0.08);
    inner.rotation.set(-0.2, 0, s * 0.3);
  }

  const eyes = [];
  for (const s of [-1, 1]) {
    const eye = add(head, new THREE.Mesh(new THREE.SphereGeometry(0.21, 14, 12), eyeMat),
      s < 0 ? 'eye-L' : 'eye-R');
    eye.position.set(s * 0.26, 0.07, 0.49);
    eye.scale.set(1.0, 1.12, 0.78);
    eyes.push(eye);

    const pupil = add(head, new THREE.Mesh(new THREE.SphereGeometry(0.115, 12, 10), pupilMat),
      s < 0 ? 'pupil-L' : 'pupil-R');
    pupil.position.set(s * 0.27, 0.06, 0.63);
    pupil.scale.set(0.78, 1.2, 0.62);

    const glint = add(head, new THREE.Mesh(new THREE.SphereGeometry(0.045, 8, 6), glintMat),
      s < 0 ? 'catchlight-L' : 'catchlight-R', false);
    glint.position.set(s * 0.215, 0.145, 0.68);
  }

  const snout = add(head, new THREE.Mesh(new THREE.SphereGeometry(0.095, 10, 8), noseMat), 'snout');
  snout.position.set(0, -0.09, 0.73);
  snout.scale.set(1.3, 0.85, 0.8);

  const bridge = add(head, new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.11, 0.035), noseMat), 'nose-bridge');
  bridge.position.set(0, -0.2, 0.715);

  const whiskerGeo = new THREE.CylinderGeometry(0.014, 0.008, 0.62, 5);
  for (const s of [-1, 1]) {
    for (let k = 0; k < 2; k++) {
      const w = add(head, new THREE.Mesh(whiskerGeo, whiskerMat),
        `whisker-${s < 0 ? 'L' : 'R'}${k}`, false);
      w.position.set(s * 0.36, -0.07 - k * 0.1, 0.56);
      w.rotation.set(0.1, 0, s * (Math.PI / 2 - 0.3 + k * 0.26));
    }
  }

  /* ---------------- blacksmith helmet ---------------- */
  const helmet = new THREE.Group();
  helmet.name = 'blacksmith-helmet';
  helmet.position.set(0, 0.3, -0.02);
  head.add(helmet);

  const dome = add(helmet, new THREE.Mesh(
    new THREE.SphereGeometry(0.66, 18, 12, 0, Math.PI * 2, 0, Math.PI * 0.56), helmetMat), 'helmet-dome');
  dome.scale.set(1.04, 1.0, 1.04);

  const brim = add(helmet, new THREE.Mesh(new THREE.TorusGeometry(0.6, 0.085, 8, 18), helmetMat), 'helmet-brim');
  brim.rotation.x = Math.PI / 2;
  brim.position.y = -0.03;

  const crest = add(helmet, new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.2, 0.94), helmetMat), 'helmet-crest');
  crest.position.y = 0.3;

  const visor = add(helmet, new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.11, 0.1), visorMat), 'helmet-visor');
  visor.position.set(0, 0.03, 0.56);
  visor.rotation.x = -0.26;

  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
    const rivet = add(helmet, new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 6), bellMat),
      `helmet-rivet-${i}`);
    rivet.position.set(Math.cos(a) * 0.52, 0.11, Math.sin(a) * 0.52);
  }

  /* ---------------- golden bell on a swinging pivot ---------------- */
  const bellPivot = new THREE.Group();
  bellPivot.name = 'bell-pivot';
  bellPivot.position.set(0, BODY_Y + 0.22, 0.86);
  cat.add(bellPivot);

  const bell = add(bellPivot, new THREE.Mesh(new THREE.SphereGeometry(0.135, 12, 10), bellMat), 'golden-bell');
  bell.position.y = -0.13;
  const bellSlit = add(bellPivot, new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.03, 0.06), pupilMat), 'bell-slit');
  bellSlit.position.set(0, -0.18, 0.08);
  const bellLoop = add(bellPivot, new THREE.Mesh(new THREE.TorusGeometry(0.05, 0.016, 6, 10), bellMat), 'bell-loop');
  bellLoop.position.y = -0.015;

  /* ---------------- 4 articulated legs ---------------- */
  const legGeo = new THREE.CylinderGeometry(0.165, 0.2, 0.52, 10);
  const pawGeo = new THREE.SphereGeometry(0.2, 10, 8);
  const legs = [];
  const legSpecs = [
    { x: -0.42, z: 0.46, name: 'leg-FL', phase: 0 },
    { x: 0.42, z: 0.46, name: 'leg-FR', phase: Math.PI },
    { x: -0.44, z: -0.5, name: 'leg-BL', phase: Math.PI },
    { x: 0.44, z: -0.5, name: 'leg-BR', phase: 0 },
  ];
  legSpecs.forEach((spec) => {
    const pivot = new THREE.Group();
    pivot.name = `${spec.name}-pivot`;
    pivot.position.set(spec.x, BODY_Y - 0.46, spec.z);
    cat.add(pivot);

    const shin = add(pivot, new THREE.Mesh(legGeo, furMat), spec.name);
    shin.position.y = -0.24;

    const paw = add(pivot, new THREE.Mesh(pawGeo, bellyMat), `${spec.name}-paw`);
    paw.position.y = -0.5;
    paw.scale.set(1.08, 0.74, 1.2);

    legs.push({ pivot, phase: spec.phase, baseY: BODY_Y - 0.46 });
  });

  /* ---------------- multi-segment wagging tail ---------------- */
  const tailRoot = new THREE.Group();
  tailRoot.name = 'tail-root';
  tailRoot.position.set(0, BODY_Y + 0.12, -0.84);
  tailRoot.rotation.x = -0.78;
  cat.add(tailRoot);

  const tailSegs = [];
  const segDefs = [
    { r0: 0.13, r1: 0.115, len: 0.42 },
    { r0: 0.115, r1: 0.1, len: 0.4 },
    { r0: 0.1, r1: 0.085, len: 0.36 },
    { r0: 0.085, r1: 0.07, len: 0.32 },
  ];
  let parent = tailRoot;
  segDefs.forEach((d, i) => {
    const joint = new THREE.Group();
    joint.name = `tail-joint-${i}`;
    joint.position.y = i === 0 ? 0 : segDefs[i - 1].len;
    parent.add(joint);
    const seg = add(joint, new THREE.Mesh(new THREE.CylinderGeometry(d.r0, d.r1, d.len, 8),
      i === 3 ? bellyMat : furMat), `tail-seg-${i}`);
    seg.position.y = d.len / 2;
    tailSegs.push(joint);
    parent = joint;
  });
  const tailTip = add(parent, new THREE.Mesh(new THREE.SphereGeometry(0.1, 10, 8), bellyMat), 'tail-tip');
  tailTip.position.y = segDefs[3].len;

  /* ---------------- rig + behaviour state ---------------- */
  cat.scale.setScalar(opts.scale || (0.84 + rng() * 0.46));

  cat.userData.rig = { head, legs, tailSegs, tailRoot, ears, eyes, bellPivot, helmet, torso };
  cat.userData.gait = {
    speed: 3.4 + rng() * 3.6,
    stride: 5.2 + rng() * 3.4,
    hopAmp: 0.16 + rng() * 0.24,
    bob: rng() * Math.PI * 2,
    wag: 2.3 + rng() * 2.5,
    tailPhase: rng() * Math.PI * 2,
    hopPhase: rng() * Math.PI * 2,
  };
  cat.userData.palette = pal.name;
  cat.userData.flip = 0;
  cat.userData.excite = 0;

  let meshCount = 0;
  cat.traverse((o) => { if (o.isMesh) meshCount++; });
  cat.userData.meshCount = meshCount;

  return cat;
}

/* ------------------------------------------------------------------ */
/* city-avenue path planning                                          */
/* ------------------------------------------------------------------ */

const LANE_OFFSET = CITY.ROAD_W * 0.26;

/** Builds a looping route that follows road centre-lines and the plaza ring. */
function makeRoute(index, rng) {
  const span = CITY.SPAN;
  const lines = [];
  for (let i = -span; i <= span; i++) lines.push(i * CITY.BLOCK);

  const pts = [];
  const mode = index % 3;

  if (mode === 0) {
    // plaza ring patrol around the forge
    const rad = 15 + (index % 4) * 4.5;
    const n = 12;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2;
      pts.push(new THREE.Vector3(Math.cos(a) * rad, 0, Math.sin(a) * rad));
    }
  } else if (mode === 1) {
    // avenue run that passes through the plaza
    const lane = lines[Math.floor(rng() * lines.length)];
    const sign = rng() < 0.5 ? 1 : -1;
    const reach = 55 + rng() * 55;
    pts.push(new THREE.Vector3(lane + LANE_OFFSET, 0, -reach * sign));
    pts.push(new THREE.Vector3(lane + LANE_OFFSET, 0, -22 * sign));
    pts.push(new THREE.Vector3(13 * sign, 0, -13 * sign));
    pts.push(new THREE.Vector3(lane - LANE_OFFSET, 0, 24 * sign));
    pts.push(new THREE.Vector3(lane - LANE_OFFSET, 0, reach * sign));
    pts.push(new THREE.Vector3(lane - LANE_OFFSET - 12, 0, reach * sign + 14));
  } else {
    // circuit around one city block
    const bx = lines[Math.floor(rng() * lines.length)];
    const bz = lines[Math.floor(rng() * lines.length)];
    const s = CITY.BLOCK;
    pts.push(new THREE.Vector3(bx + LANE_OFFSET, 0, bz + LANE_OFFSET));
    pts.push(new THREE.Vector3(bx + s - LANE_OFFSET, 0, bz + LANE_OFFSET));
    pts.push(new THREE.Vector3(bx + s - LANE_OFFSET, 0, bz + s - LANE_OFFSET));
    pts.push(new THREE.Vector3(bx + LANE_OFFSET, 0, bz + s - LANE_OFFSET));
  }

  const lim = (CITY.SPAN + 0.5) * CITY.BLOCK;
  pts.forEach((p) => {
    p.x = THREE.MathUtils.clamp(p.x, -lim, lim);
    p.z = THREE.MathUtils.clamp(p.z, -lim, lim);
  });

  return { pts, i: 0, t: 0 };
}

/** Spawns a cat with a route attached and parents it into `group`. */
export function spawnMoruCat(group, index, rng) {
  const cat = createMoruCat({ rng, paletteIndex: index });
  cat.userData.route = makeRoute(index, rng);
  const start = cat.userData.route.pts[0];
  cat.position.set(start.x, 0.02, start.z);
  group.add(cat);
  return cat;
}

/* ------------------------------------------------------------------ */
/* per-frame animation                                                */
/* ------------------------------------------------------------------ */

const _tmp = new THREE.Vector3();

/**
 * Advances one cat: trots along its route (world position changes every
 * frame), swings all four legs, wags the multi-segment tail, bobs/hops the
 * body, flicks ears, blinks and jingles the bell.
 */
export function updateMoruCat(cat, t, dt) {
  const g = cat.userData.gait;
  const rig = cat.userData.rig;
  const route = cat.userData.route;
  if (!g || !rig || !route) return;

  /* ---- path following ---- */
  const pts = route.pts;
  const n = pts.length;
  _tmp.subVectors(pts[(route.i + 1) % n], pts[route.i % n]);
  const segLen = Math.max(0.0001, _tmp.length());
  const excite = cat.userData.excite;
  const speed = g.speed * (1 + excite * 0.95);
  route.t += (speed * dt) / segLen;
  let guard = 0;
  while (route.t >= 1 && guard++ < 8) {
    route.t -= 1;
    route.i = (route.i + 1) % n;
  }
  const a = pts[route.i % n];
  const b = pts[(route.i + 1) % n];
  const px = a.x + (b.x - a.x) * route.t;
  const pz = a.z + (b.z - a.z) * route.t;

  /* ---- hop / bob ---- */
  const strideT = t * g.stride * (1 + excite * 0.6) + g.bob;
  const hop = Math.abs(Math.sin(strideT * 0.5 + g.hopPhase)) * g.hopAmp;
  cat.position.set(px, 0.02 + hop, pz);

  /* ---- facing ---- */
  const heading = Math.atan2(b.x - a.x, b.z - a.z);
  let dy = heading - cat.rotation.y;
  while (dy > Math.PI) dy -= Math.PI * 2;
  while (dy < -Math.PI) dy += Math.PI * 2;
  cat.rotation.y += dy * Math.min(1, dt * 7);

  /* ---- celebratory backflip after an anvil strike ---- */
  if (cat.userData.flip > 0) {
    cat.userData.flip = Math.max(0, cat.userData.flip - dt * 1.5);
    const k = 1 - cat.userData.flip;
    cat.rotation.x = -k * Math.PI * 2;
    cat.position.y += Math.sin(k * Math.PI) * 1.9;
  } else {
    cat.rotation.x = Math.sin(strideT * 0.5) * 0.05;
  }

  if (excite > 0) cat.userData.excite = Math.max(0, excite - dt * 0.55);

  /* ---- four-legged trot: diagonal pairs out of phase ---- */
  rig.legs.forEach((leg) => {
    const swing = Math.sin(strideT + leg.phase);
    leg.pivot.rotation.x = swing * (0.54 + excite * 0.26);
    leg.pivot.rotation.z = Math.cos(strideT + leg.phase) * 0.07;
    leg.pivot.position.y = leg.baseY + Math.max(0, swing) * 0.06;
  });

  /* ---- multi-segment tail wag ---- */
  rig.tailSegs.forEach((joint, i) => {
    const ph = g.tailPhase + i * 0.55;
    joint.rotation.z = Math.sin(t * g.wag + ph) * (0.2 + i * 0.1);
    joint.rotation.x = Math.sin(t * g.wag * 0.7 + ph) * 0.1;
  });
  rig.tailRoot.rotation.x = -0.78 + Math.sin(t * g.wag * 0.6) * 0.13;

  /* ---- squash & stretch on the torso ---- */
  const sq = 1 + Math.sin(strideT) * 0.035;
  rig.torso.scale.set(1.0 / sq, 0.88 * sq, 1.28);

  /* ---- head look-around + ear flick ---- */
  rig.head.rotation.y = Math.sin(t * 0.85 + g.bob) * 0.3;
  rig.head.rotation.x = Math.sin(t * 1.3 + g.bob) * 0.09 - hop * 0.22;
  rig.ears.forEach((ear, i) => {
    const s = i === 0 ? -1 : 1;
    ear.rotation.x = -0.16 + Math.sin(t * 5.2 + i * 1.7) * 0.12;
    ear.rotation.z = s * (0.3 + Math.sin(t * 3.4 + i) * 0.08);
  });

  /* ---- blinking ---- */
  const lid = Math.sin(t * 1.9 + g.bob * 2.0) > 0.965 ? 0.12 : 1.12;
  rig.eyes.forEach((eye) => { eye.scale.y = lid; });

  /* ---- bell jingle ---- */
  rig.bellPivot.rotation.x = Math.sin(strideT * 1.1) * 0.3;
  rig.bellPivot.rotation.z = Math.cos(strideT * 0.9) * 0.22;
}

/** Makes every cat celebrate a hammer strike. */
export function exciteCats(cats) {
  cats.forEach((cat, i) => {
    cat.userData.excite = 1;
    if (i % 2 === 0) cat.userData.flip = 1;
  });
}

export function disposeMoruCat(cat) {
  let n = 0;
  cat.traverse((o) => {
    if (o.isMesh && o.geometry) { o.geometry.dispose(); n++; }
  });
  (cat.userData.materials || []).forEach((m) => { m.dispose(); n++; });
  return n;
}


