  state.spinning = !state.spinning;
  spinBtn.classList.toggle('active', state.spinning);
  spinBtn.textContent = state.spinning ? 'G9 · Freeze Photo' : 'G9 · Resume Motion';
  document.body.classList.toggle('frozen', !state.spinning);
  if (state.spinning) {
    lastTime = performance.now();
    dirty = true;
  } else {
    // render exactly one settled frame, then hold it forever
    dirty = true;
  }
});
if (spinBtn) spinBtn.classList.add('active');

window.addEventListener('resize', () => {
  const w = window.innerWidth;
  const h = window.innerHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h, false);
  composer.setSize(w, h);
  bloomPass.resolution.set(w, h);
  dirty = true;
});

/* ================================================================== */
/* render loop                                                        */
/* ================================================================== */

let lastTime = performance.now();
let clockT = 0;

function tick(now) {
  requestAnimationFrame(tick);

  const rawDt = (now - lastTime) / 1000;
  lastTime = now;

  if (!state.spinning) {
    // ── photo freeze: no simulation, no HUD churn, one held frame
    if (dirty) {
      composer.render();
      dirty = false;
    }
    return;
  }

  const dt = Math.min(0.05, Math.max(0.0005, rawDt));
  clockT += dt;

  // world animation
  city.update(clockT);
  forge.update(clockT, dt);
  for (const cat of cats) updateMoruCat(cat, clockT, dt);

  // camera
  if (state.cameraMode === 'follow') {
    updateFollowCam(dt);
  } else {
    controls.update();
  }

  composer.render();

  state.frame++;
  frameAcc++;
  hudAcc += dt;
  if (hudAcc >= 0.22) {
    state.fps = frameAcc / hudAcc;
    frameAcc = 0;
    hudAcc = 0;
    renderHud(now);
    lastHud = now;
  }
}

requestAnimationFrame(tick);

/* ================================================================== */
/* public handle                                                      */
/* ================================================================== */

window.__app = {
  scene,
  camera,
  renderer,
  composer,
  controls,
  state,
  city,
  forge,
  cats,
  themes: THEMES,
  setTheme: applyTheme,
  setCamera: setCameraPreset,
  countTriangles,
  CITY,
};


