  0xa78bfa, 0xff8a4c, 0x4df0ff, 0xff6b6b,
];

/* ------------------------------------------------------------------ */
/* helpers                                                            */
/* ------------------------------------------------------------------ */

function mergeList(list) {
  if (!list.length) return null;
  const normalized = list.map((g) => {
    const nonIdx = g.index ? g.toNonIndexed() : g;
    // keep only position, normal, uv so mergeGeometries never fails on mismatched attributes
    const keep = new Set(['position', 'normal', 'uv']);
    for (const k of Object.keys(nonIdx.attributes)) {
      if (!keep.has(k)) nonIdx.deleteAttribute(k);
    }
    if (!nonIdx.attributes.uv) {
      const count = nonIdx.attributes.position.count;
      nonIdx.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(count * 2), 2));
    }
    return nonIdx;
  });
  return normalized.length === 1 ? normalized[0] : mergeGeometries(normalized, false);
}

function pushGeo(out, geo, { x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0 } = {}) {
  const m = new THREE.Matrix4();
  const e = new THREE.Euler(rx, ry, rz);
  m.makeRotationFromEuler(e);
  m.setPosition(x, y, z);
  geo.applyMatrix4(m);
  out.push(geo);
  return geo;
}

/* ------------------------------------------------------------------ */
/* buildings                                                          */
/* ------------------------------------------------------------------ */

/**
 * One multi-tier tower. Returns a Group holding three merged meshes
 * (facade / neon trim / concrete detail) so the skyline stays cheap to draw
 * while keeping a high triangle budget per building.
 */
function makeBuilding(rng, facadeMats, trimMatFor, concreteMat, heightScale) {
  const group = new THREE.Group();
  group.name = 'building';

  const facadeGeos = [];
  const trimGeos = [];
  const detailGeos = [];

  let w = 9 + rng() * 9;
  let d = 9 + rng() * 9;
  const tiers = 2 + Math.floor(rng() * 2.9); // 2 – 4 tiers
  let y = 0;
  let topW = w;
  let topD = d;

  for (let t = 0; t < tiers; t++) {
    const h = (t === 0 ? 15 + rng() * 24 : 7 + rng() * 15) * heightScale;
    const box = new THREE.BoxGeometry(w, h, d, 2, 3, 2);
    pushGeo(facadeGeos, box, { y: y + h / 2 });

    // rooftop neon trim frame around every tier
    const tw = 0.55;
    const ty = y + h + 0.3;
    pushGeo(trimGeos, new THREE.BoxGeometry(w + 0.6, 0.6, tw), { y: ty, z: d / 2 });
    pushGeo(trimGeos, new THREE.BoxGeometry(w + 0.6, 0.6, tw), { y: ty, z: -d / 2 });
    pushGeo(trimGeos, new THREE.BoxGeometry(tw, 0.6, d + 0.6), { y: ty, x: w / 2 });
    pushGeo(trimGeos, new THREE.BoxGeometry(tw, 0.6, d + 0.6), { y: ty, x: -w / 2 });

    // parapet lip (concrete)
    pushGeo(detailGeos, new THREE.BoxGeometry(w + 1.1, 0.5, d + 1.1), { y: y + h + 0.02 });

    // vertical corner accent strip on the tallest tier
    if (t === 0 && rng() < 0.55) {
      pushGeo(trimGeos, new THREE.BoxGeometry(0.4, h * 0.82, 0.4), {
        x: w / 2 - 0.3, y: y + h * 0.5, z: d / 2 - 0.3,
      });
    }

    y += h + 0.35;
    topW = w; topD = d;
    w = Math.max(4.2, w * (0.62 + rng() * 0.2));
    d = Math.max(4.2, d * (0.62 + rng() * 0.2));
  }

  const roofY = y;
  const roll = rng();

  if (roll < 0.34) {
    // ── helipad: disc + painted H + glowing ring
    const r = Math.min(topW, topD) * 0.36;
    pushGeo(detailGeos, new THREE.CylinderGeometry(r, r, 0.45, 24), { y: roofY + 0.2 });
    pushGeo(detailGeos, new THREE.BoxGeometry(r * 0.22, 0.14, r * 1.0), { x: -r * 0.3, y: roofY + 0.45 });
    pushGeo(detailGeos, new THREE.BoxGeometry(r * 0.22, 0.14, r * 1.0), { x: r * 0.3, y: roofY + 0.45 });
    pushGeo(detailGeos, new THREE.BoxGeometry(r * 0.78, 0.14, r * 0.22), { y: roofY + 0.45 });
    pushGeo(trimGeos, new THREE.TorusGeometry(r * 1.02, 0.1, 8, 20), {
      y: roofY + 0.5, rx: Math.PI / 2,
    });
    // corner approach lights
    for (let i = 0; i < 4; i++) {
      const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
      pushGeo(trimGeos, new THREE.SphereGeometry(0.22, 8, 6), {
        x: Math.cos(a) * r * 1.25, y: roofY + 0.6, z: Math.sin(a) * r * 1.25,
      });
    }
  } else if (roll < 0.72) {
    // ── spire + antenna mast with beacon
    const spireH = 8 + rng() * 18;
    pushGeo(detailGeos, new THREE.CylinderGeometry(topW * 0.2, topW * 0.3, 2.4, 10), { y: roofY + 1.2 });
    pushGeo(detailGeos, new THREE.ConeGeometry(topW * 0.19, spireH, 12), { y: roofY + 2.4 + spireH / 2 });
    pushGeo(trimGeos, new THREE.CylinderGeometry(0.11, 0.11, spireH * 0.55, 6), {
      y: roofY + 2.4 + spireH + spireH * 0.27,
    });
    pushGeo(trimGeos, new THREE.SphereGeometry(0.42, 10, 8), {
      y: roofY + 2.4 + spireH + spireH * 0.55 + 0.3,
    });
    pushGeo(trimGeos, new THREE.TorusGeometry(topW * 0.26, 0.09, 8, 18), {
      y: roofY + 1.0, rx: Math.PI / 2,
    });
  } else {
    // ── rooftop plant: AC blocks, water tank, mast array
    for (let i = 0; i < 3; i++) {
      const bw = 1.4 + rng() * 2.6;
      pushGeo(detailGeos, new THREE.BoxGeometry(bw, 1.2 + rng() * 2.2, bw), {
        x: (rng() - 0.5) * topW * 0.55,
        y: roofY + 1.1,
        z: (rng() - 0.5) * topD * 0.55,
      });
    }
    pushGeo(detailGeos, new THREE.CylinderGeometry(1.5, 1.5, 3.2, 14), {
      x: topW * 0.2, y: roofY + 1.6, z: -topD * 0.2,
    });
    pushGeo(detailGeos, new THREE.CylinderGeometry(0.1, 0.1, 9 + rng() * 7, 6), {
      x: -topW * 0.25, y: roofY + 6, z: topD * 0.25,
    });
    pushGeo(trimGeos, new THREE.SphereGeometry(0.3, 10, 8), {
      x: -topW * 0.25, y: roofY + 10.6, z: topD * 0.25,
    });
    pushGeo(trimGeos, new THREE.TorusGeometry(Math.min(topW, topD) * 0.44, 0.1, 8, 20), {
      y: roofY + 0.9, rx: Math.PI / 2,
    });
  }

  const neon = NEON_COLORS[Math.floor(rng() * NEON_COLORS.length)];
  const facadeMat = facadeMats[Math.floor(rng() * facadeMats.length)];

  const fg = mergeList(facadeGeos);
  const facadeMesh = new THREE.Mesh(fg, facadeMat);
  facadeMesh.name = 'facade';
  group.add(facadeMesh);

  const tg = mergeList(trimGeos);
  const trimMesh = new THREE.Mesh(tg, trimMatFor(neon));
  trimMesh.name = 'neon-trim';
  group.add(trimMesh);

  const dg = mergeList(detailGeos);
  const detailMesh = new THREE.Mesh(dg, concreteMat);
  detailMesh.name = 'roof-detail';
  group.add(detailMesh);

  group.userData.height = y;
  group.userData.neon = neon;
  return group;
}

/* ------------------------------------------------------------------ */
/* trees                                                              */
/* ------------------------------------------------------------------ */

function makeTree(rng, trunkMat, leafMats) {
  const group = new THREE.Group();
  group.name = 'tree';
  const scale = 0.8 + rng() * 0.7;
  const trunkH = 2.6 + rng() * 2.2;

  const trunkGeos = [];
  pushGeo(trunkGeos, new THREE.CylinderGeometry(0.26, 0.46, trunkH, 8), { y: trunkH / 2 });
  // two angled branches
  for (let i = 0; i < 2; i++) {
    const a = rng() * Math.PI * 2;
    pushGeo(trunkGeos, new THREE.CylinderGeometry(0.1, 0.17, 1.5, 6), {
      x: Math.cos(a) * 0.5, y: trunkH * 0.78, z: Math.sin(a) * 0.5,
      rz: Math.cos(a) * 0.6, rx: Math.sin(a) * 0.6,
    });
  }
  pushGeo(trunkGeos, new THREE.CylinderGeometry(0.75, 0.95, 0.3, 10), { y: 0.12 });

  const leafGeos = [];
  const blobs = 3 + Math.floor(rng() * 2.4);
  for (let i = 0; i < blobs; i++) {
    const r = 1.25 + rng() * 0.95;
    const a = (i / blobs) * Math.PI * 2 + rng();
    const rad = i === 0 ? 0 : 0.7 + rng() * 0.75;
    pushGeo(leafGeos, new THREE.IcosahedronGeometry(r, 1), {
      x: Math.cos(a) * rad,
      y: trunkH + 0.55 + rng() * 1.3,
      z: Math.sin(a) * rad,
    });
  }
  // conifer crown on some trees
  if (rng() < 0.45) {
    pushGeo(leafGeos, new THREE.ConeGeometry(1.25, 3.1, 10), { y: trunkH + 2.7 });
  }

  const trunk = new THREE.Mesh(mergeList(trunkGeos), trunkMat);
  trunk.name = 'trunk';
  trunk.castShadow = true;
  group.add(trunk);

  const leaves = new THREE.Mesh(mergeList(leafGeos), leafMats[Math.floor(rng() * leafMats.length)]);
  leaves.name = 'foliage';
  leaves.castShadow = true;
  group.add(leaves);

  group.scale.setScalar(scale);
  group.rotation.y = rng() * Math.PI * 2;
  return group;
}

/* ------------------------------------------------------------------ */
/* streetlamps                                                        */
/* ------------------------------------------------------------------ */

function makeLamp(poleMat, bulbMat, poolMat, geos, rotY) {
  const group = new THREE.Group();
  group.name = 'streetlamp';

  const pole = new THREE.Mesh(geos.pole, poleMat);
  pole.name = 'lamp-pole';
  group.add(pole);

  const head = new THREE.Mesh(geos.head, poleMat);
  head.name = 'lamp-head';
  group.add(head);

  const bulb = new THREE.Mesh(geos.bulb, bulbMat);
  bulb.name = 'lamp-bulb';
  group.add(bulb);

  const pool = new THREE.Mesh(geos.pool, poolMat);
  pool.name = 'light-pool';
  pool.rotation.x = -Math.PI / 2;
  pool.position.y = 0.035;
  group.add(pool);

  group.rotation.y = rotY;
  return group;
}

/* ------------------------------------------------------------------ */
/* main builder                                                       */
/* ------------------------------------------------------------------ */

export function buildCity(scene, state) {
  const rng = makeRng(0xc17ba5);
  const root = new THREE.Group();
  root.name = 'city';
  scene.add(root);

  const disposables = [];
  const track = (x) => { disposables.push(x); return x; };

  /* ---- shared textures & materials ---- */
  const facadeTexs = createFacadeSet(6).map(track);
  const roadTex = track(createRoadTexture());
  const crossTex = track(createCrosswalkTexture());
  const groundTex = track(createGroundTexture());
  const sidewalkTex = track(createPavingTexture('#434a58', 'rgba(20,22,30,0.65)', 6));
  const poolTex = track(createLightPoolTexture());

  const facadeMats = facadeTexs.map((tex) => track(new THREE.MeshStandardMaterial({
    map: tex,
    emissiveMap: tex,
    emissive: 0xffffff,
    emissiveIntensity: 1.5,
    color: 0xaab3c4,
    roughness: 0.62,
    metalness: 0.22,
  })));

  const trimMatCache = new Map();
  const trimMatFor = (hex) => {
    if (!trimMatCache.has(hex)) {
      trimMatCache.set(hex, track(new THREE.MeshStandardMaterial({
        color: hex,
        emissive: hex,
        emissiveIntensity: 1.9,
        roughness: 0.35,
        metalness: 0.1,
      })));
    }
    return trimMatCache.get(hex);
  };

  const concreteMat = track(new THREE.MeshStandardMaterial({
    color: 0x5a6273, roughness: 0.82, metalness: 0.14,
  }));
  const trunkMat = track(new THREE.MeshStandardMaterial({
    color: 0x6a4b33, roughness: 0.9, metalness: 0.05,
  }));
  const leafMats = [0x2f8f58, 0x3aa46a, 0x27754a, 0x46b57b, 0x1f6b47].map((c) => track(
    new THREE.MeshStandardMaterial({
      color: c, emissive: c, emissiveIntensity: 0.14, roughness: 0.78, metalness: 0.02, flatShading: true,
    })
  ));
  const poleMat = track(new THREE.MeshStandardMaterial({
    color: 0x3b4150, roughness: 0.55, metalness: 0.65,
  }));
  const bulbMat = track(new THREE.MeshStandardMaterial({
    color: 0xfff1cf, emissive: 0xffd98a, emissiveIntensity: 2.3, roughness: 0.3, metalness: 0.0,
  }));
  const poolMat = track(new THREE.MeshBasicMaterial({
    map: poolTex, transparent: true, opacity: 0.6, depthWrite: false,
    blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
  }));

  /* ---- ground ---- */
  const groundMat = track(new THREE.MeshStandardMaterial({
    map: groundTex, color: 0x767e90, roughness: 0.92, metalness: 0.08,
  }));
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(760, 760, 24, 24), groundMat);
  ground.name = 'ground';
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  root.add(ground);

  /* ---- road grid ---- */
  const span = CITY.SPAN;
  const half = (span + 0.5) * CITY.BLOCK;
  const roadMat = track(new THREE.MeshStandardMaterial({
    map: roadTex, color: 0x9aa2b2, roughness: 0.88, metalness: 0.1,
  }));
  const crossMat = track(new THREE.MeshStandardMaterial({
    map: crossTex, color: 0x9aa2b2, roughness: 0.8, metalness: 0.08,
  }));
  const roadGroup = new THREE.Group();
  roadGroup.name = 'roads';
  root.add(roadGroup);

  const roadLines = [];
  for (let i = -span; i <= span; i++) roadLines.push(i * CITY.BLOCK);

  for (const c of roadLines) {
    const ew = new THREE.Mesh(new THREE.PlaneGeometry(half * 2, CITY.ROAD_W, 10, 1), roadMat);
    ew.rotation.x = -Math.PI / 2;
    ew.rotation.z = Math.PI / 2;
    ew.position.set(0, 0.02, c);
    ew.name = 'road-ew';
    ew.receiveShadow = true;
    roadGroup.add(ew);

    const ns = new THREE.Mesh(new THREE.PlaneGeometry(half * 2, CITY.ROAD_W, 10, 1), roadMat);
    ns.rotation.x = -Math.PI / 2;
    ns.position.set(c, 0.021, 0);
    ns.name = 'road-ns';
    ns.receiveShadow = true;
    roadGroup.add(ns);
  }

  // crosswalks at every intersection (4 approaches)
  const cwGeo = new THREE.PlaneGeometry(CITY.ROAD_W, 4.2);
  for (const cx of roadLines) {
    for (const cz of roadLines) {
      if (Math.hypot(cx, cz) < CITY.PLAZA_R * 0.55) continue;
      const off = CITY.ROAD_W / 2 + 2.3;
      const specs = [
        [cx, cz - off, 0], [cx, cz + off, 0],
        [cx - off, cz, Math.PI / 2], [cx + off, cz, Math.PI / 2],
      ];
      for (const [px, pz, rot] of specs) {
        const cw = new THREE.Mesh(cwGeo, crossMat);
        cw.rotation.x = -Math.PI / 2;
        cw.rotation.z = rot;
        cw.position.set(px, 0.035, pz);
        cw.name = 'crosswalk';
        roadGroup.add(cw);
      }
    }
  }

  /* ---- buildings in blocks ---- */
  const buildings = [];
  const buildingGroup = new THREE.Group();
  buildingGroup.name = 'buildings';
  root.add(buildingGroup);

  const sidewalkMat = track(new THREE.MeshStandardMaterial({
    map: sidewalkTex, color: 0x8e96a6, roughness: 0.9, metalness: 0.06,
  }));
  const sidewalkGeo = new THREE.BoxGeometry(
    CITY.BLOCK - CITY.ROAD_W + 1.5, 0.3, CITY.BLOCK - CITY.ROAD_W + 1.5
  );

  const blocks = [];
  for (let bx = -span; bx < span; bx++) {
    for (let bz = -span; bz < span; bz++) {
      const cx = bx * CITY.BLOCK + CITY.BLOCK / 2;
      const cz = bz * CITY.BLOCK + CITY.BLOCK / 2;
      const dist = Math.hypot(cx, cz);
      if (dist < CITY.PLAZA_R) continue;   // keep plaza sightline clear
      blocks.push({ cx, cz, dist });
    }
  }
  blocks.sort((a, b) => a.dist - b.dist);

  const TARGET_BUILDINGS = 66;
  for (let i = 0; i < blocks.length && buildings.length < TARGET_BUILDINGS; i++) {
    const { cx, cz, dist } = blocks[i];
    // downtown core is taller, outskirts lower
    const falloff = THREE.MathUtils.clamp(1.35 - dist / 230, 0.45, 1.3);
    const heightScale = falloff * (0.72 + rng() * 0.75);
    const b = makeBuilding(rng, facadeMats, trimMatFor, concreteMat, heightScale);
    const jitter = 3.2;
    b.position.set(cx + (rng() - 0.5) * jitter, 0, cz + (rng() - 0.5) * jitter);
    b.rotation.y = (rng() < 0.5 ? 0 : Math.PI / 2) + (rng() - 0.5) * 0.22;
    if (dist < 95) {
      b.children.forEach((m) => { m.castShadow = true; });
    }
    buildingGroup.add(b);
    buildings.push(b);

    // sidewalk slab under each block
    const sw = new THREE.Mesh(sidewalkGeo, sidewalkMat);
    sw.position.set(cx, 0.14, cz);
    sw.name = 'sidewalk';
    sw.receiveShadow = true;
    root.add(sw);
  }

  /* ---- trees along the sidewalks + plaza park ring ---- */
  const trees = [];
  const treeGroup = new THREE.Group();
  treeGroup.name = 'trees';
  root.add(treeGroup);

  const edge = CITY.ROAD_W / 2 + 2.6;
  const treeSlots = [];
  for (const c of roadLines) {
    for (let k = -span; k < span; k++) {
      const along = k * CITY.BLOCK + CITY.BLOCK / 2;
      treeSlots.push([along, c + edge]);
      treeSlots.push([along, c - edge]);
      treeSlots.push([c + edge, along]);
      treeSlots.push([c - edge, along]);
    }
  }
  // plaza perimeter ring of trees
  for (let i = 0; i < 18; i++) {
    const a = (i / 18) * Math.PI * 2;
    treeSlots.push([Math.cos(a) * 33, Math.sin(a) * 33]);
  }

  const TARGET_TREES = 76;
  for (let i = 0; i < treeSlots.length && trees.length < TARGET_TREES; i++) {
    const idx = Math.floor(rng() * treeSlots.length);
    const slot = treeSlots[idx] || treeSlots[i];
    const [tx, tz] = slot;
    const d = Math.hypot(tx, tz);
    if (d < 26 || d > half + 6) continue;
    const t = makeTree(rng, trunkMat, leafMats);
    t.position.set(tx + (rng() - 0.5) * 1.6, 0.18, tz + (rng() - 0.5) * 1.6);
    treeGroup.add(t);
    trees.push(t);
  }
  // guarantee the minimum by filling the plaza ring if slots were sparse
  let guardRing = 0;
  while (trees.length < TARGET_TREES && guardRing < 200) {
    const a = (guardRing / 24) * Math.PI * 2;
    const rad = 36 + (guardRing % 5) * 4;
    const t = makeTree(rng, trunkMat, leafMats);
    t.position.set(Math.cos(a) * rad, 0.18, Math.sin(a) * rad);
    treeGroup.add(t);
    trees.push(t);
    guardRing++;
  }

  /* ---- streetlamps ---- */
  const lamps = [];
  const lampGroup = new THREE.Group();
  lampGroup.name = 'streetlamps';
  root.add(lampGroup);

  const lampGeos = {
    pole: (() => {
      const g = [];
      pushGeo(g, new THREE.CylinderGeometry(0.6, 0.78, 0.4, 10), { y: 0.2 });
      pushGeo(g, new THREE.CylinderGeometry(0.17, 0.24, 7.2, 8), { y: 3.7 });
      pushGeo(g, new THREE.CylinderGeometry(0.13, 0.13, 1.9, 6), { x: 0.85, y: 7.2, rz: Math.PI / 2 });
      return mergeList(g);
    })(),
    head: new THREE.ConeGeometry(0.62, 0.9, 10),
    bulb: new THREE.SphereGeometry(0.38, 10, 8),
    pool: new THREE.CircleGeometry(3.4, 18),
  };
  lampGeos.head.translate(1.75, 6.95, 0);
  lampGeos.bulb.translate(1.75, 6.5, 0);

  const lampSlots = [];
  for (const c of roadLines) {
    for (let k = -span; k < span; k++) {
      const along = k * CITY.BLOCK + 8;
      lampSlots.push([along, c + CITY.ROAD_W / 2 + 0.9, Math.PI]);
      lampSlots.push([along + 14, c - CITY.ROAD_W / 2 - 0.9, 0]);
      lampSlots.push([c + CITY.ROAD_W / 2 + 0.9, along, -Math.PI / 2]);
      lampSlots.push([c - CITY.ROAD_W / 2 - 0.9, along + 14, Math.PI / 2]);
    }
  }
  // plaza approach lamps
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    lampSlots.push([Math.cos(a) * 30, Math.sin(a) * 30, a + Math.PI]);
  }

  const TARGET_LAMPS = 98;
  for (let i = 0; i < lampSlots.length && lamps.length < TARGET_LAMPS; i++) {
    const [lx, lz, lr] = lampSlots[i];
    const d = Math.hypot(lx, lz);
    if (d < 24 || d > half + 4) continue;
    const lamp = makeLamp(poleMat, bulbMat, poolMat, lampGeos, lr);
    lamp.position.set(lx, 0.16, lz);
    lamps.push(lamp);
    lampGroup.add(lamp);
  }
  let guardLamp = 0;
  while (lamps.length < TARGET_LAMPS && guardLamp < 240) {
    const a = (guardLamp / 20) * Math.PI * 2;
    const rad = 28 + (guardLamp % 6) * 5;
    const lamp = makeLamp(poleMat, bulbMat, poolMat, lampGeos, a + Math.PI);
    lamp.position.set(Math.cos(a) * rad, 0.16, Math.sin(a) * rad);
    lamps.push(lamp);
    lampGroup.add(lamp);
    guardLamp++;
  }

  /* ---- theme hooks ---- */
  const api = {
    root,
    buildings,
    trees,
    lamps,
    counts: { buildings: buildings.length, trees: trees.length, lamps: lamps.length },
    materials: { facadeMats, trimMatCache, bulbMat, poolMat, groundMat, roadMat, leafMats, sidewalkMat },
    applyTheme(theme) {
      api._baseLamp = theme.lampGlow;
      facadeMats.forEach((m) => { m.emissiveIntensity = theme.windowGlow; m.needsUpdate = true; });
      trimMatCache.forEach((m) => { m.emissiveIntensity = theme.neonGlow; });
      bulbMat.emissiveIntensity = theme.lampGlow;
      bulbMat.emissive.setHex(theme.lampColor);
      poolMat.opacity = theme.poolOpacity;
      poolMat.visible = theme.poolOpacity > 0.02;
      groundMat.color.setHex(theme.groundTint);
      roadMat.color.setHex(theme.roadTint);
      leafMats.forEach((m) => { m.emissiveIntensity = theme.leafGlow; });
    },
    /** Lamp bulbs breathe very slightly so the skyline feels alive. */
    update(t) {
      const p = 1 + Math.sin(t * 1.7) * 0.06;
      bulbMat.emissiveIntensity = api._baseLamp * p;
    },
    _baseLamp: 2.3,
    dispose() {
      let n = 0;
      disposables.forEach((o) => { if (o && o.dispose) { o.dispose(); n++; } });
      return n;
    },
  };

  if (state) {
