function merge(list) {
  if (!list.length) return null;
  const normalized = list.map((g) => {
    const nonIdx = g.index ? g.toNonIndexed() : g;
    const keep = new Set(['position', 'normal', 'uv']);
    for (const k of Object.keys(nonIdx.attributes)) {
      if (!keep.has(k)) nonIdx.deleteAttribute(k);
    }
    if (!nonIdx.attributes.uv) {
      const count = nonIdx.attributes.position.count;
      nonIdx.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(count * 2), 2));
    }
    return nonIdx;
  });
  return normalized.length === 1 ? normalized[0] : mergeGeometries(normalized, false);
}

function place(out, geo, { x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0 } = {}) {
  const m = new THREE.Matrix4();
  m.makeRotationFromEuler(new THREE.Euler(rx, ry, rz));
  m.setPosition(x, y, z);
  geo.applyMatrix4(m);
  out.push(geo);
}

