      const flick = 0.86 + Math.sin(t * 7.3) * 0.08 + Math.sin(t * 3.1) * 0.06;
      magmaMat.emissiveIntensity = api._baseMagma * flick;
      forgeLight.intensity = api._baseLight * flick;
      lavaGlow.scale.setScalar(0.95 + Math.sin(t * 2.6) * 0.09);
