        const ph = f.userData.phase;
        f.scale.set(
          0.85 + Math.sin(t * 8 + ph) * 0.13,
          1.0 + Math.sin(t * 6.2 + ph * 1.7) * 0.22,
          0.85 + Math.cos(t * 7.4 + ph) * 0.13
        );
        f.rotation.y = t * 1.6 + ph;
      }

      // embers & sparks
      for (const m of embers) {
        const u = m.userData;
        u.life += dt * u.speed * 0.42;
        if (u.life > 1) u.life -= 1;
        const k = u.life;
        const rad = u.spread * (0.35 + k * 1.7);
        const ang = u.ang + k * 2.4;
        m.position.x = u.origin.x + Math.cos(ang) * rad;
        m.position.z = u.origin.z + Math.sin(ang) * rad;
        if (u.isSpark && u.bounce > 0) {
          const h = Math.abs(Math.sin(k * Math.PI * 3)) * u.bounce * 2.4;
          m.position.y = u.origin.y - 1.0 + h;
        } else {
          m.position.y = u.origin.y + k * u.rise;
        }
        const s = (1 - k) * (u.isSpark ? 1.25 : 1.0);
