    },

    _shockIdx: 0,
    _baseLight: 55,
    _baseMagma: 1.9,
    _baseRune: 0.92,

    dispose() {
      let n = 0;
      disposables.forEach((o) => { if (o && o.dispose) { o.dispose(); n++; } });
      return n;
    },
  };

  return api;
}


