/**
 * textures.js — Procedural THREE.CanvasTexture generators for the
 * "Moru 3D Neon Forge City & Animated Cat Village" showcase.
 *
 * Everything here is drawn at runtime on 2D canvases: multi-color glowing
 * skyscraper window grids, asphalt + lane markings + crosswalks, forge rune
 * rings, lamp ground-light pools and tiered stone paving.
