import * as THREE from 'three';

/* ------------------------------------------------------------------ */
/* small deterministic RNG so the whole city is reproducible           */
/* ------------------------------------------------------------------ */
export function makeRng(seed) {
  let s = (seed >>> 0) || 0x9e3779b9;
  return function rng() {
    s ^= s << 13; s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5;  s >>>= 0;
    return s / 4294967296;
  };
}

function canvas2d(w, h) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d');
  g.imageSmoothingEnabled = true;
  return { c, g };
}

function finish(c, { repeatX = 1, repeatY = 1, srgb = true, aniso = 4 } = {}) {
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeatX, repeatY);
  tex.anisotropy = aniso;
  if (srgb) tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  return tex;
}

function noiseOverlay(g, w, h, rng, amount, alpha) {
  g.save();
  for (let i = 0; i < amount; i++) {
    const x = rng() * w;
    const y = rng() * h;
    const r = 0.6 + rng() * 2.2;
    const v = Math.floor(120 + rng() * 135);
    g.fillStyle = `rgba(${v},${v},${v},${alpha})`;
    g.beginPath();
    g.arc(x, y, r, 0, Math.PI * 2);
    g.fill();
  }
  g.restore();
}

/* ------------------------------------------------------------------ */
/* 1 · Multi-color illuminated skyscraper facades                      */
/* ------------------------------------------------------------------ */

/** Window glow palettes — each facade variant mixes 3-4 hues. */
const GLOW_PALETTES = [
  ['#ffe9a8', '#ffd166', '#fff3cf', '#8fd8ff'],
  ['#9be7ff', '#5ad2ff', '#c8f4ff', '#ffd2f0'],
  ['#ffb0e6', '#ff7ad0', '#ffd9f3', '#9effe0'],
  ['#a8ffd6', '#5bf0b0', '#e2fff2', '#ffe08a'],
  ['#ffd0a0', '#ff9f5e', '#ffe8cc', '#b4c8ff'],
  ['#c7b4ff', '#9b84ff', '#e8dfff', '#8ff0ff'],
];

const WALL_TONES = [
  ['#1b2130', '#242c3e', '#10151f'],
  ['#231d2b', '#2e2638', '#15111b'],
  ['#1a2630', '#23323f', '#0f171d'],
  ['#2a2228', '#352b33', '#171318'],
];

/**
 * Draws a tower facade: concrete bands, mullions and a dense grid of
 * windows where a tunable fraction are lit with a glowing multi-color core.
 */
export function createFacadeTexture(variantIndex = 0, opts = {}) {
  const W = 512;
  const H = 512;
  const { c, g } = canvas2d(W, H);
  const rng = makeRng(0x51bc07 + variantIndex * 7919);
  const palette = GLOW_PALETTES[variantIndex % GLOW_PALETTES.length];
  const wall = WALL_TONES[variantIndex % WALL_TONES.length];
  const cols = opts.cols || 10 + (variantIndex % 3) * 2;
  const rows = opts.rows || 16 + (variantIndex % 4) * 3;
  const litChance = opts.litChance != null ? opts.litChance : 0.52;

  // base wall with soft vertical shading
  const grd = g.createLinearGradient(0, 0, 0, H);
  grd.addColorStop(0, wall[1]);
  grd.addColorStop(0.55, wall[0]);
  grd.addColorStop(1, wall[2]);
  g.fillStyle = grd;
  g.fillRect(0, 0, W, H);

  // vertical mullion ribs
  const colW = W / cols;
  for (let i = 0; i <= cols; i++) {
    g.fillStyle = 'rgba(8,10,16,0.55)';
    g.fillRect(i * colW - 1.5, 0, 3, H);
  }
  // horizontal floor slabs
  const rowH = H / rows;
  for (let j = 0; j <= rows; j++) {
    g.fillStyle = 'rgba(255,255,255,0.045)';
    g.fillRect(0, j * rowH - 1, W, 1.4);
    g.fillStyle = 'rgba(6,8,12,0.5)';
    g.fillRect(0, j * rowH, W, 2.2);
  }

  // window cells
  const padX = colW * 0.22;
  const padY = rowH * 0.24;
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      const x = i * colW + padX;
      const y = j * rowH + padY;
      const w = colW - padX * 2;
      const h = rowH - padY * 2;
      const lit = rng() < litChance;
      if (lit) {
        const col = palette[Math.floor(rng() * palette.length)];
        g.save();
        g.shadowColor = col;
        g.shadowBlur = 9 + rng() * 11;
        g.fillStyle = col;
        g.globalAlpha = 0.58 + rng() * 0.42;
        g.fillRect(x, y, w, h);
        g.shadowBlur = 0;
        // bright inner core for bloom pickup
        g.globalAlpha = 0.85;
        g.fillStyle = col;
        g.fillRect(x + w * 0.16, y + h * 0.14, w * 0.68, h * 0.5);
        g.restore();
        // occasional silhouette inside the room
        if (rng() < 0.16) {
          g.fillStyle = 'rgba(16,14,24,0.55)';
          g.fillRect(x + w * 0.3, y + h * 0.35, w * 0.26, h * 0.6);
        }
      } else {
        // dark glass with a faint sky reflection streak
        g.fillStyle = 'rgba(10,14,22,0.82)';
        g.fillRect(x, y, w, h);
        g.fillStyle = 'rgba(120,150,200,0.11)';
        g.fillRect(x, y, w, h * 0.38);
      }
    }
  }

  // service bands every few floors to break the rhythm
  for (let j = 3; j < rows; j += 5 + (variantIndex % 3)) {
    g.fillStyle = 'rgba(14,18,26,0.78)';
    g.fillRect(0, j * rowH - rowH * 0.18, W, rowH * 0.36);
    g.fillStyle = 'rgba(255,255,255,0.05)';
    g.fillRect(0, j * rowH - rowH * 0.18, W, 1.2);
  }

  noiseOverlay(g, W, H, rng, 900, 0.05);
  return finish(c, { repeatX: 1, repeatY: 1 });
}

/** Builds the full set of facade variants used across the skyline. */
export function createFacadeSet(count = 6) {
  const out = [];
  for (let i = 0; i < count; i++) {
    out.push(createFacadeTexture(i, {
      cols: 8 + (i % 4) * 3,
      rows: 14 + (i % 5) * 4,
      litChance: 0.42 + (i % 3) * 0.12,
    }));
  }
  return out;
}

/* ------------------------------------------------------------------ */
/* 2 · Roads: asphalt, dashed lane markings, crosswalks                */
/* ------------------------------------------------------------------ */

export function createRoadTexture() {
  const W = 256;
  const H = 512;
  const { c, g } = canvas2d(W, H);
  const rng = makeRng(0x20dd51);

  g.fillStyle = '#2b2f39';
  g.fillRect(0, 0, W, H);
  // patchy tarmac tone
  for (let i = 0; i < 90; i++) {
    const x = rng() * W;
    const y = rng() * H;
    const r = 8 + rng() * 42;
    g.fillStyle = `rgba(${40 + rng() * 26 | 0},${44 + rng() * 26 | 0},${54 + rng() * 26 | 0},0.5)`;
    g.beginPath();
    g.arc(x, y, r, 0, Math.PI * 2);
    g.fill();
  }
  // kerbs / shoulder lines
  g.fillStyle = '#cdd6e2';
  g.fillRect(10, 0, 5, H);
  g.fillRect(W - 15, 0, 5, H);
  g.fillStyle = 'rgba(190,200,215,0.35)';
  g.fillRect(2, 0, 7, H);
  g.fillRect(W - 9, 0, 7, H);
  // dashed centre line (double amber)
  g.fillStyle = '#f2c14e';
  for (let y = 0; y < H; y += 56) {
    g.fillRect(W * 0.5 - 9, y, 5, 34);
    g.fillRect(W * 0.5 + 4, y, 5, 34);
  }
  // inner lane dashes
  g.fillStyle = 'rgba(232,240,250,0.8)';
  for (let y = 24; y < H; y += 72) {
    g.fillRect(W * 0.25 - 2.5, y, 5, 30);
    g.fillRect(W * 0.75 - 2.5, y, 5, 30);
  }
  noiseOverlay(g, W, H, rng, 1100, 0.045);
  return finish(c, { repeatX: 1, repeatY: 6 });
}

export function createCrosswalkTexture() {
  const S = 256;
  const { c, g } = canvas2d(S, S);
  const rng = makeRng(0x7c0551);
  g.fillStyle = '#30343e';
  g.fillRect(0, 0, S, S);
  const stripes = 8;
  const sw = S / (stripes * 2 - 1);
  for (let i = 0; i < stripes; i++) {
    g.fillStyle = i % 2 === 0 ? 'rgba(236,243,250,0.93)' : 'rgba(236,243,250,0.88)';
    g.fillRect(i * sw * 2, S * 0.08, sw, S * 0.84);
  }
  // stop bar
  g.fillStyle = 'rgba(240,246,252,0.7)';
  g.fillRect(0, 2, S, 6);
  g.fillRect(0, S - 8, S, 6);
  noiseOverlay(g, S, S, rng, 500, 0.07);
  return finish(c, { repeatX: 1, repeatY: 1 });
}

/* ------------------------------------------------------------------ */
/* 3 · Forge rune ring                                                 */
/* ------------------------------------------------------------------ */

export function createRuneRingTexture(tint = '#ff9a3c') {
  const S = 512;
  const { c, g } = canvas2d(S, S);
  const rng = makeRng(0x4a9e21);
  const cx = S / 2;
  const cy = S / 2;
  g.clearRect(0, 0, S, S);

  const ring = (radius, width, color, blur, alpha) => {
    g.save();
    g.globalAlpha = alpha;
    g.strokeStyle = color;
    g.lineWidth = width;
    g.shadowColor = color;
    g.shadowBlur = blur;
    g.beginPath();
    g.arc(cx, cy, radius, 0, Math.PI * 2);
    g.stroke();
    g.restore();
  };

  ring(S * 0.46, 7, tint, 26, 0.95);
  ring(S * 0.40, 3, '#ffe2a8', 18, 0.9);
  ring(S * 0.30, 5, tint, 22, 0.8);
  ring(S * 0.22, 2.5, '#fff0cf', 14, 0.75);

  // radial rune ticks
  const ticks = 32;
  for (let i = 0; i < ticks; i++) {
    const a = (i / ticks) * Math.PI * 2;
    const long = i % 4 === 0;
    const r0 = S * (long ? 0.31 : 0.355);
    const r1 = S * 0.398;
    g.save();
    g.strokeStyle = long ? '#ffe9bd' : tint;
    g.lineWidth = long ? 6 : 3;
    g.shadowColor = tint;
    g.shadowBlur = 16;
    g.globalAlpha = 0.9;
    g.beginPath();
    g.moveTo(cx + Math.cos(a) * r0, cy + Math.sin(a) * r0);
    g.lineTo(cx + Math.cos(a) * r1, cy + Math.sin(a) * r1);
    g.stroke();
    g.restore();
  }

  // angular glyphs between the rings
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2 + 0.18;
    const r = S * 0.255;
    const px = cx + Math.cos(a) * r;
    const py = cy + Math.sin(a) * r;
    g.save();
    g.translate(px, py);
    g.rotate(a);
    g.strokeStyle = '#ffeec9';
    g.lineWidth = 3;
    g.shadowColor = tint;
    g.shadowBlur = 12;
    g.globalAlpha = 0.85;
    g.beginPath();
    const segs = 3 + Math.floor(rng() * 3);
    g.moveTo(-9, -9);
    for (let s = 0; s < segs; s++) {
      g.lineTo(-9 + rng() * 18, -9 + rng() * 18);
    }
    g.stroke();
    g.restore();
  }

  // inner sigil star
  g.save();
  g.strokeStyle = tint;
  g.lineWidth = 3.5;
  g.shadowColor = tint;
  g.shadowBlur = 20;
  g.globalAlpha = 0.8;
  g.beginPath();
  for (let i = 0; i <= 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    const r = S * (i % 2 ? 0.08 : 0.19);
    const px = cx + Math.cos(a) * r;
    const py = cy + Math.sin(a) * r;
    if (i === 0) g.moveTo(px, py); else g.lineTo(px, py);
  }
  g.closePath();
  g.stroke();
  g.restore();

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  return tex;
}

/* ------------------------------------------------------------------ */
/* 4 · Lamp ground light pool + magma + paving                         */
/* ------------------------------------------------------------------ */

export function createLightPoolTexture(inner = 'rgba(255,230,160,0.95)', outer = 'rgba(255,170,60,0)') {
  const S = 256;
  const { c, g } = canvas2d(S, S);
  const grd = g.createRadialGradient(S / 2, S / 2, 2, S / 2, S / 2, S / 2);
  grd.addColorStop(0, inner);
  grd.addColorStop(0.35, 'rgba(255,205,120,0.42)');
  grd.addColorStop(0.72, 'rgba(255,170,70,0.13)');
  grd.addColorStop(1, outer);
  g.fillStyle = grd;
  g.fillRect(0, 0, S, S);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  return tex;
}

export function createMagmaTexture() {
  const S = 256;
  const { c, g } = canvas2d(S, S);
  const rng = makeRng(0x3c1a77);
  g.fillStyle = '#2a0c06';
  g.fillRect(0, 0, S, S);
  // crust cells
  for (let i = 0; i < 160; i++) {
    const x = rng() * S;
    const y = rng() * S;
    const r = 6 + rng() * 26;
    g.fillStyle = `rgba(${30 + rng() * 40 | 0},${12 + rng() * 14 | 0},${8 + rng() * 10 | 0},0.8)`;
    g.beginPath();
    g.arc(x, y, r, 0, Math.PI * 2);
    g.fill();
  }
  // glowing lava veins
  for (let i = 0; i < 46; i++) {
    g.save();
    g.strokeStyle = ['#ff7a1c', '#ffb43c', '#ffe08a', '#ff4d10'][Math.floor(rng() * 4)];
    g.lineWidth = 2 + rng() * 7;
    g.shadowColor = '#ff8a2a';
    g.shadowBlur = 16;
    g.globalAlpha = 0.75 + rng() * 0.25;
    g.beginPath();
    let x = rng() * S;
    let y = rng() * S;
    g.moveTo(x, y);
    for (let s = 0; s < 5; s++) {
      x += (rng() - 0.5) * 70;
      y += (rng() - 0.5) * 70;
      g.lineTo(x, y);
    }
    g.stroke();
    g.restore();
  }
  return finish(c, { repeatX: 1, repeatY: 1 });
}

export function createPavingTexture(base = '#3a3f4c', seam = 'rgba(16,18,24,0.7)', tiles = 8) {
  const S = 512;
  const { c, g } = canvas2d(S, S);
  const rng = makeRng(0x6f2d19);
  g.fillStyle = base;
  g.fillRect(0, 0, S, S);
  const t = S / tiles;
  for (let j = 0; j < tiles; j++) {
    for (let i = 0; i < tiles; i++) {
      const v = 0.82 + rng() * 0.3;
      g.save();
      g.globalAlpha = 0.5;
      g.fillStyle = `rgba(${Math.min(255, 86 * v) | 0},${Math.min(255, 94 * v) | 0},${Math.min(255, 110 * v) | 0},0.7)`;
      g.fillRect(i * t + 1.5, j * t + 1.5, t - 3, t - 3);
      g.restore();
      g.strokeStyle = seam;
      g.lineWidth = 3;
      g.strokeRect(i * t + 1, j * t + 1, t - 2, t - 2);
    }
  }
  noiseOverlay(g, S, S, rng, 1400, 0.055);
  return finish(c, { repeatX: 1, repeatY: 1 });
}

/** Big tiling sidewalk / plaza concrete used by the ground plane. */
export function createGroundTexture() {
  const S = 512;
  const { c, g } = canvas2d(S, S);
  const rng = makeRng(0x11a7c3);
  g.fillStyle = '#343a47';
  g.fillRect(0, 0, S, S);
  for (let i = 0; i < 220; i++) {
    const x = rng() * S;
    const y = rng() * S;
    const r = 10 + rng() * 60;
    g.fillStyle = `rgba(${52 + rng() * 34 | 0},${58 + rng() * 34 | 0},${70 + rng() * 34 | 0},0.38)`;
    g.beginPath();
    g.arc(x, y, r, 0, Math.PI * 2);
    g.fill();
  }
  g.strokeStyle = 'rgba(150,164,186,0.16)';
  g.lineWidth = 2;
  for (let i = 0; i <= 4; i++) {
    g.beginPath(); g.moveTo(i * S / 4, 0); g.lineTo(i * S / 4, S); g.stroke();
    g.beginPath(); g.moveTo(0, i * S / 4); g.lineTo(S, i * S / 4); g.stroke();
  }
  noiseOverlay(g, S, S, rng, 2000, 0.05);
  return finish(c, { repeatX: 24, repeatY: 24 });
}

/** Vertical sky gradient used as scene.background per theme. */
export function createSkyTexture(stops) {
  const W = 8;
  const H = 256;
  const { c, g } = canvas2d(W, H);
  const grd = g.createLinearGradient(0, 0, 0, H);
  grd.addColorStop(0, stops[0]);
  grd.addColorStop(0.55, stops[1]);
  grd.addColorStop(1, stops[2]);
  g.fillStyle = grd;
  g.fillRect(0, 0, W, H);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = THREE.ClampToEdgeWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;
  tex.needsUpdate = true;
  return tex;
}


