// ====== src/main.js (26847 bytes) ======
import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";

/* -------------------------------------------------------------------------- */
/* Core renderer / scene / camera                                             */
/* -------------------------------------------------------------------------- */

const canvas = document.getElementById("scene-canvas");
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x05060c, 0.014);

const camera = new THREE.PerspectiveCamera(
  55,
  window.innerWidth / window.innerHeight,
  0.1,
  500
);
camera.position.set(38, 36, 46);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.maxPolarAngle = Math.PI * 0.49;
controls.minDistance = 4;
controls.maxDistance = 140;
controls.target.set(0, 2, 0);

/* -------------------------------------------------------------------------- */
/* Global state exposed on window.__app                                      */
/* -------------------------------------------------------------------------- */

const state = {
  running: true,
  theme: "night",
  cameraMode: "overview",
  cats: [],
  maxCats: 24,
  clockElapsed: 0,
  fps: 0,
  anvil: {
    cooldown: 0,
    strikeStrength: 0,
  },
  plaza: { radius: 9 },
};

window.__app = { scene, camera, renderer, state };

/* -------------------------------------------------------------------------- */
/* Lighting rig (theme-dependent)                                            */
/* -------------------------------------------------------------------------- */

const hemiLight = new THREE.HemisphereLight(0x8fb6ff, 0x101018, 0.6);
scene.add(hemiLight);

const sunLight = new THREE.DirectionalLight(0xffffff, 1.0);
sunLight.position.set(30, 40, 10);
sunLight.castShadow = true;
sunLight.shadow.mapSize.set(2048, 2048);
sunLight.shadow.camera.near = 1;
sunLight.shadow.camera.far = 200;
sunLight.shadow.camera.left = -70;
sunLight.shadow.camera.right = 70;
sunLight.shadow.camera.top = 70;
sunLight.shadow.camera.bottom = -70;
sunLight.shadow.bias = -0.0005;
scene.add(sunLight);

const ambientLight = new THREE.AmbientLight(0x3a4a6b, 0.4);
scene.add(ambientLight);

const forgeGlowLight = new THREE.PointLight(0xff7a33, 4, 22, 2);
forgeGlowLight.position.set(0, 2.4, 0);
scene.add(forgeGlowLight);

/* -------------------------------------------------------------------------- */
/* Materials palette                                                         */
/* -------------------------------------------------------------------------- */

const neonPalette = [0x7cf9ff, 0xff6ec7, 0xffd166, 0x9b5cff, 0x5cffb0];

function makeBuildingMaterial(colorHex) {
  return new THREE.MeshStandardMaterial({
    color: colorHex,
    roughness: 0.55,
    metalness: 0.35,
  });
}

function makeNeonWindowMaterial(colorHex) {
  return new THREE.MeshStandardMaterial({
    color: colorHex,
    emissive: colorHex,
    emissiveIntensity: 1.6,
    roughness: 0.3,
    metalness: 0.1,
  });
}

/* -------------------------------------------------------------------------- */
/* Ground, plaza, roads                                                      */
/* -------------------------------------------------------------------------- */

const cityGroup = new THREE.Group();
scene.add(cityGroup);

const groundMat = new THREE.MeshStandardMaterial({
  color: 0x14172a,
  roughness: 0.95,
  metalness: 0.05,
});
const groundGeo = new THREE.PlaneGeometry(220, 220, 1, 1);
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
cityGroup.add(ground);

const roadMat = new THREE.MeshStandardMaterial({
  color: 0x1c1f30,
  roughness: 0.85,
  metalness: 0.1,
});

function addRoadStrip(width, length, x, z, rotY = 0) {
  const geo = new THREE.PlaneGeometry(width, length);
  const mesh = new THREE.Mesh(geo, roadMat);
  mesh.rotation.x = -Math.PI / 2;
  mesh.rotation.z = rotY;
  mesh.position.set(x, 0.01, z);
  mesh.receiveShadow = true;
  cityGroup.add(mesh);

