function buildBuilding(x, z, w, d, h, colorHex, neonHex) {
  const group = new THREE.Group();
  const mat = makeBuildingMaterial(colorHex);
  const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  body.position.y = h / 2;
  body.castShadow = true;
  body.receiveShadow = true;
  group.add(body);

  // neon window strips
  const stripMat = makeNeonWindowMaterial(neonHex);
  const floors = Math.max(2, Math.floor(h / 2.2));
  for (let f = 1; f < floors; f++) {
    const y = (f / floors) * h;
    if (Math.random() > 0.35) {
      const strip = new THREE.Mesh(new THREE.BoxGeometry(w * 0.92, 0.18, d * 1.001), stripMat);
      strip.position.y = y;
      group.add(strip);
      windowLights.push(strip.material);
    }
  }

  // rooftop antenna/beacon for taller buildings
  if (h > 10) {
    const beacon = new THREE.Mesh(
      new THREE.SphereGeometry(0.22, 8, 8),
      new THREE.MeshStandardMaterial({ color: neonHex, emissive: neonHex, emissiveIntensity: 3 })
    );
    beacon.position.y = h + 0.3;
    group.add(beacon);
    const pole = new THREE.Mesh(
      new THREE.CylinderGeometry(0.05, 0.05, 0.8, 6),
      new THREE.MeshStandardMaterial({ color: 0x222222 })
    );
    pole.position.y = h + 0.0;
    group.add(pole);
  }

  group.position.set(x, 0, z);
  buildingsGroup.add(group);
}

function randomChoice(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

// Procedural city block layout around the plaza, avoiding roads (multiples of ~40 corridors)
const blockCenters = [];
