  for (let gz = -2; gz <= 2; gz++) {
    if (gx === 0 && gz === 0) continue; // plaza
    const cx = gx * 20;
    const cz = gz * 20;
    blockCenters.push({ cx, cz });
  }
}

blockCenters.forEach(({ cx, cz }) => {
  const clusterCount = 1 + Math.floor(Math.random() * 2);
  for (let i = 0; i < clusterCount; i++) {
    const w = 3 + Math.random() * 3.5;
    const d = 3 + Math.random() * 3.5;
    const h = 4 + Math.random() * 18;
    const x = cx + (Math.random() - 0.5) * 8;
    const z = cz + (Math.random() - 0.5) * 8;
