  const head = new THREE.Mesh(new THREE.SphereGeometry(0.26, 14, 14), furMat);
  head.position.set(0.5, 0.46, 0);
  head.castShadow = true;
  cat.add(head);

  const earGeo = new THREE.ConeGeometry(0.1, 0.16, 8);
  const earL = new THREE.Mesh(earGeo, furMat);
  earL.position.set(0.44, 0.68, 0.14);
  earL.rotation.x = -0.3;
  cat.add(earL);
  const earR = earL.clone();
  earR.position.z = -0.14;
  earR.rotation.x = 0.3;
  cat.add(earR);

  const eyeGeo = new THREE.SphereGeometry(0.045, 8, 8);
  const eyeL = new THREE.Mesh(eyeGeo, darkMat);
  eyeL.position.set(0.72, 0.5, 0.11);
  cat.add(eyeL);
  const eyeR = eyeL.clone();
  eyeR.position.z = -0.11;
  cat.add(eyeR);

  const nose = new THREE.Mesh(new THREE.SphereGeometry(0.035, 6, 6), pinkMat);
  nose.position.set(0.77, 0.44, 0);
  cat.add(nose);

  const legGeo = new THREE.CylinderGeometry(0.055, 0.055, 0.28, 6);
  const legPositions = [
    [0.22, 0.14, 0.17],
    [0.22, 0.14, -0.17],
    [-0.22, 0.14, 0.17],
    [-0.22, 0.14, -0.17],
  ];
  const legs = legPositions.map((p) => {
    const leg = new THREE.Mesh(legGeo, furMat);
    leg.position.set(...p);
    leg.castShadow = true;
    cat.add(leg);
    return leg;
  });

  const tail = new THREE.Mesh(new THREE.CapsuleGeometry(0.05, 0.4, 4, 8), furMat);
  tail.position.set(-0.45, 0.42, 0);
  tail.rotation.z = Math.PI / 2.6;
