  cat.userData.legs = legs;
  cat.userData.tail = tail;
  cat.userData.head = head;
  cat.scale.setScalar(0.9 + Math.random() * 0.5);
  return cat;
}

function spawnCat() {
  if (state.cats.length >= state.maxCats) {
    const removed = state.cats.shift();
    catsGroup.remove(removed.mesh);
  }
  const furColor = randomChoice(catFurPalette);
  const mesh = buildCatMesh(furColor);
  const angle = Math.random() * Math.PI * 2;
  const radius = state.plaza.radius - 1.5 + Math.random() * 1.2;
  const x = Math.cos(angle) * radius;
  const z = Math.sin(angle) * radius;
  mesh.position.set(x, 0, z);
  catsGroup.add(mesh);

  const catState = {
    mesh,
    speed: 2.2 + Math.random() * 2.0,
    heading: Math.random() * Math.PI * 2,
    changeDirTimer: Math.random() * 2,
    jumpPhase: Math.random() * Math.PI * 2,
    jumpSpeed: 5 + Math.random() * 3,
    wanderRadius: 10 + Math.random() * 60,
    bornAt: state.clockElapsed,
  };
  state.cats.push(catState);
  return catState;
}

