/* -------------------------------------------------------------------------- */
/* Animation loop                                                            */
/* -------------------------------------------------------------------------- */

const timer = new THREE.Timer();
timer.connect(document);
const fpsHud = document.getElementById("fps-hud");
let fpsAccum = 0;
let fpsFrames = 0;
let fpsTimer = 0;

function updateCats(dt) {
  state.cats.forEach((cat) => {
    cat.changeDirTimer -= dt;
    if (cat.changeDirTimer <= 0) {
      cat.heading += (Math.random() - 0.5) * 2.4;
      cat.changeDirTimer = 1 + Math.random() * 2;
    }

    const mesh = cat.mesh;
    const dist = Math.hypot(mesh.position.x, mesh.position.z);
    if (dist > cat.wanderRadius) {
      const toCenter = Math.atan2(-mesh.position.z, -mesh.position.x);
      cat.heading = toCenter + (Math.random() - 0.5) * 0.6;
    }

    const vx = Math.cos(cat.heading) * cat.speed * dt;
    const vz = Math.sin(cat.heading) * cat.speed * dt;
    mesh.position.x += vx;
    mesh.position.z += vz;

    cat.jumpPhase += dt * cat.jumpSpeed;
    const bounce = Math.abs(Math.sin(cat.jumpPhase)) * 0.35;
    mesh.position.y = bounce;

    mesh.rotation.y = -cat.heading + Math.PI / 2;

    const legs = mesh.userData.legs;
    legs.forEach((leg, i) => {
      leg.rotation.x = Math.sin(cat.jumpPhase * 2 + i * Math.PI / 2) * 0.5;
    });
    mesh.userData.tail.rotation.y = Math.sin(cat.jumpPhase * 0.7) * 0.4;
  });
}

function updateForge(dt) {
  if (state.anvil.cooldown > 0) {
    state.anvil.cooldown -= dt;
    const t = Math.max(0, state.anvil.cooldown / 0.5);
    hammerGroup.rotation.z = -0.5 + Math.sin(t * Math.PI) * 0.9;
  } else {
    hammerGroup.rotation.z = -0.5;
  }

  forgeGlowLight.intensity += (3.5 - forgeGlowLight.intensity) * Math.min(1, dt * 4);
  forgePit.material.emissiveIntensity = 1.8 + Math.sin(state.clockElapsed * 6) * 0.4;

  if (sparkLife > 0) {
    sparkLife -= dt;
    const positions = sparkGeo.attributes.position.array;
    for (let i = 0; i < SPARK_COUNT; i++) {
      const v = sparkVelocities[i];
      v.y -= 9.8 * dt;
      positions[i * 3 + 0] += v.x * dt;
      positions[i * 3 + 1] += v.y * dt;
      positions[i * 3 + 2] += v.z * dt;
    }
    sparkGeo.attributes.position.needsUpdate = true;
    sparkMat.opacity = Math.max(0, sparkLife / 0.9);
  } else {
    sparkMat.opacity = 0;
  }
}

function updateCameraFollow() {
  if (state.cameraMode !== "follow-cat" || state.cats.length === 0) return;
  const target = state.cats[state.cats.length - 1].mesh;
  const offset = new THREE.Vector3(2.2, 2.0, 2.2);
  const desired = target.position.clone().add(offset);
  camera.position.lerp(desired, 0.08);
  camera.lookAt(target.position.x, target.position.y + 0.4, target.position.z);
}

function animate(timestamp) {
  requestAnimationFrame(animate);
  timer.update(timestamp);
  const dt = Math.min(timer.getDelta(), 0.05);

  if (state.running) {
    state.clockElapsed += dt;
    updateCats(dt);
    updateForge(dt);
    plazaRing.rotation.z += dt * 0.15;
  }

  updateCameraFollow();
  if (state.cameraMode !== "follow-cat") {
    controls.update();
  }

  renderer.render(scene, camera);

  fpsAccum += dt;
  fpsFrames += 1;
  fpsTimer += dt;
  if (fpsTimer >= 0.4) {
    state.fps = Math.round(fpsFrames / fpsAccum);
    fpsHud.textContent = `FPS: ${state.fps}\ncats: ${state.cats.length}\nmode: ${state.theme}\ncamera: ${state.cameraMode}${state.running ? "" : " (paused)"}`;
    fpsAccum = 0;
    fpsFrames = 0;
    fpsTimer = 0;
  }
}

