import * as THREE from 'three';

const FUR_PALETTE = [0xe8a95c, 0xd9d2c4, 0x8a6a4e, 0xe3ded3, 0xc77b3f, 0x5a4a3c];

function rand(min, max) {
  return min + Math.random() * (max - min);
}

function pick(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

// ---------------------------------------------------------------------------
// Builds one expressive Chibi 3D Moru Cat. Returns a THREE.Group with
// userData.isMoruCat = true and >= 14 named child meshes referenced in
// userData.parts for animation (legs, tail segments, ears, head, etc).
// ---------------------------------------------------------------------------
export function createMoruCat(opts = {}) {
  const group = new THREE.Group();
  group.name = 'moruCat';
  group.userData.isMoruCat = true;

  const furColor = opts.furColor || pick(FUR_PALETTE);
  const furMat = new THREE.MeshStandardMaterial({ color: furColor, roughness: 0.85, metalness: 0.05 });
  const bellyMat = new THREE.MeshStandardMaterial({ color: 0xfbf3e3, roughness: 0.9 });
  const pinkMat = new THREE.MeshStandardMaterial({ color: 0xe88ba0, roughness: 0.6 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x241f1c, roughness: 0.4 });
  const whiteMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.2 });
  const goldMat = new THREE.MeshStandardMaterial({
    color: 0xffcc33,
    emissive: 0xffaa22,
    emissiveIntensity: 0.6,
    metalness: 0.7,
    roughness: 0.3,
  });
  const helmetMat = new THREE.MeshStandardMaterial({ color: 0x4a4e58, roughness: 0.4, metalness: 0.75 });
  const collarMat = new THREE.MeshStandardMaterial({ color: 0xc0392b, roughness: 0.6 });

  const parts = {};
  const bodyScale = opts.scale || 1;

  // ---- Torso: rounded capsule-ish body (scaled sphere) -----------------
  const torsoGeo = new THREE.SphereGeometry(0.42, 14, 10);
  const torso = new THREE.Mesh(torsoGeo, furMat);
  torso.scale.set(1.15, 0.95, 1.0);
  torso.position.y = 0.52;
  torso.castShadow = true;
  group.add(torso);
  parts.torso = torso;

  // ---- Belly patch ------------------------------------------------------
  const bellyGeo = new THREE.SphereGeometry(0.3, 12, 8);
  const belly = new THREE.Mesh(bellyGeo, bellyMat);
  belly.scale.set(1.0, 0.8, 0.6);
  belly.position.set(0, 0.42, 0.22);
  group.add(belly);
  parts.belly = belly;

  // ---- Head --------------------------------------------------------------
  const headGroup = new THREE.Group();
  headGroup.position.set(0, 0.82, 0.38);
  group.add(headGroup);
  parts.headGroup = headGroup;

  const headGeo = new THREE.SphereGeometry(0.33, 14, 10);
  const head = new THREE.Mesh(headGeo, furMat);
  head.castShadow = true;
  headGroup.add(head);
  parts.head = head;

  // ---- Puffy cheeks -------------------------------------------------------
  const cheekGeo = new THREE.SphereGeometry(0.14, 10, 8);
  const cheekL = new THREE.Mesh(cheekGeo, furMat);
  cheekL.position.set(-0.22, -0.06, 0.2);
  headGroup.add(cheekL);
  parts.cheekL = cheekL;

  const cheekR = new THREE.Mesh(cheekGeo, furMat);
  cheekR.position.set(0.22, -0.06, 0.2);
  headGroup.add(cheekR);
  parts.cheekR = cheekR;

  // ---- Ears with inner-ear detail ------------------------------------------
  function buildEar(sign) {
    const earOuterGeo = new THREE.ConeGeometry(0.14, 0.26, 8);
    const earOuter = new THREE.Mesh(earOuterGeo, furMat);
    earOuter.position.set(sign * 0.2, 0.3, -0.02);
    earOuter.rotation.z = sign * 0.25;
    headGroup.add(earOuter);

    const earInnerGeo = new THREE.ConeGeometry(0.08, 0.16, 8);
    const earInner = new THREE.Mesh(earInnerGeo, pinkMat);
    earInner.position.set(sign * 0.2, 0.28, 0.04);
    earInner.rotation.z = sign * 0.25;
    headGroup.add(earInner);

    return { outer: earOuter, inner: earInner };
  }
  const earL = buildEar(-1);
  const earR = buildEar(1);
  parts.earLOuter = earL.outer;
  parts.earLInner = earL.inner;
  parts.earROuter = earR.outer;
  parts.earRInner = earR.inner;

  // ---- Glossy eyes with pupils + white catchlights -------------------------
  function buildEye(sign) {
    const eyeGeo = new THREE.SphereGeometry(0.1, 10, 8);
    const eye = new THREE.Mesh(eyeGeo, whiteMat);
    eye.position.set(sign * 0.15, 0.02, 0.27);
    headGroup.add(eye);

    const pupilGeo = new THREE.SphereGeometry(0.055, 8, 6);
    const pupil = new THREE.Mesh(pupilGeo, darkMat);
    pupil.position.set(sign * 0.15, 0.02, 0.33);
    headGroup.add(pupil);

    const catchGeo = new THREE.SphereGeometry(0.02, 6, 4);
    const catchMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xffffff, emissiveIntensity: 1.5 });
    const catchlight = new THREE.Mesh(catchGeo, catchMat);
    catchlight.position.set(sign * 0.15 + 0.02, 0.06, 0.37);
    headGroup.add(catchlight);

    return { eye, pupil, catchlight };
  }
  const eyeL = buildEye(-1);
  const eyeR = buildEye(1);
  parts.eyeL = eyeL.eye;
  parts.pupilL = eyeL.pupil;
  parts.catchL = eyeL.catchlight;
  parts.eyeR = eyeR.eye;
  parts.pupilR = eyeR.pupil;
  parts.catchR = eyeR.catchlight;

  // ---- Pink snout ----------------------------------------------------------
  const snoutGeo = new THREE.SphereGeometry(0.06, 8, 6);
  const snout = new THREE.Mesh(snoutGeo, pinkMat);
  snout.position.set(0, -0.08, 0.35);
  headGroup.add(snout);
  parts.snout = snout;

  // ---- Whiskers (4 thin cylinders) ------------------------------------------
  const whiskerMat = new THREE.MeshStandardMaterial({ color: 0xf5f0e6, roughness: 0.3 });
  const whiskerPositions = [
    { x: -0.3, y: -0.08, z: 0.3, rot: 0.3 },
    { x: -0.32, y: -0.11, z: 0.26, rot: 0.55 },
    { x: 0.3, y: -0.08, z: 0.3, rot: -0.3 },
    { x: 0.32, y: -0.11, z: 0.26, rot: -0.55 },
  ];
  parts.whiskers = whiskerPositions.map((p) => {
    const geo = new THREE.CylinderGeometry(0.008, 0.008, 0.26, 4);
    const whisker = new THREE.Mesh(geo, whiskerMat);
    whisker.position.set(p.x, p.y, p.z);
    whisker.rotation.z = Math.PI / 2 + p.rot;
    headGroup.add(whisker);
    return whisker;
  });

  // ---- Blacksmith helmet -----------------------------------------------------
  const helmetGeo = new THREE.SphereGeometry(0.3, 12, 8, 0, Math.PI * 2, 0, Math.PI * 0.55);
  const helmet = new THREE.Mesh(helmetGeo, helmetMat);
  helmet.position.set(0, 0.17, -0.02);
  helmet.castShadow = true;
  headGroup.add(helmet);
  parts.helmet = helmet;

  const helmetRimGeo = new THREE.TorusGeometry(0.28, 0.025, 6, 16);
  const helmetRim = new THREE.Mesh(helmetRimGeo, goldMat);
  helmetRim.rotation.x = Math.PI / 2;
  helmetRim.position.set(0, 0.06, -0.02);
  headGroup.add(helmetRim);
  parts.helmetRim = helmetRim;

  // ---- Collar + golden bell --------------------------------------------------
  const collarGeo = new THREE.TorusGeometry(0.28, 0.045, 8, 16);
  const collar = new THREE.Mesh(collarGeo, collarMat);
  collar.rotation.x = Math.PI / 2;
  collar.position.set(0, 0.56, 0.3);
  group.add(collar);
  parts.collar = collar;

  const bellGeo = new THREE.SphereGeometry(0.09, 10, 8);
  const bell = new THREE.Mesh(bellGeo, goldMat);
  bell.position.set(0, 0.42, 0.48);
  group.add(bell);
  parts.bell = bell;

  // ---- Four articulated swinging legs ----------------------------------------
  function buildLeg(x, z) {
    const legGroup = new THREE.Group();
    legGroup.position.set(x, 0.3, z);
    group.add(legGroup);

    const upperGeo = new THREE.CylinderGeometry(0.08, 0.07, 0.3, 7);
    const upper = new THREE.Mesh(upperGeo, furMat);
    upper.position.y = -0.1;
    upper.castShadow = true;
    legGroup.add(upper);

    const pawGeo = new THREE.SphereGeometry(0.075, 8, 6);
    const paw = new THREE.Mesh(pawGeo, darkMat);
    paw.position.y = -0.27;
    legGroup.add(paw);

    return legGroup;
  }
  parts.legFL = buildLeg(-0.22, 0.28);
  parts.legFR = buildLeg(0.22, 0.28);
  parts.legBL = buildLeg(-0.22, -0.26);
  parts.legBR = buildLeg(0.22, -0.26);

  // ---- Multi-segment wagging tail -----------------------------------------
  const tailMat = furMat;
  const tailSegCount = 3;
  let tailParent = group;
  const tailSegs = [];
  let tailBaseZ = -0.4;
  for (let i = 0; i < tailSegCount; i++) {
    const segGroup = new THREE.Group();
    segGroup.position.set(0, i === 0 ? 0.5 : 0, i === 0 ? tailBaseZ : -0.18);
    tailParent.add(segGroup);

    const segGeo = new THREE.CylinderGeometry(0.07 - i * 0.015, 0.06 - i * 0.015, 0.22, 7);
    const segMesh = new THREE.Mesh(segGeo, tailMat);
    segMesh.rotation.x = Math.PI / 2;
    segMesh.position.z = -0.1;
    segGroup.add(segMesh);

    tailSegs.push(segGroup);
    tailParent = segGroup;
  }
  parts.tailSegs = tailSegs;

  group.userData.parts = parts;

  // ---- Locomotion state -----------------------------------------------------
  group.userData.locomotion = {
    speed: rand(1.6, 2.6),
    waypoint: new THREE.Vector3(rand(-28, 28), 0, rand(-28, 28)),
    gaitPhase: rand(0, Math.PI * 2),
    hopPhase: rand(0, Math.PI * 2),
    excited: false,
    exciteTimer: 0,
  };

  return group;
}

// ---------------------------------------------------------------------------
// Advances one cat's position + articulation for a single frame.
// roamRadius bounds the wander area (kept near plaza / avenues).
// ---------------------------------------------------------------------------
export function updateMoruCat(cat, dt, elapsed, roamRadius = 34) {
  const loco = cat.userData.locomotion;
  const parts = cat.userData.parts;

  // steer toward waypoint; pick a new one when close
  const toTarget = new THREE.Vector3().subVectors(loco.waypoint, cat.position);
  toTarget.y = 0;
  const dist = toTarget.length();
  if (dist < 0.6) {
    const angle = Math.random() * Math.PI * 2;
    const radius = rand(4, roamRadius);
    loco.waypoint.set(Math.cos(angle) * radius, 0, Math.sin(angle) * radius);
  } else {
    toTarget.normalize();
    const speedMul = loco.excited ? 1.8 : 1.0;
    cat.position.x += toTarget.x * loco.speed * speedMul * dt;
    cat.position.z += toTarget.z * loco.speed * speedMul * dt;
    const targetAngle = Math.atan2(toTarget.x, toTarget.z);
    let angDiff = targetAngle - cat.rotation.y;
    angDiff = Math.atan2(Math.sin(angDiff), Math.cos(angDiff));
    cat.rotation.y += angDiff * Math.min(1, dt * 6);
  }

  // gait cycle: legs swing opposite pairs, hop bob, tail wag
  const gaitSpeed = loco.excited ? 14 : 8;
  loco.gaitPhase += dt * gaitSpeed;
  loco.hopPhase += dt * (loco.excited ? 10 : 5);

  const swingA = Math.sin(loco.gaitPhase) * 0.5;
  const swingB = Math.sin(loco.gaitPhase + Math.PI) * 0.5;
  parts.legFL.rotation.x = swingA;
  parts.legBR.rotation.x = swingA;
  parts.legFR.rotation.x = swingB;
  parts.legBL.rotation.x = swingB;

  const hop = Math.abs(Math.sin(loco.hopPhase)) * (loco.excited ? 0.28 : 0.1);
  cat.position.y = hop;

  const tailWag = Math.sin(elapsed * 4 + loco.gaitPhase * 0.3);
  parts.tailSegs.forEach((seg, i) => {
    seg.rotation.y = tailWag * (0.25 + i * 0.12);
    seg.rotation.x = Math.sin(elapsed * 3 + i) * 0.06;
  });

  // head bob + cheek breathing for liveliness
  parts.headGroup.rotation.z = Math.sin(elapsed * 2 + loco.gaitPhase * 0.2) * 0.04;
  const breathe = 1 + Math.sin(elapsed * 3) * 0.02;
  parts.torso.scale.set(1.15 * breathe, 0.95, 1.0 * breathe);

  if (loco.excited) {
    loco.exciteTimer -= dt;
    if (loco.exciteTimer <= 0) loco.excited = false;
  }
}

export function exciteCat(cat, duration = 1.4) {
  const loco = cat.userData.locomotion;
  loco.excited = true;
  loco.exciteTimer = duration;
}


