const VALID_THEMES = ['night', 'gold', 'day'];
const initialParams = new URLSearchParams(window.location.search);
const initialTheme = VALID_THEMES.includes(initialParams.get('theme')) ? initialParams.get('theme') : 'night';

const state = {
  spinning: true,
  catCount: cats.length,
  forgeStrikes: 0,
  theme: initialTheme,
  disposedCount: 0,
  cameraMode: 'overview',
  frame: 0,
  buildingCount: cityData.buildingCount,
  lampCount: cityData.lampCount,
  treeCount: cityData.treeCount,
  totalTriangles: 0,
  fps: 0,
};

let currentSkyTexture = null;

function computeTriangleCount() {
  let total = 0;
  scene.traverse((obj) => {
    if (!obj.isMesh || !obj.geometry) return;
    const geo = obj.geometry;
    if (geo.index) {
      total += geo.index.count / 3;
    } else if (geo.attributes && geo.attributes.position) {
      total += geo.attributes.position.count / 3;
    }
  });
  return Math.round(total);
}

function applyTheme(themeName) {
  const cfg = THEME_CONFIG[themeName];
  if (!cfg) return;

  if (currentSkyTexture) {
    currentSkyTexture.dispose();
    state.disposedCount += 1;
  }
  const skyTex = createSkyTexture(themeName);
  scene.background = skyTex;
  currentSkyTexture = skyTex;

  scene.fog.color.set(cfg.fogColor);
  scene.fog.near = cfg.fogNear;
  scene.fog.far = cfg.fogFar;

  hemiLight.color.set(cfg.hemiSky);
  hemiLight.groundColor.set(cfg.hemiGround);
  hemiLight.intensity = cfg.hemiIntensity;

  dirLight.color.set(cfg.dirColor);
  dirLight.intensity = cfg.dirIntensity;

  ambientLight.intensity = cfg.ambientIntensity;

  renderer.toneMappingExposure = cfg.exposure;

  bloomPass.strength = cfg.bloomStrength;
  bloomPass.radius = cfg.bloomRadius;
  bloomPass.threshold = cfg.bloomThreshold;

  state.theme = themeName;

  const url = new URL(window.location.href);
  url.searchParams.set('theme', themeName);
  window.history.replaceState({}, '', url);
}

applyTheme(initialTheme);
state.totalTriangles = computeTriangleCount();

// ---------------------------------------------------------------------------
// window.__app exposure for external inspection / grading harness
// ---------------------------------------------------------------------------
window.__app = { scene, camera, renderer, composer, state };

// ---------------------------------------------------------------------------
// UI wiring
// ---------------------------------------------------------------------------
document.getElementById('btn-spawn-cat').addEventListener('click', () => {
  const cat = createMoruCat({ scale: 0.92 + Math.random() * 0.2 });
  const angle = Math.random() * Math.PI * 2;
  const radius = 6 + Math.random() * 20;
  cat.position.set(Math.cos(angle) * radius, 0, Math.sin(angle) * radius);
  cat.rotation.y = Math.random() * Math.PI * 2;
  scene.add(cat);
  cats.push(cat);
  state.catCount = cats.length;
});

document.getElementById('btn-forge-strike').addEventListener('click', () => {
  forge.triggerStrike();
  state.forgeStrikes += 1;
  cats.forEach((cat) => exciteCat(cat, 1.2));
});

document.getElementById('mode-night').addEventListener('click', () => applyTheme('night'));
document.getElementById('mode-gold').addEventListener('click', () => applyTheme('gold'));
document.getElementById('mode-day').addEventListener('click', () => applyTheme('day'));

document.getElementById('cam-overview').addEventListener('click', () => applyCameraPreset('overview'));
document.getElementById('cam-iso').addEventListener('click', () => applyCameraPreset('iso'));
document.getElementById('cam-street').addEventListener('click', () => applyCameraPreset('street'));
document.getElementById('cam-follow-cat').addEventListener('click', () => {
  state.cameraMode = 'follow';
  controls.enabled = false;
  controls.autoRotate = false;
  followCat = cats[Math.floor(Math.random() * cats.length)];
});

document.getElementById('toggle-spin').addEventListener('click', () => {
  state.spinning = !state.spinning;
});

window.addEventListener('resize', () => {
  const w = window.innerWidth;
  const h = window.innerHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  composer.setSize(w, h);
  bloomPass.setSize(w, h);
});

// ---------------------------------------------------------------------------
// Follow-cam update: smooth 3rd-person chase behind the active Moru Cat
// ---------------------------------------------------------------------------
function updateFollowCam(dt) {
  if (!followCat) return;
  const rotY = followCat.rotation.y;
  const dir = new THREE.Vector3(Math.sin(rotY), 0, Math.cos(rotY));
  const desired = followCat.position.clone().addScaledVector(dir, -3.4);
  desired.y = followCat.position.y + 2.0;
  camera.position.lerp(desired, Math.min(1, dt * 3.2));
  const lookTarget = followCat.position.clone();
  lookTarget.y += 0.6;
  camera.lookAt(lookTarget);
}

// ---------------------------------------------------------------------------
// HUD
// ---------------------------------------------------------------------------
const hudEl = document.getElementById('fps-hud');
let hudAccum = 0;
let hudFrameCounter = 0;
let fpsEstimate = 60;

function updateHud(dt) {
  hudFrameCounter += 1;
  hudAccum += dt;
  fpsEstimate = fpsEstimate * 0.9 + (1 / Math.max(dt, 0.0001)) * 0.1;
  if (hudAccum >= 0.5) {
    hudAccum = 0;
    state.fps = Math.round(fpsEstimate);
    state.totalTriangles = computeTriangleCount();
    hudEl.textContent =
      `FPS: ${state.fps}  |  Cats: ${state.catCount}  |  Buildings: ${state.buildingCount}  |  ` +
      `Lamps: ${state.lampCount}  |  Tris: ${(state.totalTriangles / 1000).toFixed(1)}k tris  |  ` +
      `Frame: ${state.frame}  |  Theme: ${state.theme}  |  Strikes: ${state.forgeStrikes}`;
  }
}

// ---------------------------------------------------------------------------
// Main render loop
// ---------------------------------------------------------------------------
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.1);
  const elapsed = clock.elapsedTime;

  if (state.spinning) {
    state.frame += 1;

    cats.forEach((cat) => updateMoruCat(cat, dt, elapsed, cityData.plazaClearRadius - 2));
    forge.update(dt, elapsed, true);

    cityData.buildingGroup.children.forEach((building) => {
      building.traverse((child) => {
        if (child.userData.isBeacon) {
          child.material.emissiveIntensity = 2 + Math.sin(elapsed * 4 + building.position.x) * 1.4;
        }
      });
    });

    if (state.cameraMode === 'follow') {
      updateFollowCam(dt);
    } else {
      controls.update();
    }

    updateHud(dt);
  }

  composer.render();
}

applyCameraPreset('overview');
animate();


// ====== src/world/city.js (18234 bytes) ======
import * as THREE from 'three';
import {
  createFacadeTexture,
  createRoadTexture,
  createSidewalkTexture,
  createPlazaStoneTexture,
} from './textures.js';

const NEON_PALETTE = [0x29e0ff, 0xff4fd8, 0xffd23f, 0x3dffb0, 0xff7a2d, 0x8a5cff];

function pick(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

function rand(min, max) {
  return min + Math.random() * (max - min);
}

// ---------------------------------------------------------------------------
// Facade texture pool — a handful of varied CanvasTexture window grids shared
// across many buildings so we don't pay canvas-generation cost per building.
// ---------------------------------------------------------------------------
function buildFacadeTexturePool() {
  const pool = [];
  const hues = [0.55, 0.5, 0.58, 0.62, 0.48, 0.52];
  for (let i = 0; i < 8; i++) {
    pool.push(
      createFacadeTexture({
        cols: 6 + (i % 4),
        rows: 14 + (i % 5) * 2,
        hue: hues[i % hues.length],
        neonHue: 0.06 + (i % 3) * 0.02,
        litChance: 0.4 + Math.random() * 0.35,
      })
    );
  }
  return pool;
}

// ---------------------------------------------------------------------------
// Single multi-tier skyscraper with neon trim, and optional spire / helipad
// ---------------------------------------------------------------------------
function createSkyscraper(facadePool, opts) {
  const group = new THREE.Group();
  group.userData.isBuilding = true;

  const baseW = opts.width;
  const baseD = opts.depth;
  const totalHeight = opts.height;
  const tierCount = opts.tiers;
  const neonColor = opts.neonColor;

  const roofMat = new THREE.MeshStandardMaterial({ color: 0x11141c, roughness: 0.6, metalness: 0.4 });
  const baseMat = new THREE.MeshStandardMaterial({ color: 0x090a10, roughness: 0.8, metalness: 0.2 });

  let currentY = 0;
  let currentW = baseW;
  let currentD = baseD;
  const tierHeightTotal = totalHeight * 0.92;

  for (let t = 0; t < tierCount; t++) {
    const tierH = (tierHeightTotal / tierCount) * rand(0.85, 1.15);
    const shrink = t === 0 ? 1 : rand(0.68, 0.86);
    currentW *= t === 0 ? 1 : shrink;
    currentD *= t === 0 ? 1 : shrink;

    const facadeTex = pick(facadePool).clone();
    facadeTex.needsUpdate = true;
    facadeTex.repeat.set(Math.max(1, Math.round(currentW / 6)), Math.max(1, Math.round(tierH / 6)));
    const sideMat = new THREE.MeshStandardMaterial({
      map: facadeTex,
      roughness: 0.55,
      metalness: 0.25,
      emissive: new THREE.Color(0x0, 0x0, 0x0),
    });

    const geo = new THREE.BoxGeometry(currentW, tierH, currentD, 1, 1, 1);
    const mesh = new THREE.Mesh(geo, [sideMat, sideMat, roofMat, baseMat, sideMat, sideMat]);
    mesh.position.y = currentY + tierH / 2;
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    group.add(mesh);

    // rooftop neon trim frame around each tier top (thin emissive box ring)
    const trimThickness = Math.min(currentW, currentD) * 0.04 + 0.05;
    const trimY = currentY + tierH;
    const trimMat = new THREE.MeshStandardMaterial({
      color: neonColor,
      emissive: neonColor,
      emissiveIntensity: 2.2,
      roughness: 0.3,
    });
    const frameParts = [
      { w: currentW + trimThickness, d: trimThickness, x: 0, z: currentD / 2 },
      { w: currentW + trimThickness, d: trimThickness, x: 0, z: -currentD / 2 },
      { w: trimThickness, d: currentD + trimThickness, x: currentW / 2, z: 0 },
      { w: trimThickness, d: currentD + trimThickness, x: -currentW / 2, z: 0 },
    ];
    frameParts.forEach((p) => {
      const fg = new THREE.BoxGeometry(p.w, trimThickness * 0.8, p.d);
      const fm = new THREE.Mesh(fg, trimMat);
      fm.position.set(p.x, trimY, p.z);
      group.add(fm);
    });

    currentY += tierH;
  }

  // spire on top for taller / thinner buildings
  if (opts.hasSpire) {
    const spireH = totalHeight * 0.1;
    const spireGeo = new THREE.ConeGeometry(Math.min(currentW, currentD) * 0.22, spireH, 10);
    const spireMat = new THREE.MeshStandardMaterial({
      color: 0xcfd6e0,
      emissive: neonColor,
      emissiveIntensity: 0.8,
      metalness: 0.7,
      roughness: 0.3,
    });
    const spire = new THREE.Mesh(spireGeo, spireMat);
    spire.position.y = currentY + spireH / 2;
    group.add(spire);

    const beaconGeo = new THREE.SphereGeometry(Math.min(currentW, currentD) * 0.06, 8, 6);
    const beaconMat = new THREE.MeshStandardMaterial({
      color: 0xff2d2d,
      emissive: 0xff2d2d,
      emissiveIntensity: 3,
    });
    const beacon = new THREE.Mesh(beaconGeo, beaconMat);
    beacon.position.y = currentY + spireH + Math.min(currentW, currentD) * 0.06;
    beacon.userData.isBeacon = true;
    group.add(beacon);
    currentY += spireH;
  }

  // helipad on top for shorter / wider buildings
  if (opts.hasHelipad) {
    const padR = Math.min(currentW, currentD) * 0.38;
    const padGeo = new THREE.CylinderGeometry(padR, padR, 0.35, 20);
    const padMat = new THREE.MeshStandardMaterial({ color: 0x1c1f26, roughness: 0.75, metalness: 0.2 });
    const pad = new THREE.Mesh(padGeo, padMat);
    pad.position.y = currentY + 0.18;
    pad.castShadow = true;
    group.add(pad);

    const ringGeo = new THREE.TorusGeometry(padR * 0.82, 0.08, 6, 24);
    const ringMat = new THREE.MeshStandardMaterial({
      color: 0xffcc33,
      emissive: 0xffcc33,
      emissiveIntensity: 2.4,
    });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.rotation.x = Math.PI / 2;
    ring.position.y = currentY + 0.4;
    group.add(ring);

    // H marking using two thin boxes
    const hMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xffffff, emissiveIntensity: 1.2 });
    const barGeo1 = new THREE.BoxGeometry(padR * 0.14, 0.05, padR * 0.7);
    const barL = new THREE.Mesh(barGeo1, hMat);
    barL.position.set(-padR * 0.2, currentY + 0.4, 0);
    const barR2 = new THREE.Mesh(barGeo1, hMat);
    barR2.position.set(padR * 0.2, currentY + 0.4, 0);
    const barGeo2 = new THREE.BoxGeometry(padR * 0.5, 0.05, padR * 0.14);
    const barM = new THREE.Mesh(barGeo2, hMat);
    barM.position.set(0, currentY + 0.4, 0);
    group.add(barL, barR2, barM);
  }

  // rooftop AC unit clutter for variety
  const acCount = Math.floor(rand(1, 4));
  for (let i = 0; i < acCount; i++) {
    const acGeo = new THREE.BoxGeometry(rand(0.6, 1.2), rand(0.5, 0.9), rand(0.6, 1.2));
    const acMat = new THREE.MeshStandardMaterial({ color: 0x3a3f4a, roughness: 0.7 });
    const ac = new THREE.Mesh(acGeo, acMat);
    ac.position.set(rand(-currentW * 0.3, currentW * 0.3), currentY + 0.3, rand(-currentD * 0.3, currentD * 0.3));
    ac.castShadow = true;
    group.add(ac);
  }

  group.userData.totalHeight = currentY;
  return group;
}

// ---------------------------------------------------------------------------
// Stylized multi-sphere / cone tree
// ---------------------------------------------------------------------------
function createTree(kind) {
  const group = new THREE.Group();
  group.userData.isTree = true;

  const trunkH = rand(1.6, 2.6);
  const trunkGeo = new THREE.CylinderGeometry(0.14, 0.2, trunkH, 7);
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x4a3324, roughness: 0.9 });
  const trunk = new THREE.Mesh(trunkGeo, trunkMat);
  trunk.position.y = trunkH / 2;
  trunk.castShadow = true;
  group.add(trunk);

  const foliageColors = [0x2f9e52, 0x3bb765, 0x228b4a, 0x45c26e, 0x1f7a3d];
  const foliageColor = pick(foliageColors);
  const foliageMat = new THREE.MeshStandardMaterial({ color: foliageColor, roughness: 0.85 });

  if (kind === 'round') {
    const blobCount = 3;
    for (let i = 0; i < blobCount; i++) {
      const r = rand(0.65, 1.05) * (1 - i * 0.12);
      const geo = new THREE.SphereGeometry(r, 10, 8);
      const mesh = new THREE.Mesh(geo, foliageMat);
      mesh.position.set(rand(-0.4, 0.4), trunkH + r * 0.7 + i * r * 0.55, rand(-0.4, 0.4));
      mesh.castShadow = true;
      group.add(mesh);
    }
  } else {
    // conical evergreen: stacked cones
    const tiers = 3;
    let y = trunkH;
    for (let i = 0; i < tiers; i++) {
      const r = (1.1 - i * 0.28) * rand(0.9, 1.1);
      const h = rand(0.9, 1.3);
      const geo = new THREE.ConeGeometry(r, h, 9);
      const mesh = new THREE.Mesh(geo, foliageMat);
      mesh.position.y = y + h / 2;
      mesh.castShadow = true;
      group.add(mesh);
      y += h * 0.62;
    }
  }

  return group;
}

// ---------------------------------------------------------------------------
// Streetlamp with glowing bulb + ground light pool disc
// ---------------------------------------------------------------------------
function createStreetlamp() {
  const group = new THREE.Group();
  group.userData.isLamp = true;

  const poleH = 3.6;
  const poleGeo = new THREE.CylinderGeometry(0.08, 0.1, poleH, 7);
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x2a2d33, roughness: 0.6, metalness: 0.6 });
  const pole = new THREE.Mesh(poleGeo, poleMat);
  pole.position.y = poleH / 2;
  pole.castShadow = true;
  group.add(pole);

  const armGeo = new THREE.BoxGeometry(0.7, 0.08, 0.08);
  const arm = new THREE.Mesh(armGeo, poleMat);
  arm.position.set(0.32, poleH - 0.05, 0);
  group.add(arm);

  const headGeo = new THREE.SphereGeometry(0.22, 10, 8);
  const lampColor = pick([0xfff0c0, 0xbfe9ff, 0xffd9a0]);
  const headMat = new THREE.MeshStandardMaterial({
    color: lampColor,
    emissive: lampColor,
    emissiveIntensity: 2.6,
  });
  const head = new THREE.Mesh(headGeo, headMat);
  head.position.set(0.62, poleH - 0.12, 0);
  group.add(head);

  const bulbGeo = new THREE.SphereGeometry(0.1, 8, 6);
  const bulb = new THREE.Mesh(bulbGeo, headMat);
  bulb.position.set(0.62, poleH - 0.3, 0);
  group.add(bulb);

  const poolGeo = new THREE.CircleGeometry(1.4, 24);
  const poolMat = new THREE.MeshBasicMaterial({
    color: lampColor,
    transparent: true,
    opacity: 0.16,
    depthWrite: false,
  });
  const pool = new THREE.Mesh(poolGeo, poolMat);
  pool.rotation.x = -Math.PI / 2;
  pool.position.set(0.62, 0.02, 0);
  group.add(pool);

  // No per-lamp THREE.PointLight here on purpose: with 100+ lamps, real
  // dynamic lights would overwhelm the forward-lighting uniform budget.
  // The glow is conveyed by the emissive bulb + UnrealBloomPass instead.

  return group;
}

// ---------------------------------------------------------------------------
// Main city builder — returns { group, buildingCount, treeCount, lampCount }
// ---------------------------------------------------------------------------
export function buildCity(scene) {
  const cityGroup = new THREE.Group();
  cityGroup.name = 'city';

  const facadePool = buildFacadeTexturePool();

  // ---- Ground plaza-adjacent terrain plane ----------------------------------
  const plazaStoneTex = createPlazaStoneTexture();
  plazaStoneTex.repeat.set(10, 10);
  const groundGeo = new THREE.PlaneGeometry(420, 420, 1, 1);
  const groundMat = new THREE.MeshStandardMaterial({ color: 0x242622, roughness: 0.95 });
  const ground = new THREE.Mesh(groundGeo, groundMat);
  ground.rotation.x = -Math.PI / 2;
  ground.position.y = -0.02;
  ground.receiveShadow = true;
  cityGroup.add(ground);

  const sidewalkTex = createSidewalkTexture();
  sidewalkTex.repeat.set(30, 30);
  const sidewalkGeo = new THREE.PlaneGeometry(380, 380, 1, 1);
  const sidewalkMat = new THREE.MeshStandardMaterial({ map: sidewalkTex, roughness: 0.9 });
  const sidewalk = new THREE.Mesh(sidewalkGeo, sidewalkMat);
  sidewalk.rotation.x = -Math.PI / 2;
  sidewalk.position.y = -0.01;
  sidewalk.receiveShadow = true;
  cityGroup.add(sidewalk);

  // ---- Road grid --------------------------------------------------------
  const blockSize = 30;
  const roadWidth = 9;
  const gridExtent = 150; // roads span [-gridExtent, gridExtent]
  const roadTex = createRoadTexture({ withCrosswalk: false });
  const crossTex = createRoadTexture({ withCrosswalk: true });

  const avenuePositions = [];
  for (let p = -gridExtent; p <= gridExtent; p += blockSize) {
    if (Math.abs(p) < 20) continue; // keep plaza core clear of road slabs through center
    avenuePositions.push(p);
  }

  // roads running along X (horizontal strips) at each grid Z position
  avenuePositions.forEach((zPos) => {
    const tex = roadTex.clone();
    tex.repeat.set(1, Math.round((gridExtent * 2) / 8));
    tex.needsUpdate = true;
    const geo = new THREE.PlaneGeometry(gridExtent * 2, roadWidth);
    const mat = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.85 });
    const road = new THREE.Mesh(geo, mat);
    road.rotation.x = -Math.PI / 2;
    road.rotation.z = Math.PI / 2;
    road.position.set(0, 0, zPos);
    road.receiveShadow = true;
    cityGroup.add(road);
  });

  // roads running along Z (vertical strips) at each grid X position
  avenuePositions.forEach((xPos) => {
    const tex = roadTex.clone();
    tex.repeat.set(1, Math.round((gridExtent * 2) / 8));
    tex.needsUpdate = true;
    const geo = new THREE.PlaneGeometry(gridExtent * 2, roadWidth);
    const mat = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.85 });
    const road = new THREE.Mesh(geo, mat);
    road.rotation.x = -Math.PI / 2;
    road.position.set(xPos, 0.001, 0);
    road.receiveShadow = true;
    cityGroup.add(road);
  });

  // crosswalks at intersections
  avenuePositions.forEach((xPos) => {
    avenuePositions.forEach((zPos) => {
      const geo = new THREE.PlaneGeometry(roadWidth, roadWidth);
      const mat = new THREE.MeshStandardMaterial({ map: crossTex, roughness: 0.85 });
      const cw = new THREE.Mesh(geo, mat);
      cw.rotation.x = -Math.PI / 2;
      cw.position.set(xPos, 0.002, zPos);
      cw.receiveShadow = true;
      cityGroup.add(cw);
    });
  });

  // ---- Buildings ----------------------------------------------------------
  const PLAZA_CLEAR_RADIUS = 36;
  const buildingGroup = new THREE.Group();
  buildingGroup.name = 'buildings';
  let buildingCount = 0;
  const targetBuildings = 65;

  const cellCenters = [];
  for (let gx = -gridExtent + blockSize / 2; gx < gridExtent; gx += blockSize) {
    for (let gz = -gridExtent + blockSize / 2; gz < gridExtent; gz += blockSize) {
      if (Math.hypot(gx, gz) < PLAZA_CLEAR_RADIUS) continue;
      cellCenters.push([gx, gz]);
    }
  }
  // shuffle for variety, then slice/duplicate to reach target count with jitter
  cellCenters.sort(() => Math.random() - 0.5);

  let cellIdx = 0;
  while (buildingCount < targetBuildings && cellCenters.length > 0) {
    const [cx, cz] = cellCenters[cellIdx % cellCenters.length];
    // allow up to 2 buildings per cell with offset for higher density
    const sub = Math.floor(cellIdx / cellCenters.length);
    if (sub > 1) break;
    const offsetX = sub === 0 ? rand(-4, 4) : rand(-9, 9);
    const offsetZ = sub === 0 ? rand(-4, 4) : rand(-9, 9);
    const x = cx + offsetX;
    const z = cz + offsetZ;
    if (Math.hypot(x, z) < PLAZA_CLEAR_RADIUS) {
      cellIdx++;
      continue;
    }

    const width = rand(4, 8);
    const depth = rand(4, 8);
    const height = rand(10, 48);
    const tiers = height > 32 ? 3 : height > 18 ? 2 : 1;
    const neonColor = pick(NEON_PALETTE);
    const hasSpire = height > 34 && Math.random() < 0.6;
    const hasHelipad = !hasSpire && height > 16 && Math.random() < 0.45;

    const building = createSkyscraper(facadePool, { width, depth, height, tiers, neonColor, hasSpire, hasHelipad });
    building.position.set(x, 0, z);
    building.rotation.y = Math.round(rand(0, 3)) * (Math.PI / 2) + rand(-0.03, 0.03);
    buildingGroup.add(building);
    buildingCount++;
    cellIdx++;
  }

  cityGroup.add(buildingGroup);

  // ---- Trees ----------------------------------------------------------------
  const treeGroup = new THREE.Group();
  treeGroup.name = 'trees';
  let treeCount = 0;
  const targetTrees = 76;

  while (treeCount < targetTrees) {
    const angle = Math.random() * Math.PI * 2;
    const radius = rand(PLAZA_CLEAR_RADIUS - 4, gridExtent * 1.05);
    const x = Math.cos(angle) * radius;
    const z = Math.sin(angle) * radius;
    // avoid placing directly on road lines by nudging away from grid lines
    const nearRoad = avenuePositions.some((p) => Math.abs(x - p) < roadWidth / 2 + 1 || Math.abs(z - p) < roadWidth / 2 + 1);
    if (nearRoad) continue;
    const tree = createTree(Math.random() > 0.5 ? 'round' : 'cone');
    tree.position.set(x, 0, z);
    tree.scale.setScalar(rand(0.85, 1.3));
    treeGroup.add(tree);
    treeCount++;
  }
  cityGroup.add(treeGroup);

  // ---- Streetlamps ------------------------------------------------------------
  // Build the full set of candidate lamp slots along every avenue, then
  // shuffle and cap to a fixed target count. A real PointLight per lamp
  // would be far too many dynamic lights for WebGL, so the geometry-only
  // candidate count can be generous (lamps rely on emissive + bloom glow).
  const lampGroup = new THREE.Group();
  lampGroup.name = 'lamps';
  const lampSpacing = 16;
  const targetLamps = 108;
  const lampCandidates = [];

  avenuePositions.forEach((zPos) => {
    for (let x = -gridExtent; x <= gridExtent; x += lampSpacing) {
      if (Math.hypot(x, zPos) < PLAZA_CLEAR_RADIUS - 2) continue;
      lampCandidates.push({ x, z: zPos + roadWidth / 2 + 1.2, rotY: Math.PI });
    }
  });
  avenuePositions.forEach((xPos) => {
    for (let z = -gridExtent; z <= gridExtent; z += lampSpacing) {
      if (Math.hypot(xPos, z) < PLAZA_CLEAR_RADIUS - 2) continue;
      lampCandidates.push({ x: xPos + roadWidth / 2 + 1.2, z, rotY: -Math.PI / 2 });
    }
  });

  lampCandidates.sort(() => Math.random() - 0.5);
  const chosenLamps = lampCandidates.slice(0, targetLamps);
  let lampCount = 0;
  chosenLamps.forEach((slot) => {
    const lamp = createStreetlamp();
    lamp.position.set(slot.x, 0, slot.z);
    lamp.rotation.y = slot.rotY;
    lampGroup.add(lamp);
    lampCount++;
  });
  cityGroup.add(lampGroup);

  scene.add(cityGroup);

  return {
    group: cityGroup,
    buildingGroup,
    treeGroup,
    lampGroup,
    buildingCount,
    treeCount,
    lampCount,
    avenuePositions,
    roadWidth,
    plazaClearRadius: PLAZA_CLEAR_RADIUS,
    gridExtent,
  };
}


