import * as THREE from 'three';
import { createRuneRingTexture } from './textures.js';

const EMBER_COUNT = 160;
const SPARK_COUNT = 90;
const MAX_SHOCKWAVES = 6;

function rand(min, max) {
  return min + Math.random() * (max - min);
}

// ---------------------------------------------------------------------------
// Detailed 3D anvil: base, waist, horn, heel, heated ingot resting on top
// ---------------------------------------------------------------------------
function buildAnvil() {
  const group = new THREE.Group();
  group.name = 'anvil';

  const ironMat = new THREE.MeshStandardMaterial({ color: 0x23242a, roughness: 0.4, metalness: 0.85 });
  const darkIronMat = new THREE.MeshStandardMaterial({ color: 0x14151a, roughness: 0.5, metalness: 0.8 });

  // base (wide stand)
  const baseGeo = new THREE.CylinderGeometry(0.55, 0.7, 0.5, 10);
  const base = new THREE.Mesh(baseGeo, darkIronMat);
  base.position.y = 0.25;
  base.castShadow = true;
  group.add(base);

  // waist (narrower neck connecting base to working top)
  const waistGeo = new THREE.CylinderGeometry(0.3, 0.45, 0.55, 10);
  const waist = new THREE.Mesh(waistGeo, ironMat);
  waist.position.y = 0.78;
  waist.castShadow = true;
  group.add(waist);

  // main body / working top (the flat-topped wedge)
  const topGeo = new THREE.BoxGeometry(1.3, 0.38, 0.62);
  const top = new THREE.Mesh(topGeo, ironMat);
  top.position.y = 1.18;
  top.castShadow = true;
  group.add(top);

  // horn (tapering cone pointing out one side)
  const hornGeo = new THREE.ConeGeometry(0.22, 0.75, 10);
  const horn = new THREE.Mesh(hornGeo, ironMat);
  horn.rotation.z = Math.PI / 2;
  horn.position.set(0.95, 1.2, 0);
  horn.castShadow = true;
  group.add(horn);

  // heel (small squared protrusion at the opposite end)
  const heelGeo = new THREE.BoxGeometry(0.4, 0.3, 0.55);
  const heel = new THREE.Mesh(heelGeo, ironMat);
  heel.position.set(-0.78, 1.14, 0);
  heel.castShadow = true;
  group.add(heel);

  // hardy hole detail (small dark box insert on top face)
  const holeGeo = new THREE.BoxGeometry(0.08, 0.08, 0.08);
  const hole = new THREE.Mesh(holeGeo, darkIronMat);
  hole.position.set(-0.4, 1.38, 0.12);
  group.add(hole);

  // heated ingot resting on the anvil top, glowing orange-white
  const ingotGeo = new THREE.BoxGeometry(0.42, 0.14, 0.2);
  const ingotMat = new THREE.MeshStandardMaterial({
    color: 0xff5a1f,
    emissive: 0xff6a20,
    emissiveIntensity: 2.4,
    roughness: 0.4,
  });
  const ingot = new THREE.Mesh(ingotGeo, ingotMat);
  ingot.position.set(0.15, 1.44, 0);
  ingot.userData.isIngot = true;
  group.add(ingot);

  const ingotLight = new THREE.PointLight(0xff6a20, 2.2, 6, 2);
  ingotLight.position.copy(ingot.position);
  ingotLight.position.y += 0.2;
  group.add(ingotLight);

  group.userData.ingot = ingot;
  group.userData.ingotLight = ingotLight;
  group.userData.anvilTopY = 1.44;
  return group;
}

// ---------------------------------------------------------------------------
// Animated forge hammer — swings down on strike, pivoted near the handle top
// ---------------------------------------------------------------------------
function buildHammer() {
  const pivot = new THREE.Group();
  pivot.name = 'forgeHammerPivot';

  const handleMat = new THREE.MeshStandardMaterial({ color: 0x5c3a22, roughness: 0.8 });
  const headMat = new THREE.MeshStandardMaterial({ color: 0x3a3d45, roughness: 0.35, metalness: 0.8 });

  const handleGeo = new THREE.CylinderGeometry(0.05, 0.06, 1.3, 8);
  const handle = new THREE.Mesh(handleGeo, handleMat);
  handle.position.y = -0.65;
  handle.castShadow = true;
  pivot.add(handle);

  const headGeo = new THREE.BoxGeometry(0.5, 0.26, 0.26);
  const head = new THREE.Mesh(headGeo, headMat);
  head.position.y = -1.28;
  head.castShadow = true;
  pivot.add(head);

  const headAccentGeo = new THREE.BoxGeometry(0.52, 0.06, 0.28);
  const headAccentMat = new THREE.MeshStandardMaterial({
    color: 0xff7a2d,
    emissive: 0xff7a2d,
    emissiveIntensity: 1.4,
  });
  const headAccent = new THREE.Mesh(headAccentGeo, headAccentMat);
  headAccent.position.y = -1.28;
  pivot.add(headAccent);

  pivot.userData.head = head;
  pivot.userData.restRotation = -0.55;
  pivot.rotation.z = pivot.userData.restRotation;
