}

// ---------------------------------------------------------------------------
// MoruForge — central plaza with octagonal dais, rune circle, magma hearth,
// anvil + hammer, shockwave rings, and ember/spark particle systems.
// ---------------------------------------------------------------------------
export class MoruForge {
  constructor(scene) {
    this.group = new THREE.Group();
    this.group.name = 'moruForge';
    this.scene = scene;

    this._buildDais();
    this._buildRuneCircle();
    this._buildMagmaHearth();

    this.anvil = buildAnvil();
    this.anvil.position.set(0.6, 0.72, 0.4);
    this.group.add(this.anvil);

    this.hammerPivot = buildHammer();
    this.hammerPivot.position.set(1.55, 2.5, 0.4);
    this.group.add(this.hammerPivot);

    this._buildEmbers();
    this._buildSparks();
    this._buildShockwaves();

    this.strikeTimer = 0;
    this.strikeActive = false;
    this.strikeCount = 0;

    scene.add(this.group);
  }

  _buildDais() {
    const tierCount = 4;
    const stoneMat = new THREE.MeshStandardMaterial({ color: 0x4a443c, roughness: 0.85 });
    const stoneMatDark = new THREE.MeshStandardMaterial({ color: 0x3a362f, roughness: 0.9 });
    let radius = 14;
    let y = 0;
    for (let i = 0; i < tierCount; i++) {
      const h = 0.45;
      const geo = new THREE.CylinderGeometry(radius, radius * 1.08, h, 8, 1);
      const mesh = new THREE.Mesh(geo, i % 2 === 0 ? stoneMat : stoneMatDark);
      mesh.position.y = y + h / 2;
      mesh.receiveShadow = true;
      mesh.castShadow = true;
      this.group.add(mesh);
      y += h;
      radius *= 0.72;
    }
    this.daisTopY = y;
    this.daisTopRadius = radius / 0.72 * 0.72; // approx top platform radius
  }

  _buildRuneCircle() {
    const runeTex = createRuneRingTexture();
    const geo = new THREE.CircleGeometry(this.daisTopRadius * 0.95, 32);
    const mat = new THREE.MeshStandardMaterial({
      map: runeTex,
      transparent: true,
      emissive: 0xff8a3d,
      emissiveMap: runeTex,
      emissiveIntensity: 1.6,
      roughness: 0.5,
    });
    const rune = new THREE.Mesh(geo, mat);
    rune.rotation.x = -Math.PI / 2;
    rune.position.y = this.daisTopY + 0.01;
    this.group.add(rune);
    this.runeMesh = rune;

    const glowLight = new THREE.PointLight(0xff8a3d, 1.8, 20, 2);
    glowLight.position.y = this.daisTopY + 1.5;
    this.group.add(glowLight);
  }

  _buildMagmaHearth() {
    const hearthGeo = new THREE.CylinderGeometry(1.6, 1.9, 0.6, 16);
    const hearthMat = new THREE.MeshStandardMaterial({ color: 0x2a221a, roughness: 0.9 });
    const hearth = new THREE.Mesh(hearthGeo, hearthMat);
    hearth.position.set(-2.4, this.daisTopY + 0.3, -1.6);
    hearth.castShadow = true;
    hearth.receiveShadow = true;
    this.group.add(hearth);

    const magmaGeo = new THREE.SphereGeometry(1.35, 16, 12, 0, Math.PI * 2, 0, Math.PI / 2);
    const magmaMat = new THREE.MeshStandardMaterial({
      color: 0xff4400,
      emissive: 0xff5500,
      emissiveIntensity: 2.8,
      roughness: 0.6,
    });
    const magma = new THREE.Mesh(magmaGeo, magmaMat);
    magma.position.set(-2.4, this.daisTopY + 0.6, -1.6);
    this.group.add(magma);
    this.magma = magma;
    this.magmaBaseIntensity = 2.8;

    const magmaLight = new THREE.PointLight(0xff5500, 3.2, 26, 2);
    magmaLight.position.copy(magma.position);
    magmaLight.position.y += 0.8;
    this.group.add(magmaLight);
    this.magmaLight = magmaLight;
    this.magmaLightBase = 3.2;

    this.hearthPosition = magma.position.clone();
  }

  _buildEmbers() {
    const positions = new Float32Array(EMBER_COUNT * 3);
    const velocities = new Float32Array(EMBER_COUNT * 3);
    const origin = this.hearthPosition || new THREE.Vector3(-2.4, this.daisTopY + 0.6, -1.6);

    for (let i = 0; i < EMBER_COUNT; i++) {
      const i3 = i * 3;
      positions[i3] = origin.x + rand(-1.4, 1.4);
      positions[i3 + 1] = origin.y + rand(0, 2.5);
      positions[i3 + 2] = origin.z + rand(-1.4, 1.4);
      velocities[i3] = rand(-0.2, 0.2);
      velocities[i3 + 1] = rand(0.6, 1.6);
      velocities[i3 + 2] = rand(-0.2, 0.2);
    }

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      color: 0xff9a3d,
      size: 0.09,
      transparent: true,
      opacity: 0.85,
      depthWrite: false,
    });
    const points = new THREE.Points(geo, mat);
    this.group.add(points);

    this.embers = { points, positions, velocities, origin };
  }

  _buildSparks() {
    const positions = new Float32Array(SPARK_COUNT * 3);
    const velocities = new Float32Array(SPARK_COUNT * 3);
    const life = new Float32Array(SPARK_COUNT);
    const origin = this.anvil ? this.anvil.position.clone().setY(this.anvil.position.y + 0.72) : new THREE.Vector3();

    for (let i = 0; i < SPARK_COUNT; i++) {
      const i3 = i * 3;
      positions[i3] = origin.x;
      positions[i3 + 1] = -999; // start inactive, off-screen
      positions[i3 + 2] = origin.z;
      velocities[i3] = 0;
      velocities[i3 + 1] = 0;
      velocities[i3 + 2] = 0;
      life[i] = 0;
    }

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      color: 0xffe08a,
      size: 0.07,
      transparent: true,
      opacity: 0.95,
      depthWrite: false,
    });
    const points = new THREE.Points(geo, mat);
    this.group.add(points);

    this.sparks = { points, positions, velocities, life, origin, cursor: 0 };
  }

  _buildShockwaves() {
    const rings = [];
    const ringGeo = new THREE.RingGeometry(0.4, 0.55, 32);
    for (let i = 0; i < MAX_SHOCKWAVES; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: 0xffb04d,
        transparent: true,
        opacity: 0,
        side: THREE.DoubleSide,
        depthWrite: false,
      });
      const mesh = new THREE.Mesh(ringGeo, mat);
      mesh.rotation.x = -Math.PI / 2;
      mesh.position.copy(this.anvil.position);
      mesh.position.y = this.daisTopY + 0.05;
      mesh.visible = false;
      mesh.userData.active = false;
      mesh.userData.age = 0;
      this.group.add(mesh);
      rings.push(mesh);
    }
    this.shockwaves = rings;
  }

  spawnShockwave() {
    const ring = this.shockwaves.find((r) => !r.userData.active);
    if (!ring) return;
    ring.userData.active = true;
    ring.userData.age = 0;
    ring.visible = true;
    ring.scale.setScalar(1);
    ring.material.opacity = 0.8;
    ring.position.set(this.anvil.position.x, this.daisTopY + 0.05, this.anvil.position.z);
  }

  burstSparks(count = 28) {
    const { positions, velocities, life, origin, cursor } = this.sparks;
    let idx = cursor;
    for (let n = 0; n < count; n++) {
      const i = idx % SPARK_COUNT;
      const i3 = i * 3;
      positions[i3] = origin.x + rand(-0.1, 0.1);
      positions[i3 + 1] = origin.y;
      positions[i3 + 2] = origin.z + rand(-0.1, 0.1);
      velocities[i3] = rand(-1.8, 1.8);
      velocities[i3 + 1] = rand(2.2, 4.2);
      velocities[i3 + 2] = rand(-1.8, 1.8);
      life[i] = rand(0.6, 1.1);
      idx++;
    }
    this.sparks.cursor = idx;
  }

  // Triggers hammer swing, sparks burst, and a shockwave ring expansion.
  triggerStrike() {
    this.strikeActive = true;
    this.strikeTimer = 0;
    this.strikeCount++;
    this.spawnShockwave();
  }

  update(dt, elapsed, spinning) {
    if (!spinning) return;

    // magma pulsing glow
    const pulse = 0.85 + Math.sin(elapsed * 2.2) * 0.15;
    this.magma.material.emissiveIntensity = this.magmaBaseIntensity * pulse;
    this.magmaLight.intensity = this.magmaLightBase * pulse;

    // rune circle slow rotation
    this.runeMesh.rotation.z += dt * 0.08;

    // embers rising and looping
    const { positions, velocities, origin } = this.embers;
    for (let i = 0; i < EMBER_COUNT; i++) {
      const i3 = i * 3;
      positions[i3] += velocities[i3] * dt;
      positions[i3 + 1] += velocities[i3 + 1] * dt;
      positions[i3 + 2] += velocities[i3 + 2] * dt;
      if (positions[i3 + 1] > origin.y + 4.5) {
        positions[i3] = origin.x + rand(-1.4, 1.4);
        positions[i3 + 1] = origin.y;
        positions[i3 + 2] = origin.z + rand(-1.4, 1.4);
      }
    }
    this.embers.points.geometry.attributes.position.needsUpdate = true;

    // sparks: gravity-affected bounce + fade via life
    const sp = this.sparks;
    for (let i = 0; i < SPARK_COUNT; i++) {
      if (sp.life[i] <= 0) continue;
      const i3 = i * 3;
      sp.velocities[i3 + 1] -= 9.8 * dt;
      sp.positions[i3] += sp.velocities[i3] * dt;
      sp.positions[i3 + 1] += sp.velocities[i3 + 1] * dt;
      sp.positions[i3 + 2] += sp.velocities[i3 + 2] * dt;
      sp.life[i] -= dt;
      if (sp.life[i] <= 0) {
        sp.positions[i3 + 1] = -999;
      }
    }
    sp.points.geometry.attributes.position.needsUpdate = true;

    // shockwave rings expansion + fade
    this.shockwaves.forEach((ring) => {
      if (!ring.userData.active) return;
      ring.userData.age += dt;
      const t = ring.userData.age / 1.1;
      if (t >= 1) {
        ring.userData.active = false;
        ring.visible = false;
        return;
      }
      ring.scale.setScalar(1 + t * 9);
      ring.material.opacity = 0.8 * (1 - t);
    });

    // hammer swing animation
    if (this.strikeActive) {
      this.strikeTimer += dt;
      const dur = 0.45;
      const t = Math.min(this.strikeTimer / dur, 1);
      // swing down fast (ease-in) then back up to rest (ease-out), simple sine arc
      const swing = Math.sin(t * Math.PI);
      this.hammerPivot.rotation.z = this.hammerPivot.userData.restRotation + swing * 1.35;
      if (t === 1 || t >= 0.48 && t < 0.52) {
        // impact moment near mid-swing — burst sparks once
      }
      if (t >= 0.45 && !this._impactFired) {
        this.burstSparks(28);
        this._impactFired = true;
      }
      if (t >= 1) {
        this.strikeActive = false;
        this._impactFired = false;
      }
    } else {
      // idle gentle sway
      this.hammerPivot.rotation.z = this.hammerPivot.userData.restRotation + Math.sin(elapsed * 0.6) * 0.03;
    }

    // ingot flicker
    const ingot = this.anvil.userData.ingot;
    const ingotLight = this.anvil.userData.ingotLight;
    const flicker = 2.0 + Math.sin(elapsed * 7.3) * 0.4 + Math.sin(elapsed * 13.1) * 0.2;
    ingot.material.emissiveIntensity = flicker;
    ingotLight.intensity = flicker * 0.9;
  }
}


