import * as THREE from 'three';

// ---------------------------------------------------------------------------
// Procedural sky dome gradient + speckle texture per atmosphere theme.
// Kept deliberately mid-toned (never pure black / pure white) so the
// rendered histogram stays inside the no-blackout / no-white-out guardrails.
// ---------------------------------------------------------------------------
export function createSkyTexture(theme) {
  const width = 512;
  const height = 512;
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  let top, horizon, stars = false, sunGlow = null;

  if (theme === 'night') {
    top = '#0b0f1e';
    horizon = '#1c2440';
    stars = true;
    sunGlow = { color: 'rgba(180,200,255,0.18)', y: 0.18 };
  } else if (theme === 'gold') {
    top = '#3a2a52';
    horizon = '#ff9a56';
    sunGlow = { color: 'rgba(255,214,150,0.4)', y: 0.62 };
  } else {
    top = '#3f7bb0';
    horizon = '#cfe6f2';
    sunGlow = { color: 'rgba(255,255,240,0.25)', y: 0.55 };
  }

  const grad = ctx.createLinearGradient(0, 0, 0, height);
  grad.addColorStop(0, top);
  grad.addColorStop(1, horizon);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  if (sunGlow) {
    const gx = width * 0.5;
    const gy = height * sunGlow.y;
    const radial = ctx.createRadialGradient(gx, gy, 0, gx, gy, width * 0.35);
    radial.addColorStop(0, sunGlow.color);
    radial.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = radial;
    ctx.fillRect(0, 0, width, height);
  }

  if (stars) {
    for (let i = 0; i < 220; i++) {
      const x = Math.random() * width;
      const y = Math.random() * height * 0.65;
      const b = 0.3 + Math.random() * 0.5;
      ctx.fillStyle = `rgba(255,255,255,${b})`;
      ctx.fillRect(x, y, 1.5, 1.5);
    }
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  return tex;
}

