import * as THREE from 'three';

function makeCanvas(w, h) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  return canvas;
}

// ---------------------------------------------------------------------------
// Skyscraper facade: multi-color illuminated window grid on a metal panel base
// ---------------------------------------------------------------------------
export function createFacadeTexture(opts = {}) {
  const {
    width = 256,
    height = 512,
    baseColor = '#1a2030',
    panelColor = '#232b3f',
    cols = 8,
    rows = 16,
    litChance = 0.55,
    hue = 0.55,
    neonHue = 0.08,
  } = opts;

  const canvas = makeCanvas(width, height);
  const ctx = canvas.getContext('2d');

  // base panel gradient
  const grad = ctx.createLinearGradient(0, 0, 0, height);
  grad.addColorStop(0, baseColor);
  grad.addColorStop(1, panelColor);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  // vertical structural mullions
  ctx.strokeStyle = 'rgba(0,0,0,0.35)';
  ctx.lineWidth = 2;
  const colW = width / cols;
  for (let c = 0; c <= cols; c++) {
    ctx.beginPath();
    ctx.moveTo(c * colW, 0);
    ctx.lineTo(c * colW, height);
    ctx.stroke();
  }

  const rowH = height / rows;
  const winMarginX = colW * 0.16;
  const winMarginY = rowH * 0.2;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const x = c * colW + winMarginX;
      const y = r * rowH + winMarginY;
      const w = colW - winMarginX * 2;
      const h = rowH - winMarginY * 2;

      const lit = Math.random() < litChance;
      if (lit) {
        const palette = Math.random();
        let colorA, colorB;
        if (palette < 0.4) {
          colorA = `hsl(${(hue * 360 + 10) % 360}, 85%, 70%)`;
          colorB = `hsl(${(hue * 360 - 10 + 360) % 360}, 90%, 45%)`;
        } else if (palette < 0.7) {
          colorA = `hsl(${(neonHue * 360 + 15) % 360}, 95%, 70%)`;
          colorB = `hsl(${(neonHue * 360 - 5 + 360) % 360}, 95%, 50%)`;
        } else {
          colorA = 'hsl(300, 80%, 75%)';
          colorB = 'hsl(280, 85%, 50%)';
        }
        const wGrad = ctx.createLinearGradient(x, y, x, y + h);
        wGrad.addColorStop(0, colorA);
        wGrad.addColorStop(1, colorB);
        ctx.fillStyle = wGrad;
        ctx.fillRect(x, y, w, h);

        // glow halo
        ctx.save();
        ctx.globalAlpha = 0.35;
        ctx.fillStyle = colorA;
        ctx.fillRect(x - w * 0.3, y - h * 0.3, w * 1.6, h * 1.6);
        ctx.restore();
      } else {
        ctx.fillStyle = 'rgba(10,14,22,0.9)';
        ctx.fillRect(x, y, w, h);
        ctx.strokeStyle = 'rgba(70,90,120,0.25)';
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, w, h);
      }
    }
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  tex.needsUpdate = true;
  return tex;
}

// ---------------------------------------------------------------------------
// Road surface: asphalt base + dashed lane lines + crosswalk stripes
// ---------------------------------------------------------------------------
export function createRoadTexture(opts = {}) {
  const { width = 512, height = 512, withCrosswalk = false, lanes = 2 } = opts;
  const canvas = makeCanvas(width, height);
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = '#23252b';
  ctx.fillRect(0, 0, width, height);

  // subtle asphalt grain
  for (let i = 0; i < 1200; i++) {
    ctx.fillStyle = `rgba(${Math.random() > 0.5 ? 255 : 0},${Math.random() > 0.5 ? 255 : 0},${Math.random() > 0.5 ? 255 : 0},${Math.random() * 0.03})`;
    ctx.fillRect(Math.random() * width, Math.random() * height, 2, 2);
  }

  // center dashed line running vertically (length axis of road)
  ctx.strokeStyle = '#f2d24b';
  ctx.lineWidth = width * 0.02;
  ctx.setLineDash([height * 0.12, height * 0.08]);
  ctx.beginPath();
  ctx.moveTo(width / 2, 0);
  ctx.lineTo(width / 2, height);
  ctx.stroke();
  ctx.setLineDash([]);

  // edge lines
  ctx.strokeStyle = 'rgba(255,255,255,0.75)';
  ctx.lineWidth = width * 0.012;
  ctx.beginPath();
  ctx.moveTo(width * 0.06, 0);
  ctx.lineTo(width * 0.06, height);
  ctx.moveTo(width * 0.94, 0);
  ctx.lineTo(width * 0.94, height);
  ctx.stroke();

  if (withCrosswalk) {
    ctx.fillStyle = 'rgba(255,255,255,0.85)';
    const stripeCount = 7;
    const stripeW = (width * 0.8) / stripeCount;
    for (let i = 0; i < stripeCount; i++) {
      const x = width * 0.1 + i * stripeW * 1.0;
      ctx.fillRect(x, height * 0.35, stripeW * 0.6, height * 0.3);
    }
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  tex.needsUpdate = true;
  return tex;
}

// ---------------------------------------------------------------------------
// Forge rune ring: glowing circular sigil pattern for the plaza dais
// ---------------------------------------------------------------------------
export function createRuneRingTexture(opts = {}) {
  const { size = 512, ringColor = '#ff7a2d', glowColor = '#ffd27a' } = opts;
  const canvas = makeCanvas(size, size);
  const ctx = canvas.getContext('2d');
  const cx = size / 2;
  const cy = size / 2;

  ctx.fillStyle = 'rgba(10,6,4,0)';
  ctx.fillRect(0, 0, size, size);

  const ringRadii = [size * 0.46, size * 0.36, size * 0.26];
  ringRadii.forEach((r, idx) => {
    ctx.save();
    ctx.strokeStyle = idx === 1 ? glowColor : ringColor;
    ctx.lineWidth = size * 0.012;
    ctx.globalAlpha = 0.9;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  });

  // rune glyphs: simple geometric ticks + triangles around the mid ring
  const glyphCount = 24;
  const glyphR = size * 0.36;
  for (let i = 0; i < glyphCount; i++) {
    const angle = (i / glyphCount) * Math.PI * 2;
    const gx = cx + Math.cos(angle) * glyphR;
    const gy = cy + Math.sin(angle) * glyphR;
    ctx.save();
    ctx.translate(gx, gy);
    ctx.rotate(angle + Math.PI / 2);
    ctx.fillStyle = i % 3 === 0 ? glowColor : ringColor;
    ctx.beginPath();
    const s = size * 0.018;
    ctx.moveTo(0, -s);
    ctx.lineTo(s * 0.7, s);
    ctx.lineTo(-s * 0.7, s);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  // inner sigil cross-lines (star pattern)
  ctx.save();
  ctx.strokeStyle = ringColor;
  ctx.globalAlpha = 0.65;
  ctx.lineWidth = size * 0.006;
  const points = 8;
  const starR = size * 0.26;
  for (let i = 0; i < points; i++) {
    const a1 = (i / points) * Math.PI * 2;
    const a2 = ((i + 3) / points) * Math.PI * 2;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(a1) * starR, cy + Math.sin(a1) * starR);
    ctx.lineTo(cx + Math.cos(a2) * starR, cy + Math.sin(a2) * starR);
    ctx.stroke();
  }
  ctx.restore();

  // outer soft glow halo
  const haloGrad = ctx.createRadialGradient(cx, cy, size * 0.3, cx, cy, size * 0.5);
  haloGrad.addColorStop(0, 'rgba(255,150,60,0.25)');
  haloGrad.addColorStop(1, 'rgba(255,150,60,0)');
  ctx.fillStyle = haloGrad;
  ctx.fillRect(0, 0, size, size);

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  return tex;
}

// ---------------------------------------------------------------------------
// Ground plaza paving: stone tile with subtle grid
// ---------------------------------------------------------------------------
export function createPlazaStoneTexture(opts = {}) {
  const { width = 512, height = 512 } = opts;
  const canvas = makeCanvas(width, height);
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = '#3a3630';
  ctx.fillRect(0, 0, width, height);

  for (let i = 0; i < 400; i++) {
    const shade = 40 + Math.random() * 30;
    ctx.fillStyle = `rgba(${shade + 20},${shade + 10},${shade},0.4)`;
    ctx.fillRect(Math.random() * width, Math.random() * height, 3, 3);
  }

  const tiles = 8;
  const tileSize = width / tiles;
  ctx.strokeStyle = 'rgba(10,8,6,0.5)';
  ctx.lineWidth = 2;
  for (let i = 0; i <= tiles; i++) {
    ctx.beginPath();
    ctx.moveTo(i * tileSize, 0);
    ctx.lineTo(i * tileSize, height);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * tileSize);
    ctx.lineTo(width, i * tileSize);
    ctx.stroke();
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  return tex;
}

// ---------------------------------------------------------------------------
// Sidewalk texture: lighter concrete with expansion joints
// ---------------------------------------------------------------------------
export function createSidewalkTexture(opts = {}) {
  const { width = 256, height = 256 } = opts;
  const canvas = makeCanvas(width, height);
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = '#9a9690';
  ctx.fillRect(0, 0, width, height);

  for (let i = 0; i < 300; i++) {
    const shade = 140 + Math.random() * 40;
    ctx.fillStyle = `rgba(${shade},${shade - 4},${shade - 10},0.3)`;
    ctx.fillRect(Math.random() * width, Math.random() * height, 2, 2);
  }

  ctx.strokeStyle = 'rgba(60,58,54,0.6)';
  ctx.lineWidth = 3;
  const seg = 4;
  for (let i = 1; i < seg; i++) {
    ctx.beginPath();
    ctx.moveTo((i * width) / seg, 0);
    ctx.lineTo((i * width) / seg, height);
    ctx.stroke();
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  return tex;
}


