    const cx = bx * (BLOCK_SIZE + ROAD_WIDTH) + (BLOCK_SIZE + ROAD_WIDTH) / 2;
    const cz = bz * (BLOCK_SIZE + ROAD_WIDTH) + (BLOCK_SIZE + ROAD_WIDTH) / 2;
    const count = 1 + Math.floor(Math.random() * 3);
