  lampLight.position.y = 4.2;
  group.add(lampLight);

  group.position.set(x, 0, z);
  return group;
}

for (let i = -CITY_RADIUS; i <= CITY_RADIUS; i++) {
  for (let j = -CITY_RADIUS; j <= CITY_RADIUS; j++) {
    const cx = i * (BLOCK_SIZE + ROAD_WIDTH);
    const cz = j * (BLOCK_SIZE + ROAD_WIDTH);
    scene.add(createStreetlamp(cx + ROAD_WIDTH, cz + ROAD_WIDTH));
  }
}

// ── Forge Plaza (center) ──
