// ── Moru Cat Character ──
function createCat(color) {
  const group = new THREE.Group();
  const catColor = color || new THREE.Color().setHSL(Math.random(), 0.7, 0.5);

  const bodyMat = new THREE.MeshStandardMaterial({ color: catColor, roughness: 0.6, metalness: 0.2 });

  // Body
  const body = new THREE.Mesh(new THREE.SphereGeometry(0.5, 12, 8), bodyMat);
  body.scale.set(1, 0.8, 1.3);
  body.position.y = 0.6;
  body.castShadow = true;
  group.add(body);

  // Head
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.35, 12, 8), bodyMat);
  head.position.set(0, 1.0, 0.5);
  head.castShadow = true;
  group.add(head);

  // Ears
  for (const side of [-1, 1]) {
    const ear = new THREE.Mesh(
      new THREE.ConeGeometry(0.12, 0.25, 4),
      bodyMat,
    );
    ear.position.set(side * 0.18, 1.35, 0.5);
    ear.rotation.z = side * 0.3;
    group.add(ear);

    const innerEar = new THREE.Mesh(
      new THREE.ConeGeometry(0.06, 0.15, 4),
      new THREE.MeshStandardMaterial({ color: 0xffaaaa }),
    );
    innerEar.position.set(side * 0.18, 1.33, 0.52);
    innerEar.rotation.z = side * 0.3;
    group.add(innerEar);
  }

  // Eyes
  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(
      new THREE.SphereGeometry(0.06, 8, 6),
      new THREE.MeshStandardMaterial({ color: 0x111111 }),
    );
    eye.position.set(side * 0.12, 1.05, 0.82);
    group.add(eye);

    const eyeShine = new THREE.Mesh(
      new THREE.SphereGeometry(0.025, 6, 4),
      neonMat(0x00ffff, 4),
    );
    eyeShine.position.set(side * 0.1, 1.07, 0.85);
    group.add(eyeShine);
  }

  // Nose
  const nose = new THREE.Mesh(
    new THREE.SphereGeometry(0.04, 6, 4),
    new THREE.MeshStandardMaterial({ color: 0xff6688 }),
  );
  nose.position.set(0, 0.97, 0.86);
  group.add(nose);

  // Tail
  const tailCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0, 0.6, -0.6),
    new THREE.Vector3(0, 0.9, -1.0),
    new THREE.Vector3(0.2, 1.3, -1.1),
    new THREE.Vector3(0.1, 1.5, -0.9),
  ]);
  const tail = new THREE.Mesh(
    new THREE.TubeGeometry(tailCurve, 12, 0.06, 6, false),
    bodyMat,
  );
  group.add(tail);

  // Legs
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) {
      const leg = new THREE.Mesh(
        new THREE.CylinderGeometry(0.08, 0.08, 0.4, 6),
        bodyMat,
      );
      leg.position.set(sx * 0.25, 0.2, sz * 0.35);
      leg.castShadow = true;
      leg.userData.isLeg = true;
      leg.userData.legPhase = (sx + sz) * 0.5;
      group.add(leg);
    }
  }

  // Neon collar
  const collar = new THREE.Mesh(
    new THREE.TorusGeometry(0.35, 0.03, 6, 16),
    neonMat(themes.night.neon[Math.floor(Math.random() * themes.night.neon.length)], 3),
  );
  collar.position.set(0, 0.9, 0.3);
  collar.rotation.x = Math.PI / 2;
  group.add(collar);

  // Cat behaviour state
  group.userData = {
    velocity: new THREE.Vector3(),
    targetPos: new THREE.Vector3(),
    speed: 2 + Math.random() * 3,
    jumpTimer: 0,
    isJumping: false,
    jumpVelocity: 0,
    idleTimer: 0,
    actionState: 'wander',
    wanderTimer: 0,
  };

  pickNewTarget(group);
  return group;
}

function pickNewTarget(cat) {
  const range = 35;
  cat.userData.targetPos.set(
    (Math.random() - 0.5) * range * 2,
    0,
    (Math.random() - 0.5) * range * 2,
  );
  cat.userData.wanderTimer = 2 + Math.random() * 5;
}

function updateCat(cat, dt) {
  const ud = cat.userData;
  ud.wanderTimer -= dt;

  if (ud.wanderTimer <= 0) {
    pickNewTarget(cat);
  }

  // Move toward target
  const dir = new THREE.Vector3().subVectors(ud.targetPos, cat.position);
  dir.y = 0;
  const dist = dir.length();

  if (dist > 1) {
    dir.normalize();
    cat.position.x += dir.x * ud.speed * dt;
    cat.position.z += dir.z * ud.speed * dt;

    // Face movement direction
    const angle = Math.atan2(dir.x, dir.z);
    cat.rotation.y = angle;

    // Leg animation
    const time = state.clock.getElapsedTime();
    cat.children.forEach((child) => {
      if (child.userData.isLeg) {
        child.position.y = 0.2 + Math.sin(time * ud.speed * 3 + child.userData.legPhase * Math.PI) * 0.1;
      }
    });

    // Bob body
    cat.position.y = (ud.isJumping ? cat.position.y : 0) +
      Math.abs(Math.sin(time * ud.speed * 3)) * 0.05;
  } else {
    pickNewTarget(cat);
  }

  // Random jumping
  ud.jumpTimer -= dt;
  if (ud.jumpTimer <= 0 && !ud.isJumping) {
    ud.isJumping = true;
    ud.jumpVelocity = 4 + Math.random() * 3;
    ud.jumpTimer = 3 + Math.random() * 5;
  }

  if (ud.isJumping) {
    cat.position.y += ud.jumpVelocity * dt;
    ud.jumpVelocity -= 12 * dt;
    if (cat.position.y <= 0) {
      cat.position.y = 0;
      ud.isJumping = false;
      ud.jumpVelocity = 0;
    }
  }
}

// Spawn initial cats
function spawnCat() {
  const cat = createCat();
  const angle = Math.random() * Math.PI * 2;
  const dist = 5 + Math.random() * 25;
  cat.position.set(Math.cos(angle) * dist, 0, Math.sin(angle) * dist);
  scene.add(cat);
  state.cats.push(cat);
  return cat;
}

for (let i = 0; i < 5; i++) spawnCat();

// ── Forge Strike Effect ──
function forgeStrike() {
  const forgeCenter = forgePlaza.position.clone();
  forgeCenter.y = 2.5;

  // Flash the forge fire light
  const fl = forgePlaza.userData.fireLight;
  if (fl) {
    fl.intensity = 8;
    setTimeout(() => { fl.intensity = 2; }, 300);
  }

  // Spawn particles
  for (let i = 0; i < 30; i++) {
    const particle = new THREE.Mesh(
      new THREE.SphereGeometry(0.08, 4, 3),
      neonMat(Math.random() > 0.5 ? 0xff6600 : 0xffaa00, 6),
    );
    particle.position.copy(forgeCenter);
    particle.userData.velocity = new THREE.Vector3(
      (Math.random() - 0.5) * 8,
      3 + Math.random() * 6,
      (Math.random() - 0.5) * 8,
    );
    particle.userData.life = 1.0;
    scene.add(particle);
    state.forgeParticles.push(particle);
  }
}

function updateForgeParticles(dt) {
  for (let i = state.forgeParticles.length - 1; i >= 0; i--) {
    const p = state.forgeParticles[i];
    p.userData.velocity.y -= 10 * dt;
    p.position.addScaledVector(p.userData.velocity, dt);
    p.userData.life -= dt * 1.5;
    p.scale.setScalar(Math.max(0.01, p.userData.life));

    if (p.userData.life <= 0) {
      scene.remove(p);
      p.geometry.dispose();
      p.material.dispose();
      state.forgeParticles.splice(i, 1);
    }
  }
}

// ── Forge embers animation ──
function updateForgeEmbers(time) {
  forgePlaza.children.forEach((child) => {
    if (child.userData.baseY !== undefined) {
      child.position.y = child.userData.baseY + Math.sin(time * child.userData.speed) * child.userData.range;
      child.material.emissiveIntensity = 3 + Math.sin(time * child.userData.speed * 2) * 2;
    }
  });
}

// ── Camera modes ──
const cameraTargets = {
  overview: { pos: new THREE.Vector3(40, 35, 40), lookAt: new THREE.Vector3(0, 0, 0) },
  iso: { pos: new THREE.Vector3(50, 50, 50), lookAt: new THREE.Vector3(0, 0, 0) },
  street: { pos: new THREE.Vector3(2, 2.5, 20), lookAt: new THREE.Vector3(0, 3, 0) },
};

function updateCamera(dt) {
  const mode = state.cameraMode;
  if (mode === 'follow-cat') {
    const cat = state.cats[0];
    if (cat) {
      const offset = new THREE.Vector3(-5, 4, -5);
      const targetPos = cat.position.clone().add(offset);
      camera.position.lerp(targetPos, dt * 3);
      const lookTarget = cat.position.clone();
      lookTarget.y += 1;
      camera.lookAt(lookTarget);
    }
    return;
  }

  const target = cameraTargets[mode];
  if (target) {
    camera.position.lerp(target.pos, dt * 2);
    camera.lookAt(target.lookAt);
  }
}

// ── Theme switching ──
function applyTheme(themeName) {
  const t = themes[themeName];
  if (!t) return;
  state.theme = themeName;

  scene.background = new THREE.Color(t.bg);
  scene.fog = new THREE.FogExp2(t.fog, t.fogDensity);
  ambientLight.color.set(t.ambient);
  ambientLight.intensity = t.ambientIntensity;
  dirLight.color.set(t.dirColor);
  dirLight.intensity = t.dirIntensity;
  renderer.toneMappingExposure = t.exposure;
  ground.material.color.set(t.groundColor);
}

applyTheme('night');

// ── Orbit angle (for overview / iso) ──
let orbitAngle = 0;

// ── FPS HUD ──
const fpsHud = document.getElementById('fps-hud');

function updateFPS(dt) {
  state.frameCount++;
  state.fpsTime += dt;
  if (state.fpsTime >= 0.5) {
    const fps = Math.round(state.frameCount / state.fpsTime);
    fpsHud.textContent = `FPS: ${fps} | Cats: ${state.cats.length} | Particles: ${state.forgeParticles.length}`;
    state.frameCount = 0;
    state.fpsTime = 0;
  }
}

// ── UI Bindings ──
document.getElementById('btn-spawn-cat').addEventListener('click', () => {
  spawnCat();
});

document.getElementById('btn-forge-strike').addEventListener('click', () => {
  forgeStrike();
});

document.getElementById('toggle-spin').addEventListener('click', (e) => {
  state.paused = !state.paused;
  e.target.textContent = state.paused ? '▶ Play' : '⏸ Pause';
  e.target.classList.toggle('active', state.paused);
});

// Camera buttons
const camButtons = ['cam-overview', 'cam-iso', 'cam-street', 'cam-follow-cat'];
camButtons.forEach((id) => {
  document.getElementById(id).addEventListener('click', () => {
    state.cameraMode = id.replace('cam-', '');
    camButtons.forEach((bid) => {
      document.getElementById(bid).classList.toggle('active', bid === id);
    });
  });
});

// Theme buttons
const themeButtons = ['mode-night', 'mode-gold', 'mode-day'];
themeButtons.forEach((id) => {
  document.getElementById(id).addEventListener('click', () => {
    applyTheme(id.replace('mode-', ''));
    themeButtons.forEach((bid) => {
      document.getElementById(bid).classList.toggle('active', bid === id);
    });
  });
});

// ── Resize ──
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ── Animation Loop ──
function animate() {
  requestAnimationFrame(animate);

  const dt = Math.min(state.clock.getDelta(), 0.05);
  const time = state.clock.getElapsedTime();

  updateFPS(dt);

  if (!state.paused) {
    // Orbit camera for overview/iso modes
    if (state.cameraMode === 'overview' || state.cameraMode === 'iso') {
      orbitAngle += dt * 0.15;
      const r = state.cameraMode === 'overview' ? 50 : 60;
      const h = state.cameraMode === 'overview' ? 35 : 50;
      cameraTargets[state.cameraMode].pos.set(
        Math.cos(orbitAngle) * r,
        h,
        Math.sin(orbitAngle) * r,
      );
    }

    updateCamera(dt);

    // Update cats
    state.cats.forEach((cat) => updateCat(cat, dt));

    // Update forge particles
    updateForgeParticles(dt);

    // Update forge embers
    updateForgeEmbers(time);
  }

  renderer.render(scene, camera);
}

animate();


