import * as THREE from 'three';

// ---------------------------------------------------------------------------
// Palette for coat colour variety -- each new cat cycles through
// ---------------------------------------------------------------------------
const CAT_PALETTE = [
  '#f0a050', // classic orange tabby
  '#e8e8e0', // cream white
  '#3a3a4a', // charcoal
  '#f08030', // ginger
  '#d0d0d0', // silver
  '#c07040', // chestnut
  '#f5c060', // golden
  '#808090', // blue-grey
];
let _paletteIndex = 0;

function nextCatColor() {
  const hex = CAT_PALETTE[_paletteIndex % CAT_PALETTE.length];
  _paletteIndex++;
  return new THREE.Color(hex);
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function mat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({
    color,
    metalness: opts.metalness ?? 0.1,
    roughness: opts.roughness ?? 0.6,
    ...opts,
  });
}

function sphere(radius, wSeg, hSeg) {
  return new THREE.SphereGeometry(radius, wSeg, hSeg);
}

// ---------------------------------------------------------------------------
// createMoruCat
// ---------------------------------------------------------------------------
export function createMoruCat(options = {}) {
  const cat = new THREE.Group();
  cat.name = 'MoruCat';

  const bodyColor = options.color
    ? new THREE.Color(options.color)
    : nextCatColor();

  // ---- 1. Rounded Torso ----
  const torsoGeo = sphere(1.0, 16, 12);
  const torsoMat = mat(bodyColor);
  const torso = new THREE.Mesh(torsoGeo, torsoMat);
  torso.name = 'torso';
  torso.scale.set(1.0, 1.0, 1.3);
  torso.position.set(0, 0.9, 0);
  torso.castShadow = true;
  torso.receiveShadow = true;
  cat.add(torso);

  // ---- 2. Belly Patch ----
  const bellyGeo = sphere(0.6, 14, 10);
  const bellyMat = mat('#fff5e0');
  const belly = new THREE.Mesh(bellyGeo, bellyMat);
  belly.name = 'belly';
  belly.scale.set(0.85, 0.75, 0.7);
  belly.position.set(0, 0.6, 0.45);
  belly.castShadow = false;
  cat.add(belly);

  // ---- 3. Chibi Head ----
  const headGeo = sphere(0.8, 16, 12);
  const headMat = mat(bodyColor);
  const head = new THREE.Mesh(headGeo, headMat);
  head.name = 'head';
  head.position.set(0, 1.85, 0.35);
  head.castShadow = true;
  cat.add(head);

  // ---- 4. Left Puffy Cheek ----
  const cheekGeo = sphere(0.22, 10, 8);
  const cheekMat = mat('#ffc0a0');
  const leftCheek = new THREE.Mesh(cheekGeo, cheekMat);
  leftCheek.name = 'leftCheek';
  leftCheek.position.set(-0.48, 1.68, 0.72);
  leftCheek.scale.set(1.0, 0.8, 0.7);
  cat.add(leftCheek);

  // ---- 5. Right Puffy Cheek ----
  const rightCheek = new THREE.Mesh(cheekGeo, cheekMat.clone());
  rightCheek.name = 'rightCheek';
  rightCheek.position.set(0.48, 1.68, 0.72);
  rightCheek.scale.set(1.0, 0.8, 0.7);
  cat.add(rightCheek);

  // ---- 6. Left Ear (outer cone + inner pink cone) ----
