    cat.scale.setScalar(s);
  }

  return cat;
}

// ---------------------------------------------------------------------------
// Animation constants
// ---------------------------------------------------------------------------
const LEG_SWING_AMP = 0.4;       // radians
const TAIL_WAG_AMP = 0.35;       // radians per segment
const TAIL_WAG_SPEED = 5.0;      // frequency multiplier
const HEAD_BOB_AMP = 0.04;       // units
const HEAD_BOB_SPEED = 6.0;
const BELL_SWING_AMP = 0.12;     // radians
const BELL_SWING_SPEED = 4.5;
const HOP_HEIGHT = 1.2;          // max Y displacement during hop
const HOP_DURATION = 0.6;        // seconds per hop
const STATE_CHANGE_MIN = 2.0;    // min seconds before state change
const STATE_CHANGE_MAX = 6.0;    // max seconds before state change
const TURN_SMOOTHNESS = 3.0;     // lerp factor per second
const IDLE_PURR_AMP = 0.02;      // slight body pulse when idle

// ---------------------------------------------------------------------------
// updateMoruCats
// ---------------------------------------------------------------------------
export function updateMoruCats(cats, dt, elapsed) {
  // Clamp dt to avoid physics explosions on tab-refocus
  const cdt = Math.min(dt, 0.1);

  for (let i = 0; i < cats.length; i++) {
    const cat = cats[i];
    const ud = cat.userData;
    if (!ud || !ud.isMoruCat) continue;

    // ----------------------------------------------------------------
    // State timer -- transition between trot / hop / idle
    // ----------------------------------------------------------------
    ud.stateTimer -= cdt;
    if (ud.stateTimer <= 0) {
      const roll = Math.random();
      if (ud.state === 'trot') {
        if (roll < 0.25) {
          ud.state = 'hop';
          ud.hopPhase = 0;
          ud.stateTimer = HOP_DURATION;
        } else if (roll < 0.4) {
          ud.state = 'idle';
          ud.idleTimer = 0;
          ud.stateTimer = STATE_CHANGE_MIN + Math.random() * (STATE_CHANGE_MAX - STATE_CHANGE_MIN);
        } else {
          // stay trotting, maybe change direction
          ud.stateTimer = STATE_CHANGE_MIN + Math.random() * STATE_CHANGE_MAX;
          pickNewDirection(ud);
        }
      } else if (ud.state === 'hop') {
        // Return from hop
        ud.state = 'trot';
        ud.hopHeight = 0;
        cat.position.y = 0; // reset Y
        ud.stateTimer = STATE_CHANGE_MIN + Math.random() * STATE_CHANGE_MAX;
      } else if (ud.state === 'idle') {
        ud.state = 'trot';
        ud.stateTimer = STATE_CHANGE_MIN + Math.random() * STATE_CHANGE_MAX;
        pickNewDirection(ud);
      }
    }

    // ----------------------------------------------------------------
    // Boundary check -- turn toward center if too far
    // ----------------------------------------------------------------
    const distFromOrigin = Math.sqrt(
      cat.position.x * cat.position.x + cat.position.z * cat.position.z
    );
    if (distFromOrigin > ud.boundaryRadius) {
      // Point back toward center
      const toCenter = new THREE.Vector3(-cat.position.x, 0, -cat.position.z).normalize();
      ud.direction.lerp(toCenter, 0.1);
      ud.direction.y = 0;
      ud.direction.normalize();
    } else if (distFromOrigin > ud.boundaryRadius * 0.85) {
      // Gentle nudge toward center when getting close to boundary
      const toCenter = new THREE.Vector3(-cat.position.x, 0, -cat.position.z).normalize();
      ud.direction.lerp(toCenter, 0.02);
      ud.direction.y = 0;
      ud.direction.normalize();
    }

    // ----------------------------------------------------------------
    // Movement
    // ----------------------------------------------------------------
    if (ud.state === 'trot' || ud.state === 'hop') {
      const moveSpeed = ud.state === 'hop' ? ud.speed * 1.3 : ud.speed;
      cat.position.x += ud.direction.x * moveSpeed * cdt;
      cat.position.z += ud.direction.z * moveSpeed * cdt;

      // Advance walk phase
      ud.walkPhase += moveSpeed * cdt * 4.0;
    }

    // ----------------------------------------------------------------
    // Face direction of movement (smooth)
    // ----------------------------------------------------------------
    if (ud.state !== 'idle') {
      const targetAngle = Math.atan2(ud.direction.x, ud.direction.z);
      let currentAngle = cat.rotation.y;

      // Shortest-path angle lerp
      let angleDiff = targetAngle - currentAngle;
      while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
      while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

      cat.rotation.y += angleDiff * Math.min(1.0, TURN_SMOOTHNESS * cdt);
    }

    // ----------------------------------------------------------------
    // Hop -- parabolic arc
    // ----------------------------------------------------------------
    if (ud.state === 'hop') {
      ud.hopPhase += cdt / HOP_DURATION;
      if (ud.hopPhase > 1.0) ud.hopPhase = 1.0;

      // Parabolic: h = 4 * H * t * (1 - t)
      const t = ud.hopPhase;
      ud.hopHeight = 4.0 * HOP_HEIGHT * t * (1.0 - t);
      cat.position.y = ud.hopHeight;
    } else {
      // Ensure Y stays grounded outside of hop
      cat.position.y = THREE.MathUtils.lerp(cat.position.y, 0, cdt * 8.0);
    }

    // ----------------------------------------------------------------
    // Leg swing (diagonal gait)
    // ----------------------------------------------------------------
    if (ud.legs && ud.legs.length === 4) {
      const phase = ud.walkPhase;
      const amp = ud.state === 'idle' ? LEG_SWING_AMP * 0.05 : LEG_SWING_AMP;

      // Front-left & back-right swing together
      const swingA = Math.sin(phase) * amp;
      // Front-right & back-left swing opposite
      const swingB = Math.sin(phase + Math.PI) * amp;

      ud.legs[0].rotation.x = swingA;  // front-left
      ud.legs[1].rotation.x = swingB;  // front-right
      ud.legs[2].rotation.x = swingB;  // back-left
      ud.legs[3].rotation.x = swingA;  // back-right
    }

    // ----------------------------------------------------------------
    // Tail wag (chained segments with increasing delay)
    // ----------------------------------------------------------------
    if (ud.tailSegments && ud.tailSegments.length >= 3) {
      for (let s = 0; s < ud.tailSegments.length; s++) {
        const seg = ud.tailSegments[s];
        const delayOffset = s * 0.6; // increasing phase delay
        const wagAmp = TAIL_WAG_AMP * (1.0 + s * 0.25); // tip wags more

        // X-axis wag (side to side relative to tail's local space)
        seg.rotation.x = Math.sin(elapsed * TAIL_WAG_SPEED + delayOffset) * wagAmp;

        // Slight Y wag for more organic feel
        seg.rotation.y = Math.cos(elapsed * TAIL_WAG_SPEED * 0.7 + delayOffset) * wagAmp * 0.3;

        // Upward tilt when idle (happy curl)
        if (ud.state === 'idle') {
          seg.rotation.x += 0.15 * (s + 1);
        }
      }
    }

    // ----------------------------------------------------------------
    // Head bob
    // ----------------------------------------------------------------
    if (ud.head) {
      if (ud.state === 'trot' || ud.state === 'hop') {
        const bob = Math.sin(ud.walkPhase * HEAD_BOB_SPEED * 0.5) * HEAD_BOB_AMP;
        ud.head.position.y = ud.headBaseY + bob;
      } else if (ud.state === 'idle') {
        // Slow, gentle breathing bob when idle
        const idleBob = Math.sin(elapsed * 1.5) * HEAD_BOB_AMP * 0.5;
        ud.head.position.y = ud.headBaseY + idleBob;
      }
    }

    // ----------------------------------------------------------------
    // Bell swing (pendulum)
    // ----------------------------------------------------------------
    if (ud.bell) {
      const bellSwing = Math.sin(elapsed * BELL_SWING_SPEED + i * 0.5) * BELL_SWING_AMP;
      ud.bell.rotation.z = bellSwing;

      // Subtle Y bounce matching walk
      if (ud.state === 'trot') {
        const bellBounce = Math.abs(Math.sin(ud.walkPhase * 2.0)) * 0.03;
        ud.bell.position.y = ud.bellBaseY - bellBounce;
      }
    }

    // ----------------------------------------------------------------
    // Idle: subtle body pulse (purring)
    // ----------------------------------------------------------------
    if (ud.state === 'idle') {
      ud.idleTimer += cdt;
      const purr = 1.0 + Math.sin(ud.idleTimer * 8.0) * IDLE_PURR_AMP;
      cat.scale.setScalar(purr * (cat.userData._baseScale || 1.0));
    } else {
      // Cache the base scale for idle use
      if (!cat.userData._baseScale) {
        cat.userData._baseScale = cat.scale.x;
      }
    }

    // ----------------------------------------------------------------
    // Ear twitch (occasional)
    // ----------------------------------------------------------------
    if (ud.leftEar && ud.rightEar) {
      const twitchCycle = Math.sin(elapsed * 0.8 + i * 2.0);
      if (twitchCycle > 0.92) {
        // Quick twitch
        const twitchAmt = (twitchCycle - 0.92) * 12.5; // 0..1
        ud.leftEar.rotation.z = 0.25 + twitchAmt * 0.3;
        ud.rightEar.rotation.z = -0.25;
      } else if (twitchCycle < -0.92) {
        ud.rightEar.rotation.z = -0.25 - (Math.abs(twitchCycle) - 0.92) * 12.5 * 0.3;
        ud.leftEar.rotation.z = 0.25;
      } else {
        ud.leftEar.rotation.z = 0.25;
        ud.rightEar.rotation.z = -0.25;
      }
    }
  }
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------
function pickNewDirection(ud) {
  const angle = Math.random() * Math.PI * 2;
  const newDir = new THREE.Vector3(Math.sin(angle), 0, Math.cos(angle));

  // Blend toward the new direction rather than snapping
  ud.direction.lerp(newDir, 0.5);
  ud.direction.y = 0;
  ud.direction.normalize();
}


