const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0x1a1a3e, 60, 280);
scene.background = new THREE.Color(0x1a1a3e);

// ─── Camera ───
const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.5, 500);
camera.position.set(42, 30, 46);
camera.lookAt(0, 3.5, 0);

// ─── Controls ───
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableRotate = true;
controls.enableZoom = true;
controls.enablePan = true;
controls.autoRotate = true;
controls.autoRotateSpeed = 2.2;
controls.target.set(0, 3.5, 0);
controls.minDistance = 5;
controls.maxDistance = 200;
controls.maxPolarAngle = Math.PI * 0.48;
controls.update();

// ─── Lights ───
const ambientLight = new THREE.AmbientLight(0x3344aa, 1.2);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0x5566bb, 0.8);
dirLight.position.set(30, 50, 20);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
dirLight.shadow.camera.left = -80;
dirLight.shadow.camera.right = 80;
dirLight.shadow.camera.top = 80;
dirLight.shadow.camera.bottom = -80;
dirLight.shadow.camera.near = 1;
dirLight.shadow.camera.far = 150;
scene.add(dirLight);

const hemiLight = new THREE.HemisphereLight(0x3355bb, 0x151530, 0.7);
scene.add(hemiLight);

const forgePointLight = new THREE.PointLight(0xff6600, 4.0, 50, 1.5);
forgePointLight.position.set(0, 6, 0);
scene.add(forgePointLight);

const forgePointLight2 = new THREE.PointLight(0xff4400, 2.5, 30, 2);
forgePointLight2.position.set(2, 3, 0);
scene.add(forgePointLight2);

// ─── Post-Processing ───
const composer = new EffectComposer(renderer);
const renderPass = new RenderPass(scene, camera);
composer.addPass(renderPass);

const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  0.65,
  0.4,
  0.3
);
composer.addPass(bloomPass);

const outputPass = new OutputPass();
composer.addPass(outputPass);

// ─── Build World ───
const cityData = createCity(scene);
state.buildingCount = cityData.buildingCount;
state.treeCount = cityData.treeCount;
state.lampCount = cityData.lampCount;

const forge = createForge(scene);

const cats = [];
const catColors = ['#f0a050', '#e8e8e0', '#3a3a4a', '#f08030', '#d0d0d0', '#c07040', '#f5c060', '#808090'];
function spawnCat() {
  const angle = Math.random() * Math.PI * 2;
  const radius = 8 + Math.random() * 20;
  const pos = new THREE.Vector3(Math.cos(angle) * radius, 0, Math.sin(angle) * radius);
  const colorIndex = state.catCount % catColors.length;
  const cat = createMoruCat({ color: catColors[colorIndex], position: pos });
  scene.add(cat);
  cats.push(cat);
  state.catCount++;
}
for (let i = 0; i < 6; i++) spawnCat();

// ─── Count Triangles ───
function countTriangles() {
  let total = 0;
  scene.traverse((obj) => {
    if (obj.isMesh && obj.geometry) {
      const geo = obj.geometry;
      if (geo.index) {
        total += geo.index.count / 3;
      } else if (geo.attributes.position) {
        total += geo.attributes.position.count / 3;
      }
    }
  });
  return Math.floor(total);
}
state.triangleCount = countTriangles();

// ─── Apply Theme ───
function applyTheme(themeName) {
  const t = themes[themeName];
  if (!t) return;

  // Dispose old fog if it exists
  if (scene.fog) {
    state.disposedCount++;
  }

  scene.fog = new THREE.Fog(t.fogColor.clone(), t.fogNear, t.fogFar);
  scene.background = t.bgColor.clone();

  ambientLight.color.set(t.ambientColor);
  ambientLight.intensity = t.ambientIntensity;

  dirLight.color.set(t.dirColor);
  dirLight.intensity = t.dirIntensity;

  hemiLight.color.set(t.hemiSky);
  hemiLight.groundColor.set(t.hemiGround);
  hemiLight.intensity = t.hemiIntensity;

  bloomPass.strength = t.bloomStrength;
  bloomPass.radius = t.bloomRadius;
  bloomPass.threshold = t.bloomThreshold;

  renderer.toneMappingExposure = t.exposure;

  state.theme = themeName;

  const url = new URL(window.location);
  url.searchParams.set('theme', themeName);
  window.history.replaceState({}, '', url);
}

// ─── Camera Transitions ───
let cameraLerpTarget = null;
let cameraLerpPos = null;
let cameraLerpProgress = 1;

function setCameraPreset(mode) {
  state.cameraMode = mode;
  if (mode === 'follow') {
    controls.autoRotate = false;
    return;
  }
  const preset = cameraPresets[mode];
  if (!preset) return;
  cameraLerpPos = preset.pos.clone();
  cameraLerpTarget = preset.target.clone();
  cameraLerpProgress = 0;
  controls.autoRotate = true;
  controls.autoRotateSpeed = 2.2;
}

function updateCameraTransition(dt) {
  if (cameraLerpProgress < 1) {
    cameraLerpProgress = Math.min(1, cameraLerpProgress + dt * 2.0);
    const t = cameraLerpProgress * cameraLerpProgress * (3 - 2 * cameraLerpProgress); // smoothstep
    camera.position.lerp(cameraLerpPos, t);
    controls.target.lerp(cameraLerpTarget, t);
  }

  if (state.cameraMode === 'follow' && cats.length > 0) {
    const targetCat = cats[0];
    const catPos = targetCat.position;
    const followOffset = new THREE.Vector3(
      catPos.x - Math.sin(targetCat.rotation.y) * 12,
      catPos.y + 8,
      catPos.z - Math.cos(targetCat.rotation.y) * 12
    );
    camera.position.lerp(followOffset, dt * 3);
    controls.target.lerp(new THREE.Vector3(catPos.x, catPos.y + 1.5, catPos.z), dt * 3);
  }
}

// ─── HUD ───
const hudEl = document.getElementById('fps-hud');
let fpsAccum = 0;
let fpsFrames = 0;
let lastFpsUpdate = 0;

function updateHUD(timestamp) {
  fpsFrames++;
  fpsAccum += timestamp - lastFpsUpdate;
  if (fpsAccum >= 500) {
    state.fps = Math.round((fpsFrames / fpsAccum) * 1000);
    fpsFrames = 0;
    fpsAccum = 0;
    hudEl.innerHTML =
      `FPS: <b>${state.fps}</b><br>` +
      `Cats: <b>${state.catCount}</b><br>` +
      `Buildings: <b>${state.buildingCount}</b> | Lamps: <b>${state.lampCount}</b><br>` +
      `Tris: <b>${(state.triangleCount / 1000).toFixed(1)}k</b><br>` +
      `Frame: <b>${state.frameCount}</b>`;
  }
  lastFpsUpdate = timestamp;
}

