});

document.getElementById('btn-forge-strike').addEventListener('click', () => {
  forge.strikeForge();
  state.forgeStrikes++;
  cats.forEach(cat => {
    cat.userData.state = 'hop';
    cat.userData.hopPhase = 0;
    cat.userData.stateTimer = 0.6;
  });
});

document.getElementById('toggle-spin').addEventListener('click', () => {
  state.spinning = !state.spinning;
  const btn = document.getElementById('toggle-spin');
  btn.textContent = state.spinning ? 'Freeze' : 'Resume';
  btn.classList.toggle('active', !state.spinning);
});

// ─── URL Theme ───
const urlParams = new URLSearchParams(window.location.search);
const urlTheme = urlParams.get('theme');
if (urlTheme && themes[urlTheme]) {
  applyTheme(urlTheme);
  updateModeButtons(urlTheme);
}

// ─── Resize ───
window.addEventListener('resize', () => {
  const w = window.innerWidth;
  const h = window.innerHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  composer.setSize(w, h);
  bloomPass.resolution.set(w, h);
});

// ─── Expose Globals ───
window.__app = { scene, camera, renderer, composer, state };

// ─── Render Loop ───
const clock = new THREE.Clock();
let lastTimestamp = 0;

function animate(timestamp) {
  requestAnimationFrame(animate);

  if (!state.spinning) return;

  const dt = Math.min(clock.getDelta(), 0.05);
  const elapsed = clock.getElapsedTime();

  state.frameCount++;

  controls.update();

  updateCameraTransition(dt);
  updateForge(forge, dt, elapsed);
  updateMoruCats(cats, dt, elapsed);

  forgePointLight.intensity = 2.5 + Math.sin(elapsed * 3) * 0.5;
  forgePointLight2.intensity = 1.5 + Math.sin(elapsed * 4 + 1) * 0.3;

  composer.render();

  updateHUD(timestamp || 0);
}

animate(0);


// ====== src/world/city.js (24160 bytes) ======
import * as THREE from 'three';
import { createWindowTexture, createRoadTexture } from './textures.js';

// ---------------------------------------------------------------------------
// Seeded pseudo-random number generator (mulberry32)
// ---------------------------------------------------------------------------
function createRNG(seed) {
  let s = seed | 0;
  return function () {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function randRange(rng, min, max) {
  return min + rng() * (max - min);
}

function randInt(rng, min, max) {
  return Math.floor(randRange(rng, min, max + 1));
}

function pickOne(rng, arr) {
  return arr[Math.floor(rng() * arr.length)];
}

function isInsidePlaza(x, z, radius) {
  return Math.sqrt(x * x + z * z) < radius;
}

// ---------------------------------------------------------------------------
// Neon color palette
// ---------------------------------------------------------------------------
const NEON_COLORS = [
  0xff00ff, // magenta
  0x00ffff, // cyan
  0xff3366, // hot pink
  0x66ff33, // lime
  0xffaa00, // orange
  0x3366ff, // blue
  0xff0066, // rose
  0x00ff99, // mint
  0xcc00ff, // purple
  0xffff00, // yellow
];

const WINDOW_COLOR_SCHEMES = [
  { base: 0x1a1a2e, glow: 0x00ffff },
  { base: 0x16213e, glow: 0xff00ff },
  { base: 0x0f3460, glow: 0xffaa00 },
  { base: 0x1a1a3e, glow: 0x66ff33 },
  { base: 0x201a2e, glow: 0xff3366 },
  { base: 0x0d1b2a, glow: 0x3366ff },
  { base: 0x1b1b2f, glow: 0x00ff99 },
  { base: 0x1e1e30, glow: 0xcc00ff },
];

// ---------------------------------------------------------------------------
// Building creation
// ---------------------------------------------------------------------------
function createBuilding(rng, x, z) {
  const group = new THREE.Group();
  group.position.set(x, 0, z);

  const scheme = pickOne(rng, WINDOW_COLOR_SCHEMES);

  // --- Base tier ---
  const baseW = randRange(rng, 6, 18);
  const baseH = randRange(rng, 15, 80);
  const baseD = randRange(rng, 6, 18);

  const baseGeo = new THREE.BoxGeometry(baseW, baseH, baseD);
  const windowTex = createWindowTexture(scheme.base, scheme.glow);
  const baseMat = new THREE.MeshStandardMaterial({
    map: windowTex,
    emissiveMap: windowTex,
    emissive: new THREE.Color(scheme.glow),
    emissiveIntensity: 0.55,
    roughness: 0.7,
    metalness: 0.3,
  });
  const baseMesh = new THREE.Mesh(baseGeo, baseMat);
  baseMesh.position.y = baseH / 2;
  baseMesh.castShadow = true;
  baseMesh.receiveShadow = true;
  group.add(baseMesh);

  let currentTopY = baseH;
  let currentW = baseW;
  let currentD = baseD;

  // --- Second tier (~40%) ---
  const hasTier2 = rng() < 0.4;
  if (hasTier2) {
    const t2W = currentW * randRange(rng, 0.5, 0.8);
    const t2H = randRange(rng, 8, 25);
    const t2D = currentD * randRange(rng, 0.5, 0.8);
    const scheme2 = pickOne(rng, WINDOW_COLOR_SCHEMES);
    const tex2 = createWindowTexture(scheme2.base, scheme2.glow);
    const t2Geo = new THREE.BoxGeometry(t2W, t2H, t2D);
    const t2Mat = new THREE.MeshStandardMaterial({
      map: tex2,
      emissiveMap: tex2,
      emissive: new THREE.Color(scheme2.glow),
      emissiveIntensity: 0.55,
      roughness: 0.7,
      metalness: 0.3,
    });
    const t2Mesh = new THREE.Mesh(t2Geo, t2Mat);
    t2Mesh.position.y = currentTopY + t2H / 2;
    t2Mesh.castShadow = true;
    t2Mesh.receiveShadow = true;
    group.add(t2Mesh);

    currentTopY += t2H;
    currentW = t2W;
    currentD = t2D;

    // --- Third tier (~20%) ---
    const hasTier3 = rng() < 0.5; // 50% of tier-2 buildings = ~20% overall
    if (hasTier3) {
      const t3W = currentW * randRange(rng, 0.4, 0.7);
      const t3H = randRange(rng, 5, 15);
      const t3D = currentD * randRange(rng, 0.4, 0.7);
      const scheme3 = pickOne(rng, WINDOW_COLOR_SCHEMES);
      const tex3 = createWindowTexture(scheme3.base, scheme3.glow);
      const t3Geo = new THREE.BoxGeometry(t3W, t3H, t3D);
      const t3Mat = new THREE.MeshStandardMaterial({
        map: tex3,
        emissiveMap: tex3,
        emissive: new THREE.Color(scheme3.glow),
        emissiveIntensity: 0.55,
        roughness: 0.7,
        metalness: 0.3,
      });
      const t3Mesh = new THREE.Mesh(t3Geo, t3Mat);
      t3Mesh.position.y = currentTopY + t3H / 2;
      t3Mesh.castShadow = true;
      t3Mesh.receiveShadow = true;
      group.add(t3Mesh);

      currentTopY += t3H;
      currentW = t3W;
      currentD = t3D;
    }
  }

  // --- Rooftop decorations ---
  addRooftopDecorations(rng, group, currentTopY, currentW, currentD);

  return group;
}

// ---------------------------------------------------------------------------
// Rooftop decorations
// ---------------------------------------------------------------------------
function addRooftopDecorations(rng, group, topY, w, d) {
  const neonColor = pickOne(rng, NEON_COLORS);

  // Neon trim frame around rooftop perimeter
  const trimThickness = 0.12;
  const trimHeight = 0.3;
  const trimMat = new THREE.MeshBasicMaterial({
    color: neonColor,
    transparent: true,
    opacity: 0.9,
  });

  // Front edge
  const frontTrim = new THREE.Mesh(
    new THREE.BoxGeometry(w, trimHeight, trimThickness),
    trimMat
  );
  frontTrim.position.set(0, topY + trimHeight / 2, d / 2);
  group.add(frontTrim);

  // Back edge
  const backTrim = new THREE.Mesh(
    new THREE.BoxGeometry(w, trimHeight, trimThickness),
    trimMat
  );
  backTrim.position.set(0, topY + trimHeight / 2, -d / 2);
  group.add(backTrim);

  // Left edge
  const leftTrim = new THREE.Mesh(
    new THREE.BoxGeometry(trimThickness, trimHeight, d),
    trimMat
  );
  leftTrim.position.set(-w / 2, topY + trimHeight / 2, 0);
  group.add(leftTrim);

  // Right edge
  const rightTrim = new THREE.Mesh(
    new THREE.BoxGeometry(trimThickness, trimHeight, d),
    trimMat
  );
  rightTrim.position.set(w / 2, topY + trimHeight / 2, 0);
  group.add(rightTrim);

  // Helipad (~30%)
  if (rng() < 0.3) {
    addHelipad(group, topY, Math.min(w, d));
  }

  // Antenna / spire (~25%)
  if (rng() < 0.25) {
    addAntenna(rng, group, topY);
  }
}

function addHelipad(group, topY, size) {
  const padRadius = size * 0.35;
  const padGeo = new THREE.CylinderGeometry(padRadius, padRadius, 0.08, 24);
  const padMat = new THREE.MeshStandardMaterial({
    color: 0x222222,
    roughness: 0.9,
    metalness: 0.1,
  });
  const pad = new THREE.Mesh(padGeo, padMat);
  pad.position.y = topY + 0.04;
  group.add(pad);

  // "H" marking via two vertical bars and a crossbar
  const markMat = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
  const barW = 0.15;
  const barH = padRadius * 0.7;

  // Left vertical bar
  const leftBar = new THREE.Mesh(
    new THREE.BoxGeometry(barW, 0.05, barH),
    markMat
  );
  leftBar.position.set(-padRadius * 0.25, topY + 0.12, 0);
  group.add(leftBar);

  // Right vertical bar
  const rightBar = new THREE.Mesh(
    new THREE.BoxGeometry(barW, 0.05, barH),
    markMat
  );
  rightBar.position.set(padRadius * 0.25, topY + 0.12, 0);
  group.add(rightBar);

  // Crossbar
  const crossBar = new THREE.Mesh(
    new THREE.BoxGeometry(padRadius * 0.5, 0.05, barW),
    markMat
  );
  crossBar.position.set(0, topY + 0.12, 0);
  group.add(crossBar);

  // Circle outline via ring geometry
  const ringGeo = new THREE.RingGeometry(
    padRadius * 0.85,
    padRadius * 0.92,
    32
  );
  const ringMat = new THREE.MeshBasicMaterial({
    color: 0xffaa00,
    side: THREE.DoubleSide,
  });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.rotation.x = -Math.PI / 2;
  ring.position.y = topY + 0.1;
  group.add(ring);
}

function addAntenna(rng, group, topY) {
  const antennaHeight = randRange(rng, 3, 8);
  const neonColor = pickOne(rng, NEON_COLORS);

  // Pole
  const poleGeo = new THREE.CylinderGeometry(0.08, 0.08, antennaHeight, 6);
  const poleMat = new THREE.MeshStandardMaterial({
    color: 0x444444,
    metalness: 0.8,
    roughness: 0.3,
  });
  const pole = new THREE.Mesh(poleGeo, poleMat);
  pole.position.y = topY + antennaHeight / 2;
  group.add(pole);

  // Tip sphere
  const tipGeo = new THREE.SphereGeometry(0.25, 12, 12);
  const tipMat = new THREE.MeshBasicMaterial({ color: neonColor });
  const tip = new THREE.Mesh(tipGeo, tipMat);
  tip.position.y = topY + antennaHeight + 0.25;
  group.add(tip);

  // Blinking light halfway up the antenna
  const blinkGeo = new THREE.SphereGeometry(0.12, 8, 8);
  const blinkMat = new THREE.MeshBasicMaterial({ color: 0xff0000 });
  const blink = new THREE.Mesh(blinkGeo, blinkMat);
  blink.position.y = topY + antennaHeight * 0.5;
  group.add(blink);
}

// ---------------------------------------------------------------------------
// Road creation
// ---------------------------------------------------------------------------
function createRoads(rng) {
  const roadsGroup = new THREE.Group();
  const roadWidth = 6;
  const cityExtent = 130;

  const roadTex = createRoadTexture();

  // Main X-axis road through the center
  const mainXGeo = new THREE.PlaneGeometry(cityExtent * 2, roadWidth);
  const mainXMat = new THREE.MeshStandardMaterial({
    map: roadTex.clone(),
    roughness: 0.85,
    metalness: 0.05,
  });
  const mainXRoad = new THREE.Mesh(mainXGeo, mainXMat);
  mainXRoad.rotation.x = -Math.PI / 2;
  mainXRoad.position.y = 0.02;
  mainXRoad.receiveShadow = true;
  roadsGroup.add(mainXRoad);

  // Main Z-axis road through the center
  const mainZGeo = new THREE.PlaneGeometry(roadWidth, cityExtent * 2);
  const mainZMat = new THREE.MeshStandardMaterial({
    map: roadTex.clone(),
    roughness: 0.85,
    metalness: 0.05,
  });
  const mainZRoad = new THREE.Mesh(mainZGeo, mainZMat);
  mainZRoad.rotation.x = -Math.PI / 2;
  mainZRoad.position.y = 0.02;
  mainZRoad.receiveShadow = true;
  roadsGroup.add(mainZRoad);

  // Secondary grid roads — X-parallel (running along X axis)
  const gridSpacing = 28;
  for (
    let z = -cityExtent + gridSpacing;
    z < cityExtent;
    z += gridSpacing
  ) {
    if (Math.abs(z) < 3) continue; // skip overlap with main road
    const geo = new THREE.PlaneGeometry(cityExtent * 2, roadWidth * 0.7);
    const mat = new THREE.MeshStandardMaterial({
      map: roadTex.clone(),
      roughness: 0.85,
      metalness: 0.05,
    });
    const road = new THREE.Mesh(geo, mat);
    road.rotation.x = -Math.PI / 2;
    road.position.set(0, 0.02, z);
    road.receiveShadow = true;
    roadsGroup.add(road);
  }

  // Secondary grid roads — Z-parallel (running along Z axis)
  for (
    let x = -cityExtent + gridSpacing;
    x < cityExtent;
    x += gridSpacing
  ) {
    if (Math.abs(x) < 3) continue;
    const geo = new THREE.PlaneGeometry(roadWidth * 0.7, cityExtent * 2);
    const mat = new THREE.MeshStandardMaterial({
      map: roadTex.clone(),
      roughness: 0.85,
      metalness: 0.05,
    });
    const road = new THREE.Mesh(geo, mat);
    road.rotation.x = -Math.PI / 2;
    road.position.set(x, 0.02, 0);
    road.receiveShadow = true;
    roadsGroup.add(road);
  }

  return roadsGroup;
}

// ---------------------------------------------------------------------------
// Tree creation
// ---------------------------------------------------------------------------
function createTree(rng, x, z) {
  const group = new THREE.Group();
  group.position.set(x, 0, z);

  // Trunk
  const trunkH = randRange(rng, 1.5, 3.0);
  const trunkR = randRange(rng, 0.15, 0.3);
  const trunkGeo = new THREE.CylinderGeometry(
    trunkR * 0.7,
    trunkR,
    trunkH,
    8
  );
  const trunkMat = new THREE.MeshStandardMaterial({
    color: pickOne(rng, [0x5c3a1e, 0x6b4226, 0x4a2f17]),
    roughness: 0.9,
  });
  const trunk = new THREE.Mesh(trunkGeo, trunkMat);
  trunk.position.y = trunkH / 2;
  trunk.castShadow = true;
  group.add(trunk);

  // Foliage layers (2-3 spheres)
  const greenShades = [0x1b5e20, 0x2e7d32, 0x388e3c, 0x43a047, 0x66bb6a];
  const layerCount = randInt(rng, 2, 3);
  let foliageY = trunkH;

  for (let i = 0; i < layerCount; i++) {
    const radius = randRange(rng, 0.8, 1.8) * (1 - i * 0.2);
    const foliageGeo = new THREE.SphereGeometry(radius, 10, 8);
    const foliageMat = new THREE.MeshStandardMaterial({
      color: pickOne(rng, greenShades),
      roughness: 0.8,
    });
    const foliage = new THREE.Mesh(foliageGeo, foliageMat);
    foliage.position.y = foliageY + radius * 0.6;
    foliage.castShadow = true;
    group.add(foliage);
    foliageY += radius * 0.9;
  }

  // Slight random scale for variety
  const s = randRange(rng, 0.7, 1.3);
  group.scale.set(s, s, s);

  return group;
}

// ---------------------------------------------------------------------------
// Streetlamp creation
// ---------------------------------------------------------------------------
function createStreetlamp(x, z, facingAngle) {
  const group = new THREE.Group();
  group.position.set(x, 0, z);

  // Pole
  const poleH = 5;
  const poleGeo = new THREE.CylinderGeometry(0.15, 0.15, poleH, 8);
  const poleMat = new THREE.MeshStandardMaterial({
    color: 0x444444,
    metalness: 0.7,
    roughness: 0.4,
  });
  const pole = new THREE.Mesh(poleGeo, poleMat);
  pole.position.y = poleH / 2;
  group.add(pole);

  // Curved arm (angled cylinder)
  const armLen = 1.5;
  const armGeo = new THREE.CylinderGeometry(0.06, 0.06, armLen, 6);
  const arm = new THREE.Mesh(armGeo, poleMat);
  arm.position.y = poleH - 0.2;
  arm.position.x = armLen * 0.4;
  arm.rotation.z = -Math.PI / 4;
  group.add(arm);

  // Bulb
  const bulbGeo = new THREE.SphereGeometry(0.25, 10, 10);
  const bulbMat = new THREE.MeshBasicMaterial({ color: 0xffcc44 });
  const bulb = new THREE.Mesh(bulbGeo, bulbMat);
  bulb.position.set(armLen * 0.75, poleH + 0.1, 0);
  group.add(bulb);

  // Lamp shade (small cone above bulb)
  const shadeGeo = new THREE.ConeGeometry(0.4, 0.25, 12);
  const shadeMat = new THREE.MeshStandardMaterial({
    color: 0x333333,
    metalness: 0.6,
    roughness: 0.5,
  });
  const shade = new THREE.Mesh(shadeGeo, shadeMat);
  shade.position.set(armLen * 0.75, poleH + 0.35, 0);
  group.add(shade);

  // Ground light pool
  const poolGeo = new THREE.CircleGeometry(2.5, 16);
  const poolMat = new THREE.MeshBasicMaterial({
    color: 0xffdd66,
    transparent: true,
    opacity: 0.3,
    side: THREE.DoubleSide,
  });
  const pool = new THREE.Mesh(poolGeo, poolMat);
  pool.rotation.x = -Math.PI / 2;
  pool.position.set(armLen * 0.4, 0.03, 0);
  group.add(pool);

  // Rotate the whole lamp to face the given angle
  group.rotation.y = facingAngle || 0;

  return group;
}

// ---------------------------------------------------------------------------
// Ground plane
// ---------------------------------------------------------------------------
function createGround() {
  const groundGeo = new THREE.PlaneGeometry(320, 320);
  const groundMat = new THREE.MeshStandardMaterial({
    color: 0x2a2a3a,
    roughness: 1.0,
    metalness: 0.0,
  });
  const ground = new THREE.Mesh(groundGeo, groundMat);
  ground.rotation.x = -Math.PI / 2;
  ground.position.y = 0;
  ground.receiveShadow = true;
  return ground;
}

// ---------------------------------------------------------------------------
// Main export: createCity
// ---------------------------------------------------------------------------
export function createCity(scene) {
  const rng = createRNG(42);
  const PLAZA_RADIUS = 35;
  const CITY_MIN = -120;
  const CITY_MAX = 120;

  // Groups
  const buildingsGroup = new THREE.Group();
  buildingsGroup.name = 'buildings';
  const treesGroup = new THREE.Group();
  treesGroup.name = 'trees';
  const lampsGroup = new THREE.Group();
  lampsGroup.name = 'lamps';

  // -----------------------------------------------------------------------
  // Ground
  // -----------------------------------------------------------------------
  const ground = createGround();
  scene.add(ground);

  // -----------------------------------------------------------------------
  // Roads
  // -----------------------------------------------------------------------
  const roadsGroup = createRoads(rng);
  roadsGroup.name = 'roads';
  scene.add(roadsGroup);

  // -----------------------------------------------------------------------
  // Buildings — grid placement with jitter
  // -----------------------------------------------------------------------
  const gridSpacing = 28; // matches road grid
  const buildingSlots = [];
  const occupiedCells = [];

  // Generate candidate positions on the grid blocks (between roads)
  for (let gx = CITY_MIN + 10; gx < CITY_MAX - 10; gx += gridSpacing) {
    for (let gz = CITY_MIN + 10; gz < CITY_MAX - 10; gz += gridSpacing) {
      // Place 2-3 buildings per grid cell with random offsets
      const countInCell = randInt(rng, 2, 3);
      for (let b = 0; b < countInCell; b++) {
        const bx = gx + randRange(rng, 3, gridSpacing - 6);
        const bz = gz + randRange(rng, 3, gridSpacing - 6);

        // Skip plaza
        if (isInsidePlaza(bx, bz, PLAZA_RADIUS)) continue;

        // Skip if too close to any road center line
        const nearMainRoadX = Math.abs(bz) < 5;
        const nearMainRoadZ = Math.abs(bx) < 5;
        const nearSecondaryX =
          Math.abs(((bz % gridSpacing) + gridSpacing) % gridSpacing) < 4 ||
          Math.abs(
            (((bz % gridSpacing) + gridSpacing) % gridSpacing) - gridSpacing
          ) < 4;
        const nearSecondaryZ =
          Math.abs(((bx % gridSpacing) + gridSpacing) % gridSpacing) < 4 ||
          Math.abs(
            (((bx % gridSpacing) + gridSpacing) % gridSpacing) - gridSpacing
          ) < 4;

        if (nearMainRoadX || nearMainRoadZ) continue;

        buildingSlots.push({ x: bx, z: bz });
      }
    }
  }

  // Ensure at least 60 buildings
  let buildingCount = 0;
  for (const slot of buildingSlots) {
    const building = createBuilding(rng, slot.x, slot.z);
    buildingsGroup.add(building);
    occupiedCells.push({ x: slot.x, z: slot.z, r: 8 });
    buildingCount++;
  }

  // If we somehow didn't reach 60, add more along the perimeter
  if (buildingCount < 60) {
    for (let extra = buildingCount; extra < 65; extra++) {
      const ex = randRange(rng, CITY_MIN + 15, CITY_MAX - 15);
      const ez = pickOne(rng, [
        randRange(rng, CITY_MIN + 5, CITY_MIN + 20),
        randRange(rng, CITY_MAX - 20, CITY_MAX - 5),
      ]);
      if (!isInsidePlaza(ex, ez, PLAZA_RADIUS)) {
        buildingsGroup.add(createBuilding(rng, ex, ez));
        occupiedCells.push({ x: ex, z: ez, r: 8 });
        buildingCount++;
      }
    }
  }

  scene.add(buildingsGroup);

  // -----------------------------------------------------------------------
  // Trees — along roads and gaps
  // -----------------------------------------------------------------------
  let treeCount = 0;

  // Trees along main X road
  for (let tx = CITY_MIN + 8; tx < CITY_MAX - 8; tx += randRange(rng, 4, 8)) {
    for (const zOff of [5, -5]) {
      const tz = zOff + randRange(rng, -0.5, 0.5);
      if (isInsidePlaza(tx, tz, PLAZA_RADIUS)) continue;
      if (isOccupied(tx, tz, occupiedCells, 3)) continue;
      treesGroup.add(createTree(rng, tx, tz));
      treeCount++;
    }
  }

  // Trees along main Z road
  for (let tz = CITY_MIN + 8; tz < CITY_MAX - 8; tz += randRange(rng, 4, 8)) {
    for (const xOff of [5, -5]) {
      const tx = xOff + randRange(rng, -0.5, 0.5);
      if (isInsidePlaza(tx, tz, PLAZA_RADIUS)) continue;
      if (isOccupied(tx, tz, occupiedCells, 3)) continue;
      treesGroup.add(createTree(rng, tx, tz));
      treeCount++;
    }
  }

  // Trees along secondary roads
  for (
    let gz = CITY_MIN + gridSpacing;
    gz < CITY_MAX;
    gz += gridSpacing
  ) {
    if (Math.abs(gz) < 3) continue;
    for (
      let tx = CITY_MIN + 10;
      tx < CITY_MAX - 10;
      tx += randRange(rng, 6, 14)
    ) {
      const zOff = pickOne(rng, [3.5, -3.5]);
      const treeX = tx + randRange(rng, -1, 1);
      const treeZ = gz + zOff;
      if (isInsidePlaza(treeX, treeZ, PLAZA_RADIUS)) continue;
      if (isOccupied(treeX, treeZ, occupiedCells, 3)) continue;
      treesGroup.add(createTree(rng, treeX, treeZ));
      treeCount++;
    }
  }

  // Fill up if below 70
  if (treeCount < 70) {
    for (let i = treeCount; i < 75; i++) {
      const tx = randRange(rng, CITY_MIN + 10, CITY_MAX - 10);
      const tz = randRange(rng, CITY_MIN + 10, CITY_MAX - 10);
      if (isInsidePlaza(tx, tz, PLAZA_RADIUS)) continue;
      if (isOccupied(tx, tz, occupiedCells, 2.5)) continue;
      treesGroup.add(createTree(rng, tx, tz));
      treeCount++;
    }
  }

  scene.add(treesGroup);

  // -----------------------------------------------------------------------
  // Streetlamps — along all roads
  // -----------------------------------------------------------------------
  let lampCount = 0;
  const lampSpacing = 10;

  // Lamps along main X road
  for (let lx = CITY_MIN + 5; lx < CITY_MAX - 5; lx += lampSpacing) {
    // Both sides
    lampsGroup.add(createStreetlamp(lx, 4.0, 0));
    lampCount++;
    lampsGroup.add(createStreetlamp(lx, -4.0, Math.PI));
    lampCount++;
  }

  // Lamps along main Z road
  for (let lz = CITY_MIN + 5; lz < CITY_MAX - 5; lz += lampSpacing) {
    if (Math.abs(lz) < 5) continue; // avoid overlap with X-road lamps
    lampsGroup.add(createStreetlamp(4.0, lz, Math.PI / 2));
    lampCount++;
    lampsGroup.add(createStreetlamp(-4.0, lz, -Math.PI / 2));
    lampCount++;
  }

  // Lamps along secondary X-parallel roads
  for (
    let gz = CITY_MIN + gridSpacing;
    gz < CITY_MAX;
    gz += gridSpacing
  ) {
    if (Math.abs(gz) < 3) continue;
    for (
      let lx = CITY_MIN + 12;
      lx < CITY_MAX - 12;
      lx += lampSpacing * 1.5
    ) {
      const side = rng() < 0.5 ? 3.0 : -3.0;
      lampsGroup.add(
        createStreetlamp(lx, gz + side, side > 0 ? 0 : Math.PI)
      );
      lampCount++;
    }
  }

  // Lamps along secondary Z-parallel roads
  for (
    let gx = CITY_MIN + gridSpacing;
    gx < CITY_MAX;
    gx += gridSpacing
  ) {
    if (Math.abs(gx) < 3) continue;
    for (
      let lz = CITY_MIN + 12;
      lz < CITY_MAX - 12;
      lz += lampSpacing * 1.5
    ) {
      const side = rng() < 0.5 ? 3.0 : -3.0;
      lampsGroup.add(
        createStreetlamp(gx + side, lz, side > 0 ? Math.PI / 2 : -Math.PI / 2)
      );
      lampCount++;
    }
  }

  // Guarantee 90+ by adding extras near intersections
  if (lampCount < 90) {
    for (
      let gz = CITY_MIN + gridSpacing;
      gz < CITY_MAX && lampCount < 95;
      gz += gridSpacing
    ) {
      for (
        let gx = CITY_MIN + gridSpacing;
        gx < CITY_MAX && lampCount < 95;
        gx += gridSpacing
      ) {
        // Corner lamps at intersections
        const offsets = [
          { dx: 3, dz: 3 },
          { dx: -3, dz: -3 },
        ];
        for (const off of offsets) {
          lampsGroup.add(
            createStreetlamp(gx + off.dx, gz + off.dz, rng() * Math.PI * 2)
          );
          lampCount++;
          if (lampCount >= 95) break;
        }
      }
    }
  }

  scene.add(lampsGroup);

  // -----------------------------------------------------------------------
  // Return summary
  // -----------------------------------------------------------------------
  return {
    buildings: buildingsGroup,
    trees: treesGroup,
    lamps: lampsGroup,
    roads: roadsGroup,
    buildingCount,
    treeCount,
    lampCount,
  };
}

// ---------------------------------------------------------------------------
// Utility: check if a position overlaps occupied cells
// ---------------------------------------------------------------------------
function isOccupied(x, z, cells, minDist) {
  for (const cell of cells) {
    const dx = x - cell.x;
    const dz = z - cell.z;
    if (Math.sqrt(dx * dx + dz * dz) < minDist + (cell.r || 0)) {
      return true;
    }
  }
  return false;
}


