// ---------------------------------------------------------------------------
// Helper — create a single stone tier
// ---------------------------------------------------------------------------
function _createTier(radius, height, color, yOffset) {
  const geo = new THREE.CylinderGeometry(radius, radius, height, 8);
  const mat = new THREE.MeshStandardMaterial({
    color,
    roughness: 0.85,
    metalness: 0.15,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.y = yOffset;
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

// ---------------------------------------------------------------------------
// Build the octagonal tiered stone dais
// ---------------------------------------------------------------------------
function _buildDais() {
  const dais = new THREE.Group();

  const bottom = _createTier(18, 1.2, 0x2a2a35, 0.6);
  const middle = _createTier(14, 1.0, 0x35354a, 1.2 + 0.5);
  const top = _createTier(10, 0.8, 0x40405a, 1.2 + 1.0 + 0.4);

  dais.add(bottom, middle, top);
  dais.userData.topY = 1.2 + 1.0 + 0.8; // combined height for placement
  return dais;
}

