  });
  const lava = new THREE.Mesh(lavaGeo, lavaMat);
  lava.rotation.x = -Math.PI / 2;
  lava.position.y = topY + 0.35;
  group.add(lava);

  // Magma bubbles
  const bubbles = [];
  for (let i = 0; i < MAGMA_BUBBLE_COUNT; i++) {
