// ---------------------------------------------------------------------------
// Ember / spark particle system
// ---------------------------------------------------------------------------
function _buildEmbers(originY) {
  const group = new THREE.Group();
  const emberTexture = createEmberTexture();

  // --- Rising embers (sprites) ---
  const embers = [];
  for (let i = 0; i < EMBER_COUNT; i++) {
    const spriteMat = new THREE.SpriteMaterial({
      map: emberTexture,
      color: new THREE.Color().setHSL(0.06 + Math.random() * 0.08, 1.0, 0.5 + Math.random() * 0.3),
      transparent: true,
      opacity: 0,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    const sprite = new THREE.Sprite(spriteMat);
    const size = 0.1 + Math.random() * 0.25;
    sprite.scale.set(size, size, size);

    // Initial state — dead, will be respawned
    sprite.userData.life = 0;
    sprite.userData.maxLife = 1.5 + Math.random() * 2.5;
    sprite.userData.vx = (Math.random() - 0.5) * 1.2;
    sprite.userData.vy = 1.5 + Math.random() * 3.0;
    sprite.userData.vz = (Math.random() - 0.5) * 1.2;
    sprite.userData.baseSize = size;
    sprite.userData.originY = originY;
    sprite.userData.active = false;
    sprite.userData.isEmber = true;

    _respawnEmber(sprite, originY);
    embers.push(sprite);
    group.add(sprite);
  }

  // --- Bouncing sparks ---
  const sparks = [];
  for (let i = 0; i < SPARK_COUNT; i++) {
    const sparkMat = new THREE.SpriteMaterial({
      map: emberTexture,
      color: 0xffffaa,
      transparent: true,
      opacity: 0,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    const spark = new THREE.Sprite(sparkMat);
    spark.scale.set(0.08, 0.08, 0.08);

    spark.userData.life = 0;
    spark.userData.maxLife = 0.8 + Math.random() * 0.6;
    spark.userData.vx = 0;
    spark.userData.vy = 0;
    spark.userData.vz = 0;
    spark.userData.active = false;
    spark.userData.isSpark = true;
    spark.userData.groundY = originY + 2.55; // anvil face level
    spark.visible = false;

    sparks.push(spark);
    group.add(spark);
  }

  return { group, embers, sparks };
}

// Respawn a single ember at the hearth / anvil area
function _respawnEmber(sprite, originY) {
  const angle = Math.random() * Math.PI * 2;
  const radius = Math.random() * 3.5;
  sprite.position.set(
    Math.cos(angle) * radius + (Math.random() - 0.5) * 2,
    originY + 0.5 + Math.random() * 0.5,
    Math.sin(angle) * radius + (Math.random() - 0.5) * 2
  );
  sprite.userData.vx = (Math.random() - 0.5) * 1.2;
  sprite.userData.vy = 1.5 + Math.random() * 3.0;
  sprite.userData.vz = (Math.random() - 0.5) * 1.2;
  sprite.userData.life = 0;
  sprite.userData.maxLife = 1.5 + Math.random() * 2.5;
  sprite.userData.active = true;
  sprite.material.opacity = 0.9;
}

// ---------------------------------------------------------------------------
// Strike — trigger burst of sparks and shockwave
// ---------------------------------------------------------------------------
function _triggerStrike(forge) {
  const { hammer, shockwaves, embers, sparks } = forge;

  // Start hammer swing
  hammer.userData.striking = true;
  hammer.userData.returning = false;
  hammer.userData.strikeTimer = 0;

  // Fire shockwaves
  for (const wave of shockwaves) {
    wave.userData.active = true;
    wave.userData.life = 0;
    wave.visible = true;
    wave.scale.set(0.01, 0.01, 0.01);
    wave.material.opacity = 0.9;
  }

  // Burst sparks
  const anvilX = forge.anvil.group.position.x;
  const anvilZ = forge.anvil.group.position.z;
  const anvilY = forge.anvil.group.position.y + 2.65;

  for (const spark of sparks) {
    spark.visible = true;
    spark.userData.active = true;
    spark.userData.life = 0;
    spark.userData.maxLife = 0.6 + Math.random() * 0.8;
    spark.position.set(
      anvilX + (Math.random() - 0.5) * 1.0,
      anvilY + 0.2,
      anvilZ + (Math.random() - 0.5) * 1.0
    );
    const speed = 4 + Math.random() * 6;
    const angle = Math.random() * Math.PI * 2;
    const upward = 3 + Math.random() * 5;
    spark.userData.vx = Math.cos(angle) * speed;
    spark.userData.vy = upward;
    spark.userData.vz = Math.sin(angle) * speed;
    spark.material.opacity = 1.0;
  }

  // Burst some extra embers from anvil
  let burst = 0;
  for (const ember of embers) {
    if (burst >= 30) break;
    if (ember.userData.life > ember.userData.maxLife * 0.7) {
      ember.position.set(
        anvilX + (Math.random() - 0.5) * 1.5,
        anvilY,
        anvilZ + (Math.random() - 0.5) * 1.5
      );
      ember.userData.vy = 3.0 + Math.random() * 4.0;
      ember.userData.vx = (Math.random() - 0.5) * 3.0;
      ember.userData.vz = (Math.random() - 0.5) * 3.0;
      ember.userData.life = 0;
      ember.userData.maxLife = 1.0 + Math.random() * 1.5;
      ember.material.opacity = 1.0;
      burst++;
    }
  }
}

// ===========================================================================
// PUBLIC: createForge
// ===========================================================================
export function createForge(scene) {
  const group = new THREE.Group();

  // --- Dais ---
  const dais = _buildDais();
  const topY = dais.userData.topY; // top surface height
  group.add(dais);

  // --- Rune circle ---
  const runeCircle = _buildRuneCircle(topY);
  group.add(runeCircle.group);

  // --- Hearth ---
  const hearth = _buildHearth(topY);
  group.add(hearth.group);

  // --- Anvil ---
  const anvil = _buildAnvil(topY);
  group.add(anvil.group);

  // Anvil world position for placing hammer and shockwaves
  const anvilWorldPos = new THREE.Vector3(
    anvil.group.position.x,
    0,
    anvil.group.position.z
  );

  // --- Hammer ---
  const hammer = _buildHammer(anvilWorldPos, topY);
  group.add(hammer);

  // --- Shockwaves ---
  const shockwaves = _buildShockwaves(anvilWorldPos, topY);
  for (const sw of shockwaves) {
    group.add(sw);
  }

  // --- Embers and sparks ---
  const emberData = _buildEmbers(topY);
  group.add(emberData.group);

  // --- Point light at the hearth for warm glow ---
  const hearthLight = new THREE.PointLight(0xff5500, 3.0, 25, 1.5);
  hearthLight.position.set(0, topY + 1.5, 0);
  group.add(hearthLight);

  // Secondary fill from anvil area
  const anvilLight = new THREE.PointLight(0xff7733, 1.5, 15, 2.0);
  anvilLight.position.set(anvilWorldPos.x, topY + 3.5, anvilWorldPos.z);
  group.add(anvilLight);

  // Add group to scene
  scene.add(group);

  // Build the public forge object
  const forge = {
    group,
    hammer,
    shockwaves,
    embers: emberData.embers,
    sparks: emberData.sparks,
    magmaBubbles: hearth.bubbles,
    runeRing: runeCircle.ring,
    anvil,
    hearthLight,
    anvilLight,
    _topY: topY,
    strikeForge: null, // assigned below
  };

  forge.strikeForge = () => _triggerStrike(forge);

  return forge;
}

// ===========================================================================
// PUBLIC: updateForge
// ===========================================================================
export function updateForge(forge, dt, elapsed) {
  _updateRuneRing(forge, dt, elapsed);
  _updateMagmaBubbles(forge, dt, elapsed);
  _updateEmbers(forge, dt);
  _updateSparks(forge, dt);
  _updateHammer(forge, dt, elapsed);
  _updateShockwaves(forge, dt);
  _updateLights(forge, dt, elapsed);
}

// ---------------------------------------------------------------------------
// Rune ring rotation
// ---------------------------------------------------------------------------
function _updateRuneRing(forge, _dt, elapsed) {
  if (forge.runeRing) {
    forge.runeRing.rotation.z = elapsed * RUNE_ROTATE_SPEED;
    // Subtle pulsing opacity
    forge.runeRing.material.opacity = 0.7 + Math.sin(elapsed * 2.0) * 0.15;
  }
}

// ---------------------------------------------------------------------------
// Magma bubble bob
// ---------------------------------------------------------------------------
function _updateMagmaBubbles(forge, _dt, elapsed) {
  for (const bubble of forge.magmaBubbles) {
    const ud = bubble.userData;
    bubble.position.y =
      ud.baseY + Math.sin(elapsed * ud.speed + ud.phase) * ud.amplitude;
    // Slight scale pulse
    const s = 1.0 + Math.sin(elapsed * ud.speed * 1.3 + ud.phase) * 0.15;
    bubble.scale.set(s, s, s);
    bubble.material.opacity = 0.6 + Math.sin(elapsed * ud.speed + ud.phase + 1.0) * 0.2;
  }
}

// ---------------------------------------------------------------------------
// Ember particles
// ---------------------------------------------------------------------------
function _updateEmbers(forge, dt) {
  for (const ember of forge.embers) {
    if (!ember.userData.active) {
      _respawnEmber(ember, forge._topY);
      continue;
    }

    const ud = ember.userData;
    ud.life += dt;

    if (ud.life >= ud.maxLife) {
      _respawnEmber(ember, forge._topY);
      continue;
    }

    // Physics
    ember.position.x += ud.vx * dt;
    ember.position.y += ud.vy * dt;
    ember.position.z += ud.vz * dt;

    // Slight drag
    ud.vx *= 0.995;
    ud.vz *= 0.995;
    ud.vy *= 0.998;

    // Wind drift
    ud.vx += (Math.random() - 0.5) * 0.3 * dt;
    ud.vz += (Math.random() - 0.5) * 0.3 * dt;

    // Fade based on life ratio
    const lifeRatio = ud.life / ud.maxLife;
    ember.material.opacity = Math.max(0, 1.0 - lifeRatio * lifeRatio);

    // Shrink as they age
    const scale = ud.baseSize * (1.0 - lifeRatio * 0.6);
    ember.scale.set(scale, scale, scale);
  }
}

// ---------------------------------------------------------------------------
// Bouncing sparks
// ---------------------------------------------------------------------------
function _updateSparks(forge, dt) {
  const gravity = -18.0;

  for (const spark of forge.sparks) {
    if (!spark.userData.active) continue;

    const ud = spark.userData;
    ud.life += dt;

    if (ud.life >= ud.maxLife) {
      ud.active = false;
      spark.visible = false;
      spark.material.opacity = 0;
      continue;
    }

    // Gravity
    ud.vy += gravity * dt;

    // Move
    spark.position.x += ud.vx * dt;
    spark.position.y += ud.vy * dt;
    spark.position.z += ud.vz * dt;

    // Bounce off ground (dais top)
    if (spark.position.y <= ud.groundY && ud.vy < 0) {
      ud.vy *= -0.4; // lose energy on bounce
      ud.vx *= 0.7;
      ud.vz *= 0.7;
      spark.position.y = ud.groundY;
    }

    // Drag
    ud.vx *= 0.99;
    ud.vz *= 0.99;

    // Fade
    const lifeRatio = ud.life / ud.maxLife;
    spark.material.opacity = Math.max(0, 1.0 - lifeRatio);
  }
}

// ---------------------------------------------------------------------------
// Hammer animation
// ---------------------------------------------------------------------------
function _updateHammer(forge, dt, elapsed) {
  const hm = forge.hammer;
  const ud = hm.userData;

  // Auto-strike timer
  ud.autoStrikeAccum += dt;
  if (ud.autoStrikeAccum >= ud.autoStrikeInterval && !ud.striking && !ud.returning) {
    ud.autoStrikeAccum = 0;
    forge.strikeForge();
  }

  if (ud.striking) {
    // Swing down rapidly
    ud.angle += HAMMER_STRIKE_SPEED * dt;
    if (ud.angle >= HAMMER_MAX_ANGLE) {
      ud.angle = HAMMER_MAX_ANGLE;
      ud.striking = false;
      ud.returning = true;

      // Impact flash — briefly boost ingot emissive
      if (forge.anvil.ingot) {
        forge.anvil.ingot.material.emissiveIntensity = 2.5;
      }
    }
  } else if (ud.returning) {
    // Slowly return up
    ud.angle -= HAMMER_RETURN_SPEED * dt;
    if (ud.angle <= 0) {
      ud.angle = 0;
      ud.returning = false;
    }
    // Decay ingot glow
    if (forge.anvil.ingot && forge.anvil.ingot.material.emissiveIntensity > 0.9) {
      forge.anvil.ingot.material.emissiveIntensity -= dt * 3.0;
    }
  } else {
    // Idle — gentle bob
    ud.idleTime += dt;
    ud.angle = Math.sin(ud.idleTime * HAMMER_IDLE_SPEED) * 0.06;

    // Restore ingot baseline
    if (forge.anvil.ingot) {
      forge.anvil.ingot.material.emissiveIntensity =
        0.9 + Math.sin(elapsed * 3.0) * 0.15;
    }
  }

  hm.rotation.z = ud.angle;
}

// ---------------------------------------------------------------------------
// Shockwave expansion
// ---------------------------------------------------------------------------
function _updateShockwaves(forge, dt) {
  for (const wave of forge.shockwaves) {
    if (!wave.userData.active) continue;

    wave.userData.life += dt;
    const t = wave.userData.life - wave.userData.delay;

    if (t < 0) continue; // still in delay

    const progress = t / wave.userData.maxLife;
    if (progress >= 1.0) {
      wave.userData.active = false;
      wave.visible = false;
      wave.material.opacity = 0;
      wave.scale.set(0.01, 0.01, 0.01);
      continue;
    }

    // Expand with easing
    const eased = 1.0 - Math.pow(1.0 - progress, 3);
    const s = 0.5 + eased * 8.0;
    wave.scale.set(s, s, s);

    // Fade out
    wave.material.opacity = 0.9 * (1.0 - progress);
    wave.visible = true;
  }
}

// ---------------------------------------------------------------------------
// Light flicker
// ---------------------------------------------------------------------------
function _updateLights(forge, _dt, elapsed) {
  // Hearth warm flicker
  const flicker = 0.85 + Math.sin(elapsed * 7.3) * 0.08 + Math.sin(elapsed * 13.1) * 0.07;
  forge.hearthLight.intensity = 3.0 * flicker;

  // Anvil light pulses with hammer strikes
  const anvilFlicker = 0.9 + Math.sin(elapsed * 5.0) * 0.1;
  forge.anvilLight.intensity = 1.5 * anvilFlicker;

  // Brief bright flash when hammer is at max strike angle
  if (forge.hammer.userData.striking) {
    forge.anvilLight.intensity = 4.0;
    forge.hearthLight.intensity = 5.0;
  }
}


