import * as THREE from 'three';

/**
 * Default neon color scheme used for lit windows throughout the city.
 */
const DEFAULT_COLOR_SCHEME = [
    '#ffd700', '#00e5ff', '#ff4081', '#76ff03',
    '#e040fb', '#ffab40', '#18ffff', '#ff6e40'
];

/**
 * Creates a procedural skyscraper window-facade texture.
 *
 * Generates a 256x512 canvas filled with a grid of small rectangles
 * simulating illuminated (and unlit) windows on a building face.
 *
 * @param {string[]} colorScheme - Array of hex color strings for lit windows.
 * @returns {THREE.CanvasTexture} The resulting repeatable window texture.
 */
export function createWindowTexture(colorScheme = DEFAULT_COLOR_SCHEME) {
    const width = 256;
    const height = 512;
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');

    // Dark building facade background
    ctx.fillStyle = '#0a0a12';
    ctx.fillRect(0, 0, width, height);

    const cols = 12;
    const rows = 24;
    const paddingX = 4;
    const paddingY = 4;
    const cellW = width / cols;
    const cellH = height / rows;
    const winW = cellW - paddingX * 2;
    const winH = cellH - paddingY * 2;

    for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
            const x = col * cellW + paddingX;
            const y = row * cellH + paddingY;

            const isLit = Math.random() < 0.65;

            if (!isLit) {
                // Unlit window — barely visible dark pane
                ctx.globalAlpha = 1.0;
                ctx.fillStyle = '#0d0d16';
                ctx.fillRect(x, y, winW, winH);
                continue;
            }

            const color = colorScheme[Math.floor(Math.random() * colorScheme.length)];
            const hasGlow = Math.random() < 0.10;

            // Optional outer glow (drawn first, behind the window)
            if (hasGlow) {
                ctx.globalAlpha = 0.15;
                ctx.fillStyle = color;
                const glowPad = 3;
                ctx.fillRect(
                    x - glowPad,
                    y - glowPad,
                    winW + glowPad * 2,
                    winH + glowPad * 2
                );
            }

            // Lit window with brightness variation
            ctx.globalAlpha = 0.5 + Math.random() * 0.5;
            ctx.fillStyle = color;
            ctx.fillRect(x, y, winW, winH);
        }
    }

    // Reset alpha
    ctx.globalAlpha = 1.0;

    const texture = new THREE.CanvasTexture(canvas);
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    return texture;
}

/**
 * Creates a procedural road-surface texture with lane markings, grain,
 * and a crosswalk at one edge.
 *
 * Generates a 512x512 canvas representing a section of road.
 *
 * @returns {THREE.CanvasTexture} The resulting repeatable road texture.
 */
export function createRoadTexture() {
    const size = 512;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');

    // Base asphalt fill
    ctx.fillStyle = '#1a1a22';
    ctx.fillRect(0, 0, size, size);

    // Subtle noise / grain across the surface
    for (let i = 0; i < 8000; i++) {
        const nx = Math.random() * size;
        const ny = Math.random() * size;
        const grey = Math.floor(20 + Math.random() * 25);
        ctx.fillStyle = `rgb(${grey},${grey},${grey})`;
        ctx.globalAlpha = 0.3 + Math.random() * 0.4;
        ctx.fillRect(nx, ny, 1, 1);
    }

    ctx.globalAlpha = 1.0;

    // Dashed center lane marking (yellow)
    const centerX = size / 2;
    const dashLength = 30;
    const gapLength = 20;
    const lineWidth = 3;

    ctx.strokeStyle = '#ffd700';
    ctx.lineWidth = lineWidth;
    ctx.setLineDash([dashLength, gapLength]);
    ctx.beginPath();
    ctx.moveTo(centerX, 0);
    ctx.lineTo(centerX, size);
    ctx.stroke();
    ctx.setLineDash([]);

    // White edge lane markings (left and right)
    const edgeOffset = 24;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.8;

    // Left edge
    ctx.beginPath();
    ctx.moveTo(edgeOffset, 0);
    ctx.lineTo(edgeOffset, size);
    ctx.stroke();

    // Right edge
    ctx.beginPath();
    ctx.moveTo(size - edgeOffset, 0);
    ctx.lineTo(size - edgeOffset, size);
    ctx.stroke();

    ctx.globalAlpha = 1.0;

    // Crosswalk stripes at the bottom edge
    const crosswalkY = size - 50;
    const stripeWidth = 30;
    const stripeHeight = 6;
    const stripeGap = 8;
    const crosswalkLeft = edgeOffset + 10;
    const crosswalkRight = size - edgeOffset - 10;
    const stripeCount = Math.floor(
        (crosswalkRight - crosswalkLeft) / (stripeWidth + stripeGap)
    );

    ctx.fillStyle = '#ffffff';
    ctx.globalAlpha = 0.9;

    for (let i = 0; i < stripeCount; i++) {
        const sx = crosswalkLeft + i * (stripeWidth + stripeGap);
        // Draw several bars to form the crosswalk block
        for (let row = 0; row < 4; row++) {
            ctx.fillRect(
                sx,
                crosswalkY + row * (stripeHeight + 3),
                stripeWidth,
                stripeHeight
            );
        }
    }

    ctx.globalAlpha = 1.0;

    const texture = new THREE.CanvasTexture(canvas);
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    return texture;
}

/**
 * Creates a procedural glowing rune-circle texture with concentric rings,
 * geometric rune symbols, connecting lines, and a bright center glow.
 *
 * Generates a 512x512 canvas.
 *
 * @returns {THREE.CanvasTexture} The resulting rune texture.
 */
export function createRuneTexture() {
    const size = 512;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');

    const cx = size / 2;
    const cy = size / 2;
    const outerRadius = 220;
    const innerRadius = 160;
    const runeRadius = 190; // where the rune symbols are placed

    // Very dark, mostly transparent background
    ctx.fillStyle = 'rgba(2, 2, 8, 0.85)';
    ctx.fillRect(0, 0, size, size);

    // --- Outer circle ring (cyan glow) ---
    ctx.strokeStyle = '#00ffcc';
    ctx.lineWidth = 3;
    ctx.shadowColor = '#00ffcc';
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.arc(cx, cy, outerRadius, 0, Math.PI * 2);
    ctx.stroke();

    // --- Inner circle ring (orange) ---
    ctx.strokeStyle = '#ff8800';
    ctx.lineWidth = 2;
    ctx.shadowColor = '#ff8800';
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.arc(cx, cy, innerRadius, 0, Math.PI * 2);
    ctx.stroke();

    ctx.shadowBlur = 0;

    // --- Rune symbols (8 evenly spaced) ---
    const runeCount = 8;
    const runePositions = [];

    for (let i = 0; i < runeCount; i++) {
        const angle = (Math.PI * 2 * i) / runeCount - Math.PI / 2;
        const rx = cx + Math.cos(angle) * runeRadius;
        const ry = cy + Math.sin(angle) * runeRadius;
        runePositions.push({ x: rx, y: ry, angle });
    }

    ctx.strokeStyle = '#00ffcc';
    ctx.lineWidth = 2;
    ctx.shadowColor = '#00ffcc';
    ctx.shadowBlur = 6;

    // Draw a different rune-like geometric shape at each position
    const runeSize = 14;

    runePositions.forEach((pos, idx) => {
        ctx.save();
        ctx.translate(pos.x, pos.y);
        ctx.rotate(pos.angle + Math.PI / 2);

        const s = runeSize;
        ctx.beginPath();

        switch (idx % 8) {
            case 0:
                // Vertical line with crossbar (cross)
                ctx.moveTo(0, -s);
                ctx.lineTo(0, s);
                ctx.moveTo(-s * 0.6, 0);
                ctx.lineTo(s * 0.6, 0);
                break;
            case 1:
                // Upward triangle
                ctx.moveTo(0, -s);
                ctx.lineTo(-s * 0.7, s * 0.6);
                ctx.lineTo(s * 0.7, s * 0.6);
                ctx.closePath();
                break;
            case 2:
                // Downward chevron
                ctx.moveTo(-s * 0.7, -s * 0.4);
                ctx.lineTo(0, s * 0.4);
                ctx.lineTo(s * 0.7, -s * 0.4);
                break;
            case 3:
                // Diamond
                ctx.moveTo(0, -s);
                ctx.lineTo(s * 0.6, 0);
                ctx.lineTo(0, s);
                ctx.lineTo(-s * 0.6, 0);
                ctx.closePath();
                break;
            case 4:
                // Double vertical with top bar (rune-like pillar)
                ctx.moveTo(-s * 0.3, -s);
                ctx.lineTo(-s * 0.3, s);
                ctx.moveTo(s * 0.3, -s);
                ctx.lineTo(s * 0.3, s);
                ctx.moveTo(-s * 0.5, -s);
                ctx.lineTo(s * 0.5, -s);
                break;
            case 5:
                // X mark
                ctx.moveTo(-s * 0.6, -s * 0.6);
                ctx.lineTo(s * 0.6, s * 0.6);
                ctx.moveTo(s * 0.6, -s * 0.6);
                ctx.lineTo(-s * 0.6, s * 0.6);
                break;
            case 6:
                // Upward chevron
                ctx.moveTo(-s * 0.7, s * 0.4);
                ctx.lineTo(0, -s * 0.4);
                ctx.lineTo(s * 0.7, s * 0.4);
                break;
            case 7:
                // Arrow pointing up
                ctx.moveTo(0, -s);
                ctx.lineTo(-s * 0.5, -s * 0.2);
                ctx.moveTo(0, -s);
                ctx.lineTo(s * 0.5, -s * 0.2);
                ctx.moveTo(0, -s);
                ctx.lineTo(0, s);
                break;
        }

        ctx.stroke();
        ctx.restore();
    });

    // --- Connecting lines between adjacent rune positions ---
    ctx.strokeStyle = '#00ffcc';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.35;
    ctx.shadowBlur = 0;

    for (let i = 0; i < runePositions.length; i++) {
        const a = runePositions[i];
        const b = runePositions[(i + 1) % runePositions.length];
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
        ctx.stroke();
    }

    // Also draw lines across every other position for a star pattern
    ctx.globalAlpha = 0.18;
    for (let i = 0; i < runePositions.length; i++) {
        const a = runePositions[i];
        const b = runePositions[(i + 3) % runePositions.length];
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
        ctx.stroke();
    }

    ctx.globalAlpha = 1.0;

    // --- Bright center glow (radial gradient) ---
    const glowRadius = 60;
    const gradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, glowRadius);
    gradient.addColorStop(0, 'rgba(255, 255, 255, 0.6)');
    gradient.addColorStop(0.25, 'rgba(0, 255, 204, 0.35)');
    gradient.addColorStop(0.6, 'rgba(0, 255, 204, 0.10)');
    gradient.addColorStop(1, 'rgba(0, 255, 204, 0)');

    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(cx, cy, glowRadius, 0, Math.PI * 2);
    ctx.fill();

    const texture = new THREE.CanvasTexture(canvas);
    return texture;
}

/**
 * Creates a small ember / spark particle texture with a radial gradient
 * from bright orange-yellow center to transparent edge.
 *
 * Generates a 32x32 canvas.
 *
 * @returns {THREE.CanvasTexture} The resulting ember particle texture.
 */
export function createEmberTexture() {
    const size = 32;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');

    const cx = size / 2;
    const cy = size / 2;
    const radius = size / 2;

    const gradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius);
    gradient.addColorStop(0, 'rgba(255, 240, 120, 1.0)');
    gradient.addColorStop(0.15, 'rgba(255, 200, 50, 0.9)');
    gradient.addColorStop(0.4, 'rgba(255, 140, 20, 0.5)');
    gradient.addColorStop(0.7, 'rgba(255, 80, 10, 0.15)');
    gradient.addColorStop(1, 'rgba(255, 60, 0, 0)');

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, size, size);

    const texture = new THREE.CanvasTexture(canvas);
    return texture;
}


