function buildCat(colorHex) {
  const group = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: colorHex, roughness: 0.8, metalness: 0.1 });
  const eyeMat = new THREE.MeshStandardMaterial({ color: 0x111111, emissive: 0x00ffaa, emissiveIntensity: 1.2 });

