  const tailGeo = new THREE.TubeGeometry(tailCurve, 8, 0.05, 6, false);
  const tail = new THREE.Mesh(tailGeo, mat);
  group.add(tail);

  // legs
  [[-0.2, -0.35, 0.15], [0.2, -0.35, 0.15], [-0.15, -0.35, -0.15], [0.15, -0.35, -0.15]].forEach(([lx, ly, lz]) => {
    const legGeo = new THREE.CylinderGeometry(0.055, 0.05, 0.35, 6);
    const leg = new THREE.Mesh(legGeo, mat);
    leg.position.set(lx, ly, lz);
    group.add(leg);
  });

  return group;
}

