  };
  scene.add(cat);
  state.cats.push(cat);
  if (state.cats.length === 1) state.followTarget = cat;
}

// spawn initial cats
for (let i = 0; i < 4; i++) spawnCat();

// ─── Forge Strike ─────────────────────────────────────────────────────────────
const forgeFlash = document.getElementById('forge-flash');

function forgeStrike() {
  emitSparks();
  forgePL.intensity = 8;
  forgeFlash.style.opacity = '1';
  state.forgeStriking = true;
  anvilBody.material.emissive = new THREE.Color(0xff8800);
  anvilBody.material.emissiveIntensity = 2;
  setTimeout(() => {
    forgePL.intensity = 2.0;
    forgeFlash.style.opacity = '0';
    state.forgeStriking = false;
    anvilBody.material.emissiveIntensity = 0;
  }, 200);
}

// ─── Camera helpers ───────────────────────────────────────────────────────────
function setCamMode(mode) {
  state.camMode = mode;
  document.querySelectorAll('#cam-overview,#cam-iso,#cam-street,#cam-follow-cat').forEach(b => b.classList.remove('active'));
  const idMap = { overview: 'cam-overview', iso: 'cam-iso', street: 'cam-street', followCat: 'cam-follow-cat' };
  document.getElementById(idMap[mode])?.classList.add('active');
}

// ─── Button wiring ────────────────────────────────────────────────────────────
document.getElementById('btn-spawn-cat').addEventListener('click', spawnCat);
document.getElementById('btn-forge-strike').addEventListener('click', forgeStrike);

document.getElementById('toggle-spin').addEventListener('click', () => {
  state.paused = !state.paused;
  document.getElementById('toggle-spin').textContent = state.paused ? '▶ Resume' : '⏸ Pause';
});

document.getElementById('cam-overview').addEventListener('click', () => setCamMode('overview'));
document.getElementById('cam-iso').addEventListener('click', () => setCamMode('iso'));
document.getElementById('cam-street').addEventListener('click', () => setCamMode('street'));
document.getElementById('cam-follow-cat').addEventListener('click', () => setCamMode('followCat'));

['night','gold','day'].forEach(m => {
  document.getElementById(`mode-${m}`).addEventListener('click', () => {
    applyTheme(m);
    document.querySelectorAll('#mode-night,#mode-gold,#mode-day').forEach(b => b.classList.remove('active'));
    document.getElementById(`mode-${m}`).classList.add('active');
  });
});

// ─── FPS HUD ─────────────────────────────────────────────────────────────────
const fpsHud = document.getElementById('fps-hud');
let fpsFrames = 0;
let fpsLast = performance.now();

function updateFps(now) {
  fpsFrames++;
  if (now - fpsLast >= 500) {
    state.fps = Math.round(fpsFrames * 1000 / (now - fpsLast));
    fpsFrames = 0;
    fpsLast = now;
    fpsHud.textContent = `FPS: ${state.fps} | Cats: ${state.cats.length} | Mode: ${state.mode}`;
  }
}

// ─── Resize ───────────────────────────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ─── Animation loop ───────────────────────────────────────────────────────────
const clock = new THREE.Clock();
let totalTime = 0;

function animate() {
  requestAnimationFrame(animate);
  const now = performance.now();
  updateFps(now);

  const delta = clock.getDelta();
  if (!state.paused) totalTime += delta;

  // forge fire flicker
  forgePL.intensity = 2.0 + Math.sin(totalTime * 8) * 0.4 + Math.sin(totalTime * 13) * 0.2;

  // spark update
  const sp = sparkGeo.attributes.position.array;
  for (let i = 0; i < SPARK_COUNT; i++) {
    const v = sparkVel[i];
    if (v.life > 0) {
      v.life -= delta / v.maxLife;
      if (v.life <= 0) {
        sp[i * 3 + 1] = -100;
      } else {
        sp[i * 3] += v.x * delta;
        sp[i * 3 + 1] += v.y * delta - 4 * delta;
        sp[i * 3 + 2] += v.z * delta;
        v.y -= 9.8 * delta;
      }
    }
  }
  sparkGeo.attributes.position.needsUpdate = true;
  sparkMat.opacity = 0.85;

  // neon pulse on ring
  ring.material.emissiveIntensity = 1.2 + Math.sin(totalTime * 3) * 0.5;

  // cats movement
  state.cats.forEach((cat, idx) => {
    if (state.paused) return;
    const u = cat.userData;

    // wander
    u.wanderTimer += delta;
    if (u.wanderTimer > 2 + Math.random() * 2) {
      u.wanderAngle += (Math.random() - 0.5) * Math.PI * 0.8;
      u.wanderTimer = 0;
    }

    const dx = Math.cos(u.wanderAngle) * u.speed;
    const dz = Math.sin(u.wanderAngle) * u.speed;
    cat.position.x += dx;
    cat.position.z += dz;

    // boundary bounce
    const BOUND = 40;
    if (Math.abs(cat.position.x) > BOUND) { cat.position.x = Math.sign(cat.position.x) * BOUND; u.wanderAngle = Math.PI - u.wanderAngle; }
    if (Math.abs(cat.position.z) > BOUND) { cat.position.z = Math.sign(cat.position.z) * BOUND; u.wanderAngle = -u.wanderAngle; }

    // face direction
    cat.rotation.y = Math.atan2(dx, dz);

    // jump animation
    u.jumpT += delta * u.jumpSpeed;
    cat.position.y = 0.42 + Math.max(0, Math.sin(u.jumpT) * 0.8);

    // body bob
    cat.children[0].scale.y = 0.85 + Math.sin(u.jumpT * 2) * 0.07;
  });

  // camera lerp
  if (!state.paused) {
    let targetPos, targetLook;

    if (state.camMode === 'followCat' && state.followTarget) {
      const cat = state.followTarget;
      targetPos = new THREE.Vector3(
        cat.position.x - Math.sin(cat.rotation.y) * 6,
        cat.position.y + 3.5,
        cat.position.z - Math.cos(cat.rotation.y) * 6
      );
      targetLook = cat.position.clone().add(new THREE.Vector3(0, 1, 0));
    } else {
      const preset = camPresets[state.camMode];
      // overview: slowly orbit
      if (state.camMode === 'overview') {
        const orbitAngle = totalTime * 0.08;
        targetPos = new THREE.Vector3(
          Math.cos(orbitAngle) * 65,
          40,
          Math.sin(orbitAngle) * 65
        );
      } else {
        targetPos = preset.pos.clone();
      }
      targetLook = preset.target.clone();
    }

    camera.position.lerp(targetPos, 0.03);
    camLerp.target.lerp(targetLook, 0.05);
    camera.lookAt(camLerp.target);
  }

  renderer.render(scene, camera);
}

animate();

// ─── Window export ────────────────────────────────────────────────────────────
window.__app = { scene, camera, renderer, state };


