import * as THREE from 'three';

function stdMat(p) { return new THREE.MeshStandardMaterial(p); }
function phongMat(p) { return new THREE.MeshPhongMaterial(p); }
function boxGeo(w, h, d) { return new THREE.BoxGeometry(w, h, d); }
function sphGeo(r, ws=12, hs=8) { return new THREE.SphereGeometry(r, ws, hs); }
function cylGeo(rt, rb, h, s=8) { return new THREE.CylinderGeometry(rt, rb, h, s); }
function coneGeo(r, h, s=8) { return new THREE.ConeGeometry(r, h, s); }

/* ── Shared materials ──────────────────────────────────────────────── */
const matBodyOrange = phongMat({ color: 0xe86820, shininess: 40 });
const matBodyCream  = phongMat({ color: 0xfff0d8, shininess: 30 });
const matEyeWhite   = stdMat({ color: 0xffffff, roughness: 0.1 });
const matEyeBlue    = stdMat({ color: 0x0066ff, emissive: new THREE.Color(0x0044aa), emissiveIntensity: 0.6, roughness: 0.1 });
const matPupil      = stdMat({ color: 0x000000, roughness: 0.05, metalness: 0.3 });
const matCatchlight = stdMat({ color: 0xffffff, emissive: new THREE.Color(0xffffff), emissiveIntensity: 1.5 });
const matNose       = stdMat({ color: 0xff8888, roughness: 0.5 });
const matWhisker    = stdMat({ color: 0xffffff, roughness: 0.4 });
const matInnerEar   = phongMat({ color: 0xff9999, shininess: 20 });
const matCollar     = stdMat({ color: 0xff2244, roughness: 0.4, metalness: 0.1 });
const matBell       = stdMat({ color: 0xffcc00, emissive: new THREE.Color(0xffaa00), emissiveIntensity: 1.2, roughness: 0.1, metalness: 0.9 });
const matHelmet     = stdMat({ color: 0x445566, roughness: 0.3, metalness: 0.8 });
const matHelmetRim  = stdMat({ color: 0x888899, roughness: 0.2, metalness: 0.9 });
const matTail       = phongMat({ color: 0xe86820, shininess: 35 });
const matTailTip    = phongMat({ color: 0xfff0c8, shininess: 30 });
const matLeg        = phongMat({ color: 0xe86820, shininess: 35 });
const matPaw        = phongMat({ color: 0xfff0d8, shininess: 25 });

const CAT_COLORS = [
  { body: 0xe86820, belly: 0xfff0d8 },
  { body: 0x555577, belly: 0xccccdd },
  { body: 0xdd8822, belly: 0xffeedd },
  { body: 0x333344, belly: 0x888899 },
  { body: 0xcc4466, belly: 0xffddee },
  { body: 0x228844, belly: 0xaaffcc },
];

/* ── Build one cat (14+ meshes) ────────────────────────────────────── */
export function createMoruCat(colorIdx = 0) {
  const colors = CAT_COLORS[colorIdx % CAT_COLORS.length];
  const bodyMat = phongMat({ color: colors.body, shininess: 40 });
  const bellyMat = phongMat({ color: colors.belly, shininess: 30 });
  const legMat = phongMat({ color: colors.body, shininess: 35 });
  const tailMat = phongMat({ color: colors.body, shininess: 35 });
  const earMat = phongMat({ color: colors.body, shininess: 30 });

  const cat = new THREE.Group();
  cat.userData.isMoruCat = true;

  /* ── TORSO ───────────────────────────────────────────────────────── */
  const torso = new THREE.Mesh(sphGeo(0.52, 14, 10), bodyMat);
  torso.scale.set(1, 0.88, 0.9);
  torso.position.y = 0.52;
  torso.castShadow = true;
  cat.add(torso);  // mesh 1

  /* belly patch */
  const belly = new THREE.Mesh(sphGeo(0.34, 10, 8), bellyMat);
  belly.scale.set(0.85, 0.7, 0.5);
  belly.position.set(0, 0.46, 0.32);
  belly.castShadow = false;
  cat.add(belly);  // mesh 2

  /* ── HEAD ────────────────────────────────────────────────────────── */
  const head = new THREE.Mesh(sphGeo(0.42, 14, 10), bodyMat);
  head.scale.set(1, 0.95, 1);
  head.position.set(0, 1.22, 0.08);
  head.castShadow = true;
  cat.add(head);  // mesh 3
  cat.userData.head = head;

  /* puffy cheeks */
  [-0.3, 0.3].forEach((cx, i) => {
    const cheek = new THREE.Mesh(sphGeo(0.18, 8, 6), bellyMat);
    cheek.position.set(cx, 1.15, 0.3);
    cat.add(cheek);  // mesh 4, 5
  });

  /* ── EARS ────────────────────────────────────────────────────────── */
  [-0.28, 0.28].forEach((ex) => {
    const ear = new THREE.Mesh(coneGeo(0.15, 0.28, 4), earMat);
    ear.position.set(ex, 1.58, 0.0);
    ear.rotation.z = ex < 0 ? 0.18 : -0.18;
    ear.castShadow = true;
    cat.add(ear);  // mesh 6, 7

    /* inner ear detail */
    const innerEar = new THREE.Mesh(coneGeo(0.08, 0.18, 4), matInnerEar);
    innerEar.position.set(ex, 1.56, 0.04);
    innerEar.rotation.z = ex < 0 ? 0.18 : -0.18;
    cat.add(innerEar);  // mesh 8, 9
  });

  /* ── EYES ────────────────────────────────────────────────────────── */
  [-0.16, 0.16].forEach((ex) => {
    /* eye white */
    const eyeWhite = new THREE.Mesh(sphGeo(0.095, 10, 8), matEyeWhite);
    eyeWhite.position.set(ex, 1.28, 0.35);
    cat.add(eyeWhite);  // mesh 10, 11

    /* iris */
    const iris = new THREE.Mesh(sphGeo(0.072, 10, 8), matEyeBlue);
    iris.position.set(ex, 1.28, 0.38);
    cat.add(iris);

    /* pupil */
    const pupil = new THREE.Mesh(sphGeo(0.042, 8, 6), matPupil);
    pupil.position.set(ex, 1.28, 0.405);
    cat.add(pupil);

    /* catchlight */
    const catchlight = new THREE.Mesh(sphGeo(0.018, 6, 4), matCatchlight);
    catchlight.position.set(ex + 0.025, 1.295, 0.415);
    cat.add(catchlight);
  });

  /* ── NOSE & SNOUT ────────────────────────────────────────────────── */
  const snout = new THREE.Mesh(sphGeo(0.1, 8, 6), bellyMat);
  snout.scale.set(1.1, 0.7, 0.75);
  snout.position.set(0, 1.17, 0.38);
  cat.add(snout);  // mesh 12

  const nose = new THREE.Mesh(sphGeo(0.04, 6, 4), matNose);
  nose.position.set(0, 1.2, 0.435);
  cat.add(nose);  // mesh 13

  /* whiskers */
  [-1, 1].forEach(side => {
    [0, 1, 2].forEach(row => {
      const whisker = new THREE.Mesh(
        new THREE.CylinderGeometry(0.005, 0.005, 0.38, 4),
        matWhisker
      );
      whisker.rotation.z = Math.PI / 2;
      whisker.position.set(
        side * 0.22,
        1.175 + row * 0.025 - 0.025,
        0.38
      );
      whisker.rotation.x = (row - 1) * 0.12;
      cat.add(whisker);
    });
  });

  /* ── COLLAR & BELL ───────────────────────────────────────────────── */
  const collar = new THREE.Mesh(
    new THREE.TorusGeometry(0.33, 0.055, 6, 20),
    matCollar
  );
  collar.rotation.x = Math.PI / 2;
  collar.position.y = 0.88;
  cat.add(collar);  // mesh 14

  const bell = new THREE.Mesh(sphGeo(0.07, 8, 6), matBell);
  bell.position.set(0, 0.82, 0.33);
  cat.add(bell);

  /* ── BLACKSMITH HELMET ───────────────────────────────────────────── */
  const helmet = new THREE.Mesh(sphGeo(0.32, 12, 8), matHelmet);
  helmet.scale.set(1.05, 0.75, 1.05);
  helmet.position.set(0, 1.55, 0.04);
  cat.add(helmet);

  /* helmet brim */
  const brim = new THREE.Mesh(
    new THREE.TorusGeometry(0.34, 0.06, 5, 20),
    matHelmetRim
  );
  brim.position.set(0, 1.45, 0.04);
  brim.rotation.x = 0.3;
  cat.add(brim);

  /* ── LEGS ────────────────────────────────────────────────────────── */
  const legDefs = [
    { x: -0.28, z:  0.18, name: 'legFL' },
    { x:  0.28, z:  0.18, name: 'legFR' },
    { x: -0.28, z: -0.2,  name: 'legBL' },
    { x:  0.28, z: -0.2,  name: 'legBR' },
  ];

  const legs = [];
  legDefs.forEach(({ x, z, name }) => {
    const legPivot = new THREE.Group();
    legPivot.position.set(x, 0.52, z);
    legPivot.name = name;

    /* upper leg */
    const upper = new THREE.Mesh(cylGeo(0.1, 0.1, 0.36, 6), legMat);
    upper.position.y = -0.18;
    upper.castShadow = true;
    legPivot.add(upper);

    /* lower leg */
    const lower = new THREE.Mesh(cylGeo(0.08, 0.09, 0.3, 6), legMat);
    lower.position.y = -0.48;
    lower.castShadow = true;
    legPivot.add(lower);

    /* paw */
    const paw = new THREE.Mesh(sphGeo(0.1, 8, 6), matPaw);
    paw.scale.set(1.0, 0.65, 1.2);
    paw.position.y = -0.66;
    legPivot.add(paw);

    cat.add(legPivot);
    legs.push(legPivot);
  });
  cat.userData.legs = legs;

  /* ── TAIL ────────────────────────────────────────────────────────── */
  const tailPivot = new THREE.Group();
  tailPivot.position.set(0, 0.6, -0.44);
  tailPivot.name = 'tailPivot';

  /* tail segments */
  const tailSegs = [];
  [
    { r: 0.09, h: 0.28, y: -0.14 },
    { r: 0.08, h: 0.25, y: -0.39 },
    { r: 0.065, h: 0.22, y: -0.6 },
  ].forEach(({ r, h, y }, i) => {
    const seg = new THREE.Mesh(cylGeo(r * 0.85, r, h, 6), tailMat);
    seg.position.y = y;
    tailPivot.add(seg);
    tailSegs.push(seg);
  });

  /* tail tip */
  const tailTip = new THREE.Mesh(sphGeo(0.12, 8, 6), matTailTip);
  tailTip.position.y = -0.76;
  tailPivot.add(tailTip);

  cat.add(tailPivot);
  cat.userData.tailPivot = tailPivot;

  /* locomotion state */
  cat.userData.phase = Math.random() * Math.PI * 2;
  cat.userData.hopPhase = Math.random() * Math.PI * 2;
  cat.userData.walkDir = new THREE.Vector3(
    Math.random() - 0.5,
    0,
    Math.random() - 0.5
  ).normalize();
  cat.userData.turnTimer = Math.random() * 3 + 1;
  cat.userData.speed = Math.random() * 0.14 + 0.12;
  cat.userData.backflipTimer = 0;
  cat.userData.backflipping = false;

  return cat;
}

/* ── Animate all cats ─────────────────────────────────────────────── */
const WALK_BOUNDS = 28;

export function animateCats(cats, dt, state, forgePos) {
  if (!state.spinning) return;

  const t = Date.now() * 0.001;

  cats.forEach((cat, ci) => {
    const ud = cat.userData;
    ud.phase += dt * 6.5;
    ud.hopPhase += dt * 3.2;

    /* turn timer */
    ud.turnTimer -= dt;
    if (ud.turnTimer <= 0) {
      ud.turnTimer = Math.random() * 3 + 1.5;
      const ang = (Math.random() - 0.5) * Math.PI;
      const cos = Math.cos(ang);
      const sin = Math.sin(ang);
      const nx = ud.walkDir.x * cos - ud.walkDir.z * sin;
      const nz = ud.walkDir.x * sin + ud.walkDir.z * cos;
      ud.walkDir.set(nx, 0, nz).normalize();
    }

    /* backflip on forge strike */
    if (ud.backflipping) {
      ud.backflipTimer += dt;
      const bt = ud.backflipTimer / 0.6;
      cat.rotation.z = Math.sin(bt * Math.PI) * Math.PI * 0.4;
      if (ud.backflipTimer > 0.6) {
        ud.backflipping = false;
        ud.backflipTimer = 0;
        cat.rotation.z = 0;
      }
    }

    /* movement */
    const moveX = ud.walkDir.x * ud.speed;
    const moveZ = ud.walkDir.z * ud.speed;

    const nx = cat.position.x + moveX;
    const nz = cat.position.z + moveZ;

    if (Math.hypot(nx, nz) > WALK_BOUNDS) {
      ud.walkDir.negate();
      ud.turnTimer = Math.random() * 2 + 1;
    } else {
      cat.position.x = nx;
      cat.position.z = nz;
    }

    /* face direction */
    if (ud.walkDir.length() > 0.01) {
      const targetAngle = Math.atan2(ud.walkDir.x, ud.walkDir.z);
      const diff = targetAngle - cat.rotation.y;
      const wrapped = ((diff + Math.PI) % (Math.PI * 2)) - Math.PI;
      cat.rotation.y += wrapped * 0.12;
    }

    /* hop */
    const hopY = Math.max(0, Math.sin(ud.hopPhase) * 0.12);
    cat.position.y = hopY;

    /* leg swing */
    if (ud.legs) {
      ud.legs.forEach((leg, li) => {
        const offset = (li % 2 === 0) ? 0 : Math.PI;
        const frontBack = li < 2 ? 0 : Math.PI;
        leg.rotation.x = Math.sin(ud.phase + offset + frontBack) * 0.55;
      });
    }

    /* tail wag */
    if (ud.tailPivot) {
      ud.tailPivot.rotation.y = Math.sin(ud.phase * 0.8) * 0.6;
      ud.tailPivot.rotation.z = Math.sin(ud.phase * 0.4) * 0.25;
    }

    /* head bob */
    if (ud.head) {
      ud.head.rotation.x = Math.sin(ud.phase * 0.5) * 0.07;
    }
  });
}

/* ── Trigger backflip for all cats ─────────────────────────────────── */
export function exciteCats(cats) {
  cats.forEach(cat => {
    cat.userData.backflipping = true;
    cat.userData.backflipTimer = 0;
  });
}


