const urlTheme = new URL(window.location.href).searchParams.get('theme');
if (urlTheme && THEMES[urlTheme]) {
  applyTheme(urlTheme);
} else {
  applyTheme('night');
}

/* ── Expose to window ──────────────────────────────────────────────── */
window.__app = { scene, camera, renderer, composer, state };

/* ── Render loop ───────────────────────────────────────────────────── */
let prevTime = performance.now();
let fpsFrames = 0;
let fpsTime = 0;

function animate() {
  requestAnimationFrame(animate);
  if (!state.spinning) return;

  const now = performance.now();
  const dt = Math.min((now - prevTime) / 1000, 0.05);
  prevTime = now;

  fpsFrames++;
  fpsTime += dt;
  if (fpsTime >= 0.5) {
    lastFps = fpsFrames / fpsTime;
    fpsFrames = 0;
    fpsTime = 0;
  }

  if (state.spinning) {
    state.frame++;

    /* animate forge */
    forgeApi.animateForge(dt, state);

    /* animate cats */
    animateCats(cats, dt, state, new THREE.Vector3(0, 0, 0));

    /* follow cam */
    if (state.cameraMode === 'follow' && cats.length > 0) {
      const target = cats[0];
      const desiredPos = target.position.clone().add(
        followCamOffset.clone().applyEuler(new THREE.Euler(0, target.rotation.y, 0))
      );
      camera.position.lerp(desiredPos, 0.06);
      followTarget.copy(target.position).y += 1.5;
      camera.lookAt(followTarget);
      controls.target.lerp(followTarget, 0.06);
    }

    controls.update();

    /* update HUD */
    updateHud(now);
  }

  composer.render();
}

