import * as THREE from 'three';
import { getTexturePool } from './textures.js';

/* ── deterministic PRNG ───────────────────────────────────────────────── */
function rng(seed) {
  let s = (seed | 0) >>> 0;
  return () => { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; return s / 0xffffffff; };
}

/* ── Geometry helpers ────────────────────────────────────────────────── */
function boxGeo(w, h, d, sw = 1, sh = 1, sd = 1) {
  return new THREE.BoxGeometry(w, h, d, sw, sh, sd);
}
function cylGeo(rt, rb, h, segs = 8, caps = true) {
  return new THREE.CylinderGeometry(rt, rb, h, segs, 1, !caps);
}
function sphGeo(r, ws = 14, hs = 10) {
  return new THREE.SphereGeometry(r, ws, hs);
}
function circGeo(r, segs = 16) {
  return new THREE.CircleGeometry(r, segs);
}

/* ── Material helpers ────────────────────────────────────────────────── */
function stdMat(params) { return new THREE.MeshStandardMaterial(params); }
function phongMat(params) { return new THREE.MeshPhongMaterial(params); }

/* ── Shared materials ─────────────────────────────────────────────────── */
const matGround = stdMat({ color: 0x151520, roughness: 0.95, metalness: 0.05 });
const matRoad   = stdMat({ color: 0x1a1a28, roughness: 0.9 });
const matCurbW  = stdMat({ color: 0x888899, roughness: 0.7 });
const matCurbY  = stdMat({ color: 0x998800, roughness: 0.7 });
const matNeonR  = stdMat({ color: 0xff2244, emissive: new THREE.Color(0xff0022), emissiveIntensity: 3.0, roughness: 0.3 });
const matNeonC  = stdMat({ color: 0x00ffff, emissive: new THREE.Color(0x00ccff), emissiveIntensity: 3.0, roughness: 0.3 });
const matNeonY  = stdMat({ color: 0xffff00, emissive: new THREE.Color(0xffdd00), emissiveIntensity: 3.0, roughness: 0.3 });
const matNeonP  = stdMat({ color: 0xff00ff, emissive: new THREE.Color(0xee00ff), emissiveIntensity: 3.0, roughness: 0.3 });
const matNeonG  = stdMat({ color: 0x00ff66, emissive: new THREE.Color(0x00ee44), emissiveIntensity: 3.0, roughness: 0.3 });
const NEON_MATS = [matNeonR, matNeonC, matNeonY, matNeonP, matNeonG];
const matMetal  = stdMat({ color: 0x445566, roughness: 0.4, metalness: 0.7 });
const matConcrete = stdMat({ color: 0x333344, roughness: 0.85 });
const matTreeTrunk = stdMat({ color: 0x4d2e0e, roughness: 0.9 });
const matTreeFoliage = phongMat({ color: 0x1a6e2e, shininess: 15 });
const matTreeFoliageDark = phongMat({ color: 0x0d4e1c, shininess: 10 });
const matLampPole = stdMat({ color: 0x2a2a44, roughness: 0.6, metalness: 0.5 });
const matBulb = stdMat({
  color: 0xffffaa,
  emissive: new THREE.Color(0xffffaa),
  emissiveIntensity: 6.0,
  roughness: 0.1,
  metalness: 0.0,
});
const matGroundDisc = stdMat({
  color: 0xffffcc,
  emissive: new THREE.Color(0xffff88),
  emissiveIntensity: 0.6,
