});

/* ── City grid constants ─────────────────────────────────────────────── */
const CITY_HALF = 130;          // city extends ±130 in X/Z
const BLOCK_STEP = 38;          // block pitch (road centre to road centre)
const ROAD_W = 6;               // road half-width
const PLAZA_RADIUS = 38;        // central forge plaza clearance

/* ── Building factory ────────────────────────────────────────────────── */
function createBuilding(x, z, width, depth, height, winTex, neonMat, rand) {
  const group = new THREE.Group();
  group.name = 'building';

  /* main body */
  const bodyGeo = boxGeo(width, height, depth);
  const bodyMat = stdMat({
    color: 0x0a0a1a,
    map: winTex,
    emissiveMap: winTex,
    emissive: new THREE.Color(0.12, 0.12, 0.18),
    roughness: 0.6,
    metalness: 0.2,
  });
  const body = new THREE.Mesh(bodyGeo, bodyMat);
  body.position.y = height * 0.5;
  body.castShadow = true;
  body.receiveShadow = true;
  group.add(body);

  /* base podium */
  const podiumH = Math.min(3, height * 0.08);
  const podium = new THREE.Mesh(
    boxGeo(width + 0.6, podiumH, depth + 0.6),
    matConcrete
  );
  podium.position.y = podiumH * 0.5;
  podium.castShadow = true;
  group.add(podium);

  /* rooftop neon trim (4 thin frame bars) */
  const trimH = 0.35;
  const trimD = 0.25;
  const ry = height + trimH * 0.5;
  const neonM = NEON_MATS[Math.floor(rand() * NEON_MATS.length)];
  [
    [0, ry, depth * 0.5, width, trimH, trimD],       // front
    [0, ry, -depth * 0.5, width, trimH, trimD],      // back
    [width * 0.5, ry, 0, trimD, trimH, depth],       // right
    [-width * 0.5, ry, 0, trimD, trimH, depth],      // left
  ].forEach(([px, py, pz, bw, bh, bd]) => {
    const bar = new THREE.Mesh(boxGeo(bw, bh, bd), neonM);
    bar.position.set(px, py, pz);
    group.add(bar);
  });

  /* rooftop slab */
  const roofSlab = new THREE.Mesh(
    boxGeo(width + 0.2, 0.4, depth + 0.2),
    matConcrete
  );
  roofSlab.position.y = height + 0.2;
  group.add(roofSlab);

  /* optional spire (taller buildings) */
  if (height > 22 && rand() > 0.35) {
    const spireH = rand() * 8 + 5;
    const spire = new THREE.Mesh(
      cylGeo(0.1, 0.35, spireH, 6),
      matMetal
    );
    spire.position.y = height + 0.4 + spireH * 0.5;
    group.add(spire);

    /* spire tip glow */
    const tipGlow = new THREE.Mesh(
      sphGeo(0.25, 8, 6),
      stdMat({ color: 0xff2244, emissive: new THREE.Color(0xff0022), emissiveIntensity: 5 })
    );
    tipGlow.position.y = height + 0.4 + spireH;
    group.add(tipGlow);
  }

  /* optional helipad (shorter-medium buildings) */
  if (height >= 8 && height <= 28 && rand() > 0.55) {
    const { helipad } = getTexturePool();
    const hpSize = Math.min(width, depth) * 0.7;
    const hp = new THREE.Mesh(
      circGeo(hpSize * 0.5, 24),
      stdMat({ map: helipad, roughness: 0.7 })
    );
    hp.rotation.x = -Math.PI * 0.5;
    hp.position.y = height + 0.45;
    group.add(hp);

    /* helipad ring light */
    const hpRing = new THREE.Mesh(
      new THREE.TorusGeometry(hpSize * 0.5, 0.12, 6, 32),
      stdMat({ color: 0xffdd00, emissive: new THREE.Color(0xffdd00), emissiveIntensity: 3 })
    );
    hpRing.rotation.x = Math.PI * 0.5;
    hpRing.position.y = height + 0.46;
    group.add(hpRing);
  }

  /* lower-floor lobby windows (glass panels) */
  if (height > 6) {
    const lobbyMat = stdMat({
      color: 0x223344,
      emissive: new THREE.Color(0.06, 0.12, 0.18),
      transparent: true,
      opacity: 0.8,
      roughness: 0.15,
      metalness: 0.6,
    });
    const lobby = new THREE.Mesh(boxGeo(width - 0.2, 2.0, depth - 0.2), lobbyMat);
    lobby.position.y = 1.0;
    group.add(lobby);
  }

  /* neon sign board (large buildings) */
  if (height > 18 && rand() > 0.4) {
    const sign = new THREE.Mesh(
      boxGeo(width * 0.55, 1.4, 0.25),
      neonM
    );
    sign.position.set(0, height * 0.65, depth * 0.5 + 0.15);
    group.add(sign);
  }

  group.position.set(x, 0, z);
  return group;
}

/* ── Tree factory ────────────────────────────────────────────────────── */
function createTree(x, z, rand) {
  const group = new THREE.Group();
  group.name = 'tree';

  const trunkH = rand() * 1.5 + 2.0;
  const trunkRb = rand() * 0.05 + 0.18;
  const trunkRt = trunkRb * 0.6;

  /* trunk */
  const trunk = new THREE.Mesh(cylGeo(trunkRt, trunkRb, trunkH, 8), matTreeTrunk);
  trunk.position.y = trunkH * 0.5;
  trunk.castShadow = true;
  group.add(trunk);

  /* 3 foliage spheres at increasing heights */
  const foliageData = [
    { r: rand() * 0.6 + 1.3, yo: trunkH + 0.5 },
    { r: rand() * 0.5 + 1.0, yo: trunkH + 1.4 },
    { r: rand() * 0.4 + 0.7, yo: trunkH + 2.2 },
  ];
  const foliageMat = rand() > 0.4 ? matTreeFoliage : matTreeFoliageDark;

  foliageData.forEach(({ r, yo }) => {
