  group.add(disc);

  /* secondary bracket lamp on opposite side (alternate) */
  const arm2 = new THREE.Mesh(boxGeo(1.4, 0.07, 0.07), matLampPole);
  arm2.position.set(-0.7, poleH - 0.5, 0);
  group.add(arm2);

  const bulb2 = new THREE.Mesh(sphGeo(0.12, 8, 6), matBulb);
  bulb2.position.set(-1.4, poleH - 0.75, 0);
  group.add(bulb2);

  const disc2 = new THREE.Mesh(circGeo(2.2, 14), matGroundDisc);
  disc2.rotation.x = -Math.PI * 0.5;
  disc2.position.set(-1.4, 0.02, 0);
  group.add(disc2);

  group.position.set(x, 0, z);
  return group;
}

/* ── Road segment ────────────────────────────────────────────────────── */
function createRoadSegment(cx, cz, length, isNS) {
  const { road } = getTexturePool();
  const group = new THREE.Group();

  const roadMat = stdMat({
    color: 0x1a1a28,
    map: road,
    roughness: 0.85,
  });

  const w = isNS ? ROAD_W * 2 : length;
  const d = isNS ? length : ROAD_W * 2;
  const plane = new THREE.Mesh(
    new THREE.PlaneGeometry(w, d, Math.ceil(w / 10), Math.ceil(d / 10)),
    roadMat
  );
  plane.rotation.x = -Math.PI * 0.5;
  plane.receiveShadow = true;

  if (isNS) {
    road.repeat.set(1, length / 12);
  } else {
    road.repeat.set(length / 12, 1);
  }

  group.add(plane);
  group.position.set(cx, 0.02, cz);
  return group;
}

/* ── Ground plane ────────────────────────────────────────────────────── */
function createGround() {
  const size = CITY_HALF * 2 + 30;
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(size, size, 20, 20),
    matGround
  );
  ground.rotation.x = -Math.PI * 0.5;
  ground.position.y = 0;
  ground.receiveShadow = true;
  ground.name = 'ground';
  return ground;
}

/* ── Pavement / sidewalk ─────────────────────────────────────────────── */
function createSidewalk(cx, cz, w, d) {
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(w, d, 4, 4),
    stdMat({ color: 0x2a2a38, roughness: 0.9 })
  );
  mesh.rotation.x = -Math.PI * 0.5;
  mesh.position.set(cx, 0.03, cz);
  mesh.receiveShadow = true;
  return mesh;
}

/* ── Main city builder ───────────────────────────────────────────────── */
export function buildCity(scene) {
  const pool = getTexturePool();
  const rand = rng(12345);

  let buildingCount = 0;
  let lampCount = 0;
  let treeCount = 0;

  /* ground */
  scene.add(createGround());

  /* ── road grid ─────────────────────────────────────────────────────── */
  const roadPositions = [];
  for (let i = -CITY_HALF; i <= CITY_HALF; i += BLOCK_STEP) {
    roadPositions.push(i);
  }

  /* EW roads */
  roadPositions.forEach(z => {
    const road = createRoadSegment(0, z, CITY_HALF * 2 + 10, false);
    scene.add(road);
  });

  /* NS roads */
  roadPositions.forEach(x => {
    const road = createRoadSegment(x, 0, CITY_HALF * 2 + 10, true);
    scene.add(road);
  });

  /* ── buildings ─────────────────────────────────────────────────────── */
  // Place buildings in the grid blocks, skip center plaza
  const blockPositions = [];
  for (let xi = -CITY_HALF + BLOCK_STEP * 0.5; xi < CITY_HALF; xi += BLOCK_STEP) {
    for (let zi = -CITY_HALF + BLOCK_STEP * 0.5; zi < CITY_HALF; zi += BLOCK_STEP) {
      blockPositions.push([xi, zi]);
    }
  }

  blockPositions.forEach(([bx, bz]) => {
    const dist = Math.hypot(bx, bz);
    if (dist < PLAZA_RADIUS) return; // keep plaza clear

    /* place 1-3 buildings per block */
    const numBuildings = rand() > 0.7 ? 2 : 1;
    const offsets = numBuildings === 1
      ? [[0, 0]]
      : [[-(BLOCK_STEP * 0.22), 0], [BLOCK_STEP * 0.22, 0]];

    offsets.forEach(([ox, oz]) => {
      const x = bx + ox + (rand() - 0.5) * 4;
      const z = bz + oz + (rand() - 0.5) * 4;

      if (Math.hypot(x, z) < PLAZA_RADIUS) return;

      /* building dimensions */
      const w = rand() * 6 + 4;
      const d = rand() * 6 + 4;

      /* varied height profile */
      let h;
      const profile = rand();
      if (profile < 0.15) h = rand() * 10 + 35; // skyscraper
      else if (profile < 0.35) h = rand() * 10 + 22; // high-rise
      else if (profile < 0.60) h = rand() * 8 + 14; // mid-rise
      else if (profile < 0.80) h = rand() * 5 + 8;  // low-rise
      else h = rand() * 4 + 4;                       // short

      const winTex = pool.windows[Math.floor(rand() * pool.windows.length)];
      const neonMat = NEON_MATS[Math.floor(rand() * NEON_MATS.length)];

      const bldg = createBuilding(x, z, w, d, h, winTex, neonMat, rand);
      scene.add(bldg);
      buildingCount++;
    });
  });

  /* extra inner-ring buildings to boost count */
  for (let angle = 0; angle < Math.PI * 2; angle += Math.PI / 8) {
    const r = PLAZA_RADIUS + 8 + rand() * 6;
    const bx = Math.cos(angle) * r;
    const bz = Math.sin(angle) * r;
    const w = rand() * 5 + 5;
    const d = rand() * 5 + 5;
    const h = rand() * 20 + 15;
    const winTex = pool.windows[Math.floor(rand() * pool.windows.length)];
    const bldg = createBuilding(bx, bz, w, d, h, winTex, NEON_MATS[0], rand);
    scene.add(bldg);
    buildingCount++;
  }

  /* ── trees ─────────────────────────────────────────────────────────── */
  // Along roads
  roadPositions.forEach(roadCoord => {
    for (let t = -CITY_HALF + 8; t < CITY_HALF; t += 72) {
      /* both sides of EW road */
      [[roadCoord + ROAD_W + 1.5, t], [roadCoord - ROAD_W - 1.5, t]].forEach(([tz, tx]) => {
        if (Math.hypot(tx, tz) < PLAZA_RADIUS - 2) return;
        scene.add(createTree(tx, tz, rand));
        treeCount++;
      });

      /* both sides of NS road */
      [[t, roadCoord + ROAD_W + 1.5], [t, roadCoord - ROAD_W - 1.5]].forEach(([tx, tz]) => {
        if (Math.hypot(tx, tz) < PLAZA_RADIUS - 2) return;
        scene.add(createTree(tx, tz, rand));
        treeCount++;
      });
    }
  });

  /* park trees – scattered around mid-distance */
  for (let i = 0; i < 30; i++) {
    const angle = rand() * Math.PI * 2;
    const r = PLAZA_RADIUS + 10 + rand() * (CITY_HALF - PLAZA_RADIUS - 15);
    const tx = Math.cos(angle) * r;
    const tz = Math.sin(angle) * r;
    scene.add(createTree(tx, tz, rand));
    treeCount++;
  }

  /* ── street lamps ───────────────────────────────────────────────────── */
  roadPositions.forEach(roadCoord => {
    for (let pos = -CITY_HALF + 10; pos < CITY_HALF; pos += 72) {
      /* EW road lamps */
      [[roadCoord + ROAD_W + 0.8, pos], [roadCoord - ROAD_W - 0.8, pos]].forEach(([lz, lx]) => {
        if (Math.hypot(lx, lz) < PLAZA_RADIUS - 3) return;
        const lamp = createStreetlamp(lx, lz);
        scene.add(lamp);
        lampCount++;
      });

      /* NS road lamps */
      [[pos, roadCoord + ROAD_W + 0.8], [pos, roadCoord - ROAD_W - 0.8]].forEach(([lx, lz]) => {
        if (Math.hypot(lx, lz) < PLAZA_RADIUS - 3) return;
        const lamp = createStreetlamp(lx, lz);
        scene.add(lamp);
        lampCount++;
      });
    }
  });

  /* plaza ring lamps */
  for (let a = 0; a < Math.PI * 2; a += Math.PI / 9) {
    const r = PLAZA_RADIUS + 2;
    const lx = Math.cos(a) * r;
    const lz = Math.sin(a) * r;
    const lamp = createStreetlamp(lx, lz);
    scene.add(lamp);
    lampCount++;
  }

  /* ── sidewalks ──────────────────────────────────────────────────────── */
  roadPositions.forEach(z => {
    scene.add(createSidewalk(0, z + ROAD_W + 2, CITY_HALF * 2, 2.5));
    scene.add(createSidewalk(0, z - ROAD_W - 2, CITY_HALF * 2, 2.5));
  });
  roadPositions.forEach(x => {
    scene.add(createSidewalk(x + ROAD_W + 2, 0, 2.5, CITY_HALF * 2));
    scene.add(createSidewalk(x - ROAD_W - 2, 0, 2.5, CITY_HALF * 2));
  });

  /* ── city edge barrier wall ─────────────────────────────────────────── */
  const wallH = 2.5;
  const wallMat = stdMat({ color: 0x222233, roughness: 0.8 });
  const wallLen = CITY_HALF * 2 + 5;
  [
    [0, CITY_HALF + 1, wallLen, wallH, 0.8, 0],
    [0, -(CITY_HALF + 1), wallLen, wallH, 0.8, 0],
    [CITY_HALF + 1, 0, 0.8, wallH, wallLen, 0],
    [-(CITY_HALF + 1), 0, 0.8, wallH, wallLen, 0],
  ].forEach(([wx, wz, ww, wh, wd]) => {
    const wall = new THREE.Mesh(boxGeo(ww, wh, wd), wallMat);
    wall.position.set(wx, wh * 0.5, wz);
    scene.add(wall);
  });

  /* ── neon sign arches over main avenues ─────────────────────────────── */
  const archMats = [
    stdMat({ color: 0xff00ff, emissive: new THREE.Color(0xee00ff), emissiveIntensity: 4 }),
    stdMat({ color: 0x00ffff, emissive: new THREE.Color(0x00ccff), emissiveIntensity: 4 }),
    stdMat({ color: 0xff8800, emissive: new THREE.Color(0xff6600), emissiveIntensity: 4 }),
  ];
  const archZ = [-48, 0, 48];
  archZ.forEach((az, idx) => {
    const archGroup = new THREE.Group();
    const archMat = archMats[idx % archMats.length];

    /* horizontal top bar */
    const topBar = new THREE.Mesh(boxGeo(ROAD_W * 2.4, 0.4, 0.3), archMat);
    topBar.position.set(0, 9, 0);
    archGroup.add(topBar);

    /* left pillar */
    const lp = new THREE.Mesh(boxGeo(0.3, 9, 0.3), archMat);
    lp.position.set(-ROAD_W * 1.1, 4.5, 0);
    archGroup.add(lp);

    /* right pillar */
    const rp = new THREE.Mesh(boxGeo(0.3, 9, 0.3), archMat);
    rp.position.set(ROAD_W * 1.1, 4.5, 0);
    archGroup.add(rp);

    archGroup.position.set(-60, 0, az);
    scene.add(archGroup);

    const archGroup2 = archGroup.clone();
    archGroup2.position.set(60, 0, az);
    scene.add(archGroup2);
  });

  /* ── decorative benches ─────────────────────────────────────────────── */
  const benchMat = stdMat({ color: 0x4a3520, roughness: 0.8 });
  for (let a = 0; a < Math.PI * 2; a += Math.PI / 6) {
    const r = PLAZA_RADIUS - 8;
    const bx = Math.cos(a) * r;
    const bz = Math.sin(a) * r;
    const bench = new THREE.Group();
    /* seat */
    const seat = new THREE.Mesh(boxGeo(2.2, 0.2, 0.7), benchMat);
    seat.position.y = 0.55;
    bench.add(seat);
    /* legs */
    [-0.8, 0.8].forEach(ox => {
      const leg = new THREE.Mesh(boxGeo(0.12, 0.55, 0.5), benchMat);
      leg.position.set(ox, 0.27, 0);
      bench.add(leg);
    });
    /* backrest */
    const back = new THREE.Mesh(boxGeo(2.2, 0.5, 0.1), benchMat);
    back.position.set(0, 0.9, -0.32);
    bench.add(back);
    bench.position.set(bx, 0, bz);
    bench.rotation.y = a + Math.PI;
    scene.add(bench);
  }

  /* ── decorative lamp posts near plaza ───────────────────────────────── */
  for (let a = 0; a < Math.PI * 2; a += Math.PI / 12) {
    const r = PLAZA_RADIUS + 5.5;
    const lx = Math.cos(a) * r;
    const lz = Math.sin(a) * r;
    const lamp = createStreetlamp(lx, lz);
    lamp.scale.set(0.8, 0.8, 0.8);
    scene.add(lamp);
    lampCount++;
  }

  return { buildingCount, lampCount, treeCount };
}


// ====== src/world/forge.js (13572 bytes) ======
import * as THREE from 'three';
import { getTexturePool } from './textures.js';

function stdMat(p) { return new THREE.MeshStandardMaterial(p); }
function phongMat(p) { return new THREE.MeshPhongMaterial(p); }
function boxGeo(w, h, d, sw=1, sh=1, sd=1) { return new THREE.BoxGeometry(w, h, d, sw, sh, sd); }
function cylGeo(rt, rb, h, s=8) { return new THREE.CylinderGeometry(rt, rb, h, s); }
function sphGeo(r, ws=12, hs=8) { return new THREE.SphereGeometry(r, ws, hs); }

const matAnvil = stdMat({ color: 0x334455, roughness: 0.35, metalness: 0.85 });
const matAnvilHot = stdMat({ color: 0xff6600, emissive: new THREE.Color(0xff3300), emissiveIntensity: 2.5, roughness: 0.4, metalness: 0.6 });
const matHammer = stdMat({ color: 0x2a2a2a, roughness: 0.4, metalness: 0.9 });
const matHammerWood = stdMat({ color: 0x6b3a1f, roughness: 0.85 });
const matDais = stdMat({ color: 0x4a4a5a, roughness: 0.75, metalness: 0.1 });
const matMagma = stdMat({ color: 0xff4400, emissive: new THREE.Color(0xff2200), emissiveIntensity: 3.0, roughness: 0.6 });
const matEmber = stdMat({ color: 0xff8800, emissive: new THREE.Color(0xff6600), emissiveIntensity: 5.0, roughness: 0.3 });
const matSpark = stdMat({ color: 0xffee00, emissive: new THREE.Color(0xffcc00), emissiveIntensity: 8.0, roughness: 0.1 });
const matShockwave = stdMat({ color: 0xff6600, emissive: new THREE.Color(0xff4400), emissiveIntensity: 2.0, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false });
const matRuneDisc = stdMat({ color: 0x220800, emissive: new THREE.Color(0xff4400), emissiveIntensity: 0.4, roughness: 0.7 });

/* ── Build 3D Anvil ─────────────────────────────────────────────────── */
function buildAnvil(parent) {
  const g = new THREE.Group();

  /* base block */
  const base = new THREE.Mesh(boxGeo(3.0, 0.9, 1.8, 2, 1, 2), matAnvil);
  base.position.y = 0.45;
  base.castShadow = true;
  g.add(base);

  /* waist */
  const waist = new THREE.Mesh(boxGeo(2.0, 0.5, 1.2), matAnvil);
  waist.position.y = 1.15;
  waist.castShadow = true;
  g.add(waist);

  /* body top */
  const body = new THREE.Mesh(boxGeo(3.2, 0.7, 1.5, 2, 1, 2), matAnvil);
  body.position.y = 1.75;
  body.castShadow = true;
  g.add(body);

  /* horn (front cone) */
  const horn = new THREE.Mesh(cylGeo(0.08, 0.38, 1.6, 10), matAnvil);
  horn.rotation.z = -Math.PI / 2;
  horn.position.set(2.2, 1.75, 0);
  horn.castShadow = true;
  g.add(horn);

  /* heel (back step) */
  const heel = new THREE.Mesh(boxGeo(0.9, 0.55, 1.5), matAnvil);
  heel.position.set(-1.4, 1.45, 0);
  heel.castShadow = true;
  g.add(heel);

  /* heated ingot on top */
  const ingot = new THREE.Mesh(boxGeo(1.4, 0.3, 0.7), matAnvilHot);
  ingot.position.set(0.2, 2.25, 0);
  ingot.castShadow = true;
  g.add(ingot);

  /* anvil legs */
  [[-0.9, 0.9], [0.9, 0.9], [-0.9, -0.9], [0.9, -0.9]].forEach(([lx, lz]) => {
    const leg = new THREE.Mesh(cylGeo(0.14, 0.18, 0.8, 6), matAnvil);
    leg.position.set(lx, 0.4, lz * 0.5);
    leg.castShadow = true;
    g.add(leg);
  });

  parent.add(g);
  return g;
}

/* ── Build Hammer ────────────────────────────────────────────────────── */
function buildHammer(parent) {
  const g = new THREE.Group();

  /* handle */
  const handle = new THREE.Mesh(cylGeo(0.09, 0.12, 3.5, 8), matHammerWood);
  handle.castShadow = true;
  g.add(handle);

  /* head */
  const head = new THREE.Mesh(boxGeo(0.7, 0.7, 1.5, 2, 2, 2), matHammer);
  head.position.y = 1.9;
  head.castShadow = true;
  g.add(head);

  /* metal band */
  const band = new THREE.Mesh(cylGeo(0.135, 0.135, 0.22, 8), matHammer);
  band.position.y = 1.4;
  g.add(band);

  parent.add(g);
  return g;
}

/* ── Build Tiered Dais ───────────────────────────────────────────────── */
function buildDais(scene) {
  const pool = getTexturePool();
  const daisGroup = new THREE.Group();
  daisGroup.name = 'forgeDais';

  const tiers = [
    { r: 18, h: 0.5 },
    { r: 14, h: 0.8 },
    { r: 10, h: 0.7 },
    { r: 6.5, h: 0.6 },
  ];

  tiers.forEach(({ r, h }, i) => {
    const tierY = tiers.slice(0, i).reduce((s, t) => s + t.h, 0);
    const mesh = new THREE.Mesh(cylGeo(r, r + 0.4, h, 32), matDais);
    mesh.position.y = tierY + h * 0.5;
    mesh.receiveShadow = true;
    mesh.castShadow = true;
    daisGroup.add(mesh);

    /* stone trim ring */
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(r, 0.18, 6, 40),
      stdMat({ color: 0x666677, roughness: 0.6, metalness: 0.2 })
    );
    ring.rotation.x = Math.PI / 2;
    ring.position.y = tierY + h;
    daisGroup.add(ring);
  });

  /* rune disc on top */
  const totalH = tiers.reduce((s, t) => s + t.h, 0);
  const runeDisc = new THREE.Mesh(
    new THREE.CircleGeometry(6.2, 48),
    stdMat({ map: pool.rune, emissiveMap: pool.rune, emissive: new THREE.Color(1, 0.4, 0), emissiveIntensity: 1.2, roughness: 0.7 })
  );
  runeDisc.rotation.x = -Math.PI / 2;
  runeDisc.position.y = totalH + 0.01;
  daisGroup.add(runeDisc);

  /* magma hearth bowl */
  const hearth = new THREE.Mesh(cylGeo(2.6, 3.0, 1.0, 24), matDais);
  hearth.position.y = totalH + 0.5;
  hearth.castShadow = true;
  daisGroup.add(hearth);

  /* lava surface */
  const lava = new THREE.Mesh(
    new THREE.CircleGeometry(2.5, 24),
    stdMat({ map: pool.lava, emissiveMap: pool.lava, emissive: new THREE.Color(1, 0.3, 0), emissiveIntensity: 2.0, roughness: 0.8 })
  );
  lava.rotation.x = -Math.PI / 2;
  lava.position.y = totalH + 1.05;
  daisGroup.add(lava);

  /* forge glow point light */
  const glow = new THREE.PointLight(0xff4400, 3.5, 28, 2);
  glow.position.y = totalH + 2;
  daisGroup.add(glow);

  scene.add(daisGroup);
  return { daisGroup, totalH };
}

/* ── Particle pool ──────────────────────────────────────────────────── */
const EMBER_COUNT = 160;
const SPARK_COUNT = 80;

function createEmbers() {
  const embers = [];
  const geo = sphGeo(0.08, 4, 3);
  for (let i = 0; i < EMBER_COUNT; i++) {
    const m = new THREE.Mesh(geo, matEmber.clone());
    m.userData.vel = new THREE.Vector3(
      (Math.random() - 0.5) * 0.04,
      Math.random() * 0.08 + 0.03,
      (Math.random() - 0.5) * 0.04
    );
    m.userData.life = Math.random();
    m.userData.maxLife = Math.random() * 2.5 + 1.5;
    m.position.set(
      (Math.random() - 0.5) * 4,
      Math.random() * 3 + 2,
      (Math.random() - 0.5) * 4
    );
    embers.push(m);
  }
  return embers;
}

function createSparks() {
  const sparks = [];
  const geo = sphGeo(0.05, 4, 3);
  for (let i = 0; i < SPARK_COUNT; i++) {
    const m = new THREE.Mesh(geo, matSpark.clone());
    m.userData.vel = new THREE.Vector3(0, 0, 0);
    m.userData.life = 99; // inactive
    m.userData.active = false;
    m.position.set(0, -10, 0);
    sparks.push(m);
  }
  return sparks;
}

function createShockwaves() {
  const waves = [];
  for (let i = 0; i < 4; i++) {
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(1, 0.08, 6, 32),
      matShockwave.clone()
    );
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.3;
    ring.userData.active = false;
    ring.userData.scale = 1;
    ring.userData.life = 0;
    ring.visible = false;
    waves.push(ring);
  }
  return waves;
}

/* ── Main forge builder ─────────────────────────────────────────────── */
export function buildForge(scene) {
  const { daisGroup, totalH } = buildDais(scene);
  const anvilY = totalH + 1.0;

  /* anvil */
  const anvilGroup = new THREE.Group();
  anvilGroup.name = 'anvil';
  buildAnvil(anvilGroup);
  anvilGroup.position.set(0, anvilY, 0);
  scene.add(anvilGroup);

  /* hammer pivot group */
  const hammerPivot = new THREE.Group();
  hammerPivot.name = 'hammerPivot';
  hammerPivot.position.set(1.8, anvilY + 2.8, 0.5);
  const hammerMesh = buildHammer(hammerPivot);
  hammerMesh.position.set(0, 0, 0);
  scene.add(hammerPivot);

  /* embers */
  const embers = createEmbers();
  const emberGroup = new THREE.Group();
  emberGroup.name = 'embers';
  embers.forEach(e => emberGroup.add(e));
  emberGroup.position.set(0, anvilY + 0.5, 0);
  scene.add(emberGroup);

  /* sparks */
  const sparks = createSparks();
  const sparkGroup = new THREE.Group();
  sparkGroup.name = 'sparks';
  sparks.forEach(s => sparkGroup.add(s));
  sparkGroup.position.set(0, anvilY + 2.2, 0);
  scene.add(sparkGroup);

  /* shockwaves */
  const shockwaves = createShockwaves();
  const waveGroup = new THREE.Group();
  waveGroup.name = 'shockwaves';
  shockwaves.forEach(w => waveGroup.add(w));
  waveGroup.position.set(0, anvilY + 0.15, 0);
  scene.add(waveGroup);

  /* iron columns around dais */
  const colMat = stdMat({ color: 0x222233, roughness: 0.5, metalness: 0.7 });
  const bracketMat = stdMat({ color: 0xff4400, emissive: new THREE.Color(0xff2200), emissiveIntensity: 2.5 });
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    const r = 15.5;
    const col = new THREE.Group();
    const shaft = new THREE.Mesh(cylGeo(0.22, 0.28, totalH + 3, 8), colMat);
    shaft.position.y = (totalH + 3) * 0.5;
    shaft.castShadow = true;
    col.add(shaft);

    /* flame bracket at top */
    const bracket = new THREE.Mesh(sphGeo(0.35, 8, 6), bracketMat);
    bracket.position.y = totalH + 3.4;
    col.add(bracket);

    col.position.set(Math.cos(a) * r, 0, Math.sin(a) * r);
    scene.add(col);
  }

  /* chains from columns */
  const chainMat = stdMat({ color: 0x444455, roughness: 0.5, metalness: 0.8 });
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    const r = 15.5;
    for (let j = 0; j < 5; j++) {
      const link = new THREE.Mesh(
        new THREE.TorusGeometry(0.15, 0.04, 4, 8),
        chainMat
      );
      const frac = j / 4;
      link.position.set(
        Math.cos(a) * r * (1 - frac * 0.6),
        totalH + 3.0 - frac * 1.5,
        Math.sin(a) * r * (1 - frac * 0.6)
      );
      link.rotation.y = a;
      link.rotation.z = frac * 0.6;
      scene.add(link);
    }
  }

  /* hammer state */
  let hammerSwing = 0;
  let hammerSwinging = false;
  let hammerTimer = 0;

  /* strike function */
  function triggerStrike(sparks, shockwaves) {
    hammerSwinging = true;
    hammerTimer = 0;

    /* burst sparks */
    sparks.forEach(s => {
      s.userData.active = true;
      s.userData.life = 0;
      s.userData.maxLife = Math.random() * 0.8 + 0.3;
      const speed = Math.random() * 0.18 + 0.08;
      const ang = Math.random() * Math.PI * 2;
      const vt = Math.random() * Math.PI * 0.5;
      s.userData.vel = new THREE.Vector3(
        Math.cos(ang) * Math.cos(vt) * speed,
        Math.sin(vt) * speed + 0.06,
        Math.sin(ang) * Math.cos(vt) * speed
      );
      s.position.set(
        (Math.random() - 0.5) * 1.5,
        0,
        (Math.random() - 0.5) * 1.5
      );
      s.visible = true;
    });

    /* activate shockwaves */
    shockwaves.forEach((w, i) => {
      w.userData.active = true;
      w.userData.scale = 0.1;
      w.userData.life = 0;
      w.userData.delay = i * 0.12;
      w.visible = true;
      w.scale.set(0.1, 0.1, 0.1);
      w.material.opacity = 0.7;
    });
  }

  /* animate function */
  function animateForge(dt, state) {
    if (!state.spinning) return;

    /* embers */
    embers.forEach(e => {
      e.userData.life += dt;
      if (e.userData.life > e.userData.maxLife) {
        e.userData.life = 0;
        e.userData.maxLife = Math.random() * 2.5 + 1.5;
        e.position.set(
          (Math.random() - 0.5) * 4,
          0,
          (Math.random() - 0.5) * 4
        );
        e.userData.vel.set(
          (Math.random() - 0.5) * 0.05,
          Math.random() * 0.07 + 0.03,
          (Math.random() - 0.5) * 0.05
        );
      }
      e.position.addScaledVector(e.userData.vel, 1);
      e.userData.vel.x += (Math.random() - 0.5) * 0.003;
      e.userData.vel.z += (Math.random() - 0.5) * 0.003;
      const t = e.userData.life / e.userData.maxLife;
      e.material.opacity = Math.max(0, 1 - t * t);
      e.material.transparent = true;
    });

    /* sparks */
    sparks.forEach(s => {
      if (!s.userData.active) return;
      s.userData.life += dt;
      if (s.userData.life > s.userData.maxLife) {
        s.userData.active = false;
        s.visible = false;
        return;
      }
      s.position.addScaledVector(s.userData.vel, 1);
      s.userData.vel.y -= 0.004;
      const t = s.userData.life / s.userData.maxLife;
      s.material.opacity = Math.max(0, 1 - t);
      s.material.transparent = true;
    });

    /* shockwaves */
    shockwaves.forEach(w => {
      if (!w.userData.active) return;
      w.userData.life += dt;
      const life = w.userData.life - (w.userData.delay || 0);
      if (life < 0) return;
      const t = life / 0.8;
      if (t >= 1) {
        w.userData.active = false;
        w.visible = false;
        return;
      }
      const sc = 0.5 + t * 7;
      w.scale.set(sc, 1, sc);
      w.material.opacity = 0.6 * (1 - t);
    });

    /* hammer swing */
    if (hammerSwinging) {
      hammerTimer += dt;
      const t = Math.min(hammerTimer / 0.5, 1);
      hammerSwing = Math.sin(t * Math.PI) * -1.1;
      hammerPivot.rotation.z = hammerSwing;
      if (hammerTimer > 0.5) {
        hammerSwinging = false;
        hammerPivot.rotation.z = 0;
      }
    } else {
      /* idle hammer bob */
      hammerPivot.rotation.z = Math.sin(Date.now() * 0.0008) * 0.12;
    }

    /* rune disc rotation */
    const runeDisc = daisGroup.children.find(c => c.material && c.material.map);
    if (runeDisc) runeDisc.rotation.z += dt * 0.3;
  }

  return {
    animateForge,
    triggerStrike: () => triggerStrike(sparks, shockwaves),
  };
}


