import * as THREE from 'three';

/* ── Colour palettes ─────────────────────────────────────────────────── */
const PALETTE_NIGHT = [
  '#00ffff', '#ffff00', '#ff00ff', '#00ff88', '#ff8800',
  '#8888ff', '#ffffff', '#ff4466', '#44ffcc', '#ffcc00',
];
const PALETTE_GOLD = [
  '#ffa040', '#ffcc44', '#ff8822', '#ff6600',
  '#ffdd88', '#ffaa55', '#ffbb33', '#ff9944',
];
const PALETTE_DAY = [
  '#aaddff', '#ccffcc', '#ffffcc', '#ddeeff',
  '#ffffff', '#eeeeff', '#ccddff', '#ddfff0',
];

/* ── Utility ─────────────────────────────────────────────────────────── */
function rng(seed) {
  let s = seed | 0;
  return () => { s = (s * 1664525 + 1013904223) & 0xffffffff; return (s >>> 0) / 0xffffffff; };
}

/* ── Window Facade Texture ───────────────────────────────────────────── */
export function makeWindowTexture({
  w = 512,
  h = 512,
  palette = PALETTE_NIGHT,
  rows = 20,
  cols = 12,
  bgColor = '#08081a',
  emissiveGlow = true,
  seed = 42,
} = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');
  const rand = rng(seed);

  /* background – concrete body */
  ctx.fillStyle = bgColor;
  ctx.fillRect(0, 0, w, h);

  /* subtle concrete grain */
  for (let i = 0; i < 400; i++) {
    const x = rand() * w;
    const y = rand() * h;
    const a = rand() * 0.04;
    ctx.fillStyle = `rgba(200,210,230,${a})`;
    ctx.fillRect(x, y, rand() * 4 + 1, rand() * 2 + 1);
  }

  /* horizontal floor dividers */
  ctx.strokeStyle = 'rgba(255,255,255,0.06)';
  ctx.lineWidth = 1;
  for (let r = 0; r <= rows; r++) {
    ctx.beginPath();
    ctx.moveTo(0, (r / rows) * h);
    ctx.lineTo(w, (r / rows) * h);
    ctx.stroke();
  }

  /* vertical column dividers */
  for (let c = 0; c <= cols; c++) {
    ctx.beginPath();
    ctx.moveTo((c / cols) * w, 0);
    ctx.lineTo((c / cols) * w, h);
    ctx.stroke();
  }

  /* windows */
  const winW = w / cols;
  const winH = h / rows;
  const padX = Math.max(2, winW * 0.12);
  const padY = Math.max(2, winH * 0.14);

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const lit = rand() > 0.22; // ~78 % of windows lit
      if (!lit) {
        /* dark window with faint reflection */
        ctx.fillStyle = 'rgba(20,25,40,0.9)';
        ctx.fillRect(
          c * winW + padX, r * winH + padY,
          winW - padX * 2, winH - padY * 2
        );
        continue;
      }

      const color = palette[Math.floor(rand() * palette.length)];
      const wx = c * winW + padX;
      const wy = r * winH + padY;
      const ww = winW - padX * 2;
      const wh = winH - padY * 2;

      /* outer glow */
      if (emissiveGlow) {
        ctx.save();
        ctx.shadowColor = color;
        ctx.shadowBlur = 16;
        ctx.fillStyle = color + '55';
        ctx.fillRect(wx - 4, wy - 4, ww + 8, wh + 8);
        ctx.restore();
      }

      /* window body gradient */
      const grad = ctx.createLinearGradient(wx, wy, wx + ww, wy + wh);
      grad.addColorStop(0, color + 'dd');
      grad.addColorStop(0.45, color + 'ff');
      grad.addColorStop(1, color + 'aa');
      ctx.fillStyle = grad;
      ctx.fillRect(wx, wy, ww, wh);

      /* highlight / reflection */
      ctx.fillStyle = 'rgba(255,255,255,0.28)';
      ctx.fillRect(wx + 1, wy + 1, ww * 0.38, wh * 0.32);

      /* venetian-blind lines */
      if (rand() > 0.6) {
        ctx.strokeStyle = 'rgba(0,0,0,0.25)';
        ctx.lineWidth = 1;
        const stripes = Math.floor(wh / 4);
        for (let s = 0; s < stripes; s++) {
          ctx.beginPath();
          ctx.moveTo(wx, wy + s * 4);
          ctx.lineTo(wx + ww, wy + s * 4);
          ctx.stroke();
        }
      }
    }
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  return tex;
}

/* ── Road / Crosswalk Texture ────────────────────────────────────────── */
export function makeRoadTexture({ w = 512, h = 512 } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');
  const rand = rng(77);

  /* asphalt base */
  ctx.fillStyle = '#181820';
  ctx.fillRect(0, 0, w, h);

  /* noise grain */
  for (let i = 0; i < 1200; i++) {
    const x = rand() * w;
    const y = rand() * h;
    const v = Math.floor(rand() * 30 + 20);
    ctx.fillStyle = `rgba(${v},${v},${v + 10},${rand() * 0.08})`;
    ctx.fillRect(x, y, rand() * 3 + 1, rand() * 2 + 1);
  }

  /* centre yellow dash */
  ctx.strokeStyle = '#ffdd00';
  ctx.lineWidth = 4;
  ctx.setLineDash([22, 18]);
  ctx.beginPath();
  ctx.moveTo(w * 0.5, 0);
  ctx.lineTo(w * 0.5, h);
  ctx.stroke();
  ctx.setLineDash([]);

  /* lane dividers white */
  ctx.strokeStyle = 'rgba(255,255,255,0.7)';
  ctx.lineWidth = 2.5;
  ctx.setLineDash([16, 22]);
  [0.25, 0.75].forEach(fx => {
    ctx.beginPath();
    ctx.moveTo(fx * w, 0);
    ctx.lineTo(fx * w, h);
    ctx.stroke();
  });
  ctx.setLineDash([]);

  /* crosswalk stripes – top band */
  ctx.fillStyle = 'rgba(240,240,240,0.72)';
  for (let i = 0; i < 9; i++) ctx.fillRect(0, i * 14, w, 9);

  /* crosswalk stripes – bottom band */
  for (let i = 0; i < 9; i++) ctx.fillRect(0, h - 130 + i * 14, w, 9);

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  return tex;
}

/* ── Forge Rune Ring Texture ─────────────────────────────────────────── */
export function makeRuneTexture({ w = 512, h = 512 } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, w, h);

  const cx = w * 0.5, cy = h * 0.5;

  /* radial background heat */
  const heatGrd = ctx.createRadialGradient(cx, cy, 0, cx, cy, w * 0.48);
  heatGrd.addColorStop(0, 'rgba(255,120,0,0.18)');
  heatGrd.addColorStop(0.5, 'rgba(255,50,0,0.08)');
  heatGrd.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = heatGrd;
  ctx.fillRect(0, 0, w, h);

  /* concentric glowing rings */
  const rings = [
    { r: w * 0.455, color: '#ff4400', blur: 22, lw: 5 },
    { r: w * 0.40,  color: '#ff6600', blur: 16, lw: 4 },
    { r: w * 0.345, color: '#ff9900', blur: 12, lw: 3 },
    { r: w * 0.29,  color: '#ffcc00', blur: 8,  lw: 2 },
  ];
  rings.forEach(({ r, color, blur, lw }) => {
    ctx.save();
    ctx.shadowColor = color;
    ctx.shadowBlur = blur;
    ctx.strokeStyle = color;
    ctx.lineWidth = lw;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  });

  /* rune symbols */
  const RUNES = ['ᚠ', 'ᚢ', 'ᚦ', 'ᚨ', 'ᚱ', 'ᚲ', 'ᚷ', 'ᚹ', 'ᚺ', 'ᚾ', 'ᛁ', 'ᛃ'];
  ctx.font = `bold ${Math.floor(w * 0.055)}px serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  RUNES.forEach((rune, i) => {
    const angle = (i / RUNES.length) * Math.PI * 2 - Math.PI / 2;
    const rx = cx + Math.cos(angle) * w * 0.425;
    const ry = cy + Math.sin(angle) * w * 0.425;
    ctx.save();
    ctx.translate(rx, ry);
    ctx.rotate(angle + Math.PI / 2);
    ctx.shadowColor = '#ff6600';
    ctx.shadowBlur = 14;
    ctx.fillStyle = '#ffaa44';
    ctx.fillText(rune, 0, 0);
    ctx.restore();
  });

  /* inner hex star lines */
  ctx.strokeStyle = 'rgba(255,140,0,0.35)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(a) * w * 0.28, cy + Math.sin(a) * w * 0.28);
    ctx.stroke();
  }

  const tex = new THREE.CanvasTexture(canvas);
  return tex;
}

/* ── Helipad Texture ─────────────────────────────────────────────────── */
export function makeHelipadTexture({ w = 256, h = 256 } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = '#1a1a2e';
  ctx.fillRect(0, 0, w, h);

  const cx = w * 0.5, cy = h * 0.5;

  /* outer ring */
  ctx.strokeStyle = '#ffdd00';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(cx, cy, w * 0.42, 0, Math.PI * 2);
  ctx.stroke();

  /* inner ring */
  ctx.strokeStyle = '#ff8800';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(cx, cy, w * 0.36, 0, Math.PI * 2);
  ctx.stroke();

  /* H letter */
  ctx.font = `bold ${Math.floor(w * 0.48)}px sans-serif`;
  ctx.fillStyle = '#ffdd00';
  ctx.shadowColor = '#ffaa00';
  ctx.shadowBlur = 10;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('H', cx, cy);

  const tex = new THREE.CanvasTexture(canvas);
  return tex;
}

/* ── Molten Lava Pool Texture ────────────────────────────────────────── */
export function makeLavaTexture({ w = 256, h = 256 } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');
  const rand = rng(99);

  ctx.fillStyle = '#220500';
  ctx.fillRect(0, 0, w, h);

  /* lava patches */
  for (let i = 0; i < 80; i++) {
    const x = rand() * w;
    const y = rand() * h;
    const r = rand() * 30 + 8;
    const brightness = rand() * 0.7 + 0.3;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(255,${Math.floor(brightness * 200)},0,0.9)`);
    g.addColorStop(0.5, `rgba(220,${Math.floor(brightness * 80)},0,0.5)`);
    g.addColorStop(1, 'rgba(100,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  /* dark crust veins */
  ctx.strokeStyle = 'rgba(10,0,0,0.6)';
  for (let i = 0; i < 30; i++) {
    ctx.lineWidth = rand() * 3 + 1;
    ctx.beginPath();
    ctx.moveTo(rand() * w, rand() * h);
    ctx.bezierCurveTo(
      rand() * w, rand() * h,
      rand() * w, rand() * h,
      rand() * w, rand() * h
    );
    ctx.stroke();
  }

  const tex = new THREE.CanvasTexture(canvas);
  return tex;
}

/* ── Stone / Ground Texture ──────────────────────────────────────────── */
export function makeStoneTexture({ w = 256, h = 256 } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');
  const rand = rng(33);

  ctx.fillStyle = '#3a3a4a';
  ctx.fillRect(0, 0, w, h);

  /* stone grain */
  for (let i = 0; i < 600; i++) {
    const x = rand() * w;
    const y = rand() * h;
    const v = Math.floor(rand() * 40 + 40);
    ctx.fillStyle = `rgba(${v},${v},${v + 10},${rand() * 0.12})`;
    ctx.fillRect(x, y, rand() * 5 + 1, rand() * 4 + 1);
  }

  /* mortar lines */
  ctx.strokeStyle = 'rgba(20,20,28,0.5)';
  ctx.lineWidth = 2;
  const tileSize = 40;
  for (let y = 0; y < h; y += tileSize) {
    const offset = (Math.floor(y / tileSize) % 2) * tileSize * 0.5;
    for (let x = -offset; x < w; x += tileSize) {
      ctx.strokeRect(x + 2, y + 2, tileSize - 4, tileSize - 4);
    }
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  return tex;
}

/* ── Neon Sign Texture ───────────────────────────────────────────────── */
export function makeNeonSignTexture({ w = 256, h = 64, text = 'MORU', color = '#ff00ff' } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = '#050510';
  ctx.fillRect(0, 0, w, h);

  ctx.font = `bold ${h * 0.7}px 'Segoe UI', sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowColor = color;
  ctx.shadowBlur = 20;
  ctx.fillStyle = color;
  ctx.fillText(text, w * 0.5, h * 0.5);
  /* double pass for stronger glow */
  ctx.fillText(text, w * 0.5, h * 0.5);

  const tex = new THREE.CanvasTexture(canvas);
  return tex;
}

/* ── Pre-built texture pool ──────────────────────────────────────────── */
let _pool = null;
export function getTexturePool() {
  if (_pool) return _pool;
  _pool = {
    /* 6 distinct night facade textures with varied seeds */
    windows: [
      makeWindowTexture({ palette: PALETTE_NIGHT, rows: 22, cols: 13, seed: 1 }),
      makeWindowTexture({ palette: PALETTE_NIGHT, rows: 18, cols: 10, seed: 2 }),
      makeWindowTexture({ palette: PALETTE_NIGHT, rows: 25, cols: 14, seed: 3 }),
      makeWindowTexture({ palette: PALETTE_NIGHT, rows: 16, cols: 9,  seed: 4 }),
      makeWindowTexture({ palette: PALETTE_NIGHT, rows: 30, cols: 16, seed: 5 }),
      makeWindowTexture({ palette: PALETTE_NIGHT, rows: 20, cols: 11, seed: 6 }),
    ],
    road: makeRoadTexture(),
    rune: makeRuneTexture(),
    helipad: makeHelipadTexture(),
    lava: makeLavaTexture(),
    stone: makeStoneTexture(),
    neonMoru: makeNeonSignTexture({ text: 'MORU', color: '#ff00ff' }),
    neonForge: makeNeonSignTexture({ text: 'FORGE', color: '#ff8800' }),
  };
  return _pool;
}


