import * as THREE from 'three';

const state = {
  isPaused: false,
  activeCameraMode: 'overview',
  atmosphereMode: 'night',
  cats: [],
  followCatIndex: 0,
  cameraRotation: 0,
  time: 0,
  forgeEnergy: 0,
};

let scene, camera, renderer;
const canvas = document.getElementById('canvas-container');

function init() {
  scene = new THREE.Scene();
  camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 10000);
  renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFShadowShadowMap;
  canvas.appendChild(renderer.domElement);

  setupLighting();
  createCityGround();
  createBuildings();
  createForge();
  createForestAndStreetlamps();
  initUI();
  setupWindowExport();
  setAtmosphere('night');

  window.addEventListener('resize', onWindowResize);
  animate();
}

function setupLighting() {
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
  scene.add(ambientLight);

  const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
  dirLight.position.set(100, 150, 100);
  dirLight.castShadow = true;
  dirLight.shadow.mapSize.width = 2048;
  dirLight.shadow.mapSize.height = 2048;
  dirLight.shadow.camera.near = 0.5;
  dirLight.shadow.camera.far = 500;
  dirLight.shadow.camera.left = -300;
  dirLight.shadow.camera.right = 300;
  dirLight.shadow.camera.top = 300;
  dirLight.shadow.camera.bottom = -300;
  scene.add(dirLight);
}

function createCityGround() {
  const groundGeometry = new THREE.PlaneGeometry(800, 800);
  const groundMaterial = new THREE.MeshLambertMaterial({ color: 0x1a1a2e });
  const ground = new THREE.Mesh(groundGeometry, groundMaterial);
  ground.receiveShadow = true;
  ground.rotation.x = -Math.PI / 2;
  scene.add(ground);

  const roadTexture = createRoadTexture();
  const roadMaterial = new THREE.MeshLambertMaterial({ map: roadTexture });

  const roadH = new THREE.Mesh(new THREE.PlaneGeometry(800, 60), roadMaterial);
  roadH.receiveShadow = true;
  roadH.rotation.x = -Math.PI / 2;
  roadH.position.y = 0.01;
  scene.add(roadH);

  const roadV = new THREE.Mesh(new THREE.PlaneGeometry(60, 800), roadMaterial);
  roadV.receiveShadow = true;
  roadV.rotation.x = -Math.PI / 2;
  roadV.position.y = 0.01;
  scene.add(roadV);
}

function createRoadTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#333';
  ctx.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 10; i++) {
    ctx.fillStyle = '#666';
    ctx.fillRect(0, i * 25, 256, 5);
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(4, 4);
  return texture;
}

function createBuildings() {
  const buildings = [
    { x: -200, z: -200, w: 60, h: 150, d: 60, color: 0x2a5f8f },
    { x: -200, z: 0, w: 50, h: 180, d: 50, color: 0x1f4e78 },
    { x: -200, z: 200, w: 70, h: 140, d: 70, color: 0x3a7ca5 },
    { x: 0, z: -220, w: 80, h: 200, d: 80, color: 0x2a5f8f },
    { x: 0, z: 220, w: 75, h: 190, d: 75, color: 0x1f4e78 },
    { x: 200, z: -200, w: 65, h: 160, d: 65, color: 0x3a7ca5 },
    { x: 200, z: 0, w: 70, h: 170, d: 70, color: 0x2a5f8f },
    { x: 200, z: 200, w: 60, h: 150, d: 60, color: 0x1f4e78 },
  ];

  buildings.forEach(b => {
    const geometry = new THREE.BoxGeometry(b.w, b.h, b.d);
    const material = new THREE.MeshLambertMaterial({ color: b.color });
    const building = new THREE.Mesh(geometry, material);
    building.position.set(b.x, b.h / 2, b.z);
    building.castShadow = true;
    building.receiveShadow = true;
    scene.add(building);

    for (let i = 0; i < b.h / 20; i++) {
      for (let j = 0; j < 3; j++) {
        const windowGeo = new THREE.BoxGeometry(8, 8, 2);
        const windowMat = new THREE.MeshLambertMaterial({
          color: Math.random() > 0.5 ? 0xffff00 : 0x444444,
        });
        const window = new THREE.Mesh(windowGeo, windowMat);
        window.position.set(
          b.x - b.w / 2 + 15 + j * 20,
          20 + i * 20,
          b.z + b.d / 2
        );
        window.castShadow = true;
        scene.add(window);
      }
    }
  });
}

function createForge() {
  const centerX = 0;
  const centerZ = 0;

  const groundGeo = new THREE.CylinderGeometry(80, 80, 5, 32);
  const groundMat = new THREE.MeshLambertMaterial({ color: 0x8b4513 });
  const ground = new THREE.Mesh(groundGeo, groundMat);
  ground.position.set(centerX, 2.5, centerZ);
  ground.castShadow = true;
  ground.receiveShadow = true;
  scene.add(ground);

  const anvilGeometry = new THREE.BoxGeometry(25, 15, 35);
  const anvilMaterial = new THREE.MeshLambertMaterial({ color: 0x333333 });
  const anvil = new THREE.Mesh(anvilGeometry, anvilMaterial);
  anvil.position.set(centerX, 20, centerZ);
  anvil.castShadow = true;
  anvil.receiveShadow = true;
  scene.add(anvil);
  scene.userData.anvil = anvil;

  const hammerGeometry = new THREE.BoxGeometry(8, 8, 20);
  const hammerMaterial = new THREE.MeshLambertMaterial({ color: 0x555555 });
  const hammer = new THREE.Mesh(hammerGeometry, hammerMaterial);
  hammer.position.set(centerX + 30, 40, centerZ);
  hammer.castShadow = true;
  hammer.receiveShadow = true;
  scene.add(hammer);
  scene.userData.hammer = hammer;

  const firePlaneGeo = new THREE.PlaneGeometry(30, 20);
  const fireCanvas = createFireTexture();
  const fireMat = new THREE.MeshLambertMaterial({ map: fireCanvas, emissive: 0xff6600 });
  const firePlane = new THREE.Mesh(firePlaneGeo, fireMat);
  firePlane.position.set(centerX, 25, centerZ - 20);
  scene.add(firePlane);
  scene.userData.fireTexture = fireCanvas;
}

function createFireTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  return new THREE.CanvasTexture(canvas);
}

function updateFireTexture(time) {
  if (!scene.userData.fireTexture) return;
  const canvas = scene.userData.fireTexture.image;
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < 30; i++) {
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height + Math.sin(time + i) * 20;
    const r = Math.floor(255 * Math.sin(time + i) * 0.5 + 0.5);
    ctx.fillStyle = `rgba(255, ${Math.floor(100 + r / 2)}, 0, 0.3)`;
    ctx.beginPath();
    ctx.arc(x, y, Math.random() * 10 + 5, 0, Math.PI * 2);
    ctx.fill();
  }
  scene.userData.fireTexture.needsUpdate = true;
}

function createForestAndStreetlamps() {
  const positions = [
    { x: -300, z: -300 },
    { x: 300, z: -300 },
    { x: -300, z: 300 },
    { x: 300, z: 300 },
    { x: -150, z: -350 },
    { x: 150, z: -350 },
    { x: -350, z: -150 },
    { x: -350, z: 150 },
  ];

  positions.forEach(pos => {
    createTree(pos.x, pos.z);
    createStreetlamp(pos.x, pos.z);
  });
}

function createTree(x, z) {
  const trunkGeo = new THREE.CylinderGeometry(8, 12, 40, 8);
  const trunkMat = new THREE.MeshLambertMaterial({ color: 0x5d4e37 });
  const trunk = new THREE.Mesh(trunkGeo, trunkMat);
  trunk.position.set(x, 20, z);
  trunk.castShadow = true;
  trunk.receiveShadow = true;
  scene.add(trunk);

  const foliageGeo = new THREE.SphereGeometry(35, 8, 8);
  const foliageMat = new THREE.MeshLambertMaterial({ color: 0x2d5016 });
  const foliage = new THREE.Mesh(foliageGeo, foliageMat);
  foliage.position.set(x, 60, z);
  foliage.castShadow = true;
  foliage.receiveShadow = true;
  scene.add(foliage);
}

function createStreetlamp(x, z) {
  const poleGeo = new THREE.CylinderGeometry(3, 3, 60, 8);
  const poleMat = new THREE.MeshLambertMaterial({ color: 0x333333 });
  const pole = new THREE.Mesh(poleGeo, poleMat);
  pole.position.set(x, 30, z);
  pole.castShadow = true;
  scene.add(pole);

  const lampGeo = new THREE.SphereGeometry(8, 8, 8);
  const lampMat = new THREE.MeshLambertMaterial({
    color: 0xffff00,
    emissive: 0xffff00,
  });
  const lamp = new THREE.Mesh(lampGeo, lampMat);
  lamp.position.set(x, 65, z);
  lamp.castShadow = true;
  scene.add(lamp);

  const light = new THREE.PointLight(0xffff00, 1, 150);
  light.position.set(x, 65, z);
  light.castShadow = true;
  scene.add(light);
}

function createCat(x, z) {
  const cat = {
    group: new THREE.Group(),
    velocity: {
      x: (Math.random() - 0.5) * 2,
      z: (Math.random() - 0.5) * 2,
    },
    position: { x, z },
    animation: {
      jumpPhase: 0,
      jumpHeight: 0,
      movePhase: Math.random() * Math.PI * 2,
    },
  };

  const bodyGeo = new THREE.SphereGeometry(8, 8, 8);
  const bodyMat = new THREE.MeshLambertMaterial({ color: 0xff69b4 });
  const body = new THREE.Mesh(bodyGeo, bodyMat);
  body.scale.set(1, 1.3, 1);
  body.position.y = 8;
  body.castShadow = true;
  body.receiveShadow = true;
  cat.group.add(body);
  cat.body = body;

  const headGeo = new THREE.SphereGeometry(6, 8, 8);
  const headMat = new THREE.MeshLambertMaterial({ color: 0xff1493 });
  const head = new THREE.Mesh(headGeo, headMat);
  head.position.set(0, 16, 0);
  head.castShadow = true;
  head.receiveShadow = true;
  cat.group.add(head);
  cat.head = head;

  const ear1Geo = new THREE.ConeGeometry(3, 8, 8);
  const ear1Mat = new THREE.MeshLambertMaterial({ color: 0xff69b4 });
  const ear1 = new THREE.Mesh(ear1Geo, ear1Mat);
  ear1.position.set(-3, 22, 0);
  ear1.rotation.z = -0.3;
  ear1.castShadow = true;
  cat.group.add(ear1);

  const ear2 = new THREE.Mesh(ear1Geo, ear1Mat);
  ear2.position.set(3, 22, 0);
  ear2.rotation.z = 0.3;
  ear2.castShadow = true;
  cat.group.add(ear2);

  const eyeGeo = new THREE.SphereGeometry(1.5, 8, 8);
  const eyeMat = new THREE.MeshLambertMaterial({ color: 0x00ff00, emissive: 0x00ff00 });
  const eye1 = new THREE.Mesh(eyeGeo, eyeMat);
  eye1.position.set(-2, 17, 6);
  cat.group.add(eye1);

  const eye2 = new THREE.Mesh(eyeGeo, eyeMat);
  eye2.position.set(2, 17, 6);
  cat.group.add(eye2);

  const tailGeo = new THREE.CylinderGeometry(2, 1.5, 15, 6);
  const tailMat = new THREE.MeshLambertMaterial({ color: 0xff69b4 });
  const tail = new THREE.Mesh(tailGeo, tailMat);
  tail.position.set(0, 10, -10);
  tail.rotation.x = 0.5;
  tail.castShadow = true;
  cat.group.add(tail);
  cat.tail = tail;

  cat.group.position.set(x, 0, z);
  scene.add(cat.group);
  state.cats.push(cat);

  return cat;
}

function updateCats(time) {
  state.cats.forEach((cat, index) => {
    cat.animation.movePhase += 0.02;
    cat.position.x += cat.velocity.x;
    cat.position.z += cat.velocity.z;

    const distance = Math.sqrt(
      cat.position.x * cat.position.x + cat.position.z * cat.position.z
    );
    if (distance > 350) {
      cat.velocity.x *= -1;
      cat.velocity.z *= -1;
    }

    cat.animation.jumpPhase += 0.15;
    if (cat.animation.jumpPhase > Math.PI * 2) {
      cat.animation.jumpPhase = 0;
    }

    const jumpCycle = Math.sin(cat.animation.jumpPhase);
    if (jumpCycle < 0) {
      cat.animation.jumpHeight = 0;
    } else {
      cat.animation.jumpHeight = jumpCycle * 15;
    }

    cat.group.position.x = cat.position.x;
    cat.group.position.z = cat.position.z;
    cat.group.position.y = cat.animation.jumpHeight;

    const angle = Math.atan2(cat.velocity.z, cat.velocity.x);
    cat.group.rotation.y = angle - Math.PI / 2;

    cat.tail.rotation.z = Math.sin(time * 0.05 + index) * 0.5;
    cat.head.rotation.z = Math.sin(time * 0.04 + index) * 0.2;
  });

  if (state.cats.length > 0 && state.activeCameraMode === 'follow-cat') {
    const followCat = state.cats[state.followCatIndex % state.cats.length];
    if (followCat) {
      camera.position.x = followCat.position.x + 50;
      camera.position.y = 40;
      camera.position.z = followCat.position.z + 50;
      camera.lookAt(
        followCat.position.x,
        followCat.animation.jumpHeight + 10,
        followCat.position.z
      );
    }
  }
}

function strikeAnvil() {
  state.forgeEnergy = 1;
  const hammer = scene.userData.hammer;
  const originalY = 40;

  const duration = 300;
  const startTime = Date.now();

  function animateStrike() {
    const elapsed = Date.now() - startTime;
    const progress = Math.min(elapsed / duration, 1);

    if (progress < 0.3) {
      hammer.position.y = originalY + progress / 0.3 * 20;
    } else if (progress < 0.6) {
      const t = (progress - 0.3) / 0.3;
      hammer.position.y = originalY + 20 - t * 20;
    } else {
      hammer.position.y = originalY;
    }

    if (progress < 1) {
      requestAnimationFrame(animateStrike);
    }
  }

  animateStrike();

  for (let i = 0; i < 15; i++) {
    const spark = createSpark();
    spark.position.copy(scene.userData.anvil.position);
    spark.userData.velocity = new THREE.Vector3(
      (Math.random() - 0.5) * 3,
      Math.random() * 2 + 2,
      (Math.random() - 0.5) * 3
    );
    spark.userData.life = 1;
    spark.userData.maxLife = 1;
    scene.add(spark);
    if (!scene.userData.sparks) scene.userData.sparks = [];
    scene.userData.sparks.push(spark);
  }
}

function createSpark() {
  const geo = new THREE.SphereGeometry(1.5, 6, 6);
  const mat = new THREE.MeshLambertMaterial({
    color: 0xffa500,
    emissive: 0xff6600,
  });
  return new THREE.Mesh(geo, mat);
}

function updateSparks(deltaTime) {
  if (!scene.userData.sparks) return;

  scene.userData.sparks = scene.userData.sparks.filter(spark => {
    spark.userData.life -= deltaTime / 1000;

    spark.position.add(
      spark.userData.velocity.clone().multiplyScalar(deltaTime / 1000)
    );
    spark.userData.velocity.y -= 9.8 * (deltaTime / 1000);

    const alpha = spark.userData.life / spark.userData.maxLife;
    spark.material.opacity = alpha;
    spark.material.transparent = true;

    if (spark.userData.life <= 0) {
      scene.remove(spark);
      return false;
    }
    return true;
  });
}

function setAtmosphere(mode) {
  state.atmosphereMode = mode;
  const skyColor = { night: 0x0a0a1a, gold: 0x4a3a0a, day: 0x87ceeb };
  const ambientIntensity = { night: 0.3, gold: 0.6, day: 0.9 };

  scene.background = new THREE.Color(skyColor[mode]);
  scene.getObjectByProperty('type', 'AmbientLight').intensity =
    ambientIntensity[mode];

  const dirLight = scene.getObjectByProperty('type', 'DirectionalLight');
  if (dirLight) {
    dirLight.color.set(
      mode === 'gold' ? 0xffa500 : mode === 'day' ? 0xffffff : 0x6666ff
    );
  }
}

function updateCamera() {
  const modes = {
    overview: () => {
      camera.position.x = 150 * Math.cos(state.cameraRotation);
      camera.position.y = 200;
      camera.position.z = 150 * Math.sin(state.cameraRotation);
      camera.lookAt(0, 50, 0);
    },
    isometric: () => {
      camera.position.x = 200;
      camera.position.y = 200;
      camera.position.z = 200;
      camera.lookAt(0, 50, 0);
    },
    street: () => {
      camera.position.x = 0;
      camera.position.y = 30;
      camera.position.z = -150;
      camera.lookAt(0, 40, 50);
    },
  };

  if (modes[state.activeCameraMode]) {
    modes[state.activeCameraMode]();
  }
}

function initUI() {
  document.getElementById('btn-spawn-cat').addEventListener('click', () => {
    const x = (Math.random() - 0.5) * 200;
    const z = (Math.random() - 0.5) * 200;
    createCat(x, z);
    updateHUD();
  });

  document.getElementById('btn-forge-strike').addEventListener('click', strikeAnvil);

  document.getElementById('cam-overview').addEventListener('click', () => {
    state.activeCameraMode = 'overview';
    updateHUD();
  });

  document.getElementById('cam-iso').addEventListener('click', () => {
    state.activeCameraMode = 'isometric';
    updateHUD();
  });

  document.getElementById('cam-street').addEventListener('click', () => {
    state.activeCameraMode = 'street';
    updateHUD();
  });

  document.getElementById('cam-follow-cat').addEventListener('click', () => {
    if (state.cats.length > 0) {
      state.activeCameraMode = 'follow-cat';
      state.followCatIndex = Math.floor(Math.random() * state.cats.length);
      updateHUD();
    }
  });

  document.getElementById('mode-night').addEventListener('click', () => {
    setAtmosphere('night');
  });

  document.getElementById('mode-gold').addEventListener('click', () => {
    setAtmosphere('gold');
  });

  document.getElementById('mode-day').addEventListener('click', () => {
    setAtmosphere('day');
  });

  document.getElementById('toggle-spin').addEventListener('click', (e) => {
    state.isPaused = !state.isPaused;
    e.target.textContent = state.isPaused ? '▶ Resume' : '⏸ Pause';
  });
}

function updateHUD() {
  const cameraModes = {
    overview: 'Overview',
    isometric: 'Isometric',
    street: 'Street',
    'follow-cat': 'Follow Cat',
  };
  document.getElementById('cat-count').textContent = state.cats.length;
  document.getElementById('cam-mode').textContent =
    cameraModes[state.activeCameraMode] || 'Unknown';
}

function setupWindowExport() {
  window.__app = {
    scene,
    camera,
    renderer,
    state,
  };
}

let lastFrameTime = Date.now();
let frameCount = 0;
let lastFpsUpdateTime = Date.now();

function animate() {
  requestAnimationFrame(animate);

  const currentTime = Date.now();
  const deltaTime = currentTime - lastFrameTime;
  lastFrameTime = currentTime;
  frameCount++;

  if (!state.isPaused) {
    state.cameraRotation += 0.0005;
    state.time += 0.016;
  }

  updateCamera();
  updateCats(state.time);
  updateFireTexture(state.time);
  updateSparks(deltaTime);

  renderer.render(scene, camera);

  if (currentTime - lastFpsUpdateTime >= 1000) {
    document.getElementById('fps-value').textContent = frameCount;
    frameCount = 0;
    lastFpsUpdateTime = currentTime;
  }
}

function onWindowResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
}

init();


