    // Tail - multi-segment with wagging
    const tailSegments = 5;
    for (let i = 0; i < tailSegments; i++) {
      const tailGeom = new THREE.SphereGeometry(0.25 - i * 0.03, 8, 8);
      const tailMat = new THREE.MeshStandardMaterial({
        color: 0xffe0b2,
        roughness: 0.7,
        metalness: 0.0
      });
