  update(deltaTime) {
    // Trotting/hopping locomotion
    this.walkPhase += this.walkSpeed;

    if (this.trotting) {
      // Leg animation - trotting gait
      const legPhase = (this.walkPhase % (Math.PI * 2)) / (Math.PI * 2);

      this.legs.forEach((leg, idx) => {
        const phase = (legPhase + (idx % 2) * 0.5) % 1.0;
        const legBend = Math.sin(phase * Math.PI) * 0.4;
        leg.upperLeg.rotation.x = -legBend;
        leg.lowerLeg.rotation.x = legBend * 1.5;
      });

      // Hop animation trigger
      this.hopTimer += deltaTime;
      if (this.hopTimer > 1.5) {
        this.hopTimer = 0;
        this.hopDuration = 0.4;
      }

      // Vertical hop bounce
      const hopAmount = Math.sin((this.hopTimer / this.hopDuration) * Math.PI) * 0.3;
      if (this.hopTimer < this.hopDuration) {
        this.group.position.y += hopAmount * 0.1;
      }

      // Move forward in direction
      const moveAmount = this.walkSpeed * deltaTime * this.speed;
      this.group.position.add(this.direction.clone().multiplyScalar(moveAmount));

      // Rotate direction occasionally
      if (Math.random() < 0.01) {
        const newAngle = Math.random() * Math.PI * 2;
        this.direction.set(Math.cos(newAngle), 0, Math.sin(newAngle));
      }
    }

    // Tail wagging
    this.tail.forEach((segment, idx) => {
      const wag = Math.sin(this.walkPhase + idx * 0.3) * 0.3;
      segment.rotation.z = wag;
    });

    // Ear wiggle
    this.ears.forEach((ear, idx) => {
      const wiggle = Math.sin(this.walkPhase * 2 + idx) * 0.1;
      ear.rotation.x = wiggle;
    });

    // Random blinking eyes
    if (Math.random() < 0.02) {
      this.eyes.forEach(eye => {
        eye.scale.y = 0.1;
      });
    } else {
      this.eyes.forEach(eye => {
        eye.scale.y = Math.max(0.1, eye.scale.y + 0.1);
      });
    }
  }

  jumpAndBackflip() {
    // Quick jump + rotation animation
    this.group.position.y += 2.0;
    this.group.rotation.x += Math.PI * 2;
  }
}

export class MoruCatManager {
  constructor() {
    this.cats = [];
    this.group = new THREE.Group();
  }

  spawnCat(position = null) {
    let spawnPos = position;
    if (!position) {
      spawnPos = new THREE.Vector3(
        (Math.random() - 0.5) * 100,
        0,
        (Math.random() - 0.5) * 100
      );
    }

    const cat = new MoruCat(spawnPos);
    this.cats.push(cat);
    this.group.add(cat.group);
    return cat;
  }

  spawnMultiple(count, position = null) {
    for (let i = 0; i < count; i++) {
      let offset = null;
      if (position) {
        offset = position.clone().add(
          new THREE.Vector3(
            (Math.random() - 0.5) * 10,
            0,
            (Math.random() - 0.5) * 10
          )
        );
      }
      this.spawnCat(offset);
    }
  }

  update(deltaTime) {
    this.cats.forEach(cat => {
      cat.update(deltaTime);
    });
  }

  exciteCats() {
    this.cats.forEach(cat => {
      cat.jumpAndBackflip();
    });
  }

  getActiveCat() {
    return this.cats.length > 0 ? this.cats[0] : null;
  }
}


