import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';

import { createCityScene } from './world/city.js';
import { createForgeScene, MoruForge } from './world/forge.js';
import { MoruCatManager } from './entities/moruCat.js';

// Global app state
const state = {
  spinning: true,
  theme: 'night',
  catCount: 0,
  buildingCount: 0,
  lampCount: 0,
  triangleCount: 0,
  forgeStrikes: 0,
  disposedCount: 0,
  frameCount: 0,
  fps: 0,
  cameraMode: 'overview'
};

let canvas, renderer, composer, camera, controls;
let scene, cityGroup, forge, catManager;
let lastFrameTime = Date.now();
let frameCounter = 0;
let fpsUpdateTime = 0;

// Camera presets
const cameraPresets = {
  overview: {
    position: new THREE.Vector3(42, 30, 46),
    target: new THREE.Vector3(0, 3.5, 0)
  },
  iso: {
    position: new THREE.Vector3(100, 80, 100),
    target: new THREE.Vector3(0, 3.5, 0)
  },
  street: {
    position: new THREE.Vector3(0, 5, -50),
    target: new THREE.Vector3(0, 3.5, 0)
  }
};

function initRenderer() {
  canvas = document.getElementById('studio-canvas');

  const width = window.innerWidth || 1280;
  const height = window.innerHeight || 800;

  renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: true,
    preserveDrawingBuffer: true
  });

  renderer.setSize(width, height);
  renderer.setPixelRatio(1);
  renderer.shadowMap.enabled = false;
  renderer.toneMapping = THREE.ReinhardToneMapping;
  renderer.toneMappingExposure = 1.15;

  window.addEventListener('resize', onWindowResize);
}

function initPostProcessing() {
  const width = window.innerWidth || 1280;
  const height = window.innerHeight || 800;

  composer = new EffectComposer(renderer);
  const renderPass = new RenderPass(scene, camera);
  composer.addPass(renderPass);

  const bloomPass = new UnrealBloomPass(
    new THREE.Vector2(width, height),
    0.85,  // strength
    0.4,   // radius
    0.25   // threshold
  );
  composer.addPass(bloomPass);
}

function initScene() {
  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x000000);
  scene.fog = new THREE.FogExp2(0x0a1022, 0.0045);

  // Create composite scene: city + forge + cats
  const { scene: cityScene, city } = createCityScene();
  const { scene: forgeScene, forge: forgeInstance } = createForgeScene();

  // Add entire scenes
  scene.add(cityScene);
  scene.add(forgeScene);

  forge = forgeInstance;

  // Add cats to scene
  catManager = new MoruCatManager();
  catManager.spawnMultiple(6, new THREE.Vector3(0, 0, 0));
  scene.add(catManager.group);

  // Count geometry for stats
  countGeometry();

  // Add lights that weren't in subscenes
  const ambientLight = new THREE.AmbientLight(0xffffff, 1.2);
  scene.add(ambientLight);
}

function initCamera() {
  const width = window.innerWidth || 1280;
  const height = window.innerHeight || 800;

  camera = new THREE.PerspectiveCamera(
    75,
    width / height,
    0.1,
    1000
  );

  camera.position.copy(cameraPresets.overview.position);
  camera.lookAt(cameraPresets.overview.target);

  // OrbitControls
  controls = new OrbitControls(camera, renderer.domElement);
  controls.enableRotate = true;
  controls.enableZoom = true;
  controls.enablePan = true;
  controls.autoRotate = true;
  controls.autoRotateSpeed = 3.5;
  controls.target.set(0, 3.5, 0);
  controls.update();
}

function countGeometry() {
  let triangles = 0;
  let buildings = 0;
  let lamps = 0;

  scene.traverse(obj => {
    if (obj.isMesh && obj.geometry) {
      if (obj.geometry.index) {
        triangles += obj.geometry.index.count / 3;
      } else if (obj.geometry.attributes.position) {
        triangles += obj.geometry.attributes.position.count / 3;
      }

      // Count buildings by name or material
      if (obj.material && obj.material.map) {
        buildings++;
      }
    }

    // Count cats
    if (obj.userData && obj.userData.isMoruCat) {
      // Counted in catManager.cats.length
    }
  });

  state.buildingCount = Math.floor(buildings / 2); // Rough estimate
  state.lampCount = Math.floor(scene.children.filter(c => c.isLight && c.type === 'PointLight').length);
  state.triangleCount = Math.floor(triangles);
  state.catCount = catManager.cats.length;
}

function setupUI() {
  // Camera buttons
  document.getElementById('cam-overview').addEventListener('click', () => {
    state.cameraMode = 'overview';
    animateCamera(cameraPresets.overview);
  });

  document.getElementById('cam-iso').addEventListener('click', () => {
    state.cameraMode = 'iso';
    animateCamera(cameraPresets.iso);
  });

  document.getElementById('cam-street').addEventListener('click', () => {
    state.cameraMode = 'street';
    animateCamera(cameraPresets.street);
  });

  document.getElementById('cam-follow-cat').addEventListener('click', () => {
    state.cameraMode = 'follow';
  });

  // Action buttons
  document.getElementById('btn-spawn-cat').addEventListener('click', () => {
    catManager.spawnCat();
    state.catCount++;
  });

  document.getElementById('btn-forge-strike').addEventListener('click', () => {
    forge.strikeForge();
    catManager.exciteCats();
    state.forgeStrikes++;
  });

  // Theme buttons
  document.getElementById('mode-night').addEventListener('click', () => {
    setTheme('night');
  });

  document.getElementById('mode-gold').addEventListener('click', () => {
    setTheme('gold');
  });

  document.getElementById('mode-day').addEventListener('click', () => {
    setTheme('day');
  });

  // Photo freeze toggle
  document.getElementById('toggle-spin').addEventListener('click', () => {
    state.spinning = !state.spinning;
    controls.autoRotate = state.spinning;
    if (!state.spinning) {
      composer.render();
    }
  });
}

function animateCamera(preset) {
  camera.position.copy(preset.position);
  controls.target.copy(preset.target);
  controls.update();
}

function setTheme(themeName) {
  state.theme = themeName;
  state.disposedCount++;

  // Update material exposures and fog
  switch (themeName) {
    case 'night':
      renderer.toneMappingExposure = 1.15;
      scene.fog.color.setHex(0x182442);
      scene.background.setHex(0x14203c);
      break;
    case 'gold':
      renderer.toneMappingExposure = 1.05;
      scene.fog.color.setHex(0x3a2818);
      scene.background.setHex(0x322214);
      break;
    case 'day':
      renderer.toneMappingExposure = 1.0;
      scene.fog.color.setHex(0x8899cc);
      scene.background.setHex(0x4488bb);
      break;
  }

  // Update URL with theme parameter
  const url = new URL(window.location);
  url.searchParams.set('theme', themeName);
  window.history.replaceState({}, '', url);
}

function updateHUD() {
  const now = Date.now();
  const deltaTime = (now - lastFrameTime) / 1000;
  lastFrameTime = now;

  frameCounter++;
  fpsUpdateTime += deltaTime;

  if (fpsUpdateTime >= 0.2) {
    state.fps = Math.round(frameCounter / fpsUpdateTime);
    frameCounter = 0;
    fpsUpdateTime = 0;
  }

  state.frameCount++;

  // Update HUD display
  if (state.spinning) {
    document.getElementById('fps-hud').textContent =
      `FPS: ${state.fps} | Cats: ${state.catCount} | Buildings: ${Math.floor(state.buildingCount)} | Lamps: ${state.lampCount} | Tris: ${(state.triangleCount / 1000).toFixed(1)}k | Frame: ${state.frameCount}`;
  }
}

function updateAnimation(deltaTime) {
  if (!state.spinning) return;

  // Update cats
  catManager.update(deltaTime);

  // Update forge
  forge.updateForge(deltaTime);

  // Animate ambient embers in forge scene
  scene.traverse(obj => {
    if (obj.floatSpeed) {
      obj.floatY += obj.floatSpeed;
      const baseY = obj.position.y;
      obj.position.y = baseY + Math.sin(obj.floatY) * 2;
    }
  });

  // Update camera follow mode
  if (state.cameraMode === 'follow') {
    const activeCat = catManager.getActiveCat();
    if (activeCat) {
      const targetPos = activeCat.group.position.clone().add(new THREE.Vector3(15, 10, 15));
      camera.position.lerp(targetPos, 0.05);
      controls.target.lerp(activeCat.group.position, 0.05);
    }
  }
}

function animate() {
  requestAnimationFrame(animate);

  if (state.spinning) {
    controls.update();
    const deltaTime = Math.min((Date.now() - lastFrameTime) / 1000, 0.1);
    updateAnimation(deltaTime);
    updateHUD();
  }

  // Render with post-processing
  composer.render();
}

function onWindowResize() {
  const width = canvas.clientWidth;
  const height = canvas.clientHeight;

  camera.aspect = width / height;
  camera.updateProjectionMatrix();

  renderer.setSize(width, height);
  composer.setSize(width, height);
}

function main() {
  try {
    initRenderer();
    initScene();
    initCamera();
    initPostProcessing();
    setupUI();

    // Load theme from URL parameter if present
    const params = new URLSearchParams(window.location.search);
    const themeParam = params.get('theme') || 'night';
    setTheme(themeParam);

    // Expose global app object
    window.__app = {
      scene,
      camera,
      renderer,
      composer,
      state
    };

    animate();
  } catch (error) {
    console.error('Application initialization failed:', error);
  }
}

main();


