    });

    // Horizontal roads
    for (let z = -150; z <= 150; z += 80) {
      const roadGeom = new THREE.PlaneGeometry(300, 15);
      const road = new THREE.Mesh(roadGeom, roadMaterial);
      road.rotation.x = -Math.PI / 2;
      road.position.set(0, 0.05, z);
      road.receiveShadow = true;
      this.group.add(road);
      this.roads.push(road);
    }

    // Vertical roads
    for (let x = -150; x <= 150; x += 80) {
      const roadGeom = new THREE.PlaneGeometry(15, 300);
      const road = new THREE.Mesh(roadGeom, roadMaterial);
      road.rotation.x = -Math.PI / 2;
      road.position.set(x, 0.05, 0);
      road.receiveShadow = true;
      this.group.add(road);
      this.roads.push(road);
    }
  }

  createBuildingCluster() {
    const windowTexture = createWindowTexture(512, 512);
    windowTexture.magFilter = THREE.NearestFilter;
    windowTexture.minFilter = THREE.NearestFilter;

    this.sharedBuildingMat = new THREE.MeshStandardMaterial({
      map: windowTexture,
      roughness: 0.8,
      metalness: 0.1
    });
    this.sharedTrimMats = [0x00ffff, 0xff00ff, 0xffaa00, 0x00ff88].map(c => new THREE.MeshStandardMaterial({
      color: c,
      emissive: c,
      emissiveIntensity: 0.8,
      roughness: 0.2,
      metalness: 0.9
    }));
    this.sharedSpireMat = new THREE.MeshStandardMaterial({
      color: 0xff0080,
      emissive: 0xff0080,
      emissiveIntensity: 0.6,
      roughness: 0.3,
      metalness: 0.8
    });
    this.sharedHelipadMat = new THREE.MeshStandardMaterial({
      color: 0xff3300,
      roughness: 0.6,
      metalness: 0.5
    });
    this.sharedHMat = new THREE.MeshStandardMaterial({ color: 0xffffff });

    const gridSpacing = 55;
    const buildingCount = { total: 0 };

    // Avoid central plaza (radius < 35)
    for (let z = -165; z <= 165; z += gridSpacing) {
      for (let x = -165; x <= 165; x += gridSpacing) {
        if (Math.hypot(x, z) < 35) continue; // Skip central plaza

        this.createBuilding(x, z, windowTexture, buildingCount);
      }
    }
  }

  createBuilding(baseX, baseZ, windowTexture, counter) {
    // Vary height and width for visual richness
    const heights = [25, 32, 40, 45, 50, 55, 60, 70, 75, 85, 95];
    const height = heights[counter.total % heights.length];
    const widthOptions = [12, 14, 16, 18, 20];
    const width = widthOptions[counter.total % widthOptions.length];
    const depth = widthOptions[(counter.total + 2) % widthOptions.length];

    // Main building block
    const buildingGeom = new THREE.BoxGeometry(width, height, depth, 2, 4, 2);
    const building = new THREE.Mesh(buildingGeom, this.sharedBuildingMat);
    building.position.set(baseX, height / 2, baseZ);
    this.group.add(building);
    this.buildings.push(building);
    counter.total++;

    // Rooftop neon trim frame
    const trimMat = this.sharedTrimMats[counter.total % this.sharedTrimMats.length];
    const frameBox = new THREE.Mesh(new THREE.BoxGeometry(width + 0.6, 0.6, depth + 0.6), trimMat);
    frameBox.position.set(baseX, height + 0.3, baseZ);
