    if (counter.total % 2 === 0) {
      const spireHeight = 12;
      const spireGeom = new THREE.ConeGeometry(1.5, spireHeight, 8);
      const spire = new THREE.Mesh(spireGeom, this.sharedSpireMat);
      spire.position.set(baseX, height + spireHeight / 2, baseZ);
      this.group.add(spire);
    } else {
      const helipadGeom = new THREE.CircleGeometry(5, 12);
      const helipad = new THREE.Mesh(helipadGeom, this.sharedHelipadMat);
      helipad.position.set(baseX, height + 0.4, baseZ);
      helipad.rotation.x = -Math.PI / 2;
      this.group.add(helipad);

      const hGeom = new THREE.PlaneGeometry(2, 2);
      const hMesh = new THREE.Mesh(hGeom, this.sharedHMat);
      hMesh.position.set(baseX, height + 0.45, baseZ);
      hMesh.rotation.x = -Math.PI / 2;
      this.group.add(hMesh);
    }
  }

  createTreescape() {
    this.sharedTrunkGeom = new THREE.CylinderGeometry(1.0, 1.5, 6, 6);
    this.sharedTrunkMat = new THREE.MeshStandardMaterial({
      color: 0x3a2f1f,
