  createTree(x, z) {
    const trunk = new THREE.Mesh(this.sharedTrunkGeom, this.sharedTrunkMat);
    trunk.position.set(x, 3, z);
    this.group.add(trunk);
    this.trees.push(trunk);

    const foliage = new THREE.Mesh(this.sharedFoliageGeom, this.sharedFoliageMat);
    foliage.position.set(x, 8.5, z);
    this.group.add(foliage);
    this.trees.push(foliage);
  }

  createStreetlighting() {
    this.sharedPoleGeom = new THREE.CylinderGeometry(0.3, 0.4, 6, 6);
    this.sharedPoleMat = new THREE.MeshStandardMaterial({
      color: 0x1a1a2a,
      roughness: 0.6,
      metalness: 0.7
    });
    this.sharedHeadGeom = new THREE.SphereGeometry(0.6, 8, 8);
    this.sharedHeadMat = new THREE.MeshStandardMaterial({
      color: 0x3a3a4a,
      roughness: 0.5,
      metalness: 0.8
    });
    this.sharedBulbGeom = new THREE.SphereGeometry(0.4, 8, 8);
    this.sharedBulbMat = new THREE.MeshStandardMaterial({
      color: 0xffdd00,
      emissive: 0xffaa00,
      emissiveIntensity: 1.2,
      roughness: 0.1,
      metalness: 0.0
    });
    this.sharedPoolGeom = new THREE.CircleGeometry(4.5, 12);
    this.sharedPoolMat = new THREE.MeshStandardMaterial({
      color: 0xffdd00,
      emissive: 0xffdd00,
      emissiveIntensity: 0.4,
      roughness: 0.9,
      metalness: 0.0
    });

    const lampSpacing = 50;

    // Along horizontal roads
    for (let z = -150; z <= 150; z += 80) {
      for (let x = -150; x <= 150; x += lampSpacing) {
        this.createStreetlamp(x, z - 12);
        this.createStreetlamp(x, z + 12);
      }
    }
  }

  createStreetlamp(x, z) {
    const group = new THREE.Group();
    group.position.set(x, 0, z);

    const pole = new THREE.Mesh(this.sharedPoleGeom, this.sharedPoleMat);
    pole.position.y = 3;
    group.add(pole);

    const head = new THREE.Mesh(this.sharedHeadGeom, this.sharedHeadMat);
    head.position.y = 6;
    group.add(head);

    const bulb = new THREE.Mesh(this.sharedBulbGeom, this.sharedBulbMat);
    bulb.position.y = 6;
    group.add(bulb);

    const pool = new THREE.Mesh(this.sharedPoolGeom, this.sharedPoolMat);
    pool.rotation.x = -Math.PI / 2;
    pool.position.y = 0.05;
    group.add(pool);

    this.group.add(group);
    this.streetlamps.push(group);
  }
