      emissiveIntensity: 0.7,
      roughness: 0.3,
      metalness: 0.6
    });
    const ingot = new THREE.Mesh(ingotGeom, ingotMat);
    ingot.position.set(0, 8.2, -10);
    ingot.castShadow = true;
    this.group.add(ingot);
  }

  createForgeHammer() {
    // Store hammer reference for animation
    this.hammerGroup = new THREE.Group();
    this.hammerGroup.position.set(-8, 8, -10);

    // Hammer handle
    const handleGeom = new THREE.CylinderGeometry(0.4, 0.5, 8, 8);
    const handleMat = new THREE.MeshStandardMaterial({
      color: 0x5a4a3a,
      roughness: 0.8,
      metalness: 0.2
    });
    const handle = new THREE.Mesh(handleGeom, handleMat);
    handle.position.y = 0;
    handle.castShadow = true;
    this.hammerGroup.add(handle);

    // Hammer head
    const headGeom = new THREE.BoxGeometry(3.5, 2, 2);
    const headMat = new THREE.MeshStandardMaterial({
      color: 0x1a1a2a,
      roughness: 0.4,
      metalness: 0.9
    });
    const head = new THREE.Mesh(headGeom, headMat);
    head.position.set(0, 4.5, 0);
    head.castShadow = true;
    this.hammerGroup.add(head);

    // Hammer face (striking surface)
    const faceGeom = new THREE.BoxGeometry(3, 1.5, 1.8);
    const faceMat = new THREE.MeshStandardMaterial({
      color: 0x0a0a1a,
      roughness: 0.3,
      metalness: 0.95
    });
    const face = new THREE.Mesh(faceGeom, faceMat);
    face.position.set(0, 4.5, 0);
    face.castShadow = true;
    this.hammerGroup.add(face);

    this.group.add(this.hammerGroup);
  }

  strikeForge() {
    if (this.isStriking) return;
    this.isStriking = true;
    this.strikeProgress = 0;
  }

  updateForge(deltaTime) {
    if (this.isStriking) {
      this.strikeProgress += deltaTime * 3; // Strike speed

      if (this.strikeProgress <= 0.5) {
        // Downswing: rotate hammer forward
        const t = this.strikeProgress / 0.5;
        this.hammerGroup.rotation.z = t * Math.PI * 0.4;
      } else if (this.strikeProgress <= 1.0) {
        // Impact and return
        const t = (this.strikeProgress - 0.5) / 0.5;
        this.hammerGroup.rotation.z = Math.PI * 0.4 * (1 - t);

        // Create particle burst on impact
        if (this.strikeProgress > 0.45 && this.strikeProgress < 0.55) {
          this.createParticleBurst();
          this.createShockwave();
        }
      } else {
        // Reset
        this.isStriking = false;
        this.hammerGroup.rotation.z = 0;
      }
    }

    // Update particles
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.position.add(p.velocity);
      p.velocity.y -= 0.15; // Gravity
      p.life -= deltaTime;

      if (p.life <= 0) {
        this.group.remove(p);
        this.particles.splice(i, 1);
      }
    }

    // Update sparks
    for (let i = this.sparks.length - 1; i >= 0; i--) {
      const s = this.sparks[i];
      s.position.add(s.velocity);
      s.velocity.y -= 0.08;
      s.life -= deltaTime;

      if (s.life <= 0) {
        this.group.remove(s);
        this.sparks.splice(i, 1);
      }
    }

    // Update shockwave rings
    for (let i = this.shockwaveRings.length - 1; i >= 0; i--) {
      const ring = this.shockwaveRings[i];
      ring.scale.x += deltaTime * 15;
      ring.scale.z += deltaTime * 15;
      ring.material.opacity -= deltaTime * 2;

      if (ring.material.opacity <= 0) {
        this.group.remove(ring);
        this.shockwaveRings.splice(i, 1);
      }
    }
  }

  createParticleBurst() {
    const particleCount = 30;
    for (let i = 0; i < particleCount; i++) {
      const angle = (i / particleCount) * Math.PI * 2;
      const speed = 0.3 + Math.random() * 0.5;

      const geom = new THREE.SphereGeometry(0.15, 6, 6);
      const mat = new THREE.MeshStandardMaterial({
        color: new THREE.Color(`hsl(${30 + Math.random() * 30}, 100%, ${50 + Math.random() * 30}%)`),
        emissive: new THREE.Color(`hsl(${30 + Math.random() * 30}, 100%, 50%)`),
        emissiveIntensity: 0.8,
        roughness: 0.3,
        metalness: 0.6
      });
      const particle = new THREE.Mesh(geom, mat);
      particle.position.set(0, 4, -10);
      particle.velocity = new THREE.Vector3(
        Math.cos(angle) * speed,
        (Math.random() - 0.3) * 0.5,
        Math.sin(angle) * speed
      );
      particle.life = 1.5 + Math.random() * 0.5;
      particle.castShadow = true;

      this.group.add(particle);
      this.particles.push(particle);
    }
  }

  createShockwave() {
    const ringGeom = new THREE.TorusGeometry(1.5, 0.3, 16, 100);
    const ringMat = new THREE.MeshStandardMaterial({
      color: 0xffff00,
      emissive: 0xffff00,
      emissiveIntensity: 0.8,
      roughness: 0.2,
      transparent: true,
      opacity: 0.6
    });
    const ring = new THREE.Mesh(ringGeom, ringMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(0, 3.5, -10);

    this.group.add(ring);
    this.shockwaveRings.push(ring);
  }
}

export function createForgeScene() {
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x0a0a15);

  // Ambient light
  const ambient = new THREE.AmbientLight(0xffffff, 0.3);
  scene.add(ambient);

  // Forge lights
  const forgeLight = new THREE.PointLight(0xff6600, 2.0, 50);
  forgeLight.position.set(0, 5, -10);
  scene.add(forgeLight);

  const runeLight = new THREE.PointLight(0x00ffff, 1.0, 35);
  runeLight.position.set(0, 2, 0);
  scene.add(runeLight);

  // Directional light for general illumination
  const sunLight = new THREE.DirectionalLight(0xffffff, 0.5);
  sunLight.position.set(20, 30, 20);
  sunLight.castShadow = true;
  sunLight.shadow.mapSize.width = 1024;
  sunLight.shadow.mapSize.height = 1024;
  scene.add(sunLight);

  // Create forge
  const forge = new MoruForge();
  scene.add(forge.group);

  // Magical floor
  const floorGeom = new THREE.CircleGeometry(50, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x0a0a1a,
    roughness: 0.9,
    metalness: 0.0
  });
  const floor = new THREE.Mesh(floorGeom, floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  scene.add(floor);

  // Ambience particles (slowly floating embers)
  for (let i = 0; i < 40; i++) {
    const emberGeom = new THREE.SphereGeometry(0.1, 4, 4);
    const emberMat = new THREE.MeshStandardMaterial({
      color: 0xff4400,
      emissive: 0xff2200,
      emissiveIntensity: 0.7
    });
    const ember = new THREE.Mesh(emberGeom, emberMat);
    ember.position.set(
      (Math.random() - 0.5) * 60,
      5 + Math.random() * 30,
      (Math.random() - 0.5) * 60
    );
    ember.floatY = Math.random() * Math.PI * 2;
    ember.floatSpeed = 0.3 + Math.random() * 0.2;
    scene.add(ember);
  }

  return { scene, forge };
}


