import * as THREE from 'three';

export function createWindowTexture(width = 512, height = 512) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  // Dark building base
  ctx.fillStyle = '#0a0a1a';
  ctx.fillRect(0, 0, width, height);

  // Grid of glowing windows with color variation
  const windowWidth = 24;
  const windowHeight = 32;
  const spacingX = 36;
  const spacingY = 44;

  const colors = [
    { r: 255, g: 200, b: 100 },  // warm yellow
    { r: 100, g: 180, b: 255 },  // cool blue
    { r: 200, g: 100, b: 255 },  // magenta
    { r: 100, g: 255, b: 180 },  // cyan
    { r: 255, g: 150, b: 150 },  // pink
    { r: 150, g: 255, b: 100 }   // lime
  ];

  for (let y = spacingY / 2; y < height; y += spacingY) {
    for (let x = spacingX / 2; x < width; x += spacingX) {
      // Randomly lit windows with variations
      if (Math.random() > 0.15) {
        const color = colors[Math.floor(Math.random() * colors.length)];
        const intensity = 0.6 + Math.random() * 0.4;

        // Outer glow
        ctx.fillStyle = `rgba(${color.r}, ${color.g}, ${color.b}, ${intensity * 0.3})`;
        ctx.fillRect(x - windowWidth / 2 - 4, y - windowHeight / 2 - 4, windowWidth + 8, windowHeight + 8);

        // Window interior
        ctx.fillStyle = `rgb(${Math.round(color.r * intensity)}, ${Math.round(color.g * intensity)}, ${Math.round(color.b * intensity)})`;
        ctx.fillRect(x - windowWidth / 2, y - windowHeight / 2, windowWidth, windowHeight);

        // Bright center spot
        ctx.fillStyle = '#ffffff';
        ctx.globalAlpha = 0.3;
        ctx.fillRect(x - windowWidth / 4, y - windowHeight / 3, windowWidth / 2, windowHeight / 3);
        ctx.globalAlpha = 1.0;
      } else {
        // Dark unlit window
        ctx.fillStyle = '#000000';
        ctx.fillRect(x - windowWidth / 2, y - windowHeight / 2, windowWidth, windowHeight);
        ctx.fillStyle = '#1a1a2e';
        ctx.fillRect(x - windowWidth / 2 + 2, y - windowHeight / 2 + 2, windowWidth - 4, windowHeight - 4);
      }
    }
  }

  // Vertical accent strips (neon lines)
  ctx.strokeStyle = '#ff00ff';
  ctx.globalAlpha = 0.5;
  ctx.lineWidth = 3;
  for (let x = 80; x < width; x += 200) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, height);
    ctx.stroke();
  }
  ctx.globalAlpha = 1.0;

  return new THREE.CanvasTexture(canvas);
}

export function createRoadTexture(width = 512, height = 512) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  // Asphalt road surface
  ctx.fillStyle = '#1a1a2a';
  ctx.fillRect(0, 0, width, height);

  // Add subtle texture variation
  for (let i = 0; i < 100; i++) {
    ctx.fillStyle = `rgba(20, 20, 30, ${Math.random() * 0.3})`;
    ctx.fillRect(
      Math.random() * width,
      Math.random() * height,
      Math.random() * 40 + 10,
      Math.random() * 40 + 10
    );
  }

  // Yellow center line (dashed)
  ctx.strokeStyle = '#ffdd00';
  ctx.lineWidth = 8;
  ctx.setLineDash([40, 30]);
  ctx.globalAlpha = 0.8;
  ctx.beginPath();
  ctx.moveTo(width / 2, 0);
  ctx.lineTo(width / 2, height);
  ctx.stroke();

  // White edge lines (solid)
  ctx.setLineDash([]);
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 4;
  ctx.globalAlpha = 0.6;
  ctx.beginPath();
  ctx.moveTo(width / 4, 0);
  ctx.lineTo(width / 4, height);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(3 * width / 4, 0);
  ctx.lineTo(3 * width / 4, height);
  ctx.stroke();
  ctx.globalAlpha = 1.0;

  // Crosswalk stripes
  ctx.fillStyle = '#ffffff';
  ctx.globalAlpha = 0.7;
  for (let y = 100; y < height; y += 400) {
    for (let x = 0; x < width; x += 40) {
      ctx.fillRect(x, y, 20, 80);
    }
  }
  ctx.globalAlpha = 1.0;

  return new THREE.CanvasTexture(canvas);
}

export function createRuneTexture(width = 256, height = 256) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  // Dark background with radial gradient
  const grad = ctx.createRadialGradient(width / 2, height / 2, 0, width / 2, height / 2, Math.max(width, height) / 2);
  grad.addColorStop(0, '#1a0033');
  grad.addColorStop(1, '#0a0015');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  // Outer ring
  ctx.strokeStyle = '#ff00ff';
  ctx.lineWidth = 8;
  ctx.globalAlpha = 0.8;
  ctx.beginPath();
  ctx.arc(width / 2, height / 2, 90, 0, Math.PI * 2);
  ctx.stroke();

  // Inner rune circle
  ctx.strokeStyle = '#00ffff';
  ctx.lineWidth = 4;
  ctx.globalAlpha = 0.6;
  ctx.beginPath();
  ctx.arc(width / 2, height / 2, 60, 0, Math.PI * 2);
  ctx.stroke();

  // Rune patterns (8-pointed star)
  const cx = width / 2;
  const cy = height / 2;
  ctx.strokeStyle = '#ffff00';
  ctx.lineWidth = 3;
  ctx.globalAlpha = 0.7;

  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x1 = cx + Math.cos(angle) * 40;
    const y1 = cy + Math.sin(angle) * 40;
    const x2 = cx + Math.cos(angle) * 100;
    const y2 = cy + Math.sin(angle) * 100;

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }

  // Mystical glow points
  ctx.fillStyle = '#ff00ff';
  ctx.globalAlpha = 0.9;
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x = cx + Math.cos(angle) * 75;
    const y = cy + Math.sin(angle) * 75;
    ctx.beginPath();
    ctx.arc(x, y, 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#00ffff';
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  // Center glow
  ctx.fillStyle = '#ffff00';
  ctx.globalAlpha = 0.6;
  ctx.beginPath();
  ctx.arc(cx, cy, 8, 0, Math.PI * 2);
  ctx.fill();

  ctx.globalAlpha = 1.0;
  return new THREE.CanvasTexture(canvas);
}

export function createMetalTexture(width = 256, height = 256) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  // Base metallic color with noise
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const noise = Math.sin(x * 0.1) * Math.cos(y * 0.1) * 0.2 + 0.3;
      const brightness = Math.floor(100 + noise * 100);
      ctx.fillStyle = `rgb(${brightness}, ${brightness}, ${brightness})`;
      ctx.fillRect(x, y, 1, 1);
    }
  }

  // Brushed metal streaks
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 50; i++) {
    const y = Math.random() * height;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(width, y + Math.random() * 10 - 5);
    ctx.stroke();
  }

  return new THREE.CanvasTexture(canvas);
}

export function createLazyGradient(fromColor = '#000000', toColor = '#ffffff', width = 128, height = 128) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  const grad = ctx.createLinearGradient(0, 0, width, height);
  grad.addColorStop(0, fromColor);
  grad.addColorStop(1, toColor);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  return new THREE.CanvasTexture(canvas);
}

export function createGlowingCircleTexture(size = 128) {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');

  ctx.clearRect(0, 0, size, size);

  // Radial gradient from bright center to transparent
  const grad = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  grad.addColorStop(0, 'rgba(255, 255, 255, 1)');
  grad.addColorStop(0.3, 'rgba(255, 200, 100, 0.8)');
  grad.addColorStop(0.7, 'rgba(100, 150, 255, 0.3)');
  grad.addColorStop(1, 'rgba(0, 0, 0, 0)');

  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);

  return new THREE.CanvasTexture(canvas);
}


