      background: #0a0;
      color: #000;
      border: 1px solid #0f0;
      border-radius: 2px;
      font-size: 11px;
      font-weight: bold;
      cursor: pointer;
      transition: all 0.2s;
      text-transform: uppercase;
    }

    button:hover {
      background: #0f0;
      box-shadow: 0 0 10px #0f0;
    }

    button:active {
      transform: scale(0.95);
    }

    .camera-buttons, .action-buttons, .theme-buttons {
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    #toggle-spin {
      background: #f00;
      color: #fff;
    }

    #toggle-spin:hover {
      background: #ff0;
      box-shadow: 0 0 10px #ff0;
    }

    .right-panel {
      position: absolute;
      bottom: 10px;
      right: 10px;
      background: rgba(0, 0, 0, 0.9);
      padding: 12px;
      border: 2px solid #0f0;
      border-radius: 4px;
      z-index: 100;
      display: flex;
      flex-direction: column;
      gap: 8px;
      max-width: 200px;
    }

    .right-panel .control-group {
      border-bottom: 1px solid #0f0;
    }

    .right-panel .control-group:last-child {
      border-bottom: none;
    }

    @keyframes glow {
      0%, 100% { text-shadow: 0 0 5px #0f0; }
      50% { text-shadow: 0 0 20px #0f0; }
    }

    #fps-hud {
      text-shadow: 0 0 5px #0f0;
    }

    /* Mobile responsiveness */
    @media (max-width: 768px) {
      .control-panel, .right-panel {
        max-width: 160px;
      }

      button {
        padding: 6px 8px;
        font-size: 10px;
      }

      #fps-hud {
        font-size: 11px;
      }
    }
