import * as THREE from 'three';

const sphere = new THREE.SphereGeometry(1, 20, 14);
const palette = ['#e6a866', '#a5c9d2', '#d9b1cf', '#d8d3bb', '#75999d', '#c18c68'];
export function createMoruCat(index) {
  const cat = new THREE.Group();
  cat.name = `Moru Cat ${index + 1}`;
  cat.userData.isMoruCat = true;
  const fur = new THREE.MeshStandardMaterial({ color: palette[index % palette.length], roughness: .72 });
  const cream = new THREE.MeshStandardMaterial({ color: '#f5ddbb', roughness: .8 });
  const pink = new THREE.MeshStandardMaterial({ color: '#e79b9c' });
  const black = new THREE.MeshStandardMaterial({ color: '#172b35', roughness: .18 });
  const gold = new THREE.MeshStandardMaterial({ color: '#d6a14e', metalness: .55, roughness: .3 });
  const helmet = new THREE.MeshStandardMaterial({ color: '#486b79', metalness: .5, roughness: .4 });
  const parts = [];
  function part(name, material, position, scale, geometry = sphere) {
    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = name;
    mesh.position.set(...position);
    mesh.scale.set(...scale);
    mesh.castShadow = true;
    cat.add(mesh);
    parts.push(mesh);
    return mesh;
  }
  part('Round torso', fur, [0, 1.3, 0], [.75, .85, 1.05]);
  part('Belly patch', cream, [0, 1.3, .8], [.57, .6, .3]);
  part('Chibi head', fur, [0, 2.35, .65], [1, .86, .8]);
  for (const side of [-1, 1]) {
    part('Puffy cheek', cream, [side * .4, 2.07, 1.28], [.38, .28, .27]);
    part('Pointed ear', fur, [side * .68, 3.1, .55], [.45, .75, .4], new THREE.ConeGeometry(1, 1, 3));
    part('Inner ear', pink, [side * .68, 3.12, .77], [.25, .47, .12], new THREE.ConeGeometry(1, 1, 3));
    part('Glossy eye', black, [side * .39, 2.45, 1.32], [.19, .24, .12]);
    part('Catchlight', cream, [side * .39 - .045, 2.53, 1.43], [.055, .068, .035]);
    for (let n = 0; n < 3; n++) {
      const whisker = part('Whisker', cream, [side * .83, 2.03 + n * .11, 1.27], [.4, .018, .018]);
      whisker.rotation.z = side * (n - 1) * .18;
    }
  }
  part('Pink nose', pink, [0, 2.16, 1.54], [.14, .1, .09]);
  part('Collar', helmet, [0, 1.85, .42], [.75, .12, .75]);
  part('Golden bell', gold, [0, 1.72, 1.16], [.17, .2, .17]);
  part('Helmet dome', helmet, [0, 2.94, .6], [.74, .32, .65]);
  part('Helmet brim', gold, [0, 2.89, .75], [.86, .07, .73]);
  part('Helmet badge', gold, [0, 3.02, 1.21], [.14, .16, .04]);
  const legs = [];
  for (const x of [-.49, .49]) for (const z of [-.62, .62]) {
    legs.push(part('Articulated leg', fur, [x, .62, z], [.29, .58, .31]));
    part('Soft paw', cream, [x, .18, z + .12], [.32, .2, .38]);
  }
  const tail = [];
  for (let n = 0; n < 6; n++) tail.push(part('Tail joint', n % 2 ? cream : fur,
    [0, 1.3 + n * .2, -1 - n * .22], [.22 - n * .015, .25, .28]));
  const bases = parts.map(mesh => mesh.position.clone());
  cat.userData.update = (time, excitement = 0) => {
    const phase = time * .22 + index * Math.PI * 2 / 8;
    const radius = 10.8 + index % 3 * 2.2;
    cat.position.set(Math.cos(phase) * radius, .15 + Math.abs(Math.sin(time * 4 + index)) * .22 + excitement * Math.abs(Math.sin(time * 9 + index)) * 2, Math.sin(phase) * radius);
    cat.rotation.y = -phase;
    cat.rotation.z = Math.sin(time * 3 + index) * .035;
    // Every child has a tiny breathing/spring motion, in addition to the gait.
    parts.forEach((mesh, i) => { mesh.position.y = bases[i].y + Math.sin(time * 4 + i * .17 + index) * .012; });
    legs.forEach((leg, i) => { leg.rotation.x = Math.sin(time * 7 + index + (i === 0 || i === 3 ? 0 : Math.PI)) * .5; });
    tail.forEach((joint, i) => { joint.position.x = Math.sin(time * 3.2 + i * .4 + index) * (.1 + i * .065); joint.rotation.z = Math.sin(time * 3 + i) * .2; });
  };
  cat.userData.update(0);
  return cat;
}


