window.__app = { scene, camera, renderer, composer, state, controls, cats, city, forge };
const themes = {
  night: { sky: '#283e56', fog: '#344b60', skyLight: '#b4d7f0', ground: '#6b7e89', sun: '#a9d3ef', ambient: 2.1, direct: 2.4, exposure: 1.08, bloom: .28 },
  gold: { sky: '#8b7b79', fog: '#95827b', skyLight: '#efceac', ground: '#7a7b85', sun: '#ffd09c', ambient: 2, direct: 2.8, exposure: .94, bloom: .19 },
