  createPavingTexture, createHelipadTexture, createPoolTexture, createSignTexture,
} from './textures.js';

const UP = new THREE.Vector3(0, 1, 0);
function mesh(geometry, material, parent, position, name) {
  const object = new THREE.Mesh(geometry, material);
  if (position) object.position.set(...position);
  object.castShadow = true;
  object.receiveShadow = true;
  if (name) object.name = name;
  parent.add(object);
  return object;
}
function box(parent, material, x, y, z, width, height, depth, name) {
  return mesh(new THREE.BoxGeometry(width, height, depth), material, parent, [x, y, z], name);
}
function horizontalPlane(parent, material, x, y, z, width, depth) {
  const object = mesh(new THREE.PlaneGeometry(width, depth), material, parent, [x, y, z]);
  object.rotation.x = -Math.PI / 2;
  object.castShadow = false;
  return object;
}
function frame(parent, material, width, depth, y, thickness = 0.1) {
  box(parent, material, 0, y, -depth / 2, width, thickness, thickness);
  box(parent, material, 0, y, depth / 2, width, thickness, thickness);
  box(parent, material, -width / 2, y, 0, thickness, thickness, depth);
  box(parent, material, width / 2, y, 0, thickness, thickness, depth);
}

