import * as THREE from 'three';

export const CAT_NAMES = ['Mochi', 'Ember', 'Miso', 'Luna', 'Copper', 'Yuki', 'Soot', 'Maple'];
const PALETTES = [
  { fur: '#e7c5a0', patch: '#fff0d7', stripe: '#ac7954', collar: '#479b9b' },
  { fur: '#b9744c', patch: '#f7d1a1', stripe: '#714c3d', collar: '#6b9eb2' },
  { fur: '#8fabb6', patch: '#dfe9dc', stripe: '#4c6b81', collar: '#d59c63' },
  { fur: '#d9d4e4', patch: '#fff0ed', stripe: '#9d90b0', collar: '#9274b6' },
  { fur: '#d9a76f', patch: '#fce9c8', stripe: '#94613f', collar: '#557b9e' },
  { fur: '#ede4cf', patch: '#fffae8', stripe: '#b8a89b', collar: '#a7797c' },
  { fur: '#526675', patch: '#a7b8bc', stripe: '#344554', collar: '#b48951' },
  { fur: '#bf8c72', patch: '#f3d8bf', stripe: '#855d55', collar: '#6d9c82' },
];
const sphereGeometry = new THREE.SphereGeometry(1, 14, 10);
const smallSphere = new THREE.SphereGeometry(1, 10, 8);
function ellipsoid(parent, material, x, y, z, sx, sy, sz, name = '') {
  const mesh = new THREE.Mesh(sphereGeometry, material);
  mesh.position.set(x, y, z);
  mesh.scale.set(sx, sy, sz);
  mesh.name = name;
  parent.add(mesh);
  return mesh;
}
function tubeBetween(parent, start, end, radius, material, name = '') {
  const a = new THREE.Vector3(...start);
  const b = new THREE.Vector3(...end);
  const direction = b.clone().sub(a);
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.7, radius, direction.length(), 8), material);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.normalize());
  mesh.name = name;
  parent.add(mesh);
  return mesh;
}

export function createMoruCat(index = 0) {
  const palette = PALETTES[index % PALETTES.length];
  const root = new THREE.Group();
  root.name = `MoruCat_${CAT_NAMES[index % CAT_NAMES.length]}_${index + 1}`;
  root.userData.isMoruCat = true;
  root.userData.catName = CAT_NAMES[index % CAT_NAMES.length];
  root.userData.index = index;
  const fur = new THREE.MeshStandardMaterial({ color: palette.fur, roughness: 0.87 });
  const patch = new THREE.MeshStandardMaterial({ color: palette.patch, roughness: 0.9 });
  const stripe = new THREE.MeshStandardMaterial({ color: palette.stripe, roughness: 0.9 });
  const pink = new THREE.MeshStandardMaterial({ color: '#e5a3a2', roughness: 0.74 });
  const eye = new THREE.MeshStandardMaterial({ color: '#172e39', metalness: 0.15, roughness: 0.08 });
  const iris = new THREE.MeshStandardMaterial({ color: index % 2 ? '#69a8a2' : '#bc9653', roughness: 0.3 });
  const white = new THREE.MeshBasicMaterial({ color: '#f5fbec' });
  const whisker = new THREE.MeshStandardMaterial({ color: '#e9dfcf', roughness: 0.8 });
  const leather = new THREE.MeshStandardMaterial({ color: palette.collar, roughness: 0.65 });
  const helmetMetal = new THREE.MeshStandardMaterial({ color: '#485f6b', metalness: 0.65, roughness: 0.4 });
  const brass = new THREE.MeshStandardMaterial({ color: '#d6ac63', metalness: 0.65, roughness: 0.3 });
  // Chibi proportions: large head and short, rounded, independently jointed paws.
  ellipsoid(root, fur, 0, 1.02, 0, 0.69, 0.68, 0.94, 'RoundedTorso');
  ellipsoid(root, patch, 0, 0.94, 0.62, 0.48, 0.47, 0.46, 'CreamBellyPatch');
  for (const side of [-1, 1]) {
    for (let mark = 0; mark < 3; mark++) {
      const spot = ellipsoid(root, stripe, side * 0.64, 1.24, -0.42 + mark * 0.35,
        0.055, 0.21, 0.075, 'TabbySideStripe');
      spot.rotation.z = side * 0.3;
    }
  }
  const head = new THREE.Group();
  head.name = 'ExpressiveHeadRig';
  head.position.set(0, 1.74, 0.53);
  root.add(head);
  ellipsoid(head, fur, 0, 0, 0, 0.87, 0.76, 0.72, 'ChibiHead');
  for (const side of [-1, 1]) {
    ellipsoid(head, patch, side * 0.48, -0.26, 0.46, 0.4, 0.32, 0.31, 'PuffyCheek');
    const ear = new THREE.Mesh(new THREE.ConeGeometry(0.4, 0.8, 3, 1), fur);
    ear.name = 'PointedEar';
    ear.position.set(side * 0.59, 0.64, -0.07);
    ear.rotation.z = -side * 0.18;
    ear.rotation.y = Math.PI;
    ear.scale.z = 0.6;
    ear.castShadow = true;
    head.add(ear);
    const inner = new THREE.Mesh(new THREE.ConeGeometry(0.24, 0.51, 3), pink);
    inner.name = 'InnerEar';
    inner.position.set(side * 0.6, 0.66, 0.095);
    inner.rotation.z = -side * 0.18;
    inner.rotation.y = Math.PI;
    inner.scale.z = 0.2;
    head.add(inner);
    ellipsoid(head, patch, side * 0.34, 0.09, 0.602, 0.29, 0.33, 0.13, 'EyeMask');
    ellipsoid(head, eye, side * 0.34, 0.07, 0.692, 0.238, 0.29, 0.115, 'GlossyEye');
    ellipsoid(head, iris, side * 0.34, 0.035, 0.79, 0.13, 0.19, 0.035, 'Iris');
    ellipsoid(head, eye, side * 0.34, 0.065, 0.815, 0.067, 0.16, 0.018, 'Pupil');
    ellipsoid(head, white, side * 0.34 - 0.075, 0.17, 0.82, 0.064, 0.078, 0.025, 'EyeCatchlight');
    ellipsoid(head, white, side * 0.34 + 0.06, -0.025, 0.825, 0.026, 0.03, 0.018, 'TinyCatchlight');
    const brow = ellipsoid(head, stripe, side * 0.34, 0.405, 0.55, 0.19, 0.045, 0.06, 'CuriousBrow');
    brow.rotation.z = side * 0.13;
    ellipsoid(head, pink, side * 0.61, -0.2, 0.68, 0.14, 0.07, 0.023, 'Blush');
    for (let w = 0; w < 2; w++) {
      tubeBetween(head, [side * 0.43, -0.24 - w * 0.12, 0.73],
        [side * 1.03, -0.14 - w * 0.27, 0.8], 0.016, whisker, 'Whisker');
    }
  }
  ellipsoid(head, patch, -0.15, -0.3, 0.73, 0.22, 0.17, 0.14, 'SnoutLeft');
  ellipsoid(head, patch, 0.15, -0.3, 0.73, 0.22, 0.17, 0.14, 'SnoutRight');
  const nose = new THREE.Mesh(new THREE.ConeGeometry(0.125, 0.13, 3), pink);
  nose.position.set(0, -0.22, 0.9);
  nose.rotation.z = Math.PI;
  nose.rotation.x = -Math.PI / 2;
  nose.name = 'PinkNose';
  head.add(nose);
  tubeBetween(head, [0, -0.26, 0.88], [0, -0.38, 0.87], 0.015, stripe);
  tubeBetween(head, [0, -0.38, 0.87], [-0.1, -0.42, 0.84], 0.015, stripe);
  tubeBetween(head, [0, -0.38, 0.87], [0.1, -0.42, 0.84], 0.015, stripe);
  // A half-sphere blacksmith cap, broad brim, central ridge and copper rivets.
  const cap = new THREE.Mesh(new THREE.SphereGeometry(0.69, 28, 14, 0, Math.PI * 2, 0, Math.PI / 2), helmetMetal);
  cap.position.set(0, 0.43, -0.13);
  cap.scale.set(1, 0.57, 0.9);
  cap.name = 'BlacksmithHelmet';
  cap.castShadow = true;
  head.add(cap);
  ellipsoid(head, helmetMetal, 0, 0.43, -0.08, 0.76, 0.065, 0.67, 'HelmetBrim');
  const ridge = new THREE.Mesh(new THREE.TorusGeometry(0.5, 0.045, 8, 24, Math.PI), brass);
  ridge.position.set(0, 0.45, -0.14);
  ridge.rotation.y = Math.PI / 2;
  ridge.scale.y = 0.72;
  head.add(ridge);
  for (let i = 0; i < 5; i++) {
