function addMesh(parent, geometry, material, x = 0, y = 0, z = 0) {
  const object = new THREE.Mesh(geometry, material);
  object.position.set(x, y, z);
  parent.add(object);
  return object;
}
function block(parent, material, x, y, z, width, height, depth) {
  return addMesh(parent, new THREE.BoxGeometry(width, height, depth), material, x, y, z);
}
function ring(parent, material, radius, tube, y) {
  const object = addMesh(parent, new THREE.TorusGeometry(radius, tube, 10, 128), material, 0, y, 0);
  object.rotation.x = Math.PI / 2;
  return object;
}

