// --- Audio Synthesizer (Zero external dependencies) ---
class CyberAudioEngine {
  constructor() {
    this.ctx = null;
    this.enabled = true;
  }

  init() {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
      }
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }

  playStrike() {
    if (!this.enabled) return;
    this.init();
    if (!this.ctx) return;

    const t = this.ctx.currentTime;

    // Heavy bass thump
    const oscBass = this.ctx.createOscillator();
    const gainBass = this.ctx.createGain();
    oscBass.type = 'triangle';
    oscBass.frequency.setValueAtTime(140, t);
    oscBass.frequency.exponentialRampToValueAtTime(35, t + 0.35);
    gainBass.gain.setValueAtTime(0.9, t);
    gainBass.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
    oscBass.connect(gainBass);
    gainBass.connect(this.ctx.destination);
    oscBass.start(t);
    oscBass.stop(t + 0.35);

    // High metallic anvil ring (FM metallic ping)
    const carrier = this.ctx.createOscillator();
    const carrierGain = this.ctx.createGain();
    carrier.type = 'sine';
    carrier.frequency.setValueAtTime(1280, t);
    carrier.frequency.exponentialRampToValueAtTime(1150, t + 1.2);

    // Metallic overtone harmonic
    const overtone = this.ctx.createOscillator();
    const overtoneGain = this.ctx.createGain();
    overtone.type = 'sine';
    overtone.frequency.setValueAtTime(2560, t);
    overtone.frequency.exponentialRampToValueAtTime(2400, t + 0.8);

    carrierGain.gain.setValueAtTime(0.6, t);
    carrierGain.gain.exponentialRampToValueAtTime(0.001, t + 1.4);

    overtoneGain.gain.setValueAtTime(0.35, t);
    overtoneGain.gain.exponentialRampToValueAtTime(0.001, t + 0.9);

    carrier.connect(carrierGain);
    carrierGain.connect(this.ctx.destination);
    overtone.connect(overtoneGain);
    overtoneGain.connect(this.ctx.destination);

    carrier.start(t);
    carrier.stop(t + 1.4);
    overtone.start(t);
    overtone.stop(t + 0.9);

    // Impact noise burst
    const bufferSize = this.ctx.sampleRate * 0.15;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (this.ctx.sampleRate * 0.03));
    }
    const noiseSource = this.ctx.createBufferSource();
    noiseSource.buffer = buffer;
    const noiseFilter = this.ctx.createBiquadFilter();
    noiseFilter.type = 'bandpass';
    noiseFilter.frequency.setValueAtTime(3200, t);
    noiseFilter.Q.setValueAtTime(2.0, t);

    const noiseGain = this.ctx.createGain();
    noiseGain.gain.setValueAtTime(0.5, t);
    noiseGain.gain.exponentialRampToValueAtTime(0.01, t + 0.15);

    noiseSource.connect(noiseFilter);
    noiseFilter.connect(noiseGain);
    noiseGain.connect(this.ctx.destination);
    noiseSource.start(t);
  }

  playMeow() {
    if (!this.enabled) return;
    this.init();
    if (!this.ctx) return;

    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    // Classic meow pitch inflection (rise then gentle fall)
    osc.frequency.setValueAtTime(450, t);
    osc.frequency.exponentialRampToValueAtTime(820, t + 0.12);
    osc.frequency.exponentialRampToValueAtTime(560, t + 0.38);

    // Subtle cute vibrato
    const vibrato = this.ctx.createOscillator();
    const vibratoGain = this.ctx.createGain();
    vibrato.frequency.setValueAtTime(6.5, t);
    vibratoGain.gain.setValueAtTime(18, t);
    vibrato.connect(osc.frequency);
    vibrato.start(t);
    vibrato.stop(t + 0.42);

    gain.gain.setValueAtTime(0.01, t);
    gain.gain.linearRampToValueAtTime(0.25, t + 0.06);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.42);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(t);
    osc.stop(t + 0.42);
  }

  playSpawn() {
    if (!this.enabled) return;
    this.init();
    if (!this.ctx) return;

    const t = this.ctx.currentTime;
    const freqs = [523.25, 659.25, 783.99, 1046.50]; // C5, E5, G5, C6 arpeggio
    freqs.forEach((f, idx) => {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(f, t + idx * 0.05);

      gain.gain.setValueAtTime(0.18, t + idx * 0.05);
      gain.gain.exponentialRampToValueAtTime(0.001, t + idx * 0.05 + 0.28);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(t + idx * 0.05);
      osc.stop(t + idx * 0.05 + 0.28);
    });
  }
}

