const catBreeds = [
  { name: 'Kuro', coat: 0x141824, belly: 0x222a38, ear: 0xff66aa, eye: 0x00ffaa, collar: 0x00f0ff },
  { name: 'Mikan', coat: 0xe67300, belly: 0xffe0b2, ear: 0xff88aa, eye: 0x225500, collar: 0xffaa00 },
  { name: 'Yuki', coat: 0xf5f8ff, belly: 0xffffff, ear: 0xff88aa, eye: 0x0088ff, collar: 0xff2a85 },
  { name: 'Calico', coat: 0xd97724, belly: 0xffffff, ear: 0xff99bb, eye: 0xd4a017, collar: 0x00ff88 },
  { name: 'Titan', coat: 0x3d485e, belly: 0x627394, ear: 0xff4500, eye: 0xffaa00, collar: 0xff5500 },
  { name: 'Sakura', coat: 0xffc4db, belly: 0xffffff, ear: 0xff4f9a, eye: 0x9b59b6, collar: 0x00f0ff }
];

class MoruCat {
  constructor(index, breedIndex = null, startPos = null) {
    this.index = index;
    const breed = breedIndex !== null
      ? catBreeds[breedIndex % catBreeds.length]
      : catBreeds[Math.floor(Math.random() * catBreeds.length)];
    this.breed = breed;
    this.name = breed.name;

    this.group = new THREE.Group();
    this.group.name = `moru-cat-${index}`;

    // Locomotion state
    this.pos = new THREE.Vector3(0, 0, 0);
    this.target = new THREE.Vector3(0, 0, 0);
    this.heading = 0;
    this.speed = 3.2 + Math.random() * 2.2;
    this.animTime = Math.random() * 10;
    this.isJumping = false;
    this.jumpProgress = 0;
    this.jumpHeight = 1.6;
    this.isSurprised = false;
    this.surpriseTimer = 0;

    // Build the cat mesh hierarchy
    this.buildMesh();

    // Spawn location & initial target
    if (startPos) {
      this.pos.copy(startPos);
    } else {
      const startAngle = (index / 6) * Math.PI * 2;
      const startDist = 10 + Math.random() * 14;
      this.pos.set(Math.cos(startAngle) * startDist, 0, Math.sin(startAngle) * startDist);
    }
    this.group.position.copy(this.pos);
    this.pickNewTarget();

    scene.add(this.group);
