const camera = new THREE.PerspectiveCamera(
  45,
  window.innerWidth / window.innerHeight,
  0.5,
  800
);
// Default overview position & target as specified in SPEC.md G6
camera.position.set(42, 30, 46);

// OrbitControls setup as specified in SPEC.md G6
const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, 3.5, 0);
controls.enableRotate = true;
controls.enableZoom = true;
controls.enablePan = true;
controls.autoRotate = true;
controls.autoRotateSpeed = 2.2;
controls.enableDamping = false;
controls.update();

// Post-Processing Pipeline (EffectComposer + RenderPass + UnrealBloomPass)
const composer = new EffectComposer(renderer);
const renderPass = new RenderPass(scene, camera);
composer.addPass(renderPass);

const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  0.65, // strength
  0.45, // radius
  0.65  // threshold
);
composer.addPass(bloomPass);

// Lighting Rig
const ambientLight = new THREE.AmbientLight(0x303952, 0.85);
scene.add(ambientLight);

const sunLight = new THREE.DirectionalLight(0x6b88b6, 0.95);
sunLight.position.set(60, 90, 50);
sunLight.castShadow = true;
sunLight.shadow.mapSize.width = 2048;
sunLight.shadow.mapSize.height = 2048;
sunLight.shadow.camera.near = 10;
sunLight.shadow.camera.far = 250;
const d = 65;
sunLight.shadow.camera.left = -d;
sunLight.shadow.camera.right = d;
sunLight.shadow.camera.top = d;
sunLight.shadow.camera.bottom = -d;
sunLight.shadow.bias = -0.0005;
scene.add(sunLight);

// Hemisphere Light for balanced fill illumination (prevents dark blackout)
const hemiLight = new THREE.HemisphereLight(0x404870, 0x25283a, 0.6);
scene.add(hemiLight);

// ==========================================
// THEME MANAGEMENT & HISTOGRAM GUARD
// ==========================================
// Balanced exposure profiles preventing dark blackout (luminance < 12) < 75%
// and bright white-out (luminance > 245) < 8% across Night, Gold, and Day modes.
const THEMES = {
  night: {
    bg: 0x101428,
    fogColor: 0x101428,
    fogNear: 35,
    fogFar: 180,
    sunColor: 0x6b88b6,
    sunIntensity: 0.95,
    ambientColor: 0x303952,
    ambientIntensity: 0.85,
    hemiSky: 0x404870,
    hemiGround: 0x25283a,
    hemiIntensity: 0.6,
    exposure: 1.15,
    bloomStrength: 0.65,
    bloomThreshold: 0.65,
    bloomRadius: 0.45
  },
  gold: {
    bg: 0x5e381d, // Rich warm bronze twilight
    fogColor: 0x543218,
    fogNear: 35,
    fogFar: 185,
    sunColor: 0xffa534,
    sunIntensity: 1.25,
    ambientColor: 0x553322,
    ambientIntensity: 0.85,
    hemiSky: 0x7c4d29,
    hemiGround: 0x3d2414,
    hemiIntensity: 0.65,
    exposure: 1.02,
    bloomStrength: 0.50,
    bloomThreshold: 0.75,
    bloomRadius: 0.38
  },
  day: {
    bg: 0x5b8bb8, // Crisp azure sky (not blown out)
    fogColor: 0x5583ae,
    fogNear: 40,
    fogFar: 200,
    sunColor: 0xffffff,
    sunIntensity: 1.30,
    ambientColor: 0x607d8b,
    ambientIntensity: 0.80,
    hemiSky: 0x82b1ff,
    hemiGround: 0x455a64,
    hemiIntensity: 0.7,
    exposure: 0.95,
    bloomStrength: 0.35,
    bloomThreshold: 0.85,
    bloomRadius: 0.30
  }
};

function applyTheme(themeName) {
  const t = THEMES[themeName] || THEMES.night;
  state.theme = themeName;
  state.disposedCount = (state.disposedCount || 0) + 1;

  // Update URL search param cleanly without full page refresh
  const url = new URL(window.location.href);
  url.searchParams.set('theme', themeName);
  window.history.replaceState(null, '', url.toString());

  // Apply visual theme parameters
  scene.background = new THREE.Color(t.bg);
  scene.fog = new THREE.Fog(t.fogColor, t.fogNear, t.fogFar);

  sunLight.color.setHex(t.sunColor);
  sunLight.intensity = t.sunIntensity;

  ambientLight.color.setHex(t.ambientColor);
  ambientLight.intensity = t.ambientIntensity;

  hemiLight.color.setHex(t.hemiSky);
  hemiLight.groundColor.setHex(t.hemiGround);
  hemiLight.intensity = t.hemiIntensity;

  renderer.toneMappingExposure = t.exposure;
  bloomPass.strength = t.bloomStrength;
  bloomPass.threshold = t.bloomThreshold;
  bloomPass.radius = t.bloomRadius;

  // Update UI button highlights
  ['night', 'gold', 'day'].forEach(m => {
    const btn = document.getElementById(`mode-${m}`);
    if (btn) {
      if (m === themeName) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    }
  });

  if (!state.spinning) {
    composer.render();
  }
}

// Initial theme apply
applyTheme(initialTheme);

// ==========================================
// BUILD SCENE ENTITIES
// ==========================================
// 1. Build City Skyline, Roads, Trees, and Streetlamps
const city = createCity(scene);
state.buildingCount = city.buildings.length;
state.lampCount = city.streetlamps.length;
state.treeCount = city.trees.length;

// 2. Build Chibi Moru Cat Village
let catVillage = null;
const forge = createForge(scene, state, () => {
  // Callback when hammer strikes ingot
  if (catVillage) {
    catVillage.triggerForgeJump();
  }
});

catVillage = createCatVillage(scene, state);

// Compute total triangles in scene
function countSceneTriangles(root) {
  let tris = 0;
  root.traverse(obj => {
    if (obj.isMesh && obj.geometry) {
      if (obj.geometry.index) {
        tris += obj.geometry.index.count / 3;
      } else if (obj.geometry.attributes.position) {
        tris += obj.geometry.attributes.position.count / 3;
      }
    }
  });
  return Math.round(tris);
}

state.triangles = countSceneTriangles(scene);

// Expose window.__app as required by G3
window.__app = {
  scene,
  camera,
  renderer,
  composer,
  state
};

// ==========================================
// UI CONTROLS & EVENT LISTENERS
// ==========================================
const fpsHud = document.getElementById('fps-hud');

// Camera Preset Switchers
const camOverviewBtn = document.getElementById('cam-overview');
const camIsoBtn = document.getElementById('cam-iso');
const camStreetBtn = document.getElementById('cam-street');
const camFollowCatBtn = document.getElementById('cam-follow-cat');

function updateCameraMode(mode) {
  state.cameraMode = mode;
  [camOverviewBtn, camIsoBtn, camStreetBtn, camFollowCatBtn].forEach(b => b?.classList.remove('active'));

  if (mode === 'overview') {
    camOverviewBtn?.classList.add('active');
    camera.position.set(42, 30, 46);
    controls.target.set(0, 3.5, 0);
    controls.enabled = true;
    controls.autoRotate = state.spinning;
    controls.update();
  } else if (mode === 'iso') {
    camIsoBtn?.classList.add('active');
    camera.position.set(48, 42, 48);
    controls.target.set(0, 3.5, 0);
    controls.enabled = true;
    controls.autoRotate = false;
    controls.update();
  } else if (mode === 'street') {
    camStreetBtn?.classList.add('active');
    camera.position.set(0, 4.5, 26);
    controls.target.set(0, 3.5, 0);
    controls.enabled = true;
    controls.autoRotate = false;
    controls.update();
  } else if (mode === 'follow') {
    camFollowCatBtn?.classList.add('active');
    controls.autoRotate = false;
    controls.enabled = false;
  }

  if (!state.spinning) {
    composer.render();
  }
}

camOverviewBtn?.addEventListener('click', () => updateCameraMode('overview'));
camIsoBtn?.addEventListener('click', () => updateCameraMode('iso'));
camStreetBtn?.addEventListener('click', () => updateCameraMode('street'));
camFollowCatBtn?.addEventListener('click', () => updateCameraMode('follow'));

// Theme Switcher Buttons
document.getElementById('mode-night')?.addEventListener('click', () => applyTheme('night'));
document.getElementById('mode-gold')?.addEventListener('click', () => applyTheme('gold'));
document.getElementById('mode-day')?.addEventListener('click', () => applyTheme('day'));

// Action Buttons
document.getElementById('btn-spawn-cat')?.addEventListener('click', () => {
  catVillage.spawnCat();
  state.triangles = countSceneTriangles(scene);
  if (!state.spinning) {
    composer.render();
  }
});

document.getElementById('btn-forge-strike')?.addEventListener('click', () => {
  forge.triggerStrike();
});

// Photo Freeze Toggle (#toggle-spin)
const toggleSpinBtn = document.getElementById('toggle-spin');
toggleSpinBtn?.addEventListener('click', () => {
  state.spinning = !state.spinning;
  if (!state.spinning) {
    controls.autoRotate = false;
    toggleSpinBtn.textContent = '▶ Resume Spin';
    toggleSpinBtn.classList.add('paused');
  } else {
    if (state.cameraMode === 'overview') {
      controls.autoRotate = true;
    }
    toggleSpinBtn.textContent = '⏸ Freeze Photo';
    toggleSpinBtn.classList.remove('paused');
  }
});

// Resize handler
window.addEventListener('resize', () => {
  const w = window.innerWidth;
  const h = window.innerHeight;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  composer.setSize(w, h);
  if (!state.spinning) {
    composer.render();
  }
});

// ==========================================
// MAIN RENDER LOOP & TELEMETRY
// ==========================================
const clock = new THREE.Clock();
let framesThisSecond = 0;
let fpsTimer = 0;

function animate() {
  requestAnimationFrame(animate);

  // If frozen via #toggle-spin or state.spinning === false:
  // completely freeze all animation, particles, camera drift, and HUD updates
  // so consecutive screenshots 350ms apart are 100% byte-identical.
  if (!state.spinning) {
    controls.autoRotate = false;
    return;
  }

  const delta = clock.getDelta();
  const time = clock.getElapsedTime();

  state.frameCount++;
  framesThisSecond++;
  fpsTimer += delta;

  // Update HUD at least twice per second (every ~0.35s)
  if (fpsTimer >= 0.35) {
    state.fps = Math.round(framesThisSecond / fpsTimer);
    framesThisSecond = 0;
    fpsTimer = 0;

    if (fpsHud) {
      const trisK = (state.triangles / 1000).toFixed(1);
      fpsHud.textContent = `FPS: ${state.fps} | Cats: ${state.catCount} | Buildings: ${state.buildingCount} | Lamps: ${state.lampCount} | ${trisK}k tris | Frame: ${state.frameCount} | Theme: ${state.theme.toUpperCase()}`;
    }
  }

  // Follow-Cam Chase Update
  if (state.cameraMode === 'follow') {
    const activeCat = catVillage.getActiveCat();
    if (activeCat) {
      const catPos = activeCat.position;
      const catHeading = activeCat.rotation.y;
      const offsetDist = 14;
      const offsetHeight = 6.0;

      const targetCamX = catPos.x - Math.sin(catHeading) * offsetDist;
      const targetCamZ = catPos.z - Math.cos(catHeading) * offsetDist;
      const targetCamY = catPos.y + offsetHeight;

      camera.position.lerp(new THREE.Vector3(targetCamX, targetCamY, targetCamZ), 0.08);
      camera.lookAt(catPos.x, catPos.y + 2.0, catPos.z);
    }
  } else {
    // Standard OrbitControls update (handles autoRotate, mouse drag, mouse wheel)
    controls.update();
  }

  // Update City animated beacons
  city.update(time);

  // Update Forge hammer, shockwaves, sparks
  forge.update(delta, time);

  // Update Cat village trotting and hopping
  catVillage.update(delta, time, state.spinning);

  // Render post-processing pipeline
  composer.render();
}

// Start loop
animate();


