import * as THREE from 'three';
import {
  createSkyscraperTexture,
  createRoadTexture,
  createLightPoolTexture,
  createHelipadTexture
} from './textures.js';

/**
 * Builds the high-density cyberpunk / blacksmith Moru City.
 * Features:
 * - 60+ multi-tier skyscrapers with rooftop neon trims, helipads, spires
 * - Central plaza clearance (Math.hypot(x, z) < 35 completely free of buildings)
 * - Paved road grid with lane markings and crosswalks
 * - 70+ multi-foliage stylized trees
 * - 90+ streetlamps with glowing bulbs and ground light pool discs
 */
export function createCity(scene) {
  const cityGroup = new THREE.Group();
  cityGroup.name = 'city';
  scene.add(cityGroup);

  // Reusable materials & textures
  const windowTex0 = createSkyscraperTexture(0);
  const windowTex1 = createSkyscraperTexture(1);
  const windowTex2 = createSkyscraperTexture(2);
  const windowTextures = [windowTex0, windowTex1, windowTex2];

  const roadTex = createRoadTexture();
  const helipadTex = createHelipadTexture();
  const lightPoolTex = createLightPoolTexture('#ffe599');

  const groundMat = new THREE.MeshStandardMaterial({
    color: 0x1b1f2e,
    roughness: 0.85,
    metalness: 0.2
  });

  const sidewalkMat = new THREE.MeshStandardMaterial({
    color: 0x242a3d,
    roughness: 0.75,
    metalness: 0.25
  });

  const roadMat = new THREE.MeshStandardMaterial({
    map: roadTex,
    roughness: 0.6,
    metalness: 0.15
  });

  const buildingDarkMat = new THREE.MeshStandardMaterial({
    color: 0x131622,
    roughness: 0.5,
    metalness: 0.5
  });

  const neonTrimColors = [0x00f2fe, 0xff007f, 0xffd166, 0x00ff88, 0x7000ff];
  const beaconMeshes = [];

  // ==========================================
  // 1. GROUND PLANE & PLAZA PERIMETER
  // ==========================================
  // Large ground plane
  const groundGeo = new THREE.PlaneGeometry(320, 320, 4, 4);
  const groundMesh = new THREE.Mesh(groundGeo, groundMat);
  groundMesh.rotation.x = -Math.PI / 2;
  groundMesh.position.y = -0.05;
  groundMesh.receiveShadow = true;
  cityGroup.add(groundMesh);

  // Outer plaza paved ring
  const plazaRingGeo = new THREE.RingGeometry(22, 34, 32);
  const plazaRingMesh = new THREE.Mesh(plazaRingGeo, sidewalkMat);
  plazaRingMesh.rotation.x = -Math.PI / 2;
  plazaRingMesh.position.y = 0.02;
  plazaRingMesh.receiveShadow = true;
  cityGroup.add(plazaRingMesh);

  // ==========================================
  // 2. PAVED ROADS & CROSSWALKS
  // ==========================================
  const roadWidth = 12;
  const avenueLength = 120;

  // 4 Grand Avenues radiating along +/-X and +/-Z from plaza edge (r=34 to 150)
  const avenueConfigs = [
    { x: 0, z: 92, rotY: 0, length: avenueLength },       // South
    { x: 0, z: -92, rotY: Math.PI, length: avenueLength }, // North
    { x: 92, z: 0, rotY: Math.PI / 2, length: avenueLength }, // East
    { x: -92, z: 0, rotY: -Math.PI / 2, length: avenueLength } // West
  ];

  avenueConfigs.forEach(cfg => {
    // Road asphalt mesh with lane markings
    const roadGeo = new THREE.PlaneGeometry(roadWidth, cfg.length, 1, 16);
    // Adjust UVs so road texture repeats along the length
    const uvAttr = roadGeo.attributes.uv;
    for (let i = 0; i < uvAttr.count; i++) {
      uvAttr.setY(i, uvAttr.getY(i) * 12);
    }
    roadGeo.uvsNeedUpdate = true;

    const roadMesh = new THREE.Mesh(roadGeo, roadMat);
    roadMesh.rotation.x = -Math.PI / 2;
    roadMesh.rotation.z = cfg.rotY;
    roadMesh.position.set(cfg.x, 0.04, cfg.z);
    roadMesh.receiveShadow = true;
    cityGroup.add(roadMesh);

    // Sidewalk borders flanking the avenue
    [-roadWidth / 2 - 1.5, roadWidth / 2 + 1.5].forEach(sideOffset => {
      const swGeo = new THREE.BoxGeometry(3, 0.18, cfg.length);
      const swMesh = new THREE.Mesh(swGeo, sidewalkMat);
      if (cfg.rotY === 0 || cfg.rotY === Math.PI) {
        swMesh.position.set(cfg.x + sideOffset, 0.09, cfg.z);
      } else {
        swMesh.position.set(cfg.x, 0.09, cfg.z + sideOffset);
        swMesh.rotation.y = Math.PI / 2;
      }
      swMesh.receiveShadow = true;
      cityGroup.add(swMesh);
    });
  });

  // Concentric circular / octagonal boulevard surrounding the central plaza
  const ringRoadGeo = new THREE.RingGeometry(35, 47, 48);
  const ringRoadMesh = new THREE.Mesh(ringRoadGeo, sidewalkMat);
  ringRoadMesh.rotation.x = -Math.PI / 2;
  ringRoadMesh.position.y = 0.03;
  ringRoadMesh.receiveShadow = true;
  cityGroup.add(ringRoadMesh);

  // Outer ring road
  const outerRingGeo = new THREE.RingGeometry(95, 107, 48);
  const outerRingMesh = new THREE.Mesh(outerRingGeo, sidewalkMat);
  outerRingMesh.rotation.x = -Math.PI / 2;
  outerRingMesh.position.y = 0.03;
  outerRingMesh.receiveShadow = true;
  cityGroup.add(outerRingMesh);

  // ==========================================
  // 3. 60+ MULTI-TIER SKYSCRAPERS
  // ==========================================
  // We place buildings in city blocks outside radius 36.
  const buildings = [];
  const buildingCandidatePositions = [];

  // Generate a regular grid of urban blocks outside radius 36
  const gridSize = 14;
  const extent = 140;
  for (let x = -extent; x <= extent; x += gridSize) {
    for (let z = -extent; z <= extent; z += gridSize) {
      const distFromCenter = Math.hypot(x, z);
      // Strictly keep central plaza open (dist >= 37)
      if (distFromCenter < 37) continue;

      // Avoid intersecting the main 4 avenues (roadWidth ~ 12, keep 10 clearance)
      if (Math.abs(x) < 9 && Math.abs(z) > 30) continue;
      if (Math.abs(z) < 9 && Math.abs(x) > 30) continue;

      // Add building location with slight organic jitter
      const jitterX = (Math.sin(x * 13.5 + z * 7.1) * 2.2);
      const jitterZ = (Math.cos(x * 9.2 + z * 15.3) * 2.2);
      const posX = x + jitterX;
      const posZ = z + jitterZ;

      if (Math.hypot(posX, posZ) >= 36.5) {
        buildingCandidatePositions.push({ x: posX, z: posZ, dist: distFromCenter });
      }
    }
  }

  // Sort candidate positions and pick ~68 well-distributed skyscraper locations
  buildingCandidatePositions.sort((a, b) => a.dist - b.dist);
  const targetSkyscraperCount = 68;
  const step = Math.max(1, Math.floor(buildingCandidatePositions.length / targetSkyscraperCount));
  const selectedBuildings = [];
  for (let i = 0; i < buildingCandidatePositions.length && selectedBuildings.length < targetSkyscraperCount; i += step) {
    selectedBuildings.push(buildingCandidatePositions[i]);
  }
  // If slightly short, take remaining ones
  for (let i = 0; i < buildingCandidatePositions.length && selectedBuildings.length < targetSkyscraperCount; i++) {
    if (!selectedBuildings.includes(buildingCandidatePositions[i])) {
      selectedBuildings.push(buildingCandidatePositions[i]);
    }
  }

  selectedBuildings.forEach((pos, idx) => {
    const building = new THREE.Group();
    building.name = `skyscraper_${idx}`;
    building.position.set(pos.x, 0, pos.z);

    // Height variation: taller toward city perimeter, mid heights near plaza
    const heightFactor = 0.5 + (pos.dist / extent) * 0.9;
    const baseHeight = 24 + (Math.sin(idx * 7.3) * 0.5 + 0.5) * 60 * heightFactor;
    const towerWidth = 8 + (idx % 4) * 1.5;
    const towerDepth = 8 + ((idx + 2) % 4) * 1.5;

    // Pick texture variant
    const texVariant = idx % windowTextures.length;
    const facadeTex = windowTextures[texVariant];

    const facadeMat = new THREE.MeshStandardMaterial({
      map: facadeTex,
      emissiveMap: facadeTex,
      roughness: 0.4,
      metalness: 0.3,
      emissive: 0xffffff,
      emissiveIntensity: 1.15
    });

    // Tier 1: Base podium / Lower Tower
    const tier1Height = baseHeight * 0.55;
    const tier1Geo = new THREE.BoxGeometry(towerWidth, tier1Height, towerDepth, 2, 8, 2);
    const tier1Mesh = new THREE.Mesh(tier1Geo, facadeMat);
    tier1Mesh.position.y = tier1Height / 2;
    tier1Mesh.castShadow = (idx % 4 === 0); // Optimize shadow casting to avoid FPS drop
    tier1Mesh.receiveShadow = true;
    building.add(tier1Mesh);

    // Tier 2: Slender Middle Tower (setback)
    const tier2Width = towerWidth * 0.78;
    const tier2Depth = towerDepth * 0.78;
    const tier2Height = baseHeight * 0.35;
    const tier2Geo = new THREE.BoxGeometry(tier2Width, tier2Height, tier2Depth, 2, 6, 2);
    const tier2Mesh = new THREE.Mesh(tier2Geo, facadeMat);
    tier2Mesh.position.y = tier1Height + tier2Height / 2;
    tier2Mesh.castShadow = (idx % 4 === 0);
    tier2Mesh.receiveShadow = true;
    building.add(tier2Mesh);

    // Tier 3: Rooftop Crown / Penthouse
    const tier3Width = tier2Width * 0.75;
    const tier3Depth = tier2Depth * 0.75;
    const tier3Height = baseHeight * 0.10 + 2;
    const tier3Geo = new THREE.BoxGeometry(tier3Width, tier3Height, tier3Depth, 2, 2, 2);
    const tier3Mesh = new THREE.Mesh(tier3Geo, buildingDarkMat);
    tier3Mesh.position.y = tier1Height + tier2Height + tier3Height / 2;
    building.add(tier3Mesh);

    const totalRoofY = tier1Height + tier2Height + tier3Height;

    // Rooftop Neon Trim Wireframe Frame
    const trimColor = neonTrimColors[idx % neonTrimColors.length];
    const trimMat = new THREE.MeshBasicMaterial({
      color: trimColor,
      wireframe: true
    });
    const trimGeo = new THREE.BoxGeometry(tier2Width + 0.3, 0.8, tier2Depth + 0.3);
    const trimMesh = new THREE.Mesh(trimGeo, trimMat);
    trimMesh.position.y = tier1Height + tier2Height + 0.4;
    building.add(trimMesh);

    // Helipad on select buildings
    if (idx % 5 === 0) {
      const helipadMat = new THREE.MeshStandardMaterial({
        map: helipadTex,
        roughness: 0.7
      });
      const heliGeo = new THREE.BoxGeometry(tier2Width * 0.9, 0.4, tier2Depth * 0.9);
      const heliMesh = new THREE.Mesh(heliGeo, helipadMat);
      heliMesh.position.y = totalRoofY + 0.2;
      building.add(heliMesh);
    }

    // Architectural Spire / Antenna on taller buildings
    if (idx % 3 === 0 || baseHeight > 55) {
      const spireHeight = 6 + (idx % 5) * 2.5;
      const spireGeo = new THREE.CylinderGeometry(0.08, 0.35, spireHeight, 8);
      const spireMat = new THREE.MeshStandardMaterial({
        color: 0x99aab5,
        metalness: 0.9,
        roughness: 0.2
      });
      const spireMesh = new THREE.Mesh(spireGeo, spireMat);
      spireMesh.position.y = totalRoofY + spireHeight / 2;
      building.add(spireMesh);

      // Blinking rooftop beacon light sphere at top of spire
      const beaconGeo = new THREE.SphereGeometry(0.35, 12, 12);
      const beaconMat = new THREE.MeshBasicMaterial({
        color: (idx % 2 === 0) ? 0xff2244 : 0x00f2fe
      });
      const beaconMesh = new THREE.Mesh(beaconGeo, beaconMat);
      beaconMesh.position.y = totalRoofY + spireHeight;
      building.add(beaconMesh);
      beaconMeshes.push({ mesh: beaconMesh, offset: idx * 0.7 });
    }

    // Rooftop HVAC / mechanical units for rich skyline detail
    const hvacCount = 2 + (idx % 3);
    for (let h = 0; h < hvacCount; h++) {
      const hvacGeo = new THREE.BoxGeometry(1.6, 1.2, 1.6);
      const hvacMesh = new THREE.Mesh(hvacGeo, buildingDarkMat);
      const hx = ((h % 2 === 0) ? 1 : -1) * (tier3Width * 0.25);
      const hz = ((h > 0) ? 1 : -1) * (tier3Depth * 0.25);
      hvacMesh.position.set(hx, totalRoofY + 0.6, hz);
      building.add(hvacMesh);
    }

    cityGroup.add(building);
    buildings.push(building);
  });

  // ==========================================
  // 4. 70+ STYLIZED MULTI-FOLIAGE TREES
  // ==========================================
  const treeCount = 84;
  const trees = [];
  const treeFoliageColors = [
    0x00e676, // Cyber Emerald
    0x2ecc71, // Bright Jade
