function createProceduralWindowTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = '#0f1422';
  ctx.fillRect(0, 0, 256, 512);

  const rows = 32;
  const cols = 8;
  const padX = 6;
  const padY = 4;
  const w = (256 - padX * (cols + 1)) / cols;
  const h = (512 - padY * (rows + 1)) / rows;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const lit = Math.random() > 0.35;
      if (lit) {
        const tone = Math.random();
        if (tone > 0.8) ctx.fillStyle = '#ffaa00'; // warm gold
        else if (tone > 0.5) ctx.fillStyle = '#00f3ff'; // cyan neon
        else if (tone > 0.3) ctx.fillStyle = '#ffffff'; // white
        else ctx.fillStyle = '#ff007f'; // neon magenta
      } else {
        ctx.fillStyle = '#161d30';
      }
      ctx.fillRect(padX + c * (w + padX), padY + r * (h + padY), w, h);
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  return texture;
}

