// Continuous Embers
function initContinuousEmbers() {
  const emberCount = 60;
  const emberGeo = new THREE.BufferGeometry();
  const positions = new Float32Array(emberCount * 3);
  const velocities = [];

  for (let i = 0; i < emberCount; i++) {
    const angle = Math.random() * Math.PI * 2;
    const r = Math.random() * 2.2;
    positions[i * 3] = Math.cos(angle) * r;
    positions[i * 3 + 1] = 2.1 + Math.random() * 2.5;
    positions[i * 3 + 2] = Math.sin(angle) * r;

    velocities.push({
      vx: (Math.random() - 0.5) * 0.015,
      vy: 0.015 + Math.random() * 0.035,
      vz: (Math.random() - 0.5) * 0.015
    });
  }

  emberGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));

  const emberMat = new THREE.PointsMaterial({
    color: 0xffaa00,
    size: 0.18,
    transparent: true,
    opacity: 0.85,
    blending: THREE.AdditiveBlending
  });

  const emberSystem = new THREE.Points(emberGeo, emberMat);
  scene.add(emberSystem);

  emberParticles = {
    system: emberSystem,
    positions,
    velocities,
    count: emberCount
  };
}
initContinuousEmbers();

// Spark Bursts on Anvil Strike
function triggerSparkBurst() {
  const count = 120;
  const sparkGeo = new THREE.BufferGeometry();
  const posArray = new Float32Array(count * 3);
  const velList = [];

  for (let i = 0; i < count; i++) {
    posArray[i * 3] = 0;
    posArray[i * 3 + 1] = 3.7;
    posArray[i * 3 + 2] = 0;

    const theta = Math.random() * Math.PI * 2;
    const phi = Math.random() * Math.PI * 0.45;
    const speed = 4 + Math.random() * 10;

    velList.push({
      vx: Math.sin(phi) * Math.cos(theta) * speed,
      vy: Math.cos(phi) * speed,
      vz: Math.sin(phi) * Math.sin(theta) * speed,
      life: 1.0,
      decay: 0.8 + Math.random() * 0.8
    });
  }

  sparkGeo.setAttribute('position', new THREE.BufferAttribute(posArray, 3));

  const sparkMat = new THREE.PointsMaterial({
    color: 0xffdd44,
    size: 0.28,
    transparent: true,
    opacity: 1.0,
    blending: THREE.AdditiveBlending
  });

  const sparkMesh = new THREE.Points(sparkGeo, sparkMat);
  scene.add(sparkMesh);

  sparkParticles.push({
    mesh: sparkMesh,
    geo: sparkGeo,
    mat: sparkMat,
    vels: velList,
    positions: posArray,
    count
  });
}

