function buildCitySkyline() {
  const buildingsGroup = new THREE.Group();
  const neonSignColors = [0x00f3ff, 0xff007f, 0xffaa00, 0x00ff88];

  const quadrants = [
    { startX: 18, endX: 75, startZ: 18, endZ: 75 },
    { startX: -75, endX: -18, startZ: 18, endZ: 75 },
    { startX: 18, endX: 75, startZ: -75, endZ: -18 },
    { startX: -75, endX: -18, startZ: -75, endZ: -18 }
  ];

  quadrants.forEach(q => {
    const count = 7;
    for (let i = 0; i < count; i++) {
      const w = 8 + Math.random() * 7;
      const d = 8 + Math.random() * 7;
      const h = 18 + Math.random() * 42;

      const x = q.startX + Math.random() * (q.endX - q.startX - w) + w / 2;
      const z = q.startZ + Math.random() * (q.endZ - q.startZ - d) + d / 2;

      const bGeo = new THREE.BoxGeometry(w, h, d);
      const bMat = new THREE.MeshStandardMaterial({
        color: 0x141b2a,
        roughness: 0.4,
        metalness: 0.5,
        map: windowTexture
      });
      const building = new THREE.Mesh(bGeo, bMat);
      building.position.set(x, h / 2, z);
      building.castShadow = true;
      building.receiveShadow = true;
      buildingsGroup.add(building);

      if (Math.random() > 0.4) {
        const spireH = 5 + Math.random() * 8;
        const spireGeo = new THREE.CylinderGeometry(0.1, 0.25, spireH, 6);
        const spireMat = new THREE.MeshBasicMaterial({ color: 0xff0055 });
        const spire = new THREE.Mesh(spireGeo, spireMat);
        spire.position.set(x, h + spireH / 2, z);
        buildingsGroup.add(spire);

        const beaconGeo = new THREE.SphereGeometry(0.35, 8, 8);
        const beaconMat = new THREE.MeshBasicMaterial({ color: 0xff0044 });
        const beacon = new THREE.Mesh(beaconGeo, beaconMat);
        beacon.position.set(x, h + spireH, z);
        buildingsGroup.add(beacon);
      }

      if (Math.random() > 0.3) {
        const signColor = neonSignColors[Math.floor(Math.random() * neonSignColors.length)];
        const signGeo = new THREE.BoxGeometry(w * 0.6, 1.6, 0.4);
        const signMat = new THREE.MeshStandardMaterial({
          color: signColor,
          emissive: signColor,
          emissiveIntensity: 1.6,
          roughness: 0.2
        });
        const sign = new THREE.Mesh(signGeo, signMat);
        sign.position.set(x, h * 0.7, z + d / 2 + 0.2);
        buildingsGroup.add(sign);
      }
    }
  });

  // Distant mountain skyline
  for (let i = 0; i < 20; i++) {
    const ang = (i / 20) * Math.PI * 2;
    const dist = 115 + Math.random() * 15;
    const mx = Math.cos(ang) * dist;
    const mz = Math.sin(ang) * dist;
    const mh = 35 + Math.random() * 45;
    const mw = 25 + Math.random() * 20;

    const mGeo = new THREE.ConeGeometry(mw, mh, 4);
    const mMat = new THREE.MeshStandardMaterial({
      color: 0x0a1020,
      roughness: 0.9,
      metalness: 0.1
    });
    const mountain = new THREE.Mesh(mGeo, mMat);
    mountain.position.set(mx, mh / 2, mz);
    mountain.rotation.y = Math.random() * Math.PI;
    buildingsGroup.add(mountain);
  }

  cityGroup.add(buildingsGroup);
}
buildCitySkyline();

