// --- Cute 3D Moru Cat Character Class ---

const CAT_COAT_PALETTES = [
  { name: 'Moru White Gold', body: 0xffffff, accent: 0xffaa00, innerEar: 0xff99bb, eyes: 0x00d4ff },
  { name: 'Calico Neko', body: 0xf4eedb, accent: 0xd96726, innerEar: 0xff99bb, eyes: 0x228b22 },
  { name: 'Cyber Neon Cat', body: 0x1b2438, accent: 0x00f3ff, innerEar: 0x00f3ff, eyes: 0xff007f },
  { name: 'Ginger Tabby', body: 0xf58a27, accent: 0xbf5504, innerEar: 0xffaabb, eyes: 0x38b000 },
  { name: 'Tuxedo Neko', body: 0x181a1f, accent: 0xffffff, innerEar: 0xff99bb, eyes: 0xffd000 }
];

class MoruCat {
  constructor(id, palette, startPos) {
    this.id = id;
    this.palette = palette;
    this.group = new THREE.Group();
    this.group.name = `moru-cat-${id}`;

    this.state = 'walk'; // 'walk', 'run', 'jump', 'idle', 'celebrate'
    this.stateTimer = 0;
    this.animTime = Math.random() * 100;
    this.speed = 2.4 + Math.random() * 1.2;
    this.jumpHeight = 0;
    this.jumpVelocity = 0;
    this.turnSpeed = 3.5;

    this.position = startPos.clone();
    this.target = new THREE.Vector3(
      (Math.random() - 0.5) * 36,
      0,
      (Math.random() - 0.5) * 36
    );
    this.velocity = new THREE.Vector3();
    this.headingAngle = Math.random() * Math.PI * 2;

    this.buildMesh();
    this.group.position.copy(this.position);
    scene.add(this.group);
  }

  buildMesh() {
    const coatMat = new THREE.MeshStandardMaterial({
      color: this.palette.body,
      roughness: 0.65,
      metalness: 0.1
    });

    const accentMat = new THREE.MeshStandardMaterial({
      color: this.palette.accent,
      roughness: 0.65,
      metalness: 0.1
    });

    const innerEarMat = new THREE.MeshStandardMaterial({
      color: this.palette.innerEar,
      roughness: 0.8
    });

    const eyeMat = new THREE.MeshStandardMaterial({
      color: this.palette.eyes,
      roughness: 0.2,
      metalness: 0.5
    });

    const noseMat = new THREE.MeshStandardMaterial({
      color: 0xff7799,
      roughness: 0.4
    });

    const whitePawMat = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.6
    });

    this.modelRoot = new THREE.Group();
    this.group.add(this.modelRoot);

    // Chubby Cat Body
    const bodyGeo = new THREE.BoxGeometry(0.85, 0.75, 1.3);
    this.bodyMesh = new THREE.Mesh(bodyGeo, coatMat);
    this.bodyMesh.position.y = 0.65;
    this.bodyMesh.castShadow = true;
    this.modelRoot.add(this.bodyMesh);

    // Back Patch
    const patchGeo = new THREE.BoxGeometry(0.65, 0.15, 0.75);
    const patchMesh = new THREE.Mesh(patchGeo, accentMat);
    patchMesh.position.set(0, 0.4, -0.05);
    this.bodyMesh.add(patchMesh);

    // Chibi Head
    this.headGroup = new THREE.Group();
    this.headGroup.position.set(0, 0.95, 0.65);
    this.modelRoot.add(this.headGroup);

    const headGeo = new THREE.BoxGeometry(0.88, 0.78, 0.78);
    const headMesh = new THREE.Mesh(headGeo, coatMat);
    headMesh.castShadow = true;
    this.headGroup.add(headMesh);

    // Cheeks
    const cheekGeo = new THREE.SphereGeometry(0.24, 8, 8);
    const cheekLeft = new THREE.Mesh(cheekGeo, whitePawMat);
    cheekLeft.position.set(-0.25, -0.15, 0.36);
    this.headGroup.add(cheekLeft);

    const cheekRight = new THREE.Mesh(cheekGeo, whitePawMat);
    cheekRight.position.set(0.25, -0.15, 0.36);
    this.headGroup.add(cheekRight);

    // Nose
    const noseGeo = new THREE.ConeGeometry(0.06, 0.08, 4);
    const noseMesh = new THREE.Mesh(noseGeo, noseMat);
    noseMesh.rotation.x = Math.PI;
    noseMesh.position.set(0, -0.08, 0.46);
    this.headGroup.add(noseMesh);

    // Big Eyes
    const eyeGeo = new THREE.SphereGeometry(0.12, 12, 12);
    const eyeL = new THREE.Mesh(eyeGeo, eyeMat);
    eyeL.position.set(-0.24, 0.06, 0.38);
    this.headGroup.add(eyeL);

    const eyeR = new THREE.Mesh(eyeGeo, eyeMat);
    eyeR.position.set(0.24, 0.06, 0.38);
    this.headGroup.add(eyeR);

    // Ears
    const earGeo = new THREE.ConeGeometry(0.22, 0.36, 4);
    const innerEarGeo = new THREE.ConeGeometry(0.14, 0.26, 4);

    const earL = new THREE.Mesh(earGeo, accentMat);
    earL.position.set(-0.28, 0.48, 0.05);
    earL.rotation.z = 0.2;
    earL.castShadow = true;
    this.headGroup.add(earL);

    const innerEarL = new THREE.Mesh(innerEarGeo, innerEarMat);
    innerEarL.position.set(-0.28, 0.47, 0.09);
    innerEarL.rotation.z = 0.2;
    this.headGroup.add(innerEarL);

    const earR = new THREE.Mesh(earGeo, accentMat);
    earR.position.set(0.28, 0.48, 0.05);
    earR.rotation.z = -0.2;
    earR.castShadow = true;
    this.headGroup.add(earR);

    const innerEarR = new THREE.Mesh(innerEarGeo, innerEarMat);
    innerEarR.position.set(0.28, 0.47, 0.09);
    innerEarR.rotation.z = -0.2;
    this.headGroup.add(innerEarR);

    // Whiskers
    const whiskerMat = new THREE.LineBasicMaterial({ color: 0xdddddd });
    [-1, 1].forEach(side => {
      [-0.04, 0.04].forEach(angle => {
        const points = [
          new THREE.Vector3(side * 0.25, -0.12, 0.38),
          new THREE.Vector3(side * 0.58, -0.12 + angle, 0.45)
        ];
        const wGeo = new THREE.BufferGeometry().setFromPoints(points);
        const whisker = new THREE.Line(wGeo, whiskerMat);
        this.headGroup.add(whisker);
      });
    });

    // Collar & Bell
    const collarGeo = new THREE.TorusGeometry(0.42, 0.05, 8, 16);
    const collarMat = new THREE.MeshStandardMaterial({ color: 0xff0055 });
    const collar = new THREE.Mesh(collarGeo, collarMat);
    collar.rotation.x = Math.PI / 2;
    collar.position.set(0, 0.65, 0.5);
    this.modelRoot.add(collar);

    const bellGeo = new THREE.SphereGeometry(0.1, 8, 8);
    const bellMat = new THREE.MeshStandardMaterial({ color: 0xffcc00, metalness: 0.9, roughness: 0.2 });
    const bell = new THREE.Mesh(bellGeo, bellMat);
    bell.position.set(0, 0.58, 0.88);
    this.modelRoot.add(bell);

    // Legs
    this.legs = [];
    const legGeo = new THREE.CylinderGeometry(0.12, 0.1, 0.38, 8);
    const pawGeo = new THREE.SphereGeometry(0.13, 8, 8);

    const legPositions = [
      { x: -0.32, z: 0.4, name: 'FL' },
      { x: 0.32, z: 0.4, name: 'FR' },
      { x: -0.32, z: -0.4, name: 'BL' },
      { x: 0.32, z: -0.4, name: 'BR' }
    ];

    legPositions.forEach(lp => {
      const legPivot = new THREE.Group();
      legPivot.position.set(lp.x, 0.42, lp.z);

      const legMesh = new THREE.Mesh(legGeo, coatMat);
      legMesh.position.y = -0.14;
      legMesh.castShadow = true;
      legPivot.add(legMesh);

      const pawMesh = new THREE.Mesh(pawGeo, whitePawMat);
      pawMesh.position.y = -0.3;
      legPivot.add(pawMesh);

      this.modelRoot.add(legPivot);
      this.legs.push({ pivot: legPivot, name: lp.name });
    });

    // Segmented Tail
    this.tailSegments = [];
    let parentJoint = this.bodyMesh;
    let jointPos = new THREE.Vector3(0, 0.15, -0.65);

    for (let t = 0; t < 3; t++) {
      const joint = new THREE.Group();
      joint.position.copy(jointPos);
      parentJoint.add(joint);

      const segGeo = new THREE.CylinderGeometry(0.08 - t * 0.015, 0.08 - t * 0.015, 0.32, 6);
      const segMesh = new THREE.Mesh(segGeo, t === 2 ? accentMat : coatMat);
      segMesh.position.set(0, 0.15, -0.1);
      segMesh.rotation.x = -Math.PI / 4;
      segMesh.castShadow = true;
      joint.add(segMesh);

      this.tailSegments.push(joint);
      parentJoint = joint;
      jointPos = new THREE.Vector3(0, 0.25, -0.18);
    }
  }

  jumpExcited() {
    this.state = 'celebrate';
    this.stateTimer = 1.2;
    this.jumpVelocity = 8.5;
    soundCtrl.playMeow();
  }

  update(dt) {
    this.animTime += dt * 6;
    this.stateTimer -= dt;

    if (this.stateTimer <= 0) {
      const r = Math.random();
      if (r < 0.6) {
        this.state = 'walk';
        this.stateTimer = 4 + Math.random() * 6;
        this.speed = 2.0 + Math.random() * 1.5;
      } else if (r < 0.8) {
        this.state = 'run';
        this.stateTimer = 2.5 + Math.random() * 3.5;
        this.speed = 4.5 + Math.random() * 2.0;
      } else {
        this.state = 'idle';
        this.stateTimer = 2 + Math.random() * 3;
        this.speed = 0;
      }

      const angle = Math.random() * Math.PI * 2;
      const dist = 6 + Math.random() * 28;
      this.target.set(Math.cos(angle) * dist, 0, Math.sin(angle) * dist);
    }

    const toTarget = new THREE.Vector3().subVectors(this.target, this.position);
    toTarget.y = 0;
    const distToTarget = toTarget.length();

    if (distToTarget < 2.0) {
      this.stateTimer = 0;
    }

    if (this.speed > 0 && distToTarget > 0.1) {
      toTarget.normalize();
      const desiredAngle = Math.atan2(toTarget.x, toTarget.z);
      let diff = desiredAngle - this.headingAngle;
      while (diff < -Math.PI) diff += Math.PI * 2;
      while (diff > Math.PI) diff -= Math.PI * 2;
      this.headingAngle += diff * Math.min(1.0, this.turnSpeed * dt);

      this.velocity.set(
        Math.sin(this.headingAngle) * this.speed,
        0,
        Math.cos(this.headingAngle) * this.speed
      );
      this.position.addScaledVector(this.velocity, dt);
    }

    if (this.state === 'celebrate' || this.jumpHeight > 0) {
      this.jumpHeight += this.jumpVelocity * dt;
      this.jumpVelocity -= 22 * dt;

      if (this.jumpHeight <= 0) {
        this.jumpHeight = 0;
        this.jumpVelocity = 0;
        if (this.state === 'celebrate') {
          this.state = 'walk';
        }
      }
    }

    this.group.position.x = this.position.x;
    this.group.position.z = this.position.z;
    this.group.position.y = this.position.y + this.jumpHeight;
    this.group.rotation.y = this.headingAngle;

    if (this.state === 'walk' || this.state === 'run') {
      const freq = this.state === 'run' ? 14 : 9;
      const legSwing = Math.sin(this.animTime * (freq / 6)) * (this.state === 'run' ? 0.65 : 0.4);

      this.legs[0].pivot.rotation.x = legSwing;
      this.legs[1].pivot.rotation.x = -legSwing;
      this.legs[2].pivot.rotation.x = -legSwing;
      this.legs[3].pivot.rotation.x = legSwing;

      this.bodyMesh.position.y = 0.65 + Math.abs(Math.sin(this.animTime * (freq / 6))) * 0.1;
      this.headGroup.position.y = 0.95 + Math.sin(this.animTime * (freq / 6)) * 0.05;

      this.tailSegments.forEach((seg, i) => {
        seg.rotation.y = Math.sin(this.animTime * 1.5 + i * 0.4) * 0.35;
      });
    } else if (this.state === 'celebrate') {
      this.modelRoot.rotation.x = (this.jumpHeight / 2.5) * Math.PI * 2;
      this.tailSegments.forEach(seg => {
        seg.rotation.y = Math.sin(this.animTime * 4) * 0.6;
      });
    } else {
      this.legs.forEach(l => (l.pivot.rotation.x = 0));
      this.bodyMesh.position.y = 0.6;
      this.headGroup.rotation.y = Math.sin(this.animTime * 0.4) * 0.3;
      this.headGroup.rotation.z = Math.cos(this.animTime * 0.3) * 0.1;
      this.tailSegments.forEach((seg, i) => {
        seg.rotation.y = Math.sin(this.animTime * 0.8 + i * 0.5) * 0.2;
      });
      this.modelRoot.rotation.x = 0;
    }
  }
}

// Cat Spawning
function spawnNewCat() {
  const id = state.cats.length + 1;
  const palette = CAT_COAT_PALETTES[(id - 1) % CAT_COAT_PALETTES.length];
  const angle = Math.random() * Math.PI * 2;
  const dist = 5 + Math.random() * 8;
  const startPos = new THREE.Vector3(Math.cos(angle) * dist, 0.2, Math.sin(angle) * dist);

  const cat = new MoruCat(id, palette, startPos);
  cat.jumpExcited();
  state.cats.push(cat);
  state.targetFollowCat = cat;

  soundCtrl.playSpawnPop();
  updateHUDTelemetry();
  return cat;
}
state.spawnCat = spawnNewCat;

// Initial Cats
function initCats() {
  const initialCount = 4;
  for (let i = 0; i < initialCount; i++) {
    spawnNewCat();
  }
}
initCats();

// --- Forge Strike System ---
let isHammerStriking = false;
let hammerAnimTime = 0;

function strikeForge() {
  state.forgeStrikes += 1;
  state.forgeHeat = Math.min(2400, state.forgeHeat + 140);
  isHammerStriking = true;
  hammerAnimTime = 0;

  soundCtrl.playAnvilStrike();
  triggerSparkBurst();

  if (shockwaveRing) {
    shockwaveRing.scale.set(1, 1, 1);
    shockwaveRing.material.opacity = 1.0;
  }

  forgeLight.intensity = 18;
  if (forgeIngotMesh) {
    forgeIngotMesh.material.emissiveIntensity = 6.0;
  }

  if (anvilGroup) {
    anvilGroup.position.y = 2.25;
  }

  state.cats.forEach(c => {
    c.jumpExcited();
  });

  updateHUDTelemetry();
}
state.strikeForge = strikeForge;

// --- Atmosphere Theme Controller ---
function setTheme(themeKey) {
  const theme = THEMES[themeKey];
  if (!theme) return;
  state.activeTheme = themeKey;

  scene.background.set(theme.bgColor);
  scene.fog.color.set(theme.fogColor);
  scene.fog.near = theme.fogNear;
  scene.fog.far = theme.fogFar;

  ambientLight.color.set(theme.ambientColor);
  ambientLight.intensity = theme.ambientIntensity;

  dirLight.color.set(theme.sunColor);
  dirLight.intensity = theme.sunIntensity;

  forgeLight.color.set(theme.forgeColor);
  forgeLight.intensity = theme.forgeIntensity;

  groundMaterial.color.set(theme.groundColor);

  document.querySelectorAll('.theme-group .btn-chip').forEach(btn => btn.classList.remove('active'));
  const activeBtn = document.getElementById(`mode-${themeKey}`);
  if (activeBtn) activeBtn.classList.add('active');

  updateHUDTelemetry();
}
state.setTheme = setTheme;

// --- Camera Controller & Modes ---
const CAMERA_PRESETS = {
  overview: { pos: new THREE.Vector3(0, 48, 62), lookAt: new THREE.Vector3(0, 3, 0) },
  iso: { pos: new THREE.Vector3(42, 38, 42), lookAt: new THREE.Vector3(0, 2, 0) },
  street: { pos: new THREE.Vector3(0, 3.2, 22), lookAt: new THREE.Vector3(0, 3.8, 0) }
};

function setCameraMode(mode) {
  state.cameraMode = mode;

  document.querySelectorAll('.camera-group .btn-chip').forEach(btn => btn.classList.remove('active'));
  const activeBtn = document.getElementById(`cam-${mode}`);
  if (activeBtn) activeBtn.classList.add('active');

  if (mode === 'follow-cat') {
    if (!state.targetFollowCat && state.cats.length > 0) {
      state.targetFollowCat = state.cats[0];
    }
    controls.autoRotate = false;
  } else if (CAMERA_PRESETS[mode]) {
    const preset = CAMERA_PRESETS[mode];
    // Snap target and update autoRotate
    if (mode === 'street') {
      controls.autoRotate = false;
    } else {
      controls.autoRotate = state.isSpinning;
    }
  }

  updateHUDTelemetry();
}
state.setCameraMode = setCameraMode;

// --- HUD Telemetry Updates ---
const hudFps = document.getElementById('hud-fps');
const hudCats = document.getElementById('hud-cats');
const hudHeat = document.getElementById('hud-heat');
const hudStrikes = document.getElementById('hud-strikes');
const hudCam = document.getElementById('hud-cam');
const hudTheme = document.getElementById('hud-theme');

function updateHUDTelemetry() {
  if (hudCats) hudCats.textContent = state.cats.length;
  if (hudHeat) hudHeat.textContent = `${Math.round(state.forgeHeat)}°C`;
  if (hudStrikes) hudStrikes.textContent = state.forgeStrikes;
  if (hudCam) hudCam.textContent = state.cameraMode.toUpperCase();
  if (hudTheme) hudTheme.textContent = state.activeTheme.toUpperCase();
}

// --- Button Listeners ---
document.getElementById('btn-forge-strike')?.addEventListener('click', () => strikeForge());
document.getElementById('btn-spawn-cat')?.addEventListener('click', () => spawnNewCat());

const btnToggleSpin = document.getElementById('toggle-spin');
if (btnToggleSpin) {
  btnToggleSpin.addEventListener('click', () => {
