      textSpan.textContent = state.isSpinning ? 'Pause Spin' : 'Resume Spin';
    }
  });
}

document.getElementById('cam-overview')?.addEventListener('click', () => setCameraMode('overview'));
document.getElementById('cam-iso')?.addEventListener('click', () => setCameraMode('iso'));
document.getElementById('cam-street')?.addEventListener('click', () => setCameraMode('street'));
document.getElementById('cam-follow-cat')?.addEventListener('click', () => setCameraMode('follow-cat'));

document.getElementById('mode-night')?.addEventListener('click', () => setTheme('night'));
document.getElementById('mode-gold')?.addEventListener('click', () => setTheme('gold'));
document.getElementById('mode-day')?.addEventListener('click', () => setTheme('day'));

document.getElementById('btn-toggle-sound')?.addEventListener('click', () => {
  soundCtrl.isMuted = !soundCtrl.isMuted;
  const icon = document.getElementById('sound-icon');
  if (icon) icon.textContent = soundCtrl.isMuted ? '🔇' : '🔊';
});

// Pointer click interactions on 3D elements
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();

window.addEventListener('pointerdown', (e) => {
  if (e.target && e.target.closest('#ui-overlay') && !e.target.closest('#canvas-container')) return;

  mouse.x = (e.clientX / window.innerWidth) * 2 - 1;
  mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);

  if (anvilGroup) {
    const anvilHits = raycaster.intersectObjects(anvilGroup.children, true);
    if (anvilHits.length > 0) {
      strikeForge();
      return;
    }
  }

  for (const cat of state.cats) {
    const catHits = raycaster.intersectObjects(cat.group.children, true);
    if (catHits.length > 0) {
      cat.jumpExcited();
      state.targetFollowCat = cat;
      return;
    }
  }
});

// Window Resize
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
});

// --- Main Animation Loop ---
let lastTime = performance.now();
let frameCount = 0;
let lastFpsUpdate = performance.now();

function animate(now) {
  requestAnimationFrame(animate);

  const dt = Math.min((now - lastTime) / 1000, 0.1);
  lastTime = now;

  // FPS Telemetry
  frameCount++;
  if (now - lastFpsUpdate >= 500) {
    const fps = Math.round((frameCount * 1000) / (now - lastFpsUpdate));
    if (hudFps) hudFps.textContent = fps;
    frameCount = 0;
    lastFpsUpdate = now;
  }

  // Forge Heat Cooling
  if (state.forgeHeat > 850) {
    state.forgeHeat = Math.max(850, state.forgeHeat - dt * 25);
    if (hudHeat) hudHeat.textContent = `${Math.round(state.forgeHeat)}°C`;
  }

  // Forge Light Decay & Subtle Flicker
  const baseIntensity = THEMES[state.activeTheme].forgeIntensity;
  if (forgeLight.intensity > baseIntensity) {
    forgeLight.intensity = THREE.MathUtils.lerp(forgeLight.intensity, baseIntensity, dt * 3.5);
  }
  forgeLight.intensity += (Math.random() - 0.5) * 0.15;

  if (forgeIngotMesh && forgeIngotMesh.material.emissiveIntensity > 2.2) {
    forgeIngotMesh.material.emissiveIntensity = THREE.MathUtils.lerp(
      forgeIngotMesh.material.emissiveIntensity,
      2.2,
      dt * 4
    );
  }

  if (anvilGroup && anvilGroup.position.y > 2.1) {
    anvilGroup.position.y = THREE.MathUtils.lerp(anvilGroup.position.y, 2.1, dt * 10);
  }

  // Hammer Strike Motion
  if (isHammerStriking && blacksmithHammer) {
    hammerAnimTime += dt * 5;
    if (hammerAnimTime < 1.0) {
      const swing = Math.sin(hammerAnimTime * Math.PI);
      blacksmithHammer.position.y = 5.2 - swing * 1.8;
      blacksmithHammer.rotation.z = 0.35 - swing * 1.1;
    } else {
      isHammerStriking = false;
      blacksmithHammer.position.set(0, 5.2, 0);
      blacksmithHammer.rotation.z = 0.35;
    }
  }

  // Shockwave Ring Expansion
  if (shockwaveRing && shockwaveRing.material.opacity > 0.01) {
    const scale = shockwaveRing.scale.x + dt * 14;
    shockwaveRing.scale.set(scale, scale, 1);
    shockwaveRing.material.opacity = Math.max(0, shockwaveRing.material.opacity - dt * 2.2);
  }

  // Spark Particles
  for (let s = sparkParticles.length - 1; s >= 0; s--) {
    const sp = sparkParticles[s];
    let allDead = true;

    for (let i = 0; i < sp.count; i++) {
      const v = sp.vels[i];
      if (v.life > 0) {
        allDead = false;
        v.life -= dt * v.decay;

        sp.positions[i * 3] += v.vx * dt;
        sp.positions[i * 3 + 1] += v.vy * dt;
        sp.positions[i * 3 + 2] += v.vz * dt;

        v.vy -= 18 * dt;

        if (sp.positions[i * 3 + 1] < 0.85) {
          sp.positions[i * 3 + 1] = 0.85;
          v.vy = -v.vy * 0.45;
          v.vx *= 0.7;
          v.vz *= 0.7;
        }
      }
    }
    sp.geo.attributes.position.needsUpdate = true;
    sp.mat.opacity = THREE.MathUtils.lerp(sp.mat.opacity, 0, dt * 1.8);

    if (allDead || sp.mat.opacity <= 0.02) {
      scene.remove(sp.mesh);
      sp.geo.dispose();
      sp.mat.dispose();
      sparkParticles.splice(s, 1);
    }
  }

  // Continuous Forge Embers
  if (emberParticles.system) {
    const pos = emberParticles.positions;
    for (let i = 0; i < emberParticles.count; i++) {
      const v = emberParticles.velocities[i];
      pos[i * 3] += v.vx;
      pos[i * 3 + 1] += v.vy;
      pos[i * 3 + 2] += v.vz;

      if (pos[i * 3 + 1] > 6.5) {
        pos[i * 3 + 1] = 2.1;
        const angle = Math.random() * Math.PI * 2;
        const r = Math.random() * 2.2;
        pos[i * 3] = Math.cos(angle) * r;
        pos[i * 3 + 2] = Math.sin(angle) * r;
      }
    }
    emberParticles.system.geometry.attributes.position.needsUpdate = true;
  }

  // Update Cats
  state.cats.forEach(cat => cat.update(dt));

  // Camera Interpolation
  if (state.cameraMode === 'follow-cat' && state.targetFollowCat) {
    const catPos = state.targetFollowCat.group.position;
    const catHeading = state.targetFollowCat.headingAngle;
    const offsetDist = 6.5;
    const offsetHeight = 3.6;

    const desiredCamPos = new THREE.Vector3(
      catPos.x - Math.sin(catHeading) * offsetDist,
      catPos.y + offsetHeight,
      catPos.z - Math.cos(catHeading) * offsetDist
    );

    const desiredLookTarget = new THREE.Vector3(
      catPos.x,
      catPos.y + 1.2,
      catPos.z
    );

    camera.position.lerp(desiredCamPos, dt * 4.5);
    controls.target.lerp(desiredLookTarget, dt * 4.5);
  } else if (CAMERA_PRESETS[state.cameraMode]) {
    const preset = CAMERA_PRESETS[state.cameraMode];
    camera.position.lerp(preset.pos, dt * 2.8);
    controls.target.lerp(preset.lookAt, dt * 2.8);
  }

  controls.update();
  renderer.render(scene, camera);
}

requestAnimationFrame(animate);

// Expose Global App Handle
window.__app = {
  scene,
  camera,
  renderer,
  state
};

console.log('⚡ Moru 3D Neon Forge City & Animated Cat Village initialized!');


