:root {
  --bg-dark: #0a0e17;
  --panel-bg: rgba(14, 20, 36, 0.75);
  --panel-border: rgba(0, 243, 255, 0.25);
  --panel-border-hover: rgba(0, 243, 255, 0.6);
  --neon-cyan: #00f3ff;
  --neon-magenta: #ff007f;
  --neon-gold: #ffaa00;
  --neon-orange: #ff5500;
  --neon-green: #00ff88;
  --text-main: #f0f6fc;
  --text-muted: #8b9bb4;
  --font-display: 'Outfit', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  user-select: none;
  -webkit-user-select: none;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-display);
}

#canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

#canvas-container canvas {
  width: 100% !important;
  height: 100% !important;
  display: block;
}

#ui-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 10;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  pointer-events: none;
  padding: 16px 20px;
}

/* Header & Brand */
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  flex-wrap: wrap;
  pointer-events: auto;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--panel-bg);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  padding: 10px 18px;
  border-radius: 14px;
  border: 1px solid var(--panel-border);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4), inset 0 0 12px rgba(0, 243, 255, 0.08);
}

.brand-icon {
  font-size: 1.8rem;
  line-height: 1;
  filter: drop-shadow(0 0 8px var(--neon-cyan));
  animation: pulse-icon 2s infinite ease-in-out;
}

@keyframes pulse-icon {
  0%, 100% { transform: scale(1); filter: drop-shadow(0 0 8px var(--neon-cyan)); }
  50% { transform: scale(1.08); filter: drop-shadow(0 0 14px var(--neon-gold)); }
}

.brand-text h1 {
  font-size: 1.15rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #ffffff 30%, var(--neon-cyan) 80%, var(--neon-gold) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.brand-text .subtitle {
  font-size: 0.72rem;
  color: var(--text-muted);
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* Live Telemetry HUD Panel */
.telemetry-hud {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--panel-bg);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  padding: 8px 18px;
  border-radius: 12px;
  border: 1px solid var(--panel-border);
  font-family: var(--font-mono);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.telemetry-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 44px;
}

.telemetry-item .label {
  font-size: 0.62rem;
  font-weight: 600;
  color: var(--neon-cyan);
  letter-spacing: 0.08em;
}

.telemetry-item .val {
  font-size: 0.88rem;
  font-weight: 700;
  color: #fff;
}

.telemetry-separator {
  width: 1px;
  height: 24px;
  background: rgba(255, 255, 255, 0.12);
}

/* Controls Dock */
.controls-dock {
  align-self: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  pointer-events: auto;
  max-width: 900px;
  width: 100%;
}

.control-group {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--panel-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  padding: 8px 16px 10px 16px;
  border-radius: 14px;
  border: 1px solid var(--panel-border);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.45);
}

.group-title {
  font-size: 0.62rem;
  font-weight: 800;
  color: var(--text-muted);
  letter-spacing: 0.12em;
  margin-bottom: 6px;
  text-transform: uppercase;
}

.button-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: center;
}

.button-row-sm {
  gap: 6px;
}

/* Generic Button Styles */
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 20px;
  border: none;
  border-radius: 10px;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.9rem;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  overflow: hidden;
  text-decoration: none;
}

.btn:active {
  transform: scale(0.96);
}

/* Primary Strike Button */
.btn-primary {
  background: linear-gradient(135deg, #ff5500 0%, #ffaa00 100%);
  color: #120500;
  box-shadow: 0 0 16px rgba(255, 102, 0, 0.45), 0 4px 12px rgba(0, 0, 0, 0.3);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 0 24px rgba(255, 120, 0, 0.7), 0 6px 16px rgba(0, 0, 0, 0.4);
}

/* Secondary Spawn Cat Button */
.btn-secondary {
  background: linear-gradient(135deg, #00f3ff 0%, #00a2ff 100%);
  color: #021a24;
  box-shadow: 0 0 16px rgba(0, 243, 255, 0.4), 0 4px 12px rgba(0, 0, 0, 0.3);
}

.btn-secondary:hover {
  transform: translateY(-2px);
  box-shadow: 0 0 24px rgba(0, 243, 255, 0.65), 0 6px 16px rgba(0, 0, 0, 0.4);
}

/* Accent Spin Toggle Button */
.btn-accent {
  background: rgba(255, 255, 255, 0.08);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.btn-accent:hover {
  background: rgba(255, 255, 255, 0.16);
  border-color: rgba(255, 255, 255, 0.4);
}

.btn-accent.paused {
  background: rgba(255, 60, 60, 0.2);
  border-color: rgba(255, 80, 80, 0.5);
  color: #ff9999;
}

/* Chip Buttons (Camera & Themes) */
.btn-chip {
  padding: 6px 14px;
  font-size: 0.8rem;
  font-weight: 600;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-muted);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.btn-chip .chip-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.3);
  transition: all 0.2s;
}

.btn-chip:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.3);
}

.btn-chip.active {
  background: rgba(0, 243, 255, 0.15);
  color: var(--neon-cyan);
  border-color: var(--neon-cyan);
  box-shadow: 0 0 10px rgba(0, 243, 255, 0.35);
}

.btn-chip.active .chip-dot {
  background: var(--neon-cyan);
  box-shadow: 0 0 6px var(--neon-cyan);
}

.btn-chip.theme-gold.active {
  background: rgba(255, 170, 0, 0.18);
  color: var(--neon-gold);
  border-color: var(--neon-gold);
  box-shadow: 0 0 10px rgba(255, 170, 0, 0.35);
}

.btn-chip.theme-gold.active .chip-dot {
  background: var(--neon-gold);
  box-shadow: 0 0 6px var(--neon-gold);
}

.btn-chip.theme-day.active {
  background: rgba(100, 210, 255, 0.18);
  color: #64d2ff;
  border-color: #64d2ff;
  box-shadow: 0 0 10px rgba(100, 210, 255, 0.35);
}

.btn-chip.theme-day.active .chip-dot {
  background: #64d2ff;
  box-shadow: 0 0 6px #64d2ff;
}

/* Footer & Hints */
.app-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  pointer-events: auto;
  gap: 12px;
}

.interaction-hint {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--panel-bg);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  padding: 6px 14px;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 0.72rem;
  color: var(--text-muted);
}

.hint-badge {
  background: rgba(0, 243, 255, 0.2);
  color: var(--neon-cyan);
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.65rem;
}

.btn-sound {
  background: var(--panel-bg);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 50%;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: #fff;
  font-size: 1rem;
  transition: all 0.2s;
}

.btn-sound:hover {
  border-color: var(--neon-cyan);
  box-shadow: 0 0 10px rgba(0, 243, 255, 0.3);
}

/* Mobile Responsiveness */
@media (max-width: 768px) {
  #ui-overlay {
    padding: 10px;
  }
  .app-header {
    flex-direction: column;
    align-items: stretch;
  }
  .brand-text h1 {
    font-size: 0.95rem;
  }
  .controls-dock {
    width: 100%;
  }
  .interaction-hint {
    display: none;
  }
}


