import * as THREE from 'three';

/**
 * Expressive Chibi 3D Moru Cat Factory & Quadruped Locomotion Engine.
 * Each cat is constructed with >= 20 distinct articulated meshes:
 * 1. Rounded Torso (chibi barrel body)
 * 2. Cream/White Belly Patch
 * 3. Chibi Head (oversized cute feline head)
 * 4. Left Puffy Cheek
 * 5. Right Puffy Cheek
 * 6. Left Pointed Outer Ear
 * 7. Left Soft Pink Inner Ear
 * 8. Right Pointed Outer Ear
 * 9. Right Soft Pink Inner Ear
 * 10. Left Big Glossy Eye
 * 11. Left Pupil with White Catchlight Highlight
 * 12. Right Big Glossy Eye
 * 13. Right Pupil with White Catchlight Highlight
 * 14. Pink Snout & Muzzle
 * 15. Whisker Set
 * 16. Woven Collar Band
 * 17. Golden Spherical Brass Bell with Clapper Ring
 * 18. Miniature Artisan Blacksmith Helmet / Visor with Horns
 * 19. Front-Left Articulated Leg & Paw
 * 20. Front-Right Articulated Leg & Paw
 * 21. Back-Left Articulated Leg & Paw
 * 22. Back-Right Articulated Leg & Paw
 * 23. Proximal Tail Segment
 * 24. Distal Fluffy Tail Tip
 *
 * Each cat has `userData.isMoruCat = true` and autonomous waypoint path navigation.
 */

const CAT_PRESETS = [
  { name: 'Moru Classic', bodyColor: 0xf97316, bellyColor: 0xffedd5, eyeColor: 0x10b981, helmetColor: 0x334155, hornColor: 0xfacc15, collarColor: 0xef4444 },
  { name: 'Cyber Neon', bodyColor: 0x1e293b, bellyColor: 0x0f172a, eyeColor: 0x00f0ff, helmetColor: 0x0284c7, hornColor: 0x38bdf8, collarColor: 0x00f0ff },
  { name: 'Amber Smith', bodyColor: 0xd97706, bellyColor: 0xfef3c7, eyeColor: 0x059669, helmetColor: 0x78350f, hornColor: 0xf59e0b, collarColor: 0x8b5cf6 },
  { name: 'Sakura Forge', bodyColor: 0xf472b6, bellyColor: 0xfdf2f8, eyeColor: 0x0284c7, helmetColor: 0x9d174d, hornColor: 0xfb7185, collarColor: 0xec4899 },
  { name: 'Titan Steel', bodyColor: 0x64748b, bellyColor: 0xe2e8f0, eyeColor: 0xf59e0b, helmetColor: 0x1e293b, hornColor: 0xe2e8f0, collarColor: 0x10b981 },
  { name: 'Snow Cloud', bodyColor: 0xf8fafc, bellyColor: 0xffffff, eyeColor: 0x3b82f6, helmetColor: 0x475569, hornColor: 0x94a3b8, collarColor: 0xe11d48 }
];

export function createMoruCat(options = {}) {
  const {
    id = 0,
    preset = CAT_PRESETS[id % CAT_PRESETS.length],
    pathRadius = 14 + (id % 4) * 5,
    pathSpeed = 1.0 + (id % 3) * 0.25,
    startAngle = (id * Math.PI * 2) / 6,
    materialsToDispose = []
  } = options;

  const catGroup = new THREE.Group();
  catGroup.name = `moruCat_${id}`;
  catGroup.userData.isMoruCat = true; // Crucial requirement!
  catGroup.scale.set(0.9, 0.9, 0.9);

  // Common Materials for this cat
  const furMat = new THREE.MeshStandardMaterial({
    color: preset.bodyColor,
    roughness: 0.6,
    metalness: 0.1
  });
  materialsToDispose.push(furMat);

  const bellyMat = new THREE.MeshStandardMaterial({
    color: preset.bellyColor,
    roughness: 0.7,
    metalness: 0.05
  });
  materialsToDispose.push(bellyMat);

  const innerEarMat = new THREE.MeshStandardMaterial({
    color: 0xfb7185,
    roughness: 0.5
  });
  materialsToDispose.push(innerEarMat);

  const eyeWhiteMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  materialsToDispose.push(eyeWhiteMat);

  const eyeIrisMat = new THREE.MeshStandardMaterial({
    color: preset.eyeColor,
    roughness: 0.1,
    metalness: 0.2
  });
  materialsToDispose.push(eyeIrisMat);

  const eyePupilMat = new THREE.MeshBasicMaterial({ color: 0x09090b });
  materialsToDispose.push(eyePupilMat);

  const noseMat = new THREE.MeshStandardMaterial({
    color: 0xf43f5e,
    roughness: 0.4
  });
  materialsToDispose.push(noseMat);

  const collarMat = new THREE.MeshStandardMaterial({
    color: preset.collarColor,
    roughness: 0.3,
    metalness: 0.4
  });
  materialsToDispose.push(collarMat);

  const bellMat = new THREE.MeshStandardMaterial({
    color: 0xfbbf24,
    metalness: 0.9,
    roughness: 0.2
  });
  materialsToDispose.push(bellMat);

  const helmetMat = new THREE.MeshStandardMaterial({
    color: preset.helmetColor,
    metalness: 0.8,
    roughness: 0.3
  });
  materialsToDispose.push(helmetMat);

  const hornMat = new THREE.MeshStandardMaterial({
    color: preset.hornColor,
    metalness: 0.85,
    roughness: 0.2
  });
  materialsToDispose.push(hornMat);

  // -------------------------------------------------------------
  // 1. TORSO (Rounded Chibi Body)
  // -------------------------------------------------------------
  const bodyGroup = new THREE.Group();
  bodyGroup.name = 'catBodyGroup';
  bodyGroup.position.y = 1.35;
  catGroup.add(bodyGroup);

  // Main plump torso
  const torsoGeo = new THREE.CapsuleGeometry(0.75, 0.85, 12, 16);
  const torsoMesh = new THREE.Mesh(torsoGeo, furMat);
  torsoMesh.name = 'torso';
  torsoMesh.rotation.x = Math.PI / 2;
  torsoMesh.castShadow = true;
  bodyGroup.add(torsoMesh);

  // 2. Soft Belly Patch (Underbelly mesh)
  const bellyGeo = new THREE.SphereGeometry(0.68, 12, 12, 0, Math.PI, 0, Math.PI / 2);
  const bellyMesh = new THREE.Mesh(bellyGeo, bellyMat);
  bellyMesh.name = 'bellyPatch';
  bellyMesh.rotation.x = -Math.PI / 2;
  bellyMesh.position.set(0, -0.15, 0.05);
  bodyGroup.add(bellyMesh);

  // -------------------------------------------------------------
  // HEAD & EXPRESSIVE FACIAL ARCHITECTURE
  // -------------------------------------------------------------
  const headGroup = new THREE.Group();
  headGroup.name = 'catHeadGroup';
  headGroup.position.set(0, 0.65, 0.85);
  bodyGroup.add(headGroup);

  // 3. Oversized Chibi Head
  const headGeo = new THREE.SphereGeometry(0.95, 20, 16);
  const headMesh = new THREE.Mesh(headGeo, furMat);
  headMesh.name = 'chibiHead';
  headMesh.castShadow = true;
  headGroup.add(headMesh);

  // 4 & 5. Left and Right Puffy Cheeks
  const cheekGeo = new THREE.SphereGeometry(0.38, 12, 10);
  const cheekL = new THREE.Mesh(cheekGeo, bellyMat);
  cheekL.name = 'leftCheek';
  cheekL.position.set(-0.52, -0.22, 0.6);
  headGroup.add(cheekL);

  const cheekR = new THREE.Mesh(cheekGeo, bellyMat);
  cheekR.name = 'rightCheek';
  cheekR.position.set(0.52, -0.22, 0.6);
  headGroup.add(cheekR);

  // 6 & 7. Left Pointed Outer Ear + Pink Inner Ear
  const earGeo = new THREE.ConeGeometry(0.42, 0.7, 4);
  const earInnerGeo = new THREE.ConeGeometry(0.26, 0.5, 4);

  const earL = new THREE.Mesh(earGeo, furMat);
  earL.name = 'leftEar';
  earL.position.set(-0.58, 0.82, 0.1);
  earL.rotation.set(0.1, 0, 0.45);
  headGroup.add(earL);

  const earInnerL = new THREE.Mesh(earInnerGeo, innerEarMat);
  earInnerL.name = 'leftInnerEar';
  earInnerL.position.set(0, 0, 0.12);
  earL.add(earInnerL);

  // 8 & 9. Right Pointed Outer Ear + Pink Inner Ear
  const earR = new THREE.Mesh(earGeo, furMat);
  earR.name = 'rightEar';
  earR.position.set(0.58, 0.82, 0.1);
  earR.rotation.set(0.1, 0, -0.45);
  headGroup.add(earR);

  const earInnerR = new THREE.Mesh(earInnerGeo, innerEarMat);
  earInnerR.name = 'rightInnerEar';
  earInnerR.position.set(0, 0, 0.12);
  earR.add(earInnerR);

  // 10 & 11. Left Glossy Eye + Pupil with Catchlight Highlight
  const eyeSocketGeo = new THREE.SphereGeometry(0.28, 12, 10);
  const pupilGeo = new THREE.SphereGeometry(0.18, 10, 8);
  const catchlightGeo = new THREE.SphereGeometry(0.07, 8, 8);

  const eyeL = new THREE.Mesh(eyeSocketGeo, eyeIrisMat);
  eyeL.name = 'leftEye';
  eyeL.position.set(-0.38, 0.08, 0.78);
  headGroup.add(eyeL);

  const pupilL = new THREE.Mesh(pupilGeo, eyePupilMat);
  pupilL.name = 'leftPupil';
  pupilL.position.set(0, 0, 0.18);
  eyeL.add(pupilL);

  const catchlightL = new THREE.Mesh(catchlightGeo, eyeWhiteMat);
  catchlightL.position.set(-0.06, 0.07, 0.12);
  pupilL.add(catchlightL);

  // 12 & 13. Right Glossy Eye + Pupil with Catchlight Highlight
  const eyeR = new THREE.Mesh(eyeSocketGeo, eyeIrisMat);
  eyeR.name = 'rightEye';
  eyeR.position.set(0.38, 0.08, 0.78);
  headGroup.add(eyeR);

  const pupilR = new THREE.Mesh(pupilGeo, eyePupilMat);
  pupilR.name = 'rightPupil';
  pupilR.position.set(0, 0, 0.18);
  eyeR.add(pupilR);

  const catchlightR = new THREE.Mesh(catchlightGeo, eyeWhiteMat);
  catchlightR.position.set(-0.06, 0.07, 0.12);
  pupilR.add(catchlightR);

  // 14. Cute Snout & Pink Nose
  const snoutGeo = new THREE.SphereGeometry(0.24, 10, 8);
  const snoutMesh = new THREE.Mesh(snoutGeo, bellyMat);
  snoutMesh.name = 'snout';
  snoutMesh.position.set(0, -0.12, 0.88);
  headGroup.add(snoutMesh);

  const noseGeo = new THREE.ConeGeometry(0.1, 0.08, 3);
  const noseMesh = new THREE.Mesh(noseGeo, noseMat);
  noseMesh.rotation.x = Math.PI;
  noseMesh.position.set(0, 0.08, 0.2);
  snoutMesh.add(noseMesh);

  // 15. Whiskers
  const whiskerGeo = new THREE.CylinderGeometry(0.015, 0.015, 0.5, 6);
  const whiskerMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  materialsToDispose.push(whiskerMat);
  const whiskersGroup = new THREE.Group();
  whiskersGroup.name = 'whiskers';

  const wAngles = [-0.15, 0.0, 0.15];
  for (const wa of wAngles) {
    const wL = new THREE.Mesh(whiskerGeo, whiskerMat);
    wL.rotation.z = Math.PI / 2 + wa;
    wL.position.set(-0.62, -0.15 + wa * 0.3, 0.65);
    whiskersGroup.add(wL);

    const wR = new THREE.Mesh(whiskerGeo, whiskerMat);
    wR.rotation.z = -Math.PI / 2 - wa;
    wR.position.set(0.62, -0.15 + wa * 0.3, 0.65);
    whiskersGroup.add(wR);
  }
  headGroup.add(whiskersGroup);

  // 16. Woven Collar Band
  const collarGeo = new THREE.TorusGeometry(0.62, 0.08, 8, 20);
  const collarMesh = new THREE.Mesh(collarGeo, collarMat);
  collarMesh.name = 'collar';
  collarMesh.rotation.x = Math.PI / 2;
  collarMesh.position.set(0, -0.1, 0.5);
  bodyGroup.add(collarMesh);

  // 17. Golden Bell
  const bellGeo = new THREE.SphereGeometry(0.18, 12, 10);
  const bellMesh = new THREE.Mesh(bellGeo, bellMat);
  bellMesh.name = 'goldenBell';
  bellMesh.position.set(0, -0.22, 1.15);
  bodyGroup.add(bellMesh);

  // 18. Miniature Artisan Blacksmith Helmet & Horn Visor
  const helmetGeo = new THREE.SphereGeometry(0.88, 16, 12, 0, Math.PI * 2, 0, Math.PI * 0.55);
  const helmetMesh = new THREE.Mesh(helmetGeo, helmetMat);
  helmetMesh.name = 'blacksmithHelmet';
  helmetMesh.position.set(0, 0.28, 0.05);
  headGroup.add(helmetMesh);

  // Twin golden horns on helmet
  const hornGeo = new THREE.ConeGeometry(0.16, 0.55, 6);
  const hornL = new THREE.Mesh(hornGeo, hornMat);
  hornL.position.set(-0.62, 0.6, 0.0);
  hornL.rotation.set(-0.2, 0, 0.6);
  helmetMesh.add(hornL);

  const hornR = new THREE.Mesh(hornGeo, hornMat);
  hornR.position.set(0.62, 0.6, 0.0);
  hornR.rotation.set(-0.2, 0, -0.6);
  helmetMesh.add(hornR);

  // -------------------------------------------------------------
  // 4 ARTICULATED SWINGING LEGS & PAWS
  // -------------------------------------------------------------
  const legGeo = new THREE.CapsuleGeometry(0.22, 0.55, 8, 10);
  const pawGeo = new THREE.SphereGeometry(0.25, 10, 8);

  function createLeg(name, x, z) {
    const pivot = new THREE.Group();
    pivot.name = name;
    pivot.position.set(x, -0.35, z);

    const legMesh = new THREE.Mesh(legGeo, furMat);
    legMesh.position.y = -0.32;
    legMesh.castShadow = true;
    pivot.add(legMesh);

    const pawMesh = new THREE.Mesh(pawGeo, bellyMat);
    pawMesh.position.set(0, -0.65, 0.06);
    pawMesh.scale.set(1.0, 0.7, 1.2);
    pivot.add(pawMesh);

    bodyGroup.add(pivot);
    return pivot;
  }

  // 19. Front-Left
  const legFL = createLeg('legFL', -0.45, 0.45);
  // 20. Front-Right
  const legFR = createLeg('legFR', 0.45, 0.45);
  // 21. Back-Left
  const legBL = createLeg('legBL', -0.45, -0.45);
  // 22. Back-Right
  const legBR = createLeg('legBR', 0.45, -0.45);

  // -------------------------------------------------------------
  // 2-SEGMENT WAGGING TAIL
  // -------------------------------------------------------------
  const tailGroup = new THREE.Group();
  tailGroup.name = 'tailGroup';
  tailGroup.position.set(0, 0.15, -0.75);
  tailGroup.rotation.x = 0.5;
  bodyGroup.add(tailGroup);

  // 23. Proximal Tail Segment
  const tail1Geo = new THREE.CylinderGeometry(0.12, 0.16, 0.7, 8);
  const tail1Mesh = new THREE.Mesh(tail1Geo, furMat);
  tail1Mesh.name = 'tailSegment1';
  tail1Mesh.position.y = 0.35;
  tailGroup.add(tail1Mesh);

  // 24. Distal Fluffy Tip Segment
  const tail2Pivot = new THREE.Group();
  tail2Pivot.position.y = 0.7;
  tailGroup.add(tail2Pivot);

  const tail2Geo = new THREE.ConeGeometry(0.16, 0.75, 8);
  const tail2Mesh = new THREE.Mesh(tail2Geo, bellyMat);
  tail2Mesh.name = 'tailSegment2';
  tail2Mesh.position.y = 0.35;
  tail2Pivot.add(tail2Mesh);

  // -------------------------------------------------------------
  // LOCOMOTION CONTROLLER STATE
  // -------------------------------------------------------------
  let currentAngle = startAngle;
  let animTime = id * 1.5;
  let jumpProgress = 1.0; // 0 = start of jump, 1 = grounded

  function triggerJump() {
    jumpProgress = 0;
  }

  function updateLocomotion(dt, isSpinning = true) {
    if (!isSpinning) return;

    animTime += dt * 6.5 * pathSpeed;

    // Advance position along circular / oval plaza boulevard loop
    currentAngle += dt * 0.15 * pathSpeed;
    const posX = Math.cos(currentAngle) * pathRadius;
    const posZ = Math.sin(currentAngle) * pathRadius;

    catGroup.position.x = posX;
    catGroup.position.z = posZ;

    // Face tangent to movement vector
    catGroup.rotation.y = -currentAngle + Math.PI / 2;

    // Quadruped Trot Gait:
    // Diagonal pairs move in sync: (FL + BR) vs (FR + BL)
    const legSwing = Math.sin(animTime) * 0.55;
    legFL.rotation.x = legSwing;
    legBR.rotation.x = legSwing;
    legFR.rotation.x = -legSwing;
    legBL.rotation.x = -legSwing;

    // Body Bobbing & Head tilt
    const bob = Math.abs(Math.sin(animTime)) * 0.15;
    bodyGroup.position.y = 1.35 + bob;
    headGroup.rotation.z = Math.sin(animTime * 0.5) * 0.08;
    headGroup.rotation.x = Math.sin(animTime) * 0.05;

    // Tail Wagging
    tailGroup.rotation.y = Math.sin(animTime * 0.7) * 0.5;
    tail2Pivot.rotation.z = Math.cos(animTime * 0.7) * 0.4;

    // Jump / Forge strike reaction
    if (jumpProgress < 1.0) {
      jumpProgress += dt * 2.2;
      // Parabolic jump arc
      const jumpY = Math.sin(jumpProgress * Math.PI) * 2.5;
      catGroup.position.y = jumpY;
      // Playful flip
      catGroup.rotation.x = Math.sin(jumpProgress * Math.PI * 2) * 0.8;
      if (jumpProgress >= 1.0) {
        catGroup.position.y = 0;
        catGroup.rotation.x = 0;
      }
    } else {
      catGroup.position.y = 0;
      catGroup.rotation.x = 0;
    }
  }

  return {
    group: catGroup,
    id,
    triggerJump,
    updateLocomotion,
    materialsToDispose
  };
}

/**
 * Manager holding all active Moru Cats.
 */
export function createCatVillage(initialCount = 6, theme = 'night') {
  const villageGroup = new THREE.Group();
  villageGroup.name = 'catVillage';

  const cats = [];
  const materialsToDispose = [];

  for (let i = 0; i < initialCount; i++) {
    const cat = createMoruCat({
      id: i,
      pathRadius: 13.5 + (i % 3) * 3.5,
      pathSpeed: 0.9 + (i % 4) * 0.2,
      startAngle: (i * Math.PI * 2) / initialCount,
      materialsToDispose
    });
    villageGroup.add(cat.group);
    cats.push(cat);
  }

  function spawnCat() {
    const nextId = cats.length;
    const newCat = createMoruCat({
      id: nextId,
      pathRadius: 12.0 + Math.random() * 8.0,
      pathSpeed: 0.8 + Math.random() * 0.5,
      startAngle: Math.random() * Math.PI * 2,
      materialsToDispose
    });
    villageGroup.add(newCat.group);
    cats.push(newCat);
    return newCat;
  }

  function triggerAllCatsJump() {
    for (const cat of cats) {
      cat.triggerJump();
    }
  }

  function updateVillage(dt, isSpinning = true) {
    for (const cat of cats) {
      cat.updateLocomotion(dt, isSpinning);
    }
  }

  return {
    group: villageGroup,
    cats,
    spawnCat,
    triggerAllCatsJump,
    updateVillage,
    materialsToDispose,
    get catCount() {
      return cats.length;
    }
  };
}


// ====== src/main.js (12932 bytes) ======
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';

import { createCity } from './world/city.js';
import { createForge } from './world/forge.js';
import { createCatVillage } from './entities/moruCat.js';
import { disposeAllTextures } from './world/textures.js';

/**
 * Flagship Moru 3D Neon Forge City & Animated Cat Village Entry Point.
 */

// 1. Initial State from URL
const urlParams = new URLSearchParams(window.location.search);
const initialTheme = urlParams.get('theme') || 'night';

const state = {
  spinning: true,
  theme: initialTheme,
  cameraMode: 'overview', // 'overview' | 'iso' | 'street' | 'follow'
  catCount: 6,
  buildingCount: 0,
  lampCount: 0,
  treeCount: 0,
  totalTriangles: 0,
  forgeStrikes: 0,
  disposedCount: 0,
  fps: 60,
  frameCount: 0
};

// 2. Scene, Camera, Renderer Setup
const canvas = document.getElementById('studio-canvas');
const renderer = new THREE.WebGLRenderer({
  canvas,
  preserveDrawingBuffer: true,
  antialias: true,
  powerPreference: 'high-performance'
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.0;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();

const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.5, 600);
camera.position.set(0, 42, 68);
camera.lookAt(0, 4, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.08;
controls.enableRotate = true;
controls.enableZoom = true;
controls.enablePan = true;
controls.minDistance = 8;
controls.maxDistance = 210;
controls.maxPolarAngle = Math.PI * 0.485;
controls.autoRotate = true;
controls.autoRotateSpeed = 2.0;
controls.target.set(0, 4, 0);

// 3. Post-Processing Pipeline (EffectComposer + UnrealBloomPass)
const composer = new EffectComposer(renderer);
const renderPass = new RenderPass(scene, camera);
composer.addPass(renderPass);

const bloomPass = new UnrealBloomPass(
  new THREE.Vector2(window.innerWidth, window.innerHeight),
  0.55, // strength
  0.4,  // radius
  0.25  // threshold
);
composer.addPass(bloomPass);

// 4. Lighting Rig
const ambientLight = new THREE.AmbientLight(0x1c2844, 1.1);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0x5c7cfa, 1.3);
dirLight.position.set(45, 90, 45);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 2048;
dirLight.shadow.mapSize.height = 2048;
dirLight.shadow.camera.near = 10;
dirLight.shadow.camera.far = 250;
dirLight.shadow.camera.left = -90;
dirLight.shadow.camera.right = 90;
dirLight.shadow.camera.top = 90;
dirLight.shadow.camera.bottom = -90;
dirLight.shadow.bias = -0.0005;
scene.add(dirLight);

const forgePointLight = new THREE.PointLight(0xff6600, 2.5, 35, 1.2);
forgePointLight.position.set(0, 4.5, 0);
scene.add(forgePointLight);

// 5. World Construction
let cityData = null;
let forgeData = null;
let catVillage = null;

function buildWorld(theme) {
  // Clear previous world if exists
  if (cityData) {
    scene.remove(cityData.group);
    for (const mat of cityData.materialsToDispose) mat.dispose();
  }
  if (forgeData) {
    scene.remove(forgeData.group);
    for (const mat of forgeData.materialsToDispose) mat.dispose();
  }
  if (catVillage) {
    scene.remove(catVillage.group);
    for (const mat of catVillage.materialsToDispose) mat.dispose();
  }

  // City Skyline & Streets
  cityData = createCity(theme);
  scene.add(cityData.group);
  state.buildingCount = cityData.buildingCount;
  state.treeCount = cityData.treeCount;
  state.lampCount = cityData.lampCount;

  // Central Blacksmith Forge Plaza
  forgeData = createForge(theme);
  scene.add(forgeData.group);

  // Animated Chibi Cat Village (6 initial cats)
  catVillage = createCatVillage(6, theme);
  scene.add(catVillage.group);
  state.catCount = catVillage.catCount;

  // Calculate Scene Triangles
  updateTriangleCount();
}

function updateTriangleCount() {
  let triangles = 0;
  scene.traverse((obj) => {
    if (obj.isMesh && obj.geometry) {
      const geom = obj.geometry;
      if (geom.index) {
        triangles += geom.index.count / 3;
      } else if (geom.attributes && geom.attributes.position) {
        triangles += geom.attributes.position.count / 3;
      }
    }
  });
  state.totalTriangles = Math.round(triangles);
}

// 6. Atmosphere & Theme Calibration (Guard Against Blackout & White-out)
function applyTheme(theme) {
  state.theme = theme;

  if (theme === 'night') {
    scene.background = new THREE.Color(0x162238);
    scene.fog = new THREE.Fog(0x18243c, 45, 260);
    ambientLight.color.setHex(0x2a3a5a);
    ambientLight.intensity = 1.35;
    dirLight.color.setHex(0x6082e8);
    dirLight.intensity = 1.45;
    forgePointLight.color.setHex(0xff6600);
    forgePointLight.intensity = 2.8;

    renderer.toneMappingExposure = 1.02;
    bloomPass.strength = 0.52;
    bloomPass.radius = 0.38;
    bloomPass.threshold = 0.28;
  } else if (theme === 'gold') {
