  }

  // Update theme button states
  document.querySelectorAll('#mode-night, #mode-gold, #mode-day').forEach((btn) => {
    btn.classList.remove('active');
  });
  const activeBtn = document.getElementById(`mode-${theme}`);
  if (activeBtn) activeBtn.classList.add('active');
}

