});

// 9. Main Animation Loop
let lastTime = performance.now();
let lastHudUpdate = performance.now();
let fpsFrames = 0;
let fpsLastTime = performance.now();

const hudEl = document.getElementById('fps-hud');

function animate() {
  requestAnimationFrame(animate);

  const now = performance.now();
  const rawDt = (now - lastTime) * 0.001;
  lastTime = now;
  const dt = Math.min(rawDt, 0.1);

  // FPS Calculation
  fpsFrames++;
  if (now - fpsLastTime >= 500) {
    state.fps = Math.round((fpsFrames * 1000) / (now - fpsLastTime));
    fpsFrames = 0;
    fpsLastTime = now;
  }

  // Only advance animations when spinning === true
  if (state.spinning) {
    state.frameCount++;

    // Update Forge Animations & Particles
    if (forgeData) {
      forgeData.updateForge(dt, true);
    }

    // Update Cat Village Quadruped Trot
    if (catVillage) {
      catVillage.updateVillage(dt, true);
    }

    // Camera Motion / Interpolation
    if (state.cameraMode === 'follow' && catVillage && catVillage.cats.length > 0) {
      controls.autoRotate = false;
      const leaderCat = catVillage.cats[0].group;
      const catPos = leaderCat.position;
      const catRotY = leaderCat.rotation.y;

      const followOffset = new THREE.Vector3(0, 3.8, -6.5);
      followOffset.applyAxisAngle(new THREE.Vector3(0, 1, 0), catRotY);

      targetCamPos.set(catPos.x + followOffset.x, catPos.y + followOffset.y, catPos.z + followOffset.z);
      targetCamLook.set(catPos.x, catPos.y + 1.2, catPos.z);
      camera.position.lerp(targetCamPos, dt * 3.5);
      controls.target.lerp(targetCamLook, dt * 3.5);
      camera.lookAt(controls.target);
    } else {
      controls.autoRotate = state.cameraMode === 'overview' || state.cameraMode === 'iso';
      controls.update();
    }

    // Update HUD text at ~4Hz
    if (hudEl && now - lastHudUpdate >= 250) {
      lastHudUpdate = now;
      const kTris = (state.totalTriangles / 1000).toFixed(1);
      hudEl.innerHTML = `
        <span class="hud-badge">FPS: <b>${state.fps}</b></span> |
        <span class="hud-badge">Cats: <b>${state.catCount}</b></span> |
        <span class="hud-badge">Bldgs: <b>${state.buildingCount}</b></span> |
        <span class="hud-badge">Lamps: <b>${state.lampCount}</b></span> |
        <span class="hud-badge"><b>${kTris}k tris</b></span> |
        <span class="hud-badge">Frame: <b>${state.frameCount}</b></span>
      `.trim();
    }
  }

  // Render Scene via Post-Processing Pipeline
  composer.render();
}

requestAnimationFrame(animate);

