import * as THREE from 'three';
import { createWindowTexture, createRoadTexture, createHelipadTexture } from './textures.js';

/**
 * Creates the high-density Moru Cyberpunk 3D City.
 * Features:
 * - 68 multi-tier skyscrapers with varied heights, setbacks, rooftop neon trims, helipads, spires
 * - Paved road boulevard grid with crosswalks and markings
 * - 84 stylized multi-tier trees with theme-responsive foliage
 * - 96 detailed streetlamps with glowing bulbs and ground light pool discs
 * - Rich architectural assets (HVAC chillers, water towers, satellite dishes, antenna masts)
 */
export function createCity(theme = 'night') {
  const cityGroup = new THREE.Group();
  cityGroup.name = 'cityGroup';

  const buildings = [];
  const trees = [];
  const lamps = [];
  const materialsToDispose = [];

  // Procedural window facade textures for varied architectural styles
  const windowTextures = [
    createWindowTexture(theme, 0),
    createWindowTexture(theme, 1),
    createWindowTexture(theme, 2),
    createWindowTexture(theme, 3)
  ];

  const helipadTex = createHelipadTexture();
  const roadTex = createRoadTexture();

  // Common materials
  const buildingBaseMat = new THREE.MeshStandardMaterial({
    color: theme === 'gold' ? 0x2c2020 : theme === 'day' ? 0x334155 : 0x182030,
    roughness: 0.7,
    metalness: 0.3
  });
  materialsToDispose.push(buildingBaseMat);

  const neonTrimColors = {
    night: [0x00f0ff, 0xff007f, 0x38bdf8, 0xa855f7, 0xfacc15],
    gold: [0xffaa00, 0xf59e0b, 0xffd700, 0xf97316, 0xffedd5],
    day: [0x0284c7, 0x0ea5e9, 0x38bdf8, 0x64748b, 0x94a3b8]
  };

  const currentNeonPalette = neonTrimColors[theme] || neonTrimColors.night;

  // -------------------------------------------------------------
  // 1. GROUND PLANE & ROAD NETWORK
  // -------------------------------------------------------------
  const groundSize = 340;
  const groundGeo = new THREE.PlaneGeometry(groundSize, groundSize, 32, 32);
  const groundMat = new THREE.MeshStandardMaterial({
    color: theme === 'gold' ? 0x2a1c1a : theme === 'day' ? 0x475569 : 0x182234,
    roughness: 0.85,
    metalness: 0.2
  });
  materialsToDispose.push(groundMat);
  const groundMesh = new THREE.Mesh(groundGeo, groundMat);
  groundMesh.rotation.x = -Math.PI / 2;
  groundMesh.position.y = -0.05;
  groundMesh.receiveShadow = true;
  cityGroup.add(groundMesh);

  // Avenues / Boulevard network
  // Main North-South & East-West Boulevards
  const roadMat = new THREE.MeshStandardMaterial({
    map: roadTex,
    roughness: 0.6,
    metalness: 0.1
  });
  materialsToDispose.push(roadMat);

  // NS Boulevard
  const roadNSGeo = new THREE.PlaneGeometry(16, groundSize);
  const roadNS = new THREE.Mesh(roadNSGeo, roadMat);
  roadNS.rotation.x = -Math.PI / 2;
  roadNS.position.set(0, 0.01, 0);
  roadNS.receiveShadow = true;
  cityGroup.add(roadNS);

  // EW Boulevard
  const roadEWGeo = new THREE.PlaneGeometry(groundSize, 16);
  const roadEW = new THREE.Mesh(roadEWGeo, roadMat);
  roadEW.rotation.x = -Math.PI / 2;
  roadEW.position.set(0, 0.01, 0);
  roadEW.receiveShadow = true;
  cityGroup.add(roadEW);

  // Outer Ring Boulevards (x = ±58, z = ±58)
  const ringOffsets = [-58, 58];
  for (const rx of ringOffsets) {
    const rGeo = new THREE.PlaneGeometry(12, groundSize);
    const rMesh = new THREE.Mesh(rGeo, roadMat);
    rMesh.rotation.x = -Math.PI / 2;
    rMesh.position.set(rx, 0.01, 0);
    rMesh.receiveShadow = true;
    cityGroup.add(rMesh);
  }
  for (const rz of ringOffsets) {
    const rGeo = new THREE.PlaneGeometry(groundSize, 12);
    const rMesh = new THREE.Mesh(rGeo, roadMat);
    rMesh.rotation.x = -Math.PI / 2;
    rMesh.position.set(0, 0.01, rz);
    rMesh.receiveShadow = true;
    cityGroup.add(rMesh);
  }

  // Raised Sidewalk Curbs along Boulevards
  const curbMat = new THREE.MeshStandardMaterial({
    color: theme === 'gold' ? 0x3d2c2c : theme === 'day' ? 0x64748b : 0x222c3d,
    roughness: 0.7
  });
  materialsToDispose.push(curbMat);

  // Add curb borders
  const curbGeoNS = new THREE.BoxGeometry(0.5, 0.25, groundSize);
  const curbL1 = new THREE.Mesh(curbGeoNS, curbMat);
  curbL1.position.set(-8.25, 0.1, 0);
  cityGroup.add(curbL1);
  const curbR1 = new THREE.Mesh(curbGeoNS, curbMat);
  curbR1.position.set(8.25, 0.1, 0);
  cityGroup.add(curbR1);

  // -------------------------------------------------------------
  // 2. 68 MULTI-TIER PROCEDURAL SKYSCRAPERS
  // -------------------------------------------------------------
  // We place skyscrapers in 4 quadrant zones outside the central plaza ring:
  // Quadrants: (+x, +z), (-x, +z), (+x, -z), (-x, -z)
  // 17 skyscrapers per quadrant = 68 skyscrapers total.

  const quadrantDefs = [
    { signX: 1, signZ: 1 },
    { signX: -1, signZ: 1 },
    { signX: 1, signZ: -1 },
    { signX: -1, signZ: -1 }
  ];

  let bldgIndex = 0;

  for (const q of quadrantDefs) {
    // Generate a 4x4 + 1 anchor skyscraper layout in this quadrant
    const colXs = [24, 40, 72, 94];
    const rowZs = [24, 40, 72, 94];

    for (let i = 0; i < colXs.length; i++) {
      for (let j = 0; j < rowZs.length; j++) {
        bldgIndex++;
        const bx = q.signX * (colXs[i] + (Math.sin(bldgIndex * 1.7) * 3));
        const bz = q.signZ * (rowZs[j] + (Math.cos(bldgIndex * 2.3) * 3));

        // Skip if directly in center plaza zone
        const distFromCenter = Math.sqrt(bx * bx + bz * bz);
        if (distFromCenter < 24) continue;

        // Skyscraper building parameters
        const baseHeight = 28 + ((bldgIndex * 7) % 52); // heights range 28 to 80
        const bWidth = 10 + (bldgIndex % 5) * 1.8; // 10 to 17.2
        const bDepth = 10 + ((bldgIndex + 2) % 5) * 1.8;
        const style = bldgIndex % 4;
        const winTex = windowTextures[style];
        const neonColor = currentNeonPalette[bldgIndex % currentNeonPalette.length];

        const bldgGroup = createMultiTierSkyscraper({
          baseWidth: bWidth,
          baseDepth: bDepth,
          totalHeight: baseHeight,
          styleIndex: style,
          windowTexture: winTex,
          baseMaterial: buildingBaseMat,
          neonColor: neonColor,
          theme: theme,
          helipadTex: helipadTex,
          hasHelipad: bldgIndex % 5 === 0,
          hasSpire: bldgIndex % 3 === 0,
          materialsToDispose: materialsToDispose
        });

        bldgGroup.position.set(bx, 0, bz);
        cityGroup.add(bldgGroup);
        buildings.push(bldgGroup);
      }
    }

    // Add 1 iconic landmark skyscraper in each quadrant corner for extra skyline drama
    bldgIndex++;
    const lx = q.signX * 115;
    const lz = q.signZ * 115;
    const landmarkBldg = createMultiTierSkyscraper({
      baseWidth: 20,
      baseDepth: 20,
      totalHeight: 92,
      styleIndex: (bldgIndex + 1) % 4,
      windowTexture: windowTextures[(bldgIndex + 1) % 4],
      baseMaterial: buildingBaseMat,
      neonColor: currentNeonPalette[(bldgIndex + 2) % currentNeonPalette.length],
      theme: theme,
      helipadTex: helipadTex,
      hasHelipad: true,
      hasSpire: true,
      materialsToDispose: materialsToDispose
    });
    landmarkBldg.position.set(lx, 0, lz);
    cityGroup.add(landmarkBldg);
    buildings.push(landmarkBldg);
  }

  // -------------------------------------------------------------
  // 3. 88+ STYLIZED MULTI-TIER TREES
  // -------------------------------------------------------------
  // 24 trees along the plaza perimeter ring (radius ~ 21)
  const plazaTreeCount = 24;
  for (let t = 0; t < plazaTreeCount; t++) {
    const angle = (t * Math.PI * 2) / plazaTreeCount;
    const rad = 20.5 + Math.sin(t * 3.5) * 1.5;
    const tx = Math.cos(angle) * rad;
    const tz = Math.sin(angle) * rad;

    const tree = createStylizedTree(theme, t, materialsToDispose);
    tree.position.set(tx, 0, tz);
    cityGroup.add(tree);
    trees.push(tree);
  }

  // 68 trees along boulevard medians and pedestrian sidewalks
  const sidewalkSpacings = [-14, 14, -50, 50];
  let treeId = 24;
  for (const swX of sidewalkSpacings) {
    for (let zPos = -135; zPos <= 135; zPos += 15) {
      if (Math.abs(zPos) < 22 && Math.abs(swX) < 20) continue; // skip plaza
      treeId++;
      const tree = createStylizedTree(theme, treeId, materialsToDispose);
      tree.position.set(swX + (Math.sin(treeId) * 0.8), 0, zPos);
      cityGroup.add(tree);
      trees.push(tree);
    }
  }

  // -------------------------------------------------------------
  // 4. 100+ DETAILED STREETLAMPS WITH GLOWING BULBS & LIGHT POOLS
  // -------------------------------------------------------------
  // 28 lamps along plaza promenade ring
  const plazaLampCount = 28;
  for (let l = 0; l < plazaLampCount; l++) {
    const angle = (l * Math.PI * 2) / plazaLampCount + (Math.PI / plazaLampCount);
    const rad = 19.0;
    const lx = Math.cos(angle) * rad;
    const lz = Math.sin(angle) * rad;

    const lamp = createDetailedStreetlamp(theme, l, angle, materialsToDispose);
    lamp.position.set(lx, 0, lz);
    cityGroup.add(lamp);
    lamps.push(lamp);
  }

  // 76 lamps along the 4 cardinal avenues
  let lampId = 28;
  const lampDistances = [-140, -122, -104, -86, -68, -50, -36, -24, 24, 36, 50, 68, 86, 104, 122, 140];
  const lampXOffsets = [-10, 10];

  for (const lx of lampXOffsets) {
    for (const lz of lampDistances) {
      lampId++;
      const lamp = createDetailedStreetlamp(theme, lampId, lx > 0 ? -Math.PI / 2 : Math.PI / 2, materialsToDispose);
      lamp.position.set(lx, 0, lz);
      cityGroup.add(lamp);
      lamps.push(lamp);
    }
  }

  // Also lamps along East-West avenue
  const lampZOffsets = [-10, 10];
  for (const lz of lampZOffsets) {
    for (const lx of lampDistances) {
      lampId++;
      const lamp = createDetailedStreetlamp(theme, lampId, lz > 0 ? 0 : Math.PI, materialsToDispose);
      lamp.position.set(lx, 0, lz);
      cityGroup.add(lamp);
      lamps.push(lamp);
    }
  }

  return {
    group: cityGroup,
    buildings,
    trees,
    lamps,
    materialsToDispose,
    buildingCount: buildings.length,
    treeCount: trees.length,
    lampCount: lamps.length
  };
}

/**
 * Creates a single high-detail multi-tier skyscraper with setbacks, rooftop
 * neon trims, architectural mechanical units, and optional helipad or spire.
 */
function createMultiTierSkyscraper(params) {
  const {
    baseWidth,
    baseDepth,
    totalHeight,
    windowTexture,
    baseMaterial,
    neonColor,
    theme,
    helipadTex,
    hasHelipad,
    hasSpire,
    materialsToDispose
  } = params;

  const bldgGroup = new THREE.Group();
  bldgGroup.name = 'skyscraper';

  // Facade material mapped with procedural window texture
  const facadeMat = new THREE.MeshStandardMaterial({
    map: windowTexture,
    roughness: 0.25,
    metalness: 0.65,
    bumpScale: 0.05
  });
  materialsToDispose.push(facadeMat);

  // Glowing neon trim material
  const neonMat = new THREE.MeshBasicMaterial({
    color: neonColor
  });
  materialsToDispose.push(neonMat);

  // 1. Podium Base (Ground to Tier 1)
  const podiumH = Math.min(totalHeight * 0.22, 10);
  const podiumGeo = new THREE.BoxGeometry(baseWidth + 1.2, podiumH, baseDepth + 1.2);
  const podiumMesh = new THREE.Mesh(podiumGeo, baseMaterial);
  podiumMesh.position.y = podiumH / 2;
  podiumMesh.castShadow = true;
  podiumMesh.receiveShadow = true;
  bldgGroup.add(podiumMesh);

  // Entrance awning / canopy
  const canopyGeo = new THREE.BoxGeometry(baseWidth * 0.5, 0.4, 3);
  const canopyMesh = new THREE.Mesh(canopyGeo, neonMat);
  canopyMesh.position.set(0, 3.5, (baseDepth + 1.2) / 2 + 1.2);
  bldgGroup.add(canopyMesh);

  // 2. Middle Main Tower (Tier 1 to Setback)
  const midH = totalHeight * 0.55;
  const midGeo = new THREE.BoxGeometry(baseWidth, midH, baseDepth);
  // Adjust UVs for window repeat
  const uvs = midGeo.attributes.uv;
  for (let i = 0; i < uvs.count; i++) {
    uvs.setY(i, uvs.getY(i) * (midH / 12));
    uvs.setX(i, uvs.getX(i) * (baseWidth / 10));
  }
  uvs.needsUpdate = true;

  const midMesh = new THREE.Mesh(midGeo, facadeMat);
  midMesh.position.y = podiumH + midH / 2;
  midMesh.castShadow = true;
  midMesh.receiveShadow = true;
  bldgGroup.add(midMesh);

  // Neon decorative vertical corner strip
  const cornerGeo = new THREE.BoxGeometry(0.25, midH, 0.25);
  const cornerPositions = [
    [-baseWidth / 2, -baseDepth / 2],
    [baseWidth / 2, -baseDepth / 2],
    [-baseWidth / 2, baseDepth / 2],
    [baseWidth / 2, baseDepth / 2]
  ];
  for (const [cx, cz] of cornerPositions) {
    const cMesh = new THREE.Mesh(cornerGeo, neonMat);
    cMesh.position.set(cx, podiumH + midH / 2, cz);
    bldgGroup.add(cMesh);
  }

  // 3. Setback Top Tier
  const topH = totalHeight * 0.23;
  const topW = baseWidth * 0.75;
  const topD = baseDepth * 0.75;
  const topGeo = new THREE.BoxGeometry(topW, topH, topD);
  const topMesh = new THREE.Mesh(topGeo, facadeMat);
  topMesh.position.y = podiumH + midH + topH / 2;
  topMesh.castShadow = true;
  topMesh.receiveShadow = true;
  bldgGroup.add(topMesh);

  // Glowing rooftop neon perimeter frame
  const roofY = podiumH + midH + topH;
  const roofEdgeH = 0.5;
  const frameThick = 0.25;

  const frameXGeo = new THREE.BoxGeometry(topW + frameThick * 2, roofEdgeH, frameThick);
  const frameZGeo = new THREE.BoxGeometry(frameThick, roofEdgeH, topD);

  const fN = new THREE.Mesh(frameXGeo, neonMat);
  fN.position.set(0, roofY + roofEdgeH / 2, topD / 2);
  bldgGroup.add(fN);
  const fS = new THREE.Mesh(frameXGeo, neonMat);
  fS.position.set(0, roofY + roofEdgeH / 2, -topD / 2);
  bldgGroup.add(fS);
  const fE = new THREE.Mesh(frameZGeo, neonMat);
  fE.position.set(topW / 2, roofY + roofEdgeH / 2, 0);
  bldgGroup.add(fE);
  const fW = new THREE.Mesh(frameZGeo, neonMat);
  fW.position.set(-topW / 2, roofY + roofEdgeH / 2, 0);
  bldgGroup.add(fW);

  // 4. Rooftop Mechanical Assets (Water towers, HVAC chillers, Helipads, Spires)
  if (hasHelipad) {
    const padSize = Math.min(topW, topD) * 0.88;
    const padGeo = new THREE.PlaneGeometry(padSize, padSize);
    const padMat = new THREE.MeshStandardMaterial({
      map: helipadTex,
      roughness: 0.5,
      metalness: 0.2
    });
    materialsToDispose.push(padMat);
    const padMesh = new THREE.Mesh(padGeo, padMat);
    padMesh.rotation.x = -Math.PI / 2;
    padMesh.position.set(0, roofY + 0.05, 0);
    bldgGroup.add(padMesh);
  } else {
    // HVAC chiller boxes
    const hvacGeo = new THREE.BoxGeometry(topW * 0.35, 1.8, topD * 0.35);
