/**
 * Creates a stylized multi-tier tree with organic multi-sphere / conical foliage.
 */
function createStylizedTree(theme, id, materialsToDispose) {
  const treeGroup = new THREE.Group();
  treeGroup.name = 'stylizedTree';

  // Trunk
  const trunkH = 2.8 + (Math.sin(id * 1.5) * 0.4);
  const trunkGeo = new THREE.CylinderGeometry(0.28, 0.45, trunkH, 8);
  const trunkMat = new THREE.MeshStandardMaterial({
    color: theme === 'gold' ? 0x4a2e18 : 0x3b2416,
    roughness: 0.9
  });
  materialsToDispose.push(trunkMat);
  const trunkMesh = new THREE.Mesh(trunkGeo, trunkMat);
  trunkMesh.position.y = trunkH / 2;
  trunkMesh.castShadow = true;
  treeGroup.add(trunkMesh);

  // Foliage Colors depending on theme
  let folColors = [0x10b981, 0x059669, 0x06b6d4, 0x34d399];
  if (theme === 'gold') {
    folColors = [0xf59e0b, 0xd97706, 0xf97316, 0xfbbf24];
  } else if (theme === 'day') {
    folColors = [0x22c55e, 0x16a34a, 0x15803d, 0x4ade80];
  }

  const fColor = folColors[id % folColors.length];
  const foliageMat = new THREE.MeshStandardMaterial({
    color: fColor,
    roughness: 0.65,
    metalness: 0.1,
    flatShading: true
  });
  materialsToDispose.push(foliageMat);

  // Multi-sphere / cloud cluster canopy (3 to 4 overlapping icospheres/dodecahedrons)
  const canopyBaseY = trunkH * 0.9;
  const clusterDefs = [
    { x: 0, y: canopyBaseY + 1.2, z: 0, r: 1.5 },
    { x: 0.5, y: canopyBaseY + 0.8, z: 0.4, r: 1.1 },
    { x: -0.6, y: canopyBaseY + 0.9, z: -0.3, r: 1.2 },
    { x: 0.2, y: canopyBaseY + 2.1, z: -0.2, r: 0.95 }
  ];

  for (const c of clusterDefs) {
    const sphereGeo = new THREE.DodecahedronGeometry(c.r, 1);
    const sphereMesh = new THREE.Mesh(sphereGeo, foliageMat);
    sphereMesh.position.set(c.x, c.y, c.z);
    sphereMesh.rotation.set(id * 0.2, id * 0.4, 0);
    sphereMesh.castShadow = true;
    sphereMesh.receiveShadow = true;
    treeGroup.add(sphereMesh);
  }

  return treeGroup;
}

