  const armH = 3.6;
  const armGeo = new THREE.BoxGeometry(0.35, armH, 0.35);
  const armMat = new THREE.MeshStandardMaterial({
    color: 0x4e342e,
    roughness: 0.8
  });
  materialsToDispose.push(armMat);
  const armMesh = new THREE.Mesh(armGeo, armMat);
  armMesh.position.set(0, -armH / 2, 1.2);
  armMesh.rotation.x = 0.35;
  hammerPivot.add(armMesh);

  // Iron reinforcement bands along shaft
  const bandGeo = new THREE.BoxGeometry(0.42, 0.15, 0.42);
  for (let b = 0; b < 3; b++) {
    const bMesh = new THREE.Mesh(bandGeo, polishedSteelMat);
    bMesh.position.set(0, -armH * (0.25 + b * 0.25), 1.2);
    bMesh.rotation.x = 0.35;
    hammerPivot.add(bMesh);
