  const hruneGeo = new THREE.BoxGeometry(0.8, 0.6, 1.55);
  const hruneMat = new THREE.MeshBasicMaterial({ color: 0x00f0ff });
  materialsToDispose.push(hruneMat);
  const hruneMesh = new THREE.Mesh(hruneGeo, hruneMat);
