  // -------------------------------------------------------------
  // 160 Rising Magma Embers + 60 Impact Sparks = 220 particles
  const emberCount = 160;
  const sparkCount = 60;
  const totalParticles = emberCount + sparkCount;

  const particleGeo = new THREE.BufferGeometry();
  const positions = new Float32Array(totalParticles * 3);
  const colors = new Float32Array(totalParticles * 3);

  // Particle simulation internal arrays
  const velocities = [];
  const lifetimes = [];
  const maxLifetimes = [];
  const particleTypes = []; // 0 = rising ember, 1 = impact spark

  for (let i = 0; i < totalParticles; i++) {
    const isSpark = i >= emberCount;
    particleTypes.push(isSpark ? 1 : 0);

    if (!isSpark) {
      // Magma ember: originates from circular magma hearth
      const rad = Math.random() * 3.2;
      const ang = Math.random() * Math.PI * 2;
      positions[i * 3 + 0] = Math.cos(ang) * rad;
      positions[i * 3 + 1] = 1.25 + Math.random() * 3.5;
      positions[i * 3 + 2] = Math.sin(ang) * rad;

      velocities.push({
        x: (Math.random() - 0.5) * 0.4,
        y: 0.8 + Math.random() * 1.4,
        z: (Math.random() - 0.5) * 0.4
      });
      lifetimes.push(Math.random() * 3.0);
      maxLifetimes.push(2.5 + Math.random() * 2.0);

      // Warm fiery colors
      colors[i * 3 + 0] = 1.0;
      colors[i * 3 + 1] = 0.4 + Math.random() * 0.5;
      colors[i * 3 + 2] = 0.05;
    } else {
      // Impact spark: initialized at rest near anvil, detonates on strike
      positions[i * 3 + 0] = 0;
      positions[i * 3 + 1] = 3.0;
      positions[i * 3 + 2] = 0;

      velocities.push({ x: 0, y: 0, z: 0 });
      lifetimes.push(999); // inactive until strike
      maxLifetimes.push(0.8);

      colors[i * 3 + 0] = 1.0;
      colors[i * 3 + 1] = 0.95;
      colors[i * 3 + 2] = 0.7;
    }
  }

  particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  particleGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));

  const particleMat = new THREE.PointsMaterial({
    size: 0.22,
    vertexColors: true,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });
  materialsToDispose.push(particleMat);

  const particleSystem = new THREE.Points(particleGeo, particleMat);
  forgeGroup.add(particleSystem);

  // -------------------------------------------------------------
  // 8. 4 RUNIC OBELISKS WITH FLOATING LEVITATING ENERGY CRYSTALS
  // -------------------------------------------------------------
  const crystalMeshes = [];
  const obeliskPositions = [
