      emissiveIntensity: 1.4,
      metalness: 0.8,
      roughness: 0.1
    });
    materialsToDispose.push(cryMat);
    const cryMesh = new THREE.Mesh(cryGeo, cryMat);
    cryMesh.position.y = 5.2;
    obGroup.add(cryMesh);
    crystalMeshes.push(cryMesh);

    forgeGroup.add(obGroup);
  }

  // -------------------------------------------------------------
  // 9. 4 BLACKSMITH FIRE BRAZIERS
  // -------------------------------------------------------------
  const brazierPositions = [
    { x: 8, z: 8 },
    { x: -8, z: 8 },
    { x: 8, z: -8 },
    { x: -8, z: -8 }
  ];

  for (const bPos of brazierPositions) {
    const bGroup = new THREE.Group();
    bGroup.position.set(bPos.x, 0.8, bPos.z);

    // Tripod iron legs
    const legGeo = new THREE.CylinderGeometry(0.08, 0.08, 1.2, 6);
    for (let l = 0; l < 3; l++) {
      const a = (l * Math.PI * 2) / 3;
      const legMesh = new THREE.Mesh(legGeo, ironMat);
      legMesh.position.set(Math.cos(a) * 0.4, 0.6, Math.sin(a) * 0.4);
      legMesh.rotation.z = Math.cos(a) * 0.15;
      legMesh.rotation.x = Math.sin(a) * 0.15;
      bGroup.add(legMesh);
    }

    // Iron bowl
    const bowlGeo = new THREE.SphereGeometry(0.75, 12, 8, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2);
    const bowlMesh = new THREE.Mesh(bowlGeo, ironMat);
    bowlMesh.rotation.x = Math.PI;
    bowlMesh.position.y = 1.2;
    bGroup.add(bowlMesh);

    // Glowing coals
    const coalGeo = new THREE.DodecahedronGeometry(0.55, 1);
    const coalMat = new THREE.MeshBasicMaterial({ color: 0xff4500 });
    materialsToDispose.push(coalMat);
    const coalMesh = new THREE.Mesh(coalGeo, coalMat);
    coalMesh.position.y = 1.15;
    bGroup.add(coalMesh);

    forgeGroup.add(bGroup);
  }

  // -------------------------------------------------------------
  // ANIMATION & STRIKE STATE MACHINE
  // -------------------------------------------------------------
  let hammerTime = 0;
  let isStriking = false;
  let strikeAnimProgress = 0;
  let shockwaveProgress = 1.0; // 0 = start, 1 = finished

  function burstSparks() {
    const posAttr = particleGeo.attributes.position;
    for (let i = emberCount; i < totalParticles; i++) {
      // Spawn at ingot surface
      posAttr.setXYZ(i, (Math.random() - 0.5) * 0.6, ingotY + 0.1, (Math.random() - 0.5) * 0.4);
      const speed = 4.0 + Math.random() * 7.0;
      const elev = 0.3 + Math.random() * 0.9;
      const azim = Math.random() * Math.PI * 2;
      velocities[i] = {
        x: Math.cos(azim) * Math.cos(elev) * speed,
        y: Math.sin(elev) * speed,
        z: Math.sin(azim) * Math.cos(elev) * speed
      };
      lifetimes[i] = 0;
    }
    posAttr.needsUpdate = true;

    // Trigger shockwave ring
    shockwaveProgress = 0;
    shockMat.opacity = 0.95;
    shockMesh.scale.set(1, 1, 1);

    // Flash ingot
    ingotMat.emissiveIntensity = 4.5;
  }

  function triggerForgeStrike() {
    isStriking = true;
    strikeAnimProgress = 0;
    burstSparks();
    return true;
  }

  function updateForge(dt, isSpinning = true) {
    if (!isSpinning) return;

    // Rotate magical rune circle
    runeMesh.rotation.z += dt * 0.08;

    // Bob and rotate floating crystals
    const timeNow = performance.now() * 0.001;
    for (let i = 0; i < crystalMeshes.length; i++) {
      const cry = crystalMeshes[i];
      cry.rotation.y += dt * 0.8;
      cry.rotation.x = Math.sin(timeNow * 1.5 + i) * 0.2;
      cry.position.y = 5.2 + Math.sin(timeNow * 2.0 + i * 1.2) * 0.3;
    }

    // Animate ForgeHammer
    if (isStriking) {
      strikeAnimProgress += dt * 4.0;
      if (strikeAnimProgress < 0.4) {
        // Slam down fast
        hammerPivot.rotation.x = 0.7 - strikeAnimProgress * 1.5;
      } else if (strikeAnimProgress < 0.7) {
        // Recoil
        hammerPivot.rotation.x = 0.1 + (strikeAnimProgress - 0.4) * 0.8;
      } else {
        isStriking = false;
        hammerTime = 0;
      }
    } else {
      hammerTime += dt * 1.8;
      // Rhythmic blacksmith strike cycle (every ~3.5 seconds)
      const cycle = hammerTime % 3.5;
      if (cycle < 1.8) {
        // Raise hammer
        const t = cycle / 1.8;
        hammerPivot.rotation.x = 0.1 + Math.sin(t * Math.PI * 0.5) * 0.65;
      } else if (cycle < 2.1) {
        // Pause at zenith
        hammerPivot.rotation.x = 0.75;
      } else if (cycle < 2.35) {
        // Fast strike downwards
        const t = (cycle - 2.1) / 0.25;
        hammerPivot.rotation.x = 0.75 - t * 0.65;
        if (cycle >= 2.3 && cycle - dt * 1.8 < 2.3) {
          burstSparks();
        }
      } else if (cycle < 2.7) {
        // Rebound
        hammerPivot.rotation.x = 0.1 + Math.sin((cycle - 2.35) * Math.PI * 2) * 0.15;
      } else {
        hammerPivot.rotation.x = 0.1;
      }
    }

    // Smoothly decay ingot flash
    if (ingotMat.emissiveIntensity > 2.2) {
      ingotMat.emissiveIntensity = Math.max(2.2, ingotMat.emissiveIntensity - dt * 4.0);
    }

    // Update Shockwave Ring
    if (shockwaveProgress < 1.0) {
      shockwaveProgress += dt * 1.6;
      const s = 1.0 + shockwaveProgress * 12.0;
      shockMesh.scale.set(s, s, s);
      shockMat.opacity = Math.max(0, 0.95 * (1.0 - shockwaveProgress));
    }

    // Update Particles
    const posAttr = particleGeo.attributes.position;
    const colAttr = particleGeo.attributes.color;

    for (let i = 0; i < totalParticles; i++) {
      const isSpark = particleTypes[i] === 1;

      if (!isSpark) {
        // Rising magma embers
        lifetimes[i] += dt;
        if (lifetimes[i] >= maxLifetimes[i]) {
          lifetimes[i] = 0;
          const rad = Math.random() * 3.2;
          const ang = Math.random() * Math.PI * 2;
          posAttr.setXYZ(i, Math.cos(ang) * rad, 1.25, Math.sin(ang) * rad);
        } else {
          const curX = posAttr.getX(i);
          const curY = posAttr.getY(i);
          const curZ = posAttr.getZ(i);

          const vx = velocities[i].x + (Math.sin(timeNow * 2.0 + i) * 0.05);
          const vy = velocities[i].y;
          const vz = velocities[i].z + (Math.cos(timeNow * 2.0 + i) * 0.05);

          posAttr.setXYZ(i, curX + vx * dt, curY + vy * dt, curZ + vz * dt);

          // Color fade from bright yellow to red to dark
          const lifeRatio = lifetimes[i] / maxLifetimes[i];
          colAttr.setXYZ(i, 1.0, Math.max(0, 0.8 - lifeRatio * 0.8), 0.05);
        }
      } else {
        // Impact sparks
        if (lifetimes[i] < maxLifetimes[i]) {
          lifetimes[i] += dt;
          const curX = posAttr.getX(i);
          const curY = posAttr.getY(i);
          const curZ = posAttr.getZ(i);

          // Gravity
          velocities[i].y -= 9.8 * dt;

          let newY = curY + velocities[i].y * dt;
          let newX = curX + velocities[i].x * dt;
          let newZ = curZ + velocities[i].z * dt;

          // Bounce off dais floor
          if (newY <= 1.23) {
            newY = 1.23;
            velocities[i].y *= -0.4;
            velocities[i].x *= 0.7;
            velocities[i].z *= 0.7;
          }

          posAttr.setXYZ(i, newX, newY, newZ);

          const lifeRatio = lifetimes[i] / maxLifetimes[i];
          colAttr.setXYZ(i, 1.0, 0.9 * (1.0 - lifeRatio), 0.4 * (1.0 - lifeRatio));
        }
      }
    }

    posAttr.needsUpdate = true;
    colAttr.needsUpdate = true;
  }

  return {
    group: forgeGroup,
    materialsToDispose,
    triggerForgeStrike,
    updateForge
  };
}


