import * as THREE from 'three';

/**
 * Procedural texture registry to track and cleanly dispose textures on theme switches.
 */
const textureRegistry = [];

export function registerTexture(tex) {
  if (tex && !textureRegistry.includes(tex)) {
    textureRegistry.push(tex);
  }
  return tex;
}

export function disposeAllTextures() {
  let count = 0;
  for (const tex of textureRegistry) {
    if (tex && typeof tex.dispose === 'function') {
      tex.dispose();
      count++;
    }
  }
  textureRegistry.length = 0;
  return count;
}

/**
 * Generates high-density illuminated skyscraper window facades.
 * Supports multiple architectural styles:
 * Style 0: Cyberpunk Cyan & Neon Yellow / Magenta (cyber high-tech)
 * Style 1: Corporate Amber & Warm White (financial towers)
 * Style 2: Matrix Emerald & Tech Blue (data center spires)
 * Style 3: Violet Neon Ribbons & Penthouse Lounges (luxury towers)
 */
export function createWindowTexture(theme = 'night', styleIndex = 0) {
  const width = 512;
  const height = 1024;
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  // Base facade background
  let baseColor = '#0b0f19';
  let mullionColor = '#161e2e';
  let frameColor = '#1f293d';
  if (theme === 'gold') {
    baseColor = '#1c1314';
    mullionColor = '#2b1c1d';
    frameColor = '#3b2628';
  } else if (theme === 'day') {
    baseColor = '#1e293b';
    mullionColor = '#334155';
    frameColor = '#475569';
  }

  ctx.fillStyle = baseColor;
  ctx.fillRect(0, 0, width, height);

  // Subtle vertical metallic panel stripes
  ctx.fillStyle = mullionColor;
  const panelCols = 16;
  const colWidth = width / panelCols;
  for (let c = 0; c < panelCols; c++) {
    if (c % 2 === 0) {
      ctx.fillRect(c * colWidth, 0, colWidth * 0.1, height);
    }
  }

  // Windows grid layout
  const rows = 48;
  const cols = 12;
  const paddingX = 8;
  const paddingY = 6;
  const winWidth = (width - paddingX * (cols + 1)) / cols;
  const winHeight = (height - paddingY * (rows + 1)) / rows;

  // Color palettes for windows depending on style
  const palettes = {
    0: {
      litRate: 0.65,
      colors: ['#00f0ff', '#38bdf8', '#ffdf00', '#f43f5e', '#ffffff', '#0ea5e9']
    },
    1: {
      litRate: 0.70,
      colors: ['#fbbf24', '#f59e0b', '#fef08a', '#ffffff', '#fde047', '#fed7aa']
    },
    2: {
      litRate: 0.60,
      colors: ['#10b981', '#34d399', '#06b6d4', '#6ee7b7', '#a7f3d0', '#ffffff']
    },
    3: {
      litRate: 0.75,
      colors: ['#c084fc', '#e879f9', '#f472b6', '#38bdf8', '#ffffff', '#818cf8']
    }
  };

  const palette = palettes[styleIndex % 4] || palettes[0];

  // Draw windows
  for (let r = 0; r < rows; r++) {
    // Floor structural divider line every 4 floors
    if (r % 4 === 0) {
      ctx.fillStyle = frameColor;
      ctx.fillRect(0, r * (winHeight + paddingY) - paddingY * 0.5, width, 3);
    }

    for (let c = 0; c < cols; c++) {
      const x = paddingX + c * (winWidth + paddingX);
      const y = paddingY + r * (winHeight + paddingY);

      // Window casing
      ctx.fillStyle = mullionColor;
      ctx.fillRect(x - 1, y - 1, winWidth + 2, winHeight + 2);

      // Pseudo-random lit state based on coordinates (strictly positive in [0, 1))
      const rawRand = Math.sin(r * 12.9898 + c * 78.233 + styleIndex * 43.12) * 43758.5453;
      const randVal = Math.abs(rawRand - Math.floor(rawRand));
      const isLit = randVal < palette.litRate;

      if (isLit) {
        const randColor = Math.abs(Math.sin(r * 39.34 + c * 11.23 + styleIndex * 5.7));
        const colorIdx = Math.floor(randColor * palette.colors.length) % palette.colors.length;
        const winColor = palette.colors[colorIdx] || palette.colors[0] || '#38bdf8';

        // Soft interior glow gradient
        const grad = ctx.createLinearGradient(x, y, x, y + winHeight);
        grad.addColorStop(0, winColor);
        grad.addColorStop(0.7, winColor);
        grad.addColorStop(1, '#05070c');

        ctx.fillStyle = grad;
        ctx.fillRect(x, y, winWidth, winHeight);

        // Blinds / horizontal louvers on some windows
        if (Math.sin(r * 3.1 + c * 5.7) > 0.4) {
          ctx.fillStyle = 'rgba(0, 0, 0, 0.45)';
          ctx.fillRect(x, y + winHeight * 0.5, winWidth, winHeight * 0.5);
        }
      } else {
        // Dark unlit glass with subtle reflection
        ctx.fillStyle = theme === 'day' ? '#15202b' : '#080d14';
        ctx.fillRect(x, y, winWidth, winHeight);
      }
    }
  }

  // Neon advertising billboard banner on certain building facades
  if (styleIndex % 2 === 0) {
    const bannerY = Math.floor(rows * 0.45) * (winHeight + paddingY);
    const bannerH = winHeight * 4 + paddingY * 3;
    ctx.fillStyle = '#050711';
    ctx.fillRect(16, bannerY, width - 32, bannerH);
    ctx.strokeStyle = styleIndex === 0 ? '#00f0ff' : '#ec4899';
    ctx.lineWidth = 3;
    ctx.strokeRect(16, bannerY, width - 32, bannerH);

    ctx.font = 'bold 24px monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = styleIndex === 0 ? '#00f0ff' : '#f43f5e';
    ctx.shadowColor = styleIndex === 0 ? '#00f0ff' : '#f43f5e';
    ctx.shadowBlur = 10;
    const bannerText = styleIndex === 0 ? '✦ MORU FORGE ✦' : '⚡ CYBER CAT 99 ⚡';
    ctx.fillText(bannerText, width / 2, bannerY + bannerH / 2);
    ctx.shadowBlur = 0;
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  return registerTexture(texture);
}

/**
 * Generates detailed paved asphalt road texture with double yellow center dividers,
 * white lane markers, edge lines, pedestrian crosswalks, and cat paw prints.
 */
export function createRoadTexture() {
  const size = 512;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');

  // Asphalt base
  ctx.fillStyle = '#1e2430';
  ctx.fillRect(0, 0, size, size);

  // Road grit and noise
  for (let i = 0; i < 4000; i++) {
    const x = Math.random() * size;
    const y = Math.random() * size;
    const alpha = Math.random() * 0.08;
    ctx.fillStyle = Math.random() > 0.5 ? `rgba(255, 255, 255, ${alpha})` : `rgba(0, 0, 0, ${alpha * 2})`;
    ctx.fillRect(x, y, 1.5, 1.5);
  }

  // Outer solid white road edge boundaries
  ctx.fillStyle = '#e2e8f0';
  ctx.fillRect(16, 0, 4, size);
  ctx.fillRect(size - 20, 0, 4, size);

  // Center double solid yellow lines
  ctx.fillStyle = '#f59e0b';
  ctx.fillRect(size / 2 - 5, 0, 3, size);
  ctx.fillRect(size / 2 + 2, 0, 3, size);

  // Dashed white lane dividers (two lanes on each side)
  ctx.fillStyle = '#f8fafc';
  const dashH = 28;
  const gapH = 20;
  const laneLeft = size * 0.28;
  const laneRight = size * 0.72;

  for (let y = 0; y < size; y += dashH + gapH) {
    ctx.fillRect(laneLeft - 1.5, y, 3, dashH);
    ctx.fillRect(laneRight - 1.5, y, 3, dashH);
  }

  // Crosswalk zebra stripes at bottom end
  const crosswalkY = size - 70;
  const crosswalkH = 50;
  const stripeW = 14;
  const stripeGap = 12;
  ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
  for (let x = 24; x < size - 24; x += stripeW + stripeGap) {
    ctx.fillRect(x, crosswalkY, stripeW, crosswalkH);
  }

  // Moru Cat paw print road stencil
  drawCatPaw(ctx, size * 0.38, size * 0.4, 18, 'rgba(56, 189, 248, 0.45)');
  drawCatPaw(ctx, size * 0.62, size * 0.2, 18, 'rgba(251, 191, 36, 0.45)');

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  return registerTexture(texture);
}

/**
 * Helper to draw a stylized cat paw print icon onto canvas.
 */
function drawCatPaw(ctx, cx, cy, radius, color) {
  ctx.save();
  ctx.fillStyle = color;
  // Main palm pad
  ctx.beginPath();
  ctx.ellipse(cx, cy + radius * 0.2, radius * 0.75, radius * 0.6, 0, 0, Math.PI * 2);
  ctx.fill();

  // 4 toe pads
  const toeOffsets = [
    { x: -radius * 0.65, y: -radius * 0.35, r: radius * 0.28 },
    { x: -radius * 0.22, y: -radius * 0.7, r: radius * 0.32 },
    { x: radius * 0.22, y: -radius * 0.7, r: radius * 0.32 },
    { x: radius * 0.65, y: -radius * 0.35, r: radius * 0.28 }
  ];
  for (const toe of toeOffsets) {
    ctx.beginPath();
    ctx.arc(cx + toe.x, cy + toe.y, toe.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

/**
 * Generates the central Moru Blacksmith Forge glowing rune circle texture.
 * Features concentric Celtic/Nordic/Cyber rune rings, glowing glyphs,
 * radiating energy conduits, and central anvil insignia.
 */
export function createRuneTexture(theme = 'night') {
  const size = 1024;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');

  const cx = size / 2;
  const cy = size / 2;

  // Clear dark stone backing
  ctx.fillStyle = '#0f141f';
  ctx.fillRect(0, 0, size, size);

  // Palette based on theme
  let glowColor = '#ff6600';
  let innerGlow = '#ffcc00';
  let cyberColor = '#00f0ff';
  let runeColor = '#ffa500';

  if (theme === 'gold') {
    glowColor = '#ffaa00';
    innerGlow = '#ffe066';
    cyberColor = '#ffd700';
    runeColor = '#ffb700';
  } else if (theme === 'day') {
    glowColor = '#0284c7';
    innerGlow = '#38bdf8';
    cyberColor = '#0ea5e9';
    runeColor = '#0284c7';
  }

  // Outer decorative rim
  ctx.strokeStyle = glowColor;
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.arc(cx, cy, 480, 0, Math.PI * 2);
  ctx.stroke();

  // Secondary outer dashed ring
  ctx.lineWidth = 3;
  ctx.setLineDash([14, 10]);
  ctx.strokeStyle = cyberColor;
  ctx.beginPath();
  ctx.arc(cx, cy, 455, 0, Math.PI * 2);
  ctx.stroke();
  ctx.setLineDash([]);

  // 16 Radiating runic staves
  const staves = 16;
  for (let i = 0; i < staves; i++) {
    const angle = (i * Math.PI * 2) / staves;
    const x1 = cx + Math.cos(angle) * 180;
    const y1 = cy + Math.sin(angle) * 180;
    const x2 = cx + Math.cos(angle) * 440;
    const y2 = cy + Math.sin(angle) * 440;

    ctx.strokeStyle = i % 2 === 0 ? glowColor : cyberColor;
    ctx.lineWidth = i % 4 === 0 ? 4 : 2;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();

    // Cross notches on staves
    const mx = cx + Math.cos(angle) * 310;
    const my = cy + Math.sin(angle) * 310;
    const crossA = angle + Math.PI / 2;
    ctx.beginPath();
    ctx.moveTo(mx - Math.cos(crossA) * 12, my - Math.sin(crossA) * 12);
    ctx.lineTo(mx + Math.cos(crossA) * 12, my + Math.sin(crossA) * 12);
    ctx.stroke();
  }

  // Intermediate rune glyph ring
  ctx.strokeStyle = innerGlow;
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(cx, cy, 380, 0, Math.PI * 2);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cx, cy, 320, 0, Math.PI * 2);
  ctx.stroke();

  // Draw 24 Runic Glyphs around ring
  const runeCount = 24;
  const runes = ['ᚠ', 'ᚢ', 'ᚦ', 'ᚨ', 'ᚱ', 'ᚲ', 'ᚷ', 'ᚹ', 'ᚺ', 'ᚾ', 'ᛁ', 'ᛃ', 'ᛈ', 'ᛇ', 'ᛉ', 'ᛊ', 'ᛏ', 'ᛒ', 'ᛖ', 'ᛗ', 'ᛚ', 'ᛜ', 'ᛞ', 'ᛟ'];
  ctx.font = 'bold 36px serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = runeColor;

  for (let i = 0; i < runeCount; i++) {
    const angle = (i * Math.PI * 2) / runeCount;
    const rDist = 350;
    const rx = cx + Math.cos(angle) * rDist;
    const ry = cy + Math.sin(angle) * rDist;

    ctx.save();
    ctx.translate(rx, ry);
    ctx.rotate(angle + Math.PI / 2);
    ctx.fillText(runes[i % runes.length], 0, 0);
    ctx.restore();
  }

  // Inner interlocking geometric stars (octagram / forge seal)
  ctx.strokeStyle = glowColor;
  ctx.lineWidth = 3;
  for (let rot = 0; rot < 2; rot++) {
    ctx.beginPath();
    const starA = (rot * Math.PI) / 4;
    for (let p = 0; p < 4; p++) {
      const a = starA + (p * Math.PI) / 2;
      const px = cx + Math.cos(a) * 230;
      const py = cy + Math.sin(a) * 230;
      if (p === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.stroke();
  }

  // Inner glowing basin ring
  ctx.strokeStyle = innerGlow;
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(cx, cy, 140, 0, Math.PI * 2);
  ctx.stroke();

  // Central Anvil Silhouette & Cross Hammers Icon
  ctx.fillStyle = innerGlow;
  ctx.beginPath();
  // Stylized Anvil Icon
  ctx.rect(cx - 50, cy - 15, 100, 25); // face
  ctx.rect(cx - 30, cy + 10, 60, 20); // waist
  ctx.rect(cx - 55, cy + 30, 110, 15); // base
  ctx.fill();

  // Central glowing core point
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(cx, cy, 12, 0, Math.PI * 2);
  ctx.fill();

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.ClampToEdgeWrapping;
  texture.wrapT = THREE.ClampToEdgeWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  return registerTexture(texture);
}

/**
 * Generates molten magma hearth flow texture.
 */
export function createMagmaTexture() {
  const size = 512;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');

  // Intense fire gradient base
  const grad = ctx.createRadialGradient(size / 2, size / 2, 20, size / 2, size / 2, size / 2);
  grad.addColorStop(0, '#ffffff');
  grad.addColorStop(0.2, '#ffea00');
  grad.addColorStop(0.5, '#ff5500');
  grad.addColorStop(0.8, '#b91c1c');
  grad.addColorStop(1, '#450a0a');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);

  // Floating dark crust obsidian plates
  ctx.fillStyle = '#1c0f0f';
  for (let i = 0; i < 35; i++) {
    const x = Math.random() * size;
    const y = Math.random() * size;
    const rad = 15 + Math.random() * 35;
    ctx.beginPath();
    ctx.arc(x, y, rad, 0, Math.PI * 2);
    ctx.fill();
  }

  // Glowing magma fissures & veins
  ctx.strokeStyle = '#ffe066';
  ctx.lineWidth = 3;
  for (let i = 0; i < 15; i++) {
    ctx.beginPath();
    ctx.moveTo(Math.random() * size, Math.random() * size);
    for (let step = 0; step < 4; step++) {
      ctx.lineTo(Math.random() * size, Math.random() * size);
    }
    ctx.stroke();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  return registerTexture(texture);
}

/**
 * Generates stone plaza paving tiles with subtle grout lines and granite flecks.
 */
export function createPlazaStoneTexture() {
  const size = 512;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');

  // Slate grey base
  ctx.fillStyle = '#2d3748';
  ctx.fillRect(0, 0, size, size);

  // Cobble / paver grid
  const tiles = 16;
  const tileSize = size / tiles;
  for (let r = 0; r < tiles; r++) {
    for (let c = 0; c < tiles; c++) {
      const shade = 35 + Math.floor(Math.random() * 25);
      ctx.fillStyle = `rgb(${shade}, ${shade + 5}, ${shade + 12})`;
      ctx.fillRect(c * tileSize + 1, r * tileSize + 1, tileSize - 2, tileSize - 2);

      // Subtle bevel highlight
      ctx.fillStyle = 'rgba(255, 255, 255, 0.08)';
      ctx.fillRect(c * tileSize + 1, r * tileSize + 1, tileSize - 2, 2);
      ctx.fillRect(c * tileSize + 1, r * tileSize + 1, 2, tileSize - 2);
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  return registerTexture(texture);
}

/**
 * Generates high-visibility rooftop helipad texture.
 */
export function createHelipadTexture() {
  const size = 512;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');

  const cx = size / 2;
  const cy = size / 2;

  // Dark concrete pad
  ctx.fillStyle = '#1e293b';
  ctx.fillRect(0, 0, size, size);

  // Yellow hazard border perimeter
  ctx.strokeStyle = '#facc15';
  ctx.lineWidth = 12;
  ctx.strokeRect(20, 20, size - 40, size - 40);

  // Yellow inner circle
  ctx.lineWidth = 14;
  ctx.beginPath();
  ctx.arc(cx, cy, 180, 0, Math.PI * 2);
  ctx.stroke();

  // White "H" symbol
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 160px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('H', cx, cy);

  // Perimeter landing quadrant dots
  ctx.fillStyle = '#ef4444';
  const dots = [
    { x: cx, y: 55 },
    { x: cx, y: size - 55 },
    { x: 55, y: cy },
    { x: size - 55, y: cy }
  ];
  for (const dot of dots) {
    ctx.beginPath();
    ctx.arc(dot.x, dot.y, 10, 0, Math.PI * 2);
    ctx.fill();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.ClampToEdgeWrapping;
  texture.wrapT = THREE.ClampToEdgeWrapping;
  texture.colorSpace = THREE.SRGBColorSpace;
  return registerTexture(texture);
}


